CREATE OR REPLACE FUNCTION crm_api.read_probe(p bytea, s bytea, q bytea)
 RETURNS TABLE(probe_id text, public_value text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; qf text[];
begin
  f := crm_f1.verify(p,s,q,'C01'); qf := crm_f1.fields(q);
  perform set_config('crm.f1_payload',encode(p,'hex'),true),
    set_config('crm.f1_mac',encode(s,'hex'),true),set_config('crm.f1_input',encode(q,'hex'),true);
  return query select a.probe_id,a.public_value from crm_private.access_probe a
    where a.probe_id collate "C" = qf[3] collate "C";
  perform crm_f1.verify(p,s,q,'C01');
  perform set_config('crm.f1_payload','',true),set_config('crm.f1_mac','',true),set_config('crm.f1_input','',true);
exception when others then raise exception 'F1_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.apply_probe_batch(p bytea, s bytea, q bytea)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; qf text[]; i integer; result text[] := '{}';
begin
  f := crm_f1.verify(p,s,q,'C03'); qf := crm_f1.fields(q);
  insert into crm_f1.consumption values (f[5],f[6]::oid,f[8]::xid8,f[21],f[20]::bigint);
  perform set_config('crm.f1_payload',encode(p,'hex'),true),
    set_config('crm.f1_mac',encode(s,'hex'),true),set_config('crm.f1_input',encode(q,'hex'),true);
  i := 6;
  while i <= cardinality(qf) loop
    insert into crm_private.access_probe (probe_id,context_scope,public_value)
      values (qf[i+1],f[14],qf[i+2]);
    result := array_append(result,qf[i+1]); i := i+3;
  end loop;
  perform crm_f1.verify(p,s,q,'C03');
  perform set_config('crm.f1_payload','',true),set_config('crm.f1_mac','',true),set_config('crm.f1_input','',true);
  return result;
exception when others then raise exception 'F1_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.set_actor_enabled(v_actor uuid, v_enabled boolean, v_state text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
begin
  if session_user<>'crm_h0_migration' or v_enabled is null
    or v_state not in ('ready','enrollment_required','recovery_in_progress','reidentification_required')
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  -- Actor is the first lock in every access/revocation path.
  perform 1 from crm_private.crm_actors where actor_id=v_actor for update;
  if not v_enabled and exists (
    select 1 from crm_private.crm_actors
      where actor_id=v_actor and access_generation=9223372036854775807
  ) then raise exception 'F2_DENIED' using errcode='42501'; end if;
  update crm_private.crm_actors set enabled=v_enabled,access_state=v_state,
    access_generation=access_generation+case when not v_enabled then 1 else 0 end,
    updated_at=clock_timestamp() where actor_id=v_actor;
  if not found then raise exception 'F2_DENIED' using errcode='42501'; end if;
exception when others then raise exception 'F2_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.establish_session(p bytea, s bytea, q bytea)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; a crm_private.crm_actors%rowtype; qf text[]; at_time timestamptz;
begin
  f:=crm_f2.verify(p,s,q,'establish','human_session','establish');
  qf:=crm_f1.fields(q);
  if f[16]<>'full-identification' or f[21]<>'identification'
    or cardinality(qf)<>5 or qf[1]<>'CRM-F2-INP1' or qf[2]<>'establish'
    or qf[3]<>f[11] or qf[4]<>f[13] or qf[5]<>f[14]
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  select * into strict a from crm_private.crm_actors
    where actor_id=f[12]::uuid for update;
  if a.auth_subject<>f[11]::uuid or not a.enabled or a.access_state<>'ready'
    or a.access_generation<>f[15]::bigint or a.admin_scope<>f[17]
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  -- Re-read PostgreSQL's real clock after the actor lock, before either INSERT.
  perform crm_f2.verify(p,s,q,'establish','human_session','establish');
  at_time:=clock_timestamp();
  insert into crm_private.crm_sessions(session_id,actor_id,auth_subject,access_generation,created_at)
    values(f[13]::uuid,a.actor_id,a.auth_subject,a.access_generation,at_time);
  insert into crm_private.identification_epochs(epoch_id,session_id,identified_at,
    last_human_activity_at,full_password,full_mfa,access_state,current_epoch)
    values(f[14]::uuid,f[13]::uuid,at_time,at_time,true,true,'ready',true);
  -- Any lock wait inside the INSERTs still aborts the entire unit on expiry.
  perform crm_f2.verify(p,s,q,'establish','human_session','establish');
  return f[14]::uuid;
exception when others then raise exception 'F2_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.reidentify_session(p bytea, s bytea, q bytea)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; qf text[]; a crm_private.crm_actors%rowtype;
  ss crm_private.crm_sessions%rowtype; old_epoch crm_private.identification_epochs%rowtype;
  at_time timestamptz;
begin
  f:=crm_f2.verify(p,s,q,'reidentify','human_session','reidentify');
  qf:=crm_f1.fields(q);
  if f[16]<>'full-identification' or f[21]<>'identification'
    or cardinality(qf)<>5 or qf[1]<>'CRM-F2-INP1' or qf[2]<>'reidentify'
    or qf[3]<>f[13] or qf[4]<>f[14] or qf[5]=''
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  select * into strict a from crm_private.crm_actors where actor_id=f[12]::uuid for update;
  select * into strict ss from crm_private.crm_sessions where session_id=f[13]::uuid for update;
  select * into strict old_epoch from crm_private.identification_epochs
    where session_id=ss.session_id and current_epoch for update;
  if not a.enabled or a.access_state<>'ready' or a.auth_subject<>f[11]::uuid
    or a.admin_scope<>f[17] or a.access_generation<>f[15]::bigint
    or ss.actor_id<>a.actor_id or ss.auth_subject<>a.auth_subject or ss.revoked_at is not null
    or ss.access_generation<>a.access_generation
    or old_epoch.epoch_id<>f[14]::uuid
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  perform crm_f2.verify(p,s,q,'reidentify','human_session','reidentify');
  at_time:=clock_timestamp();
  update crm_private.identification_epochs set current_epoch=false,closed_at=at_time
    where epoch_id=old_epoch.epoch_id;
  update crm_private.crm_sessions set access_generation=a.access_generation
    where session_id=ss.session_id;
  insert into crm_private.identification_epochs(epoch_id,session_id,identified_at,
    last_human_activity_at,full_password,full_mfa,access_state,current_epoch)
    values(qf[5]::uuid,ss.session_id,at_time,at_time,true,true,'ready',true);
  perform crm_f2.verify(p,s,q,'reidentify','human_session','reidentify');
  return qf[5]::uuid;
exception when others then raise exception 'F2_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.revoke_session(p bytea, s bytea, q bytea)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; qf text[]; a crm_private.crm_actors%rowtype;
  ss crm_private.crm_sessions%rowtype; ep crm_private.identification_epochs%rowtype;
begin
  f:=crm_f2.verify(p,s,q,'revoke_one','human_session','revoke_one');
  qf:=crm_f1.fields(q);
  if f[16]<>'session-revocation' or f[21]<>'administrative_action'
    or cardinality(qf)<>3 or qf[1]<>'CRM-F2-INP1' or qf[2]<>'revoke_one'
    or qf[3]<>f[13]
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  select * into strict a from crm_private.crm_actors where actor_id=f[12]::uuid for update;
  select * into strict ss from crm_private.crm_sessions where session_id=f[13]::uuid for update;
  select * into strict ep from crm_private.identification_epochs
    where epoch_id=f[14]::uuid for update;
  if a.auth_subject<>f[11]::uuid or a.access_generation<>f[15]::bigint
    or ss.actor_id<>a.actor_id or ss.auth_subject<>a.auth_subject
    or ss.revoked_at is not null or ep.session_id<>ss.session_id or not ep.current_epoch
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  perform crm_f2.verify(p,s,q,'revoke_one','human_session','revoke_one');
  update crm_private.crm_sessions set revoked_at=clock_timestamp() where session_id=ss.session_id;
  perform crm_f2.verify(p,s,q,'revoke_one','human_session','revoke_one');
exception when others then raise exception 'F2_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.revoke_all_sessions(p bytea, s bytea, q bytea)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; qf text[]; a crm_private.crm_actors%rowtype;
  ss crm_private.crm_sessions%rowtype; ep crm_private.identification_epochs%rowtype;
  at_time timestamptz; new_generation bigint;
begin
  f:=crm_f2.verify(p,s,q,'revoke_all','human_actor','revoke_all');
  qf:=crm_f1.fields(q);
  if f[16]<>'session-revocation' or f[21]<>'administrative_action'
    or cardinality(qf)<>3 or qf[1]<>'CRM-F2-INP1' or qf[2]<>'revoke_all'
    or qf[3]<>f[12]
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  select * into strict a from crm_private.crm_actors
    where actor_id=f[12]::uuid for update;
  select * into strict ss from crm_private.crm_sessions
    where session_id=f[13]::uuid for update;
  select * into strict ep from crm_private.identification_epochs
    where epoch_id=f[14]::uuid for update;
  at_time:=clock_timestamp();
  if a.auth_subject<>f[11]::uuid or not a.enabled or a.access_state<>'ready'
    or a.admin_scope<>f[17] or a.access_generation<>f[15]::bigint
    or ss.actor_id<>a.actor_id or ss.auth_subject<>a.auth_subject
    or ss.access_generation<>a.access_generation or ss.revoked_at is not null
    or ep.session_id<>ss.session_id or not ep.current_epoch
    or not ep.full_password or not ep.full_mfa or ep.access_state<>'ready'
    or not crm_f2.within_limit(at_time,ep.identified_at,30)
    or not crm_f2.within_limit(at_time,ep.last_human_activity_at,7)
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  perform crm_f2.verify(p,s,q,'revoke_all','human_actor','revoke_all');
  if a.access_generation=9223372036854775807
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  update crm_private.crm_actors set access_generation=access_generation+1,
    updated_at=clock_timestamp() where actor_id=a.actor_id
    returning access_generation into new_generation;
  perform crm_f2.verify(p,s,q,'revoke_all','human_actor','revoke_all');
  return new_generation;
exception when others then raise exception 'F2_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.human_read_probe(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(probe_id text, public_value text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[];
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_probe');
  tf:=crm_f1.verify(f1p,f1s,q,'C01');
  if tf[14] collate "C"<>hf[17] collate "C" then
    raise exception 'F2_DENIED' using errcode='42501'; end if;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_core_probe','read_probe');
  return query select r.probe_id,r.public_value from crm_api.read_probe(f1p,f1s,q) r;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_core_probe','read_probe');
exception when others then raise exception 'F2_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.human_apply_probe_batch(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; result text[];
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C03','apply_probe_batch');
  tf:=crm_f1.verify(f1p,f1s,q,'C03');
  if tf[14] collate "C"<>hf[17] collate "C" then
    raise exception 'F2_DENIED' using errcode='42501'; end if;
  perform crm_f2.verify(f2p,f2s,q,'C03','human_core_probe','apply_probe_batch');
  result:=crm_api.apply_probe_batch(f1p,f1s,q);
  perform crm_f2.verify(f2p,f2s,q,'C03','human_core_probe','apply_probe_batch');
  return result;
exception when others then raise exception 'F2_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.h0_m04_command(f2p bytea, f2s bytea, p bytea, s bytea, q bytea)
 RETURNS TABLE(command_state text, proposal_id text, decision_id text, reservation_id text, attempt_id text, state text, material_fingerprint text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_column
declare f text[]; qf text[]; d text[]; hf text[]; material bytea; part_material bytea;
  proposal_row crm_ha.proposals%rowtype; part_row crm_ha.parts%rowtype;
  decision_row crm_ha.decisions%rowtype; reservation_row crm_ha.reservations%rowtype;
  old crm_ha.command_receipts%rowtype; digest_value text; now_at timestamptz:=clock_timestamp();
  decision_value text; decision_key text; reservation_key text; attempt_key text;
  effect_key text; intent_key text; part_count integer; i integer; part_fields text[];
begin
  qf:=crm_f1.fields(q);
  if qf is null or cardinality(qf)<4 or qf[1]<>'CRM-H0-M04'
    or qf[3] !~ '^[a-z][a-z0-9-]{0,127}$' then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
  f:=crm_f1.verify_envelope(p,s,q,
    case when qf[2]='read' then 'C01' else 'C03' end,
    'human_approval',case when qf[2]='read' then 'read_proposal' else 'manage_effect' end);
  if qf[2] in ('propose','decide','reserve') then
    hf:=crm_f2.admit(f2p,f2s,q,'C03','apply_probe_batch');
    if hf[17] collate "C"<>f[14] collate "C" then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
  end if;
  digest_value:=encode(crm_crypto.digest(q,'sha256'),'hex');
  insert into crm_f1.consumption values(f[5],f[6]::oid,f[8]::xid8,f[21],f[20]::bigint);
  perform pg_advisory_xact_lock(hashtextextended(qf[3],0));
  select * into old from crm_ha.command_receipts where command_id=qf[3];
  if found then
    if old.command_fingerprint collate "C"<>digest_value collate "C" then raise exception 'H0_M04_CONFLICT' using errcode='H0002'; end if;
    perform crm_f1.verify_envelope(p,s,q,'C03','human_approval','manage_effect');
    return query select 'previous',old.proposal_id,old.decision_id,old.reservation_id,old.attempt_id,old.state,old.command_fingerprint;
    return;
  end if;
  if qf[2]='propose' then
    if cardinality(qf)<>5 or qf[4] not in ('human','ai') then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    material:=decode(qf[5],'hex'); d:=crm_f1.fields(material);
    if encode(crm_f1.pack_fields(d),'hex')<>qf[5] or cardinality(d)<21
      or d[1]<>'CRM-H0-HA-MATERIAL1' or d[2]<>'1' or d[3]='' or d[4]=''
      or d[6] not in ('not-applicable','unknown','value') or d[8] not in ('not-applicable','unknown','value')
      or d[10] not in ('not-applicable','unknown','value') or d[14] not in ('not-applicable','unknown','value')
      or d[16] not in ('none','required') or d[20] !~ '^[1-9][0-9]?$'
      or cardinality(d)<>20+d[20]::integer*3
      or (d[6]<>'value' and d[7]<>'') or (d[8]<>'value' and d[9]<>'')
      or (d[10]<>'value' and d[11]<>'') or (d[14]<>'value' and d[15]<>'')
      or (d[16]='none' and (d[17]<>'' or d[18]<>'' or d[19]<>''))
      or (d[16]='required' and (d[17]='' or d[18] !~ '^[0-9a-f]{64}$' or d[19]=''))
    then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    perform 1 from crm_private.crm_actors a where a.actor_id=hf[12]::uuid and a.enabled
      and a.access_state='ready' and a.admin_scope=d[12] for update;
    if not found then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    hf:=crm_f2.admit(f2p,f2s,q,'C03','apply_probe_batch');
    now_at:=clock_timestamp();
    insert into crm_ha.proposals values(qf[3],encode(crm_crypto.digest(material,'sha256'),'hex'),material,
      qf[4],hf[12]::uuid,d[12],now_at);
    part_count:=d[20]::integer;
    for i in 0..part_count-1 loop
      part_material:=decode(d[22+i*3],'hex'); part_fields:=crm_f1.fields(part_material);
      if encode(crm_f1.pack_fields(part_fields),'hex')<>d[22+i*3]
        or encode(crm_crypto.digest(part_material,'sha256'),'hex')<>d[23+i*3]
        or cardinality(part_fields)<>13 or part_fields[1]<>'CRM-H0-HA-PART1'
        or part_fields[2]<>d[21+i*3] or part_fields[12]<>d[12]
      then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
      insert into crm_ha.parts values(qf[3],d[21+i*3],d[23+i*3],part_material);
    end loop;
    insert into crm_ha.events values(qf[3],qf[3],null,null,'proposed',
      case when qf[4]='human' then 'human' else 'technical' end,
      hf[12],now_at,digest_value);
    insert into crm_ha.command_receipts values(qf[3],digest_value,'propose',qf[3],null,null,null,'proposed',now_at);
    return query select 'applied',qf[3],null::text,null::text,null::text,'proposed',encode(crm_crypto.digest(material,'sha256'),'hex'); return;
  elsif qf[2]='decide' then
    d:=crm_f1.fields(decode(qf[4],'hex'));
    if cardinality(qf)<>4 or cardinality(d)<>5 or d[1] !~ '^[a-z][a-z0-9-]{0,127}$'
      or d[2] !~ '^[a-z][a-z0-9-]{0,127}$' or d[3] not in ('approved','rejected') or d[4]='' or d[5] !~ '^[0-9a-f]{64}$'
    then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    perform pg_advisory_xact_lock(hashtextextended(d[1]||':decision',0));
    select * into strict proposal_row from crm_ha.proposals where proposal_id=d[1];
    if proposal_row.material_fingerprint collate "C"<>d[5] collate "C" or proposal_row.scope collate "C"<>hf[17] collate "C"
    then raise exception 'H0_M04_CONFLICT' using errcode='H0002'; end if;
    hf:=crm_f2.admit(f2p,f2s,q,'C03','apply_probe_batch');
    now_at:=clock_timestamp();
    decision_key:=d[2]; decision_value:=d[3];
    insert into crm_ha.decisions values(decision_key,d[1],d[5],decision_value,d[4],hf[12]::uuid,hf[13]::uuid,now_at);
    insert into crm_ha.events values(qf[3],d[1],null,null,decision_value,'human',hf[12],now_at,digest_value);
    insert into crm_ha.command_receipts values(qf[3],digest_value,'decide',d[1],decision_key,null,null,decision_value,now_at);
    return query select 'applied',d[1],decision_key,null::text,null::text,decision_value,d[5]; return;
  elsif qf[2]='reserve' then
    d:=crm_f1.fields(decode(qf[4],'hex'));
    if cardinality(qf)<>4 or cardinality(d)<>7 or d[1] !~ '^[a-z][a-z0-9-]{0,127}$' or d[2] !~ '^[a-z][a-z0-9-]{0,127}$'
      or d[3] !~ '^[a-z][a-z0-9-]{0,127}$' or d[4] !~ '^[0-9a-f]{64}$'
      or d[5] !~ '^[0-9a-f]{64}$' or d[6] !~ '^[a-z][a-z0-9-]{0,127}$'
      or d[7] !~ '^[a-z][a-z0-9-]{0,127}$'
    then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    select * into strict proposal_row from crm_ha.proposals where proposal_id=d[1];
    select * into strict decision_row from crm_ha.decisions where decision_id=d[2] and proposal_id=d[1];
    perform pg_advisory_xact_lock(hashtextextended(d[1]||':'||d[3],0));
    select * into strict part_row from crm_ha.parts where proposal_id=d[1] and part_id=d[3];
    if decision_row.decision<>'approved' or proposal_row.material_fingerprint collate "C"<>d[4] collate "C"
      or part_row.material_fingerprint collate "C"<>d[5] collate "C" or proposal_row.scope collate "C"<>hf[17] collate "C"
      or proposal_row.material_payload is null
    then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    if (crm_f1.fields(proposal_row.material_payload))[16]<>'none' then
      if not exists(select 1 from crm_ha.evidence_revalidations e where e.command_id=qf[3]
        and e.proposal_id=d[1] and e.part_id=d[3] and e.command_fingerprint=digest_value
        and e.context_scope=hf[17] and e.created_xid=pg_current_xact_id()) then
        raise exception 'H0_M04_EVIDENCE_UNVERIFIED' using errcode='42501'; end if;
      perform crm_ha.check_evidence_at_end(qf[3]);
    end if;
    effect_key:='effect-'||substr(encode(crm_crypto.digest(convert_to(d[1]||':'||d[3],'UTF8'),'sha256'),'hex'),1,32);
    intent_key:='intent-'||substr(encode(crm_crypto.digest(convert_to(d[1]||':'||d[3],'UTF8'),'sha256'),'hex'),1,32);
    if d[6]<>effect_key or d[7]<>intent_key then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    hf:=crm_f2.admit(f2p,f2s,q,'C03','apply_probe_batch');
    now_at:=clock_timestamp();
    insert into crm_ha.reservations values(qf[3],d[1],d[2],d[3],d[5],effect_key,intent_key,'reserved',now_at,now_at);
    insert into crm_ha.events values(qf[3],d[1],qf[3],null,'reserved','human',hf[12],now_at,digest_value);
    insert into crm_ha.command_receipts values(qf[3],digest_value,'reserve',d[1],d[2],qf[3],null,'reserved',now_at);
    return query select 'applied',d[1],d[2],qf[3],null::text,'reserved',d[4]; return;
  elsif qf[2]='attempt' then
    d:=crm_f1.fields(decode(qf[4],'hex'));
    if cardinality(d)<>2 then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    select * into strict reservation_row from crm_ha.reservations where reservation_id=d[1] for update;
    if reservation_row.state<>'reserved' then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    now_at:=clock_timestamp();
    update crm_ha.reservations set state='attempting',updated_at=now_at where reservation_id=d[1];
    select * into strict proposal_row from crm_ha.proposals where proposal_id=reservation_row.proposal_id;
    insert into crm_ha.events values(qf[3],reservation_row.proposal_id,d[1],d[2],'attempted','technical',f[11],now_at,digest_value);
    perform set_config('crm.ha_payload',encode(p,'hex'),true),set_config('crm.ha_mac',encode(s,'hex'),true),
      set_config('crm.ha_input',encode(q,'hex'),true);
    insert into crm_private.external_effect_records(record_id,operation_id,root_id,context_scope,effect_id,
      stage,intent_id,attempt_id,recorded_at)
      values(d[2],d[1],'ha-'||d[1],proposal_row.scope,reservation_row.effect_id,'attempt',reservation_row.intent_id,d[2],now_at);
    perform set_config('crm.ha_payload','',true),set_config('crm.ha_mac','',true),set_config('crm.ha_input','',true);
    insert into crm_ha.command_receipts values(qf[3],digest_value,'attempt',reservation_row.proposal_id,reservation_row.decision_id,d[1],d[2],'attempting',now_at);
    return query select 'applied',reservation_row.proposal_id,reservation_row.decision_id,d[1],d[2],'attempting',reservation_row.material_fingerprint; return;
  elsif qf[2] in ('outcome','reconcile') then
    d:=crm_f1.fields(decode(qf[4],'hex'));
    if cardinality(d)<>4 or d[3] not in ('succeeded','failed','uncertain') or d[4]=''
    then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    select * into strict reservation_row from crm_ha.reservations where reservation_id=d[1] for update;
    perform 1 from crm_ha.events where attempt_id=d[2] and reservation_id=d[1] and event_kind='attempted';
    if not found or (qf[2]='outcome' and reservation_row.state<>'attempting')
      or (qf[2]='reconcile' and reservation_row.state<>'uncertain')
      or (qf[2]='reconcile' and d[3]='uncertain')
    then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    now_at:=clock_timestamp();
    decision_value:=case when d[3]='uncertain' then 'uncertain' when d[3]='succeeded' then 'consumed' else 'reserved' end;
    update crm_ha.reservations set state=decision_value,updated_at=now_at where reservation_id=d[1];
    select * into strict proposal_row from crm_ha.proposals where proposal_id=reservation_row.proposal_id;
    insert into crm_ha.events values(qf[3],reservation_row.proposal_id,d[1],d[2],
      case when d[3]='uncertain' then 'uncertain' when qf[2]='reconcile' and d[3]='succeeded'
        then 'reconciled-succeeded' when qf[2]='reconcile' then 'reconciled-failed'
        when d[3]='succeeded' then 'succeeded' else 'failed-known' end,
      'technical',f[11],now_at,digest_value);
    perform set_config('crm.ha_payload',encode(p,'hex'),true),set_config('crm.ha_mac',encode(s,'hex'),true),
      set_config('crm.ha_input',encode(q,'hex'),true);
    if d[3]='uncertain' then
      insert into crm_private.external_effect_records(record_id,operation_id,root_id,context_scope,effect_id,
        stage,intent_id,attempt_id,recorded_at)
        values('uncertain-'||qf[3],d[1],'ha-'||d[1],proposal_row.scope,reservation_row.effect_id,
          'uncertain',reservation_row.intent_id,d[2],now_at);
    else
      insert into crm_private.external_effect_records(record_id,operation_id,root_id,context_scope,effect_id,
        stage,intent_id,attempt_id,outcome,result_reference,recorded_at)
        values('result-'||qf[3],d[1],'ha-'||d[1],proposal_row.scope,reservation_row.effect_id,
          'result',reservation_row.intent_id,d[2],d[3],d[4],now_at);
    end if;
    perform set_config('crm.ha_payload','',true),set_config('crm.ha_mac','',true),set_config('crm.ha_input','',true);
    insert into crm_ha.command_receipts values(qf[3],digest_value,qf[2],reservation_row.proposal_id,
      reservation_row.decision_id,d[1],d[2],decision_value,now_at);
    return query select 'applied',reservation_row.proposal_id,reservation_row.decision_id,d[1],d[2],decision_value,reservation_row.material_fingerprint; return;
  else raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
exception when sqlstate 'H0002' or unique_violation then raise exception 'H0_M04_CONFLICT' using errcode='H0002';
  when others then raise exception 'H0_M04_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.h0_m04_read_proposal(f2p bytea, f2s bytea, p bytea, s bytea, q bytea, proposal_key text)
 RETURNS TABLE(proposal_id text, material_fingerprint text, material_payload bytea, decision text, decision_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_column
declare f text[]; hf text[]; qf text[]; prop crm_ha.proposals%rowtype;
begin
  f:=crm_f1.verify_envelope(p,s,q,'C01','human_approval','read_proposal');
  qf:=crm_f1.fields(q);
  if cardinality(qf)<>3 or qf[1]<>'CRM-INP1' or qf[2]<>'C01'
    or qf[3]<>proposal_key then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_probe');
  if hf[17] collate "C"<>f[14] collate "C" then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
  select * into strict prop from crm_ha.proposals where proposal_id=proposal_key and scope=f[14];
  return query select prop.proposal_id,prop.material_fingerprint,prop.material_payload,d.decision,d.decision_id
    from crm_ha.decisions d where d.proposal_id=prop.proposal_id
    union all select prop.proposal_id,prop.material_fingerprint,prop.material_payload,null::text,null::text
    where not exists(select 1 from crm_ha.decisions where proposal_id=prop.proposal_id);
exception when others then raise exception 'H0_M04_DENIED' using errcode='42501'; end $function$

CREATE OR REPLACE FUNCTION crm_api.commit_internal_unit(p bytea, s bytea, q bytea, f2p bytea, f2s bytea, hq bytea)
 RETURNS TABLE(replayed boolean, operation_id text, root_id text, resulting_version bigint, after_value text, material_fingerprint text, effect_id text, intent_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_column
declare tf text[]; tq text[]; hqf text[]; receipt crm_ha.command_receipts%rowtype;
begin
  perform crm_f2.admit(f2p,f2s,hq,'C03','apply_probe_batch');
  tf:=crm_f1.verify_envelope(p,s,q,'C03','internal_unit','commit_internal_unit');
  if tf[13] collate "C"<>'h0-011-human-unit' collate "C" then
    raise exception 'H0_M04_UNIT_DENIED' using errcode='42501';
  end if;
  tq:=crm_f1.fields(q); hqf:=crm_f1.fields(hq);
  if cardinality(tq)<>18 or tq[1]<>'CRM-UNIT1' or cardinality(hqf)<3
    or hqf[1]<>'CRM-H0-M04' or hqf[2] not in ('propose','decide','reserve')
    or tq[2] collate "C"<>hqf[3] collate "C"
    or tq[4] collate "C"<>('ha-'||hqf[3]) collate "C"
    or tf[14] collate "C"<>(crm_f2.verify(f2p,f2s,hq,'C03','human_core_probe','apply_probe_batch'))[17] collate "C"
  then raise exception 'H0_M04_UNIT_DENIED' using errcode='42501'; end if;
  select * into receipt from crm_ha.command_receipts where command_id=tq[2];
  if not found or receipt.command_name collate "C"<>hqf[2] collate "C"
    or receipt.command_fingerprint collate "C"<>encode(crm_crypto.digest(hq,'sha256'),'hex') collate "C"
    or receipt.proposal_id is null
  then raise exception 'H0_M04_UNIT_DENIED' using errcode='42501'; end if;
  return query select * from crm_internal.commit_internal_unit_core(p,s,q);
  perform crm_f2.admit(f2p,f2s,hq,'C03','apply_probe_batch');
  perform crm_ha.check_evidence_at_end(hqf[3]);
exception
  when serialization_failure or deadlock_detected then raise;
  when sqlstate 'H0002' then raise;
  when others then raise exception 'H0_M04_UNIT_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.commit_internal_unit(p bytea, s bytea, q bytea)
 RETURNS TABLE(replayed boolean, operation_id text, root_id text, resulting_version bigint, after_value text, material_fingerprint text, effect_id text, intent_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[];
begin
  f:=crm_f1.verify_unit(p,s,q);
  if f[13] collate "C"='h0-011-human-unit' collate "C" then
    raise exception 'H0_009_DENIED' using errcode='42501';
  end if;
  return query select * from crm_internal.commit_internal_unit_core(p,s,q);
exception
  when serialization_failure or deadlock_detected then raise;
  when sqlstate 'H0002' then raise;
  when others then raise exception 'H0_009_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.h0_m04_evidence_replay(p bytea, s bytea, q bytea)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; h text[]; d text[]; r crm_ha.command_receipts%rowtype;
begin
  f:=crm_f1.verify_envelope(p,s,q,'C01','human_approval_evidence','check_replay');
  if f[13] is distinct from 'h0-011-evidence-revalidation' then raise exception 'denied'; end if;
  h:=crm_f1.fields(q);
  if cardinality(h)<>4 or h[1]<>'CRM-H0-M04' or h[2]<>'reserve' then raise exception 'denied'; end if;
  d:=crm_f1.fields(decode(h[4],'hex'));
  if cardinality(d)<>7 then raise exception 'denied'; end if;
  select * into r from crm_ha.command_receipts where command_id=h[3];
  if not found then return false; end if;
  if r.command_fingerprint is distinct from encode(crm_crypto.digest(q,'sha256'),'hex') then
    raise exception 'H0_M04_CONFLICT' using errcode='H0002'; end if;
  if not exists(select 1 from crm_ha.proposals where proposal_id=r.proposal_id and scope=f[14])
    then raise exception 'denied'; end if;
  return true;
exception when sqlstate 'H0002' then raise;
  when others then raise exception 'H0_M04_EVIDENCE_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.h0_m04_revalidate_evidence(p bytea, s bytea, q bytea, f2p bytea, f2s bytea, hq bytea)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; h text[]; d text[]; e text[]; m text[]; hf text[];
  prop crm_ha.proposals%rowtype; old crm_ha.command_receipts%rowtype;
  now_us bigint; approved_us bigint;
begin
  -- Same actor/session/epoch -> command lock order as M04.
  hf:=crm_f2.admit(f2p,f2s,hq,'C03','apply_probe_batch');
  f:=crm_f1.verify_envelope(p,s,q,'C03','human_approval_evidence','revalidate_evidence');
  if f[13] is distinct from 'h0-011-evidence-revalidation' or f[14] is distinct from hf[17]
    then raise exception 'denied'; end if;
  h:=crm_f1.fields(hq); e:=crm_f1.fields(q);
  if cardinality(h)<>4 or h[1]<>'CRM-H0-M04' or h[2]<>'reserve'
    or cardinality(e)<>12 or e[1]<>'CRM-HA-EVIDENCE1'
    or e[2] is distinct from h[3]
    or e[5] is distinct from encode(crm_crypto.digest(hq,'sha256'),'hex') then raise exception 'denied'; end if;
  d:=crm_f1.fields(decode(h[4],'hex'));
  if cardinality(d)<>7 or e[3] is distinct from d[1] or e[4] is distinct from d[3]
    then raise exception 'denied'; end if;
  perform pg_advisory_xact_lock(hashtextextended(h[3],0));
  select * into old from crm_ha.command_receipts where command_id=h[3];
  if found then
    if old.command_fingerprint is distinct from e[5] then
      raise exception 'H0_M04_CONFLICT' using errcode='H0002'; end if;
    return; -- Concurrent winner already committed; no new evidence/effect.
  end if;
  select * into strict prop from crm_ha.proposals where proposal_id=d[1] and scope=f[14];
  m:=crm_f1.fields(prop.material_payload);
  if m[16] is distinct from 'required' or m[17] is distinct from e[6] or m[18] is distinct from e[7]
    or prop.material_fingerprint is distinct from d[4]
    or not exists(select 1 from crm_ha.parts where proposal_id=d[1] and part_id=d[3] and material_fingerprint=d[5])
    or not exists(select 1 from crm_ha.decisions where proposal_id=d[1] and decision_id=d[2]
      and decision='approved' and material_fingerprint=d[4]) then raise exception 'denied'; end if;
  if e[8] !~ '^[0-9]{1,18}$' or e[9] !~ '^[0-9]{1,18}$' or e[10] !~ '^[0-9]{1,18}$'
    then raise exception 'denied'; end if;
  approved_us:=floor(extract(epoch from m[19]::timestamptz)*1000000)::bigint;
  now_us:=floor(extract(epoch from clock_timestamp())*1000000)::bigint;
  if e[8]::bigint>now_us or e[8]::bigint>=e[10]::bigint or now_us>=e[10]::bigint
    or e[10]::bigint<>least(approved_us,e[9]::bigint) then raise exception 'denied'; end if;
  perform crm_f1.verify_envelope(p,s,q,'C03','human_approval_evidence','revalidate_evidence');
  perform crm_f2.verify(f2p,f2s,hq,'C03','human_core_probe','apply_probe_batch');
  insert into crm_ha.evidence_revalidations values(h[3],d[1],d[3],e[5],e[6],e[7],e[8]::bigint,
    e[9]::bigint,approved_us,e[10]::bigint,e[11],e[12],f[14],pg_current_xact_id(),clock_timestamp(),'verified');
exception when serialization_failure or deadlock_detected then raise;
  when sqlstate 'H0002' then raise;
  when others then raise exception 'H0_M04_EVIDENCE_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.start_global_access_revocation(p bytea, s bytea, q bytea)
 RETURNS TABLE(revocation_id uuid, access_generation bigint, admin_scope text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_column
declare f text[]; qf text[]; a crm_private.crm_actors%rowtype;
  ss crm_private.crm_sessions%rowtype; ep crm_private.identification_epochs%rowtype;
  at_time timestamptz; new_generation bigint; requested_revocation uuid;
begin
  f:=crm_f2.verify(p,s,q,'revoke_all','human_actor','revoke_all');
  qf:=crm_f1.fields(q);
  if f[16]<>'session-revocation' or f[21]<>'administrative_action'
    or cardinality(qf)<>4 or qf[1]<>'CRM-F2-INP1' or qf[2]<>'revoke_all'
    or qf[3]<>f[12]
  then raise exception 'H0_M05_DENIED' using errcode='42501'; end if;
  requested_revocation:=qf[4]::uuid;
  select * into strict a from crm_private.crm_actors where actor_id=f[12]::uuid for update;
  select * into strict ss from crm_private.crm_sessions where session_id=f[13]::uuid for update;
  select * into strict ep from crm_private.identification_epochs where epoch_id=f[14]::uuid for update;
  at_time:=clock_timestamp();
  if a.auth_subject<>f[11]::uuid or not a.enabled or a.access_state<>'ready'
    or a.admin_scope<>f[17] or a.access_generation<>f[15]::bigint
    or a.access_generation=9223372036854775807
    or ss.actor_id<>a.actor_id or ss.auth_subject<>a.auth_subject
    or ss.access_generation<>a.access_generation or ss.revoked_at is not null
    or ep.session_id<>ss.session_id or not ep.current_epoch
    or not ep.full_password or not ep.full_mfa or ep.access_state<>'ready'
    or not crm_f2.within_limit(at_time,ep.identified_at,30)
    or not crm_f2.within_limit(at_time,ep.last_human_activity_at,7)
  then raise exception 'H0_M05_DENIED' using errcode='42501'; end if;
  perform crm_f2.verify(p,s,q,'revoke_all','human_actor','revoke_all');
  update crm_private.crm_actors set access_generation=crm_actors.access_generation+1,
    updated_at=at_time where actor_id=a.actor_id returning crm_actors.access_generation into new_generation;
  insert into crm_private.global_access_revocations(
    revocation_id,actor_id,auth_subject,initiating_session_id,
    previous_access_generation,access_generation,admin_scope,core_revoked_at
  ) values (
    requested_revocation,a.actor_id,a.auth_subject,ss.session_id,
    a.access_generation,new_generation,a.admin_scope,at_time
  );
  perform crm_f2.verify(p,s,q,'revoke_all','human_actor','revoke_all');
  return query select requested_revocation,new_generation,a.admin_scope;
exception when others then raise exception 'H0_M05_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.record_global_auth_revocation_outcome(p bytea, s bytea, q bytea)
 RETURNS TABLE(auth_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_column
declare f text[]; qf text[]; current_record crm_private.global_access_revocations%rowtype;
  requested_revocation uuid; requested_attempt uuid; requested_outcome text;
  at_time timestamptz; next_attempt integer;
begin
  f:=crm_f1.verify_envelope(p,s,q,'C03','global_access_revocation','record_auth_outcome');
  qf:=crm_f1.fields(q);
  if cardinality(qf)<>5 or qf[1]<>'CRM-H0-M05-AUTH1' or qf[2]<>'C03'
    or qf[5] not in ('revoked','failed','uncertain')
  then raise exception 'H0_M05_DENIED' using errcode='42501'; end if;
  requested_revocation:=qf[3]::uuid;
  requested_attempt:=qf[4]::uuid;
  requested_outcome:=qf[5];
  select * into strict current_record from crm_private.global_access_revocations
    where revocation_id=requested_revocation for update;
  if current_record.admin_scope collate "C"<>f[14] collate "C"
    or current_record.auth_state='revoked'
  then raise exception 'H0_M05_DENIED' using errcode='42501'; end if;
  at_time:=clock_timestamp();
  next_attempt:=current_record.auth_attempt_count+1;
  insert into crm_private.global_access_revocation_attempts(
    attempt_id,revocation_id,attempt_number,outcome,recorded_at
  ) values (requested_attempt,requested_revocation,next_attempt,requested_outcome,at_time);
  update crm_private.global_access_revocations set
    auth_state=requested_outcome,
    auth_attempt_count=next_attempt,
    last_auth_attempt_at=at_time,
    auth_revoked_at=case when requested_outcome='revoked' then at_time else null end
    where revocation_id=requested_revocation;
  perform crm_f1.verify_envelope(p,s,q,'C03','global_access_revocation','record_auth_outcome');
  return query select requested_outcome;
exception when others then raise exception 'H0_M05_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.begin_access_recovery(p bytea, s bytea, q bytea)
 RETURNS TABLE(recovery_id uuid, access_generation bigint, admin_scope text, fresh boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_column
declare f text[]; v text[]; a crm_private.crm_actors%rowtype;
  prior crm_private.access_recoveries%rowtype; rid uuid; aid uuid; subj uuid;
  new_generation bigint; at_time timestamptz;
begin
  f:=crm_f1.verify_envelope(p,s,q,'C03','access_recovery','begin');
  v:=crm_f1.fields(q);
  if cardinality(v)<>6 or v[1]<>'CRM-H0-M06-REC1' or v[2]<>'begin'
    or v[4] not in ('password','break_glass')
  then raise exception 'H0_M06_DENIED' using errcode='42501'; end if;
  rid:=v[3]::uuid; aid:=v[5]::uuid; subj:=v[6]::uuid;
  select * into strict a from crm_private.crm_actors where actor_id=aid for update;
  if not a.enabled or a.auth_subject<>subj or a.admin_scope collate "C"<>f[14] collate "C"
  then raise exception 'H0_M06_DENIED' using errcode='42501'; end if;
  select * into prior from crm_private.access_recoveries where access_recoveries.recovery_id=rid;
  if found then
    if prior.actor_id<>aid or prior.auth_subject<>subj or prior.recovery_kind<>v[4]
      or prior.completed_at is not null or a.access_state<>'recovery_in_progress'
      or prior.access_generation<>a.access_generation
    then raise exception 'H0_M06_DENIED' using errcode='42501'; end if;
    perform crm_f1.verify_envelope(p,s,q,'C03','access_recovery','begin');
    return query select rid,prior.access_generation,a.admin_scope,false;
    return;
  end if;
  if a.access_state not in ('ready','enrollment_required','reidentification_required')
    or a.access_generation=9223372036854775807
    or exists(select 1 from crm_private.access_recoveries r
      where r.actor_id=aid and r.completed_at is null)
  then raise exception 'H0_M06_DENIED' using errcode='42501'; end if;
  at_time:=clock_timestamp();
  update crm_private.crm_actors set access_generation=crm_actors.access_generation+1,
    access_state='recovery_in_progress',updated_at=at_time
    where actor_id=aid returning crm_actors.access_generation into new_generation;
  insert into crm_private.access_recoveries(recovery_id,actor_id,auth_subject,recovery_kind,
    admin_scope,previous_generation,access_generation,started_at)
    values(rid,aid,subj,v[4],a.admin_scope,a.access_generation,new_generation,at_time);
  perform crm_f1.verify_envelope(p,s,q,'C03','access_recovery','begin');
  return query select rid,new_generation,a.admin_scope,true;
exception when others then raise exception 'H0_M06_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.record_recovery_auth_outcome(p bytea, s bytea, q bytea)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; v text[]; r crm_private.access_recoveries%rowtype;
  a crm_private.crm_actors%rowtype; rid uuid; outcome text;
begin
  f:=crm_f1.verify_envelope(p,s,q,'C03','access_recovery','record_auth_outcome');
  v:=crm_f1.fields(q);
  if cardinality(v)<>4 or v[1]<>'CRM-H0-M06-REC1' or v[2]<>'auth'
    or v[4] not in ('revoked','failed','uncertain')
  then raise exception 'H0_M06_DENIED' using errcode='42501'; end if;
  rid:=v[3]::uuid; outcome:=v[4];
  select * into strict r from crm_private.access_recoveries where recovery_id=rid;
  select * into strict a from crm_private.crm_actors where actor_id=r.actor_id for update;
  select * into strict r from crm_private.access_recoveries where recovery_id=rid for update;
  if r.admin_scope collate "C"<>f[14] collate "C"
    or a.access_generation<>r.access_generation or a.access_state<>'recovery_in_progress'
    or r.completed_at is not null or (r.auth_state<>'pending' and r.auth_state<>outcome)
  then raise exception 'H0_M06_DENIED' using errcode='42501'; end if;
  if r.auth_state='pending' then
    update crm_private.access_recoveries set auth_state=outcome,
      auth_recorded_at=clock_timestamp() where recovery_id=rid;
  end if;
  perform crm_f1.verify_envelope(p,s,q,'C03','access_recovery','record_auth_outcome');
  return outcome;
exception when others then raise exception 'H0_M06_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.complete_access_recovery(p bytea, s bytea, q bytea)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; v text[]; r crm_private.access_recoveries%rowtype;
  a crm_private.crm_actors%rowtype; rid uuid; aid uuid; subj uuid;
begin
  f:=crm_f1.verify_envelope(p,s,q,'C03','access_recovery','complete');
  v:=crm_f1.fields(q);
  if cardinality(v)<>10 or v[1]<>'CRM-H0-M06-REC1' or v[2]<>'complete'
    or v[6]<>'true' or v[7]<>'true'
  then raise exception 'H0_M06_DENIED' using errcode='42501'; end if;
  rid:=v[3]::uuid; aid:=v[4]::uuid; subj:=v[5]::uuid;
  select * into strict a from crm_private.crm_actors where actor_id=aid for update;
  select * into strict r from crm_private.access_recoveries where recovery_id=rid for update;
  if not a.enabled or a.auth_subject<>subj or r.actor_id<>aid or r.auth_subject<>subj
    or a.admin_scope collate "C"<>f[14] collate "C"
    or r.admin_scope collate "C"<>f[14] collate "C"
    or a.access_generation<>r.access_generation or r.auth_state<>'revoked'
    or (r.recovery_kind='break_glass' and (v[8]<>'true' or v[9]<>'true' or v[10]<>'true'))
    or a.access_state not in ('recovery_in_progress','ready')
    or (r.completed_at is null and a.access_state<>'recovery_in_progress')
    or (r.completed_at is not null and a.access_state<>'ready')
  then raise exception 'H0_M06_DENIED' using errcode='42501'; end if;
  if r.completed_at is null then
    update crm_private.access_recoveries set completed_at=clock_timestamp(),
      password_ready=true,totp_verified=true,new_factor_enrolled=(v[8]='true'),
      old_factor_revoked=(v[9]='true'),new_paper_copy_verified=(v[10]='true')
      where recovery_id=rid;
    update crm_private.crm_actors set access_state='ready',updated_at=clock_timestamp()
      where actor_id=aid;
  end if;
  perform crm_f1.verify_envelope(p,s,q,'C03','access_recovery','complete');
  return r.access_generation;
exception when others then raise exception 'H0_M06_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.identity_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, result_version bigint, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; op crm_private.identity_operations%rowtype;
  ent crm_private.identity_entities%rowtype; ctx crm_private.identity_contexts%rowtype;
  old_state jsonb; new_state jsonb; fingerprint text; target uuid; related uuid;
  context_ref uuid; history_context uuid; expected bigint; actor uuid; scope text; new_version bigint;
  candidate boolean; party_kind text; old_primary jsonb;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C03','write_identity');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','identities','write_identity');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'IDENTITY_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>22 or v[1]<>'CRM-H1-ID1' or v[2] not in
    ('create_context','create_entity','update_entity','link_organization_contact','designate')
    or v[3] is null or v[4] is null or v[9] is null or v[9]=''
    or v[11] is null or v[11]='' or v[12] !~ '^(0|[1-9][0-9]{0,18})$'
    or v[13] not in ('true','false')
  then raise exception 'IDENTITY_INPUT_INVALID' using errcode='22023'; end if;
  target:=v[4]::uuid; related:=nullif(v[5],'')::uuid;
  context_ref:=nullif(v[6],'')::uuid; expected:=v[12]::bigint;
  candidate:=v[13]='true'; actor:=hf[12]::uuid; scope:=hf[17];
  fingerprint:=encode(crm_crypto.digest(q,'sha256'),'hex');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v[3],0));
  select * into op from crm_private.identity_operations where operation_id=v[3]::uuid;
  if found then
    if op.actor_id<>actor or op.admin_scope<>scope or op.material_fingerprint<>fingerprint then
      raise exception 'IDENTITY_REPLAY_CONFLICT' using errcode='23505'; end if;
    perform crm_f2.verify(f2p,f2s,q,'C03','human_identities','write_identity');
    result_ref:=op.result_ref; result_version:=op.resulting_version;
    replayed:=true; return next; return;
  end if;
  old_state:=null;
  if v[2]='create_context' then
    if v[7] not in ('opportunity','booking') or related is not null or context_ref is not null
      or expected<>0 or not candidate or v[10]='' then
      raise exception 'IDENTITY_EVIDENCE_REQUIRED' using errcode='22023'; end if;
    insert into crm_private.identity_contexts(context_id,context_kind,admin_scope,source_ref,evidence_ref,verified)
      values(target,v[7],scope,v[9],v[10],true) returning version into new_version;
    history_context:=target;
    select to_jsonb(c) into new_state from crm_private.identity_contexts c where c.context_id=target;
  elsif v[2]='create_entity' then
    if v[7] not in ('contact','organization','group') or related is not null or expected<>0
      or (v[7]='group')<>(context_ref is not null) or (candidate and v[10]='') then
      raise exception 'IDENTITY_INPUT_INVALID' using errcode='22023'; end if;
    if context_ref is not null then
      select * into ctx from crm_private.identity_contexts where context_id=context_ref;
      if not found or ctx.admin_scope<>scope or not ctx.verified then
        raise exception 'IDENTITY_CONTEXT_UNVERIFIED' using errcode='22023'; end if;
    end if;
    insert into crm_private.identity_entities(identity_id,identity_kind,admin_scope,context_id,
      display_name,given_name,family_name,email,phone,group_type,estimated_size,
      confirmed_size,size_source,source_ref,evidence_ref,identity_verified)
      values(target,v[7],scope,context_ref,nullif(v[8],''),nullif(v[18],''),nullif(v[19],''),
        nullif(v[20],''),nullif(v[21],''),nullif(v[14],''),nullif(v[15],'')::integer,
        nullif(v[16],'')::integer,nullif(v[17],''),v[9],nullif(v[10],''),candidate)
      returning version into new_version;
    select to_jsonb(e) into new_state from crm_private.identity_entities e where e.identity_id=target;
  elsif v[2]='update_entity' then
    if related is not null or context_ref is not null then
      raise exception 'IDENTITY_INPUT_INVALID' using errcode='22023'; end if;
    select * into ent from crm_private.identity_entities where identity_id=target for update;
    if not found or ent.admin_scope<>scope or ent.identity_kind<>v[7] then
      raise exception 'IDENTITY_DENIED' using errcode='42501'; end if;
    if ent.version<>expected then raise exception 'IDENTITY_VERSION_CONFLICT' using errcode='40001'; end if;
    if candidate and (v[10]=chr(31) or (v[10]='' and ent.evidence_ref is null)) then
      raise exception 'IDENTITY_EVIDENCE_REQUIRED' using errcode='22023'; end if;
    if not candidate and exists(select 1 from crm_private.identity_designations d
      where d.party_id=target and d.role_kind='primary_contact' and d.ended_at is null) then
      raise exception 'IDENTITY_ACTIVE_DESIGNATION' using errcode='22023'; end if;
    old_state:=to_jsonb(ent);
    history_context:=ent.context_id;
    update crm_private.identity_entities set
      display_name=case when v[8]='' then ent.display_name when v[8]=chr(31) then null else v[8] end,
      given_name=case when v[18]='' then ent.given_name when v[18]=chr(31) then null else v[18] end,
      family_name=case when v[19]='' then ent.family_name when v[19]=chr(31) then null else v[19] end,
      email=case when v[20]='' then ent.email when v[20]=chr(31) then null else v[20] end,
      phone=case when v[21]='' then ent.phone when v[21]=chr(31) then null else v[21] end,
      group_type=case when v[14]='' then ent.group_type when v[14]=chr(31) then null else v[14] end,
      estimated_size=case when v[15]='' then ent.estimated_size when v[15]=chr(31) then null else v[15]::integer end,
      confirmed_size=case when v[16]='' then ent.confirmed_size when v[16]=chr(31) then null else v[16]::integer end,
      size_source=case when v[17]='' then ent.size_source when v[17]=chr(31) then null else v[17] end,
      source_ref=v[9],
      evidence_ref=case when v[10]='' then ent.evidence_ref when v[10]=chr(31) then null else v[10] end,
      identity_verified=candidate,version=version+1,
      updated_at=clock_timestamp() where identity_id=target returning version into new_version;
    select to_jsonb(e) into new_state from crm_private.identity_entities e where e.identity_id=target;
  elsif v[2]='link_organization_contact' then
    if related is null or context_ref is null or v[10]='' or not candidate or expected<>0 then
      raise exception 'IDENTITY_EVIDENCE_REQUIRED' using errcode='22023'; end if;
    if not exists(select 1 from crm_private.identity_entities e where e.identity_id=related
      and e.identity_kind='contact' and e.admin_scope=scope and e.identity_verified)
      or not exists(select 1 from crm_private.identity_entities e where e.identity_id=context_ref
      and e.identity_kind='organization' and e.admin_scope=scope and e.identity_verified)
    then raise exception 'IDENTITY_RELATION_UNVERIFIED' using errcode='22023'; end if;
    insert into crm_private.identity_organization_contacts
      (link_id,organization_id,contact_id,admin_scope,source_ref,evidence_ref)
      values(target,context_ref,related,scope,v[9],v[10]);
    new_version:=0;
    select to_jsonb(l) into new_state from crm_private.identity_organization_contacts l where l.link_id=target;
  else
    if related is null or context_ref is null or v[7] not in
      ('primary_contact','client','payer','participant') or (candidate and v[10]='') then
      raise exception 'IDENTITY_INPUT_INVALID' using errcode='22023'; end if;
    select * into ctx from crm_private.identity_contexts where context_id=context_ref for update;
    if not found or ctx.admin_scope<>scope or not ctx.verified then
      raise exception 'IDENTITY_CONTEXT_UNVERIFIED' using errcode='22023'; end if;
    if ctx.version<>expected then raise exception 'IDENTITY_VERSION_CONFLICT' using errcode='40001'; end if;
    select * into ent from crm_private.identity_entities where identity_id=related;
    if not found or ent.admin_scope<>scope or (candidate and not ent.identity_verified)
      or (ent.identity_kind='group' and ent.context_id<>context_ref)
      or (v[7]='primary_contact' and (not candidate or ent.identity_kind<>'contact')) then
      raise exception 'IDENTITY_RELATION_UNVERIFIED' using errcode='22023'; end if;
    party_kind:=ent.identity_kind;
    if v[7]='primary_contact' then
      select to_jsonb(d) into old_primary from crm_private.identity_designations d
        where d.context_id=context_ref and d.role_kind='primary_contact' and d.ended_at is null;
      update crm_private.identity_designations set ended_at=clock_timestamp()
        where context_id=context_ref and role_kind='primary_contact' and ended_at is null;
    end if;
    insert into crm_private.identity_designations
      (designation_id,context_id,party_id,party_kind,role_kind,admin_scope,source_ref,
       evidence_ref,verified,recorded_by,effective_at)
      values(target,context_ref,related,party_kind,v[7],scope,v[9],nullif(v[10],''),candidate,
        actor,nullif(v[22],'')::timestamptz);
    update crm_private.identity_contexts set version=version+1 where context_id=context_ref
      returning version into new_version;
    old_state:=old_primary;
    select to_jsonb(d) into new_state from crm_private.identity_designations d where d.designation_id=target;
    if old_primary is not null then
      new_state:=jsonb_build_object('current',new_state,'replaced',
        (select to_jsonb(d) from crm_private.identity_designations d
          where d.designation_id=(old_primary->>'designation_id')::uuid));
    end if;
  end if;
  insert into crm_private.identity_operations
    (operation_id,admin_scope,actor_id,material_fingerprint,action_kind,result_ref,resulting_version)
    values(v[3]::uuid,scope,actor,fingerprint,v[2],target,new_version);
  insert into crm_private.identity_history
    (history_id,operation_id,subject_id,context_id,related_id,subject_kind,before_state,after_state,
     source_ref,evidence_ref,reason,actor_id,happened_at)
    values(v[3]::uuid,v[3]::uuid,target,coalesce(history_context,context_ref),related,v[2],old_state,new_state,
      v[9],nullif(v[10],''),v[11],actor,nullif(v[22],'')::timestamptz);
  perform crm_f2.verify(f2p,f2s,q,'C03','human_identities','write_identity');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C03','identities','write_identity');
  result_ref:=target; result_version:=new_version; replayed:=false;
  return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.identity_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; output jsonb; target uuid;
  page_limit integer; page_offset integer; total integer; next_page text;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_identity');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','identities','read_identity');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'IDENTITY_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>5 or v[1]<>'CRM-H1-ID-READ1'
    or v[2] not in ('entity','context','designations','history','organization_contacts')
    or v[4] !~ '^[1-9][0-9]{0,2}$' or v[5] !~ '^(0|[1-9][0-9]{0,8})$'
  then raise exception 'IDENTITY_INPUT_INVALID' using errcode='22023'; end if;
  target:=v[3]::uuid; page_limit:=v[4]::integer; page_offset:=v[5]::integer;
  if page_limit>100 then raise exception 'IDENTITY_INPUT_INVALID' using errcode='22023'; end if;
  if v[2]='entity' then
    select to_jsonb(e) into output from crm_private.identity_entities e
      where e.identity_id=target and e.admin_scope=hf[17];
  elsif v[2]='context' then
    select to_jsonb(c) into output from crm_private.identity_contexts c
      where c.context_id=target and c.admin_scope=hf[17];
  elsif v[2]='designations' then
    select coalesce(jsonb_agg(to_jsonb(d) order by d.recorded_at,d.designation_id),'[]'::jsonb)
      into output from crm_private.identity_designations d
      where d.context_id=target and d.admin_scope=hf[17];
  elsif v[2]='organization_contacts' then
    select coalesce(jsonb_agg(to_jsonb(l) order by l.recorded_at,l.link_id),'[]'::jsonb)
      into output from crm_private.identity_organization_contacts l
      where l.organization_id=target and l.admin_scope=hf[17];
  else
    select coalesce(jsonb_agg(to_jsonb(h) order by h.recorded_at,h.history_id),'[]'::jsonb)
      into output from crm_private.identity_history h
      join crm_private.identity_operations o on o.operation_id=h.operation_id
      where (h.subject_id=target or h.context_id=target or h.related_id=target)
        and o.admin_scope=hf[17];
  end if;
  if v[2] in ('designations','history','organization_contacts') then
    total:=jsonb_array_length(output);
    select coalesce(jsonb_agg(item.value order by item.ordinality),'[]'::jsonb) into output
      from jsonb_array_elements(output) with ordinality as item(value,ordinality)
      where item.ordinality>page_offset and item.ordinality<=page_offset+page_limit;
    next_page:=case when page_offset+page_limit<total then (page_offset+page_limit)::text else null end;
  else
    if page_offset<>0 then raise exception 'IDENTITY_INPUT_INVALID' using errcode='22023'; end if;
    next_page:=null;
  end if;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_identities','read_identity');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C01','identities','read_identity');
  return jsonb_build_object('data',output,'nextPage',next_page);
end $function$

CREATE OR REPLACE FUNCTION crm_api.identity_resolve(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, result_version bigint, human_code text, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; op crm_private.identity_operations%rowtype;
  source_entity crm_private.identity_entities%rowtype;
  destination crm_private.identity_entities%rowtype;
  before_state jsonb; after_state jsonb; fingerprint text;
  subject uuid; related uuid; actor uuid; scope text; expected bigint;
  next_version bigint; assigned timestamptz; annual_year integer; serial bigint;
  issued_code text;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C03','write_identity');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','identities','write_identity');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'IDENTITY_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>10 or v[1]<>'CRM-H1-RESOLVE1'
    or v[2] not in ('merge','archive','restore','assign_code')
    or v[3] is null or v[4] is null or v[7] is null or v[7]=''
    or v[8] is null or v[8]='' or v[9] is null or v[9]=''
    or v[10] !~ '^(0|[1-9][0-9]{0,18})$'
  then raise exception 'IDENTITY_RESOLUTION_INPUT_INVALID' using errcode='22023'; end if;
  subject:=v[4]::uuid; related:=nullif(v[5],'')::uuid;
  expected:=v[10]::bigint; actor:=hf[12]::uuid; scope:=hf[17];
  fingerprint:=encode(crm_crypto.digest(q,'sha256'),'hex');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v[3],0));
  select * into op from crm_private.identity_operations where operation_id=v[3]::uuid;
  if found then
    if op.actor_id<>actor or op.admin_scope<>scope or op.material_fingerprint<>fingerprint then
      raise exception 'IDENTITY_REPLAY_CONFLICT' using errcode='23505'; end if;
    select c.human_code into issued_code from crm_private.identity_codes c
      where c.operation_id=op.operation_id and c.admin_scope=scope;
    perform crm_f2.verify(f2p,f2s,q,'C03','human_identities','write_identity');
    result_ref:=op.result_ref; result_version:=op.resulting_version;
    human_code:=issued_code; replayed:=true; return next; return;
  end if;
  if v[2]='assign_code' then
    if related is not null or expected<>0 or v[6] not in ('OP','PR','RES','INC') then
      raise exception 'IDENTITY_RESOLUTION_INPUT_INVALID' using errcode='22023'; end if;
    if v[6] in ('OP','RES') and not exists(select 1 from crm_private.identity_contexts c
      where c.context_id=subject and c.context_kind=
        case v[6] when 'OP' then 'opportunity' else 'booking' end
        and c.admin_scope=scope and c.verified) then
      raise exception 'IDENTITY_RESOLUTION_TARGET_INVALID' using errcode='22023'; end if;
    -- PR/INC targets are stable IDs supplied by their later lifecycle.
    -- The H1 context is only a local reference, not a Booking or Opportunity.
    if exists(select 1 from crm_private.identity_codes c
      where c.code_kind=v[6] and c.target_id=subject) then
      raise exception 'IDENTITY_CODE_ALREADY_ASSIGNED' using errcode='23505'; end if;
    -- The assignment instant follows serialization, including a wait across midnight.
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('H1-CODE-' || v[6],0));
    assigned:=clock_timestamp();
    annual_year:=crm_private.code_year_at(assigned);
    insert into crm_private.identity_code_counters(code_kind,code_year,last_serial)
      values(v[6],annual_year,1)
      on conflict(code_kind,code_year)
      do update set last_serial=crm_private.identity_code_counters.last_serial+1
      returning last_serial into serial;
    issued_code:=v[6] || '-' || annual_year::text || '-' ||
      lpad(serial::text,greatest(4,length(serial::text)),'0');
    next_version:=0;
    after_state:=jsonb_build_object('code_kind',v[6],'target_id',subject,
      'human_code',issued_code,'assigned_at',assigned,'code_year',annual_year);
  else
    if v[6] not in ('contact','organization') or
      (v[2]='merge' and (related is null or related=subject)) or
      (v[2]<>'merge' and related is not null) then
      raise exception 'IDENTITY_RESOLUTION_INPUT_INVALID' using errcode='22023'; end if;
    -- Lock both identities in stable UUID order, including the target of merge.
    perform 1 from crm_private.identity_entities e
      where e.identity_id in (subject,related) order by e.identity_id for update;
    select * into source_entity from crm_private.identity_entities e where e.identity_id=subject;
    if not found or source_entity.admin_scope<>scope or source_entity.identity_kind<>v[6] then
      raise exception 'IDENTITY_RESOLUTION_TARGET_INVALID' using errcode='22023'; end if;
    if source_entity.version<>expected then
      raise exception 'IDENTITY_VERSION_CONFLICT' using errcode='40001'; end if;
    before_state:=to_jsonb(source_entity);
    if v[2]='merge' then
      select * into destination from crm_private.identity_entities e where e.identity_id=related;
      if not found or destination.admin_scope<>scope
        or destination.identity_kind<>source_entity.identity_kind
        or not source_entity.identity_verified or not destination.identity_verified
        or source_entity.archived_at is not null or destination.archived_at is not null
        or source_entity.merged_into_id is not null or destination.merged_into_id is not null
      then raise exception 'IDENTITY_RESOLUTION_TARGET_INVALID' using errcode='22023'; end if;
      update crm_private.identity_entities set merged_into_id=related,
        archived_at=clock_timestamp(),version=version+1,updated_at=clock_timestamp()
        where identity_id=subject returning version into next_version;
      select jsonb_build_object('source',to_jsonb(e),'destination',to_jsonb(destination))
        into after_state from crm_private.identity_entities e where e.identity_id=subject;
    elsif v[2]='archive' then
      if source_entity.archived_at is not null then
        raise exception 'IDENTITY_RESOLUTION_TARGET_INVALID' using errcode='22023'; end if;
      update crm_private.identity_entities set archived_at=clock_timestamp(),
        version=version+1,updated_at=clock_timestamp()
        where identity_id=subject returning version into next_version;
      select to_jsonb(e) into after_state from crm_private.identity_entities e
        where e.identity_id=subject;
    else
      if source_entity.archived_at is null or source_entity.merged_into_id is not null then
        raise exception 'IDENTITY_RESOLUTION_TARGET_INVALID' using errcode='22023'; end if;
      update crm_private.identity_entities set archived_at=null,
        version=version+1,updated_at=clock_timestamp()
        where identity_id=subject returning version into next_version;
      select to_jsonb(e) into after_state from crm_private.identity_entities e
        where e.identity_id=subject;
    end if;
  end if;
  insert into crm_private.identity_operations
    (operation_id,admin_scope,actor_id,material_fingerprint,action_kind,result_ref,resulting_version)
    values(v[3]::uuid,scope,actor,fingerprint,v[2],subject,next_version);
  if v[2]='assign_code' then
    insert into crm_private.identity_codes
      (code_id,operation_id,code_kind,target_id,admin_scope,code_year,serial_number,
       human_code,assigned_at,source_ref,evidence_ref,actor_id)
      values(v[3]::uuid,v[3]::uuid,v[6],subject,scope,annual_year,serial,
        issued_code,assigned,v[7],v[8],actor);
  end if;
  insert into crm_private.identity_history
    (history_id,operation_id,subject_id,related_id,subject_kind,before_state,after_state,
     source_ref,evidence_ref,reason,actor_id)
    values(v[3]::uuid,v[3]::uuid,subject,related,v[2],before_state,after_state,
      v[7],v[8],v[9],actor);
  perform crm_f2.verify(f2p,f2s,q,'C03','human_identities','write_identity');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C03','identities','write_identity');
  result_ref:=subject; result_version:=next_version;
  human_code:=issued_code; replayed:=false; return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.identity_candidates(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; source_entity crm_private.identity_entities%rowtype;
  result jsonb;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_identity');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','identities','read_identity');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'IDENTITY_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>2 or v[1]<>'CRM-H1-CANDIDATES1' then
    raise exception 'IDENTITY_RESOLUTION_INPUT_INVALID' using errcode='22023'; end if;
  select * into source_entity from crm_private.identity_entities e
    where e.identity_id=v[2]::uuid and e.admin_scope=hf[17]
      and e.identity_kind in ('contact','organization') and e.archived_at is null;
  if not found then raise exception 'IDENTITY_RESOLUTION_TARGET_INVALID' using errcode='22023'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('identity_id',e.identity_id,
      'identity_kind',e.identity_kind,'signals',jsonb_build_array(
        case when source_entity.email is not null and lower(trim(e.email))=lower(trim(source_entity.email))
          then 'email' end,
        case when source_entity.phone is not null and trim(e.phone)=trim(source_entity.phone)
          then 'phone' end,
        case when source_entity.display_name is not null and
          lower(trim(e.display_name))=lower(trim(source_entity.display_name))
          then 'name' end)) order by e.identity_id),'[]'::jsonb) into result
    from crm_private.identity_entities e
    where e.identity_id<>source_entity.identity_id and e.admin_scope=hf[17]
      and e.identity_kind=source_entity.identity_kind and e.archived_at is null
      and ((source_entity.email is not null and e.email is not null
            and lower(trim(e.email))=lower(trim(source_entity.email)))
        or (source_entity.phone is not null and e.phone is not null
            and trim(e.phone)=trim(source_entity.phone))
        or (source_entity.display_name is not null and e.display_name is not null
            and lower(trim(e.display_name))=lower(trim(source_entity.display_name))));
  perform crm_f2.verify(f2p,f2s,q,'C01','human_identities','read_identity');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C01','identities','read_identity');
  return result;
end $function$

CREATE OR REPLACE FUNCTION crm_api.identity_code_lookup(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; result jsonb;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_identity');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','identities','read_identity');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'IDENTITY_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>4 or v[1]<>'CRM-H1-CODE-LOOKUP1'
    or v[2] not in ('code','target') or v[3] not in ('OP','PR','RES','INC')
    or (v[2]='code' and v[4] !~ '^(OP|PR|RES|INC)-[0-9]{4}-[0-9]{4,}$')
    or (v[2]='target' and v[4] !~
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
  then raise exception 'IDENTITY_RESOLUTION_INPUT_INVALID' using errcode='22023'; end if;
  if v[2]='code' then
    select jsonb_build_object('target_id',c.target_id,'code_kind',c.code_kind,
      'human_code',c.human_code,'assigned_at',c.assigned_at,'source_ref',c.source_ref)
      into result from crm_private.identity_codes c
      where c.human_code=v[4] and c.code_kind=v[3] and c.admin_scope=hf[17];
  else
    select jsonb_build_object('target_id',c.target_id,'code_kind',c.code_kind,
      'human_code',c.human_code,'assigned_at',c.assigned_at,'source_ref',c.source_ref)
      into result from crm_private.identity_codes c
      where c.target_id=v[4]::uuid and c.code_kind=v[3] and c.admin_scope=hf[17];
  end if;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_identities','read_identity');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C01','identities','read_identity');
  return result;
end $function$

CREATE OR REPLACE FUNCTION crm_api.catalog_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, result_version bigint, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; op crm_private.catalog_operations%rowtype;
  item crm_private.catalog_items%rowtype; endpoint crm_private.catalog_items%rowtype;
  rev crm_private.catalog_revisions%rowtype; parent_rev crm_private.catalog_revisions%rowtype;
  related_rev crm_private.catalog_revisions%rowtype;
  actor uuid; scope text; target uuid; parent uuid; related uuid; party uuid;
  expected bigint; next_version bigint; fingerprint text; before_state jsonb;
  after_state jsonb; result_id uuid; refs text[]; seen text[]:=array[]::text[];
  ref text; snapshot jsonb:='[]'::jsonb; definition jsonb;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C03','write_catalog');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','catalog','write_catalog');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'CATALOG_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>15 or v[1]<>'CRM-H1-CAT1'
    or v[2] not in ('create_item','publish_version','fix_application')
    or v[3] is null or v[4] is null or v[11] is null
    or v[12] is null or v[12]='' or v[13] is null or v[13]=''
    or v[14] !~ '^(0|[1-9][0-9]{0,18})$'
  then raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
  target:=v[4]::uuid; parent:=nullif(v[6],'')::uuid;
  related:=nullif(v[7],'')::uuid; party:=nullif(v[8],'')::uuid;
  actor:=hf[12]::uuid; scope:=hf[17]; expected:=v[14]::bigint;
  fingerprint:=encode(crm_crypto.digest(q,'sha256'),'hex');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v[3],0));
  select * into op from crm_private.catalog_operations where operation_id=v[3]::uuid;
  if found then
    if op.actor_id<>actor or op.admin_scope<>scope or op.material_fingerprint<>fingerprint then
      raise exception 'CATALOG_REPLAY_CONFLICT' using errcode='23505'; end if;
    perform crm_f2.verify(f2p,f2s,q,'C03','human_catalog','write_catalog');
    result_ref:=op.result_ref; result_version:=op.result_version;
    replayed:=true; return next; return;
  end if;
  if v[2]='create_item' then
    if expected<>0 or v[10]<>'{}' or v[15]<>'' or v[5] not in
      ('service','variant','category','attribute','audience','unit','pricing_form','provider',
       'offering','category_assignment','attribute_assignment','audience_recommendation',
       'unit_assignment','pricing_form_assignment')
    then raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
    if v[5] in ('service','category','attribute','audience','unit','pricing_form','provider') then
      if parent is not null or related is not null then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    elsif v[5]='variant' then
      if parent is null or related is not null then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    else
      if parent is null or related is null then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    if v[5]<>'provider' and (party is not null or v[9]<>'') then
      raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    if v[5]='provider' and (party is null)<>(v[9]='') then
      raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    if party is not null and not exists(select 1 from crm_private.identity_entities e
      where e.identity_id=party and e.identity_kind=v[9] and e.admin_scope=scope
        and e.identity_verified and e.archived_at is null) then
      raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    if parent is not null then
      select * into endpoint from crm_private.catalog_items where item_id=parent for share;
      if not found or endpoint.admin_scope<>scope or not (
        (v[5]='variant' and endpoint.item_kind='service') or
        (v[5]='offering' and endpoint.item_kind='provider') or
        (v[5] in ('category_assignment','attribute_assignment','audience_recommendation',
          'unit_assignment','pricing_form_assignment')
          and endpoint.item_kind in ('service','variant'))) then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    if related is not null then
      select * into endpoint from crm_private.catalog_items where item_id=related for share;
      if not found or endpoint.admin_scope<>scope or not (
        (v[5]='offering' and endpoint.item_kind in ('service','variant')) or
        (v[5]='category_assignment' and endpoint.item_kind='category') or
        (v[5]='attribute_assignment' and endpoint.item_kind='attribute') or
        (v[5]='audience_recommendation' and endpoint.item_kind='audience') or
        (v[5]='unit_assignment' and endpoint.item_kind='unit') or
        (v[5]='pricing_form_assignment' and endpoint.item_kind='pricing_form')) then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    insert into crm_private.catalog_items(item_id,item_kind,admin_scope,parent_id,related_id,
      party_id,party_kind,source_ref,evidence_ref,created_by)
      values(target,v[5],scope,parent,related,party,nullif(v[9],''),v[11],v[12],actor);
    select to_jsonb(i) into after_state from crm_private.catalog_items i where i.item_id=target;
    result_id:=target; next_version:=0;
  elsif v[2]='publish_version' then
    if party is not null or v[9]<>'' or v[15]<>'' then
      raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
    select * into item from crm_private.catalog_items i where i.item_id=target for update;
    if not found or item.admin_scope<>scope or item.item_kind<>v[5] then
      raise exception 'CATALOG_DENIED' using errcode='42501'; end if;
    select coalesce(max(revision_number),0) into next_version
      from crm_private.catalog_revisions where item_id=target;
    if next_version<>expected then
      raise exception 'CATALOG_VERSION_CONFLICT' using errcode='40001'; end if;
    definition:=v[10]::jsonb;
    if not crm_private.catalog_definition_valid(item.item_kind,definition) then
      raise exception 'CATALOG_DEFINITION_INVALID' using errcode='22023'; end if;
    if item.parent_id is null and parent is not null
      or item.parent_id is not null and parent is null
      or item.related_id is null and related is not null
      or item.related_id is not null and related is null then
      raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    if parent is not null then
      select * into parent_rev from crm_private.catalog_revisions r where r.revision_id=parent;
      if not found or parent_rev.item_id<>item.parent_id or parent_rev.admin_scope<>scope then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    if related is not null then
      select * into related_rev from crm_private.catalog_revisions r where r.revision_id=related;
      if not found or related_rev.item_id<>item.related_id or related_rev.admin_scope<>scope then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    select to_jsonb(r) into before_state from crm_private.catalog_revisions r
      where r.item_id=target order by r.revision_number desc limit 1;
    insert into crm_private.catalog_revisions(revision_id,item_id,admin_scope,revision_number,
      definition,parent_revision_id,related_revision_id,source_ref,evidence_ref,reason,actor_id)
      values(v[3]::uuid,target,scope,next_version+1,definition,parent,related,
        v[11],v[12],v[13],actor);
    next_version:=next_version+1; result_id:=v[3]::uuid;
    select jsonb_build_object('revision',to_jsonb(r),'item',to_jsonb(i))
      into after_state from crm_private.catalog_revisions r
      join crm_private.catalog_items i on i.item_id=r.item_id
      where r.revision_id=result_id;
  else
    if v[5]<>'application' or parent is null or related is not null
      or party is not null or v[9]<>'' or v[10]<>'{}' or expected<>0
    then raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
    refs:=string_to_array(v[15],',');
    if refs is null or cardinality(refs)<1 or cardinality(refs)>50 then
      raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
    foreach ref in array refs loop
      if ref !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or ref=any(seen) then
        raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
      seen:=array_append(seen,ref);
      select * into rev from crm_private.catalog_revisions r where r.revision_id=ref::uuid;
      if not found or rev.admin_scope<>scope then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
      select * into item from crm_private.catalog_items i where i.item_id=rev.item_id;
      snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
        'revision',to_jsonb(rev),'item',to_jsonb(item)));
    end loop;
    insert into crm_private.catalog_applications(application_id,subject_ref,admin_scope,
      applied_revisions,source_ref,evidence_ref,reason,actor_id)
      values(target,parent,scope,snapshot,v[11],v[12],v[13],actor);
    select to_jsonb(a) into after_state from crm_private.catalog_applications a
      where a.application_id=target;
    result_id:=target; next_version:=0;
  end if;
  insert into crm_private.catalog_operations(operation_id,admin_scope,actor_id,
    material_fingerprint,action_kind,result_ref,result_version)
    values(v[3]::uuid,scope,actor,fingerprint,v[2],result_id,next_version);
  insert into crm_private.catalog_history(history_id,operation_id,subject_id,admin_scope,
    before_state,after_state,source_ref,evidence_ref,reason,actor_id)
    values(v[3]::uuid,v[3]::uuid,target,scope,before_state,after_state,
      v[11],v[12],v[13],actor);
  perform crm_f2.verify(f2p,f2s,q,'C03','human_catalog','write_catalog');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C03','catalog','write_catalog');
  result_ref:=result_id; result_version:=next_version; replayed:=false; return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.catalog_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; target uuid; output jsonb;
  page_limit integer; page_offset integer; total integer; next_page text;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_catalog');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','catalog','read_catalog');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'CATALOG_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>5 or v[1]<>'CRM-H1-CAT-READ1'
    or v[2] not in ('item','version','application','history')
    or v[4] !~ '^[1-9][0-9]{0,2}$' or v[5] !~ '^(0|[1-9][0-9]{0,8})$'
  then raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
  target:=v[3]::uuid; page_limit:=v[4]::integer; page_offset:=v[5]::integer;
  if page_limit>100 then raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
  if v[2]='item' then
    select jsonb_build_object('item',to_jsonb(i),'latest_revision',to_jsonb(r))
      into output from crm_private.catalog_items i
      left join lateral (select * from crm_private.catalog_revisions r
        where r.item_id=i.item_id order by r.revision_number desc limit 1) r on true
      where i.item_id=target and i.admin_scope=hf[17];
  elsif v[2]='version' then
    select jsonb_build_object('revision',to_jsonb(r),'item',to_jsonb(i))
      into output from crm_private.catalog_revisions r
      join crm_private.catalog_items i on i.item_id=r.item_id
      where r.revision_id=target and r.admin_scope=hf[17];
  elsif v[2]='application' then
    select to_jsonb(a) into output from crm_private.catalog_applications a
      where a.application_id=target and a.admin_scope=hf[17];
  else
    select coalesce(jsonb_agg(to_jsonb(h) order by h.recorded_at,h.history_id),'[]'::jsonb)
      into output from crm_private.catalog_history h
      where h.subject_id=target and h.admin_scope=hf[17];
  end if;
  if v[2]='history' then
    total:=jsonb_array_length(output);
    select coalesce(jsonb_agg(x.value order by x.ordinality),'[]'::jsonb) into output
      from jsonb_array_elements(output) with ordinality x(value,ordinality)
      where x.ordinality>page_offset and x.ordinality<=page_offset+page_limit;
    next_page:=case when page_offset+page_limit<total
      then (page_offset+page_limit)::text else null end;
  else
    if page_offset<>0 then raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
    next_page:=null;
  end if;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_catalog','read_catalog');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C01','catalog','read_catalog');
  return jsonb_build_object('data',output,'nextPage',next_page);
end $function$

CREATE OR REPLACE FUNCTION crm_api.commercial_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, result_version bigint, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; op crm_private.commercial_operations%rowtype;
  item crm_private.commercial_items%rowtype; catalog_item crm_private.catalog_items%rowtype;
  catalog_rev crm_private.catalog_revisions%rowtype; prior crm_private.commercial_revisions%rowtype;
  rev crm_private.commercial_revisions%rowtype; source_item crm_private.commercial_items%rowtype;
  actor uuid; scope text; target uuid; linked_item uuid; linked_rev uuid; origin uuid;
  expected bigint; next_version bigint; fingerprint text; before_state jsonb;
  after_state jsonb; result_id uuid; definition jsonb; snapshot jsonb:='[]'::jsonb;
  component jsonb; unit_id uuid; refs text[]; seen text[]:=array[]::text[];
  ref text; ref_kind text;
  start_value text; end_value text; validity_kind_value text;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C03','write_catalog');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','catalog','write_catalog');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'COMMERCIAL_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>16 or v[1]<>'CRM-H1-COM1'
    or v[2] not in ('create','publish','fix_application','promote_custom')
    or v[3] is null or v[4] is null or v[13] is null or v[13]=''
    or v[14] is null or v[14]='' or v[15] is null or v[15]=''
    or v[16] !~ '^(0|[1-9][0-9]{0,18})$'
  then raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
  target:=v[4]::uuid; linked_item:=nullif(v[6],'')::uuid;
  linked_rev:=nullif(v[7],'')::uuid; origin:=nullif(v[8],'')::uuid;
  actor:=hf[12]::uuid; scope:=hf[17]; expected:=v[16]::bigint;
  fingerprint:=encode(crm_crypto.digest(q,'sha256'),'hex');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v[3],0));
  select * into op from crm_private.commercial_operations where operation_id=v[3]::uuid;
  if found then
    if op.actor_id<>actor or op.admin_scope<>scope or op.fingerprint<>fingerprint then
      raise exception 'COMMERCIAL_REPLAY_CONFLICT' using errcode='23505'; end if;
    perform crm_f2.verify(f2p,f2s,q,'C03','human_catalog','write_catalog');
    result_ref:=op.result_ref; result_version:=op.result_version;
    replayed:=true; return next; return;
  end if;
  if v[2]='create' then
    if expected<>0 or v[9]<>'{}' or v[7]<>'' or v[8]<>'' or v[10]<>'' or v[11]<>'' or v[12]<>''
      or v[5] not in ('tariff','pack','custom_pack','promotion','capacity_rule','eligibility_rule','document_requirement')
    then raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
    if (v[5] in ('pack','custom_pack','promotion'))<>(linked_item is null) then
      raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
    if linked_item is not null then
      select * into catalog_item from crm_private.catalog_items where item_id=linked_item for share;
      if not found or catalog_item.admin_scope<>scope or catalog_item.item_kind not in
        ('service','variant','offering','provider')
        or (v[5] in ('tariff','capacity_rule','eligibility_rule') and catalog_item.item_kind='provider')
      then raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    insert into crm_private.commercial_items(item_id,item_kind,admin_scope,catalog_item_id,
      source_ref,evidence_ref,created_by)
      values(target,v[5],scope,linked_item,v[13],v[14],actor);
    select to_jsonb(i) into after_state from crm_private.commercial_items i where i.item_id=target;
    result_id:=target; next_version:=0;
  elsif v[2]='publish' then
    if v[8]<>'' or v[5]='application' or v[12]<>'' then
      raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
    select * into item from crm_private.commercial_items i where i.item_id=target for update;
    if not found or item.admin_scope<>scope or item.item_kind<>v[5]
      or item.catalog_item_id is distinct from linked_item then
      raise exception 'COMMERCIAL_DENIED' using errcode='42501'; end if;
    select coalesce(max(revision_number),0) into next_version
      from crm_private.commercial_revisions where item_id=target;
    if next_version<>expected then
      raise exception 'COMMERCIAL_VERSION_CONFLICT' using errcode='40001'; end if;
    definition:=v[9]::jsonb;
    if not crm_private.commercial_definition_valid(item.item_kind,definition) then
      raise exception 'COMMERCIAL_DEFINITION_INVALID' using errcode='22023'; end if;
    start_value:=nullif(v[10],''); end_value:=nullif(v[11],'');
    validity_kind_value:=case when start_value is null and end_value is null then 'unknown'
      when coalesce(start_value,end_value) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then 'civil_date'
      else 'instant' end;
    if validity_kind_value='civil_date' then
      if (start_value is not null and start_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')
        or (end_value is not null and end_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')
        or (start_value is not null and end_value is not null
          and start_value::date>end_value::date) then
        raise exception 'COMMERCIAL_VALIDITY_INVALID' using errcode='22023'; end if;
    elsif validity_kind_value='instant' then
      if (start_value is not null and start_value !~
          '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$')
        or (end_value is not null and end_value !~
          '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$')
        or (start_value is not null and end_value is not null
          and start_value::timestamptz>end_value::timestamptz) then
        raise exception 'COMMERCIAL_VALIDITY_INVALID' using errcode='22023'; end if;
    end if;
    if linked_item is null and linked_rev is not null
      or linked_item is not null and linked_rev is null then
      raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
    if linked_rev is not null then
      select * into catalog_rev from crm_private.catalog_revisions where revision_id=linked_rev;
      if not found or catalog_rev.item_id<>linked_item or catalog_rev.admin_scope<>scope then
        raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
      select * into catalog_item from crm_private.catalog_items where item_id=linked_item;
      snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
        'role','scope','revision',to_jsonb(catalog_rev),'item',to_jsonb(catalog_item)));
    end if;
    if item.item_kind='tariff' then
      for ref,ref_kind in select value,case ordinality when 1 then 'unit'
        else 'pricing_form' end from jsonb_array_elements_text(jsonb_build_array(
        definition->>'unit_revision_id',definition->>'pricing_form_revision_id'))
        with ordinality loop
        if ref is null then continue; end if;
        select * into catalog_rev from crm_private.catalog_revisions where revision_id=ref::uuid;
        if not found or catalog_rev.admin_scope<>scope then
          raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
        select * into catalog_item from crm_private.catalog_items where item_id=catalog_rev.item_id;
        if catalog_item.item_kind<>ref_kind then
          raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
        snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
          'role',catalog_item.item_kind,'revision',to_jsonb(catalog_rev),'item',to_jsonb(catalog_item)));
      end loop;
      if definition ? 'tiers' then
        for component in select value from jsonb_array_elements(definition->'tiers') loop
          for ref,ref_kind in select value,case ordinality when 1 then 'unit'
            else 'variant' end from jsonb_array_elements_text(jsonb_build_array(
            component->>'unit_revision_id',component->>'variant_revision_id'))
            with ordinality loop
            if ref is null then continue; end if;
            select * into catalog_rev from crm_private.catalog_revisions where revision_id=ref::uuid;
            if not found or catalog_rev.admin_scope<>scope then
              raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
            select * into catalog_item from crm_private.catalog_items where item_id=catalog_rev.item_id;
            if catalog_item.item_kind<>ref_kind then
              raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
            snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
              'role','tier_'||catalog_item.item_kind,'revision',to_jsonb(catalog_rev),
              'item',to_jsonb(catalog_item)));
          end loop;
        end loop;
      end if;
    elsif item.item_kind in ('pack','custom_pack') then
      for component in select value from jsonb_array_elements(definition->'components') loop
        select * into catalog_rev from crm_private.catalog_revisions
          where revision_id=(component->>'service_revision_id')::uuid;
        if not found or catalog_rev.admin_scope<>scope then
          raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
        select * into catalog_item from crm_private.catalog_items where item_id=catalog_rev.item_id;
        if catalog_item.item_kind not in ('service','variant') then
          raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
        snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
          'role','component','revision',to_jsonb(catalog_rev),'item',to_jsonb(catalog_item),
          'quantity',component->>'quantity','included',component->'included'));
        if component ? 'unit_revision_id' then
          unit_id:=(component->>'unit_revision_id')::uuid;
          select * into catalog_rev from crm_private.catalog_revisions where revision_id=unit_id;
          if not found or catalog_rev.admin_scope<>scope then
            raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
          select * into catalog_item from crm_private.catalog_items where item_id=catalog_rev.item_id;
          if catalog_item.item_kind<>'unit' then
            raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
          snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
            'role','component_unit','revision',to_jsonb(catalog_rev),'item',to_jsonb(catalog_item)));
        end if;
      end loop;
    elsif item.item_kind='capacity_rule' and definition ? 'unit_revision_id' then
      unit_id:=(definition->>'unit_revision_id')::uuid;
      select * into catalog_rev from crm_private.catalog_revisions
        where revision_id=unit_id;
      if not found or catalog_rev.admin_scope<>scope then
        raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
      select * into catalog_item from crm_private.catalog_items where item_id=catalog_rev.item_id;
      if catalog_item.item_kind<>'unit' then
        raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
      snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
        'role','capacity_unit','revision',to_jsonb(catalog_rev),'item',to_jsonb(catalog_item)));
    end if;
    select to_jsonb(r) into before_state from crm_private.commercial_revisions r
      where r.item_id=target order by r.revision_number desc limit 1;
    insert into crm_private.commercial_revisions(revision_id,item_id,admin_scope,revision_number,
      definition,catalog_snapshot,validity_kind,valid_from,valid_until,source_ref,evidence_ref,reason,actor_id)
      values(v[3]::uuid,target,scope,next_version+1,definition,snapshot,validity_kind_value,start_value,end_value,
        v[13],v[14],v[15],actor);
    next_version:=next_version+1; result_id:=v[3]::uuid;
    select jsonb_build_object('revision',to_jsonb(r),'item',to_jsonb(i)) into after_state
      from crm_private.commercial_revisions r join crm_private.commercial_items i using(item_id)
      where r.revision_id=result_id;
  elsif v[2]='promote_custom' then
    if v[5]<>'pack' or linked_item is not null or linked_rev is not null or origin is null
      or v[9]<>'{}' or v[10]<>'' or v[11]<>'' or v[12]<>'' or expected<>0 then
      raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
    select * into prior from crm_private.commercial_revisions where revision_id=origin;
    if not found or prior.admin_scope<>scope then
      raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
    select * into source_item from crm_private.commercial_items where item_id=prior.item_id;
    if source_item.item_kind<>'custom_pack' then
      raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
    insert into crm_private.commercial_items(item_id,item_kind,admin_scope,origin_custom_revision_id,
      source_ref,evidence_ref,created_by)
      values(target,'pack',scope,origin,v[13],v[14],actor);
    insert into crm_private.commercial_revisions(revision_id,item_id,admin_scope,revision_number,
      definition,catalog_snapshot,validity_kind,valid_from,valid_until,source_ref,evidence_ref,reason,actor_id)
      values(v[3]::uuid,target,scope,1,prior.definition,prior.catalog_snapshot,
        prior.validity_kind,prior.valid_from,prior.valid_until,v[13],v[14],v[15],actor);
    result_id:=target; next_version:=1;
    select jsonb_build_object('item',to_jsonb(i),'revision',to_jsonb(r),
      'origin_revision',to_jsonb(prior)) into after_state
      from crm_private.commercial_items i join crm_private.commercial_revisions r using(item_id)
      where i.item_id=target and r.revision_number=1;
  else
    if v[5]<>'application' or linked_item is not null or linked_rev is not null
      or origin is null or v[9]<>'{}' or v[10]<>'' or v[11]<>'' or expected<>0 then
      raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
    refs:=string_to_array(v[12],',');
    if refs is null or cardinality(refs)<1 or cardinality(refs)>50 then
      raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
    foreach ref in array refs loop
      if ref !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or ref=any(seen) then
        raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
      seen:=array_append(seen,ref);
      select * into rev from crm_private.commercial_revisions where revision_id=ref::uuid;
      if not found or rev.admin_scope<>scope then
        raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
      select * into item from crm_private.commercial_items where item_id=rev.item_id;
      snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
        'revision',to_jsonb(rev),'item',to_jsonb(item)));
    end loop;
    insert into crm_private.commercial_applications(application_id,subject_ref,admin_scope,
      applied_revisions,source_ref,evidence_ref,reason,actor_id)
      values(target,origin,scope,snapshot,v[13],v[14],v[15],actor);
    select to_jsonb(a) into after_state from crm_private.commercial_applications a
      where a.application_id=target;
    result_id:=target; next_version:=0;
  end if;
  insert into crm_private.commercial_operations(operation_id,admin_scope,actor_id,
    fingerprint,result_ref,result_version)
    values(v[3]::uuid,scope,actor,fingerprint,result_id,next_version);
  insert into crm_private.commercial_history(history_id,operation_id,subject_id,admin_scope,
    before_state,after_state,source_ref,evidence_ref,reason,actor_id)
    values(v[3]::uuid,v[3]::uuid,target,scope,before_state,after_state,v[13],v[14],v[15],actor);
  perform crm_f2.verify(f2p,f2s,q,'C03','human_catalog','write_catalog');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C03','catalog','write_catalog');
  result_ref:=result_id; result_version:=next_version; replayed:=false; return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.commercial_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; target uuid; output jsonb;
  page_limit integer; page_offset integer; total integer; next_page text;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_catalog');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','catalog','read_catalog');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'COMMERCIAL_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>5 or v[1]<>'CRM-H1-COM-READ1'
    or v[2] not in ('item','version','application','history')
    or v[4] !~ '^[1-9][0-9]{0,2}$' or v[5] !~ '^(0|[1-9][0-9]{0,8})$'
  then raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
  target:=v[3]::uuid; page_limit:=v[4]::integer; page_offset:=v[5]::integer;
  if page_limit>100 then raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
  if v[2]='item' then
    select jsonb_build_object('item',to_jsonb(i),'latest_revision',to_jsonb(r))
      into output from crm_private.commercial_items i
      left join lateral (select * from crm_private.commercial_revisions r
        where r.item_id=i.item_id order by r.revision_number desc limit 1) r on true
      where i.item_id=target and i.admin_scope=hf[17];
  elsif v[2]='version' then
    select jsonb_build_object('revision',to_jsonb(r),'item',to_jsonb(i))
      into output from crm_private.commercial_revisions r
      join crm_private.commercial_items i using(item_id)
      where r.revision_id=target and r.admin_scope=hf[17];
  elsif v[2]='application' then
    select to_jsonb(a) into output from crm_private.commercial_applications a
      where a.application_id=target and a.admin_scope=hf[17];
  else
    select coalesce(jsonb_agg(to_jsonb(h) order by h.recorded_at,h.history_id),'[]'::jsonb)
      into output from crm_private.commercial_history h
      where h.subject_id=target and h.admin_scope=hf[17];
  end if;
  if v[2]='history' then
    total:=jsonb_array_length(output);
    select coalesce(jsonb_agg(x.value order by x.ordinality),'[]'::jsonb) into output
      from jsonb_array_elements(output) with ordinality x(value,ordinality)
      where x.ordinality>page_offset and x.ordinality<=page_offset+page_limit;
    next_page:=case when page_offset+page_limit<total
      then (page_offset+page_limit)::text else null end;
  else
    if page_offset<>0 then raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
    next_page:=null;
  end if;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_catalog','read_catalog');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C01','catalog','read_catalog');
  return jsonb_build_object('data',output,'nextPage',next_page);
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];op crm_private.b07_operations%rowtype;
  parent crm_private.b07_records%rowtype; related crm_private.b07_records%rowtype;
  actor uuid;scope text;target uuid;original uuid;corrects uuid;target_context uuid;
  payload_data jsonb;prior_state jsonb;after_state jsonb;fingerprint text;occurred timestamptz;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'B07_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>15 or v[1]<>'CRM-H1-B07-1' or v[2] not in ('create','link')
    or v[7]='' or v[8]='' or v[14]='' or v[15]='' or v[12] not in
      ('contact','organization','opportunity','booking','booking_service','provider','proposal','other')
  then raise exception 'B07_INPUT_INVALID' using errcode='22023'; end if;
  target:=v[4]::uuid;target_context:=v[13]::uuid;
  original:=nullif(v[10],'')::uuid;corrects:=nullif(v[11],'')::uuid;
  occurred:=nullif(v[9],'')::timestamptz;payload_data:=v[6]::jsonb;
  actor:=hf[12]::uuid;scope:=hf[17];
  fingerprint:=encode(crm_crypto.digest(q,'sha256'),'hex');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v[3],0));
  select * into op from crm_private.b07_operations where operation_id=v[3]::uuid;
  if found then
    if op.admin_scope<>scope or op.actor_id<>actor or op.fingerprint<>fingerprint then
      raise exception 'B07_REPLAY_CONFLICT' using errcode='23505'; end if;
    perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');
    result_ref:=op.result_ref;replayed:=true;return next;return;
  end if;
  if v[2]='create' then
    if v[5] not in ('document','evidence','communication','communication_fact',
       'integration_source','external_reference','external_event')
      or not coalesce(crm_private.b07_material_valid(v[5],payload_data,original,occurred),false) then
      raise exception 'B07_INPUT_INVALID' using errcode='22023'; end if;
    if original is not null then
      select * into parent from crm_private.b07_records where record_id=original;
      if not found or parent.admin_scope<>scope or not (
        (v[5]='document' and parent.record_kind='document') or
        (v[5]='communication_fact' and parent.record_kind='communication')) then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if v[5]='document' and parent.material->>'relation'<>'original' then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if not exists(select 1 from crm_private.b07_links l where l.record_id=original
        and l.admin_scope=scope and l.context_kind=v[12] and l.context_id=target_context) then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if v[5]='communication_fact' and (
        (payload_data->>'fact_kind'='sent' and parent.material->>'direction'<>'outgoing') or
        (payload_data->>'fact_kind'='received' and parent.material->>'direction'<>'outgoing') or
        (payload_data->>'fact_kind'='sent' and parent.material->>'recipient_ref' is distinct from payload_data->>'party_ref') or
        (payload_data->>'fact_kind'='sent' and v[12]='proposal' and
          (nullif(parent.material->>'proposal_version_ref','') is null or
           nullif(parent.material->>'authorization_ref','') is null))
      ) then raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    if corrects is not null then
      select * into related from crm_private.b07_records where record_id=corrects;
      if not found or related.admin_scope<>scope or related.record_kind<>v[5] then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if not exists(select 1 from crm_private.b07_links l where l.record_id=corrects
        and l.admin_scope=scope and l.context_kind=v[12] and l.context_id=target_context) then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      prior_state:=to_jsonb(related);
    end if;
    if v[5]='evidence' and payload_data ? 'document_id' then
      select * into related from crm_private.b07_records
        where record_id=(payload_data->>'document_id')::uuid;
      if not found or related.admin_scope<>scope or related.record_kind<>'document' then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if not exists(select 1 from crm_private.b07_links l where l.record_id=related.record_id
        and l.admin_scope=scope and l.context_kind=v[12] and l.context_id=target_context) then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    if v[5]='communication_fact' then
      select * into related from crm_private.b07_records
        where record_id=(payload_data->>'evidence_id')::uuid;
      if not found or related.admin_scope<>scope or related.record_kind<>'evidence' then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if not exists(select 1 from crm_private.b07_links l where l.record_id=related.record_id
        and l.admin_scope=scope and l.context_kind=v[12] and l.context_id=target_context) then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if exists(select 1 from crm_private.b07_records r where r.record_kind='communication_fact'
        and r.original_id=original and r.material->>'evidence_id'=payload_data->>'evidence_id') then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if payload_data->>'fact_kind'='sent' and payload_data->>'coverage' is distinct from parent.material->>'coverage' then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    if v[5] in ('external_reference','external_event') then
      select * into related from crm_private.b07_records
        where record_id=(payload_data->>'source_id')::uuid;
      if not found or related.admin_scope<>scope or related.record_kind<>'integration_source' then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if not exists(select 1 from crm_private.b07_links l where l.record_id=related.record_id
        and l.admin_scope=scope and l.context_kind=v[12] and l.context_id=target_context) then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    insert into crm_private.b07_records(record_id,record_kind,admin_scope,material,source_ref,
      purpose,occurred_at,recorded_by,original_id,corrects_id)
      values(target,v[5],scope,payload_data,v[7],v[8],occurred,actor,original,corrects);
    insert into crm_private.b07_links(link_id,record_id,admin_scope,context_kind,context_id,
      coverage,source_ref,linked_by) values(v[3]::uuid,target,scope,v[12],target_context,v[15],v[7],actor);
    select jsonb_build_object('record',to_jsonb(r),'link',to_jsonb(l)) into after_state
      from crm_private.b07_records r join crm_private.b07_links l on l.record_id=r.record_id
      where r.record_id=target and l.link_id=v[3]::uuid;
  else
    if v[5]<>'' or payload_data<>'{}'::jsonb or v[9]<>'' or corrects is not null
      or original is null then raise exception 'B07_INPUT_INVALID' using errcode='22023'; end if;
    select * into parent from crm_private.b07_records where record_id=original;
    if not found or parent.admin_scope<>scope then
      raise exception 'B07_DENIED' using errcode='42501'; end if;
    insert into crm_private.b07_links(link_id,record_id,admin_scope,context_kind,context_id,
      coverage,source_ref,linked_by) values(target,original,scope,v[12],target_context,v[15],v[7],actor);
    select to_jsonb(l) into after_state from crm_private.b07_links l where link_id=target;
  end if;
  insert into crm_private.b07_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref)
    values(v[3]::uuid,scope,actor,fingerprint,target);
  insert into crm_private.b07_history(history_id,operation_id,subject_id,admin_scope,action_kind,
    before_state,after_state,reason,source_ref,occurred_at,actor_id)
    values(v[3]::uuid,v[3]::uuid,target,scope,v[2],prior_state,after_state,v[14],v[7],occurred,actor);
  perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
  result_ref:=target;replayed:=false;return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];wanted_record uuid;wanted_context uuid;result jsonb;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'B07_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>4 or v[1]<>'CRM-H1-B07-READ1'
    or v[3] not in ('contact','organization','opportunity','booking','booking_service','provider','proposal','other')
  then raise exception 'B07_INPUT_INVALID' using errcode='22023'; end if;
  wanted_record:=v[2]::uuid;wanted_context:=v[4]::uuid;
  select jsonb_build_object('record',to_jsonb(r),
    'links',(select jsonb_agg(to_jsonb(l2) order by l2.linked_at,l2.link_id)
      from crm_private.b07_links l2 where l2.record_id=r.record_id
        and l2.admin_scope=hf[17] and l2.context_kind=v[3] and l2.context_id=wanted_context))
    into result from crm_private.b07_records r
    join crm_private.b07_links l on l.record_id=r.record_id
    where r.record_id=wanted_record and r.admin_scope=hf[17]
      and l.admin_scope=hf[17] and l.context_kind=v[3] and l.context_id=wanted_context;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
  return result;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_object_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];m jsonb;actor uuid;scope text;opid uuid;target uuid;
 fingerprint text;op crm_private.b07_operations%rowtype;
 old crm_private.b07_object_versions%rowtype;previous crm_private.b07_object_versions%rowtype;
 before_data jsonb;after_data jsonb;next_state text;root uuid;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');
 tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OBJECT_DENIED' using errcode='42501'; end if;
 v:=crm_f1.fields(q);
 if cardinality(v)<>2 or v[1]<>'CRM-H1-OBJECT-1' then raise exception 'OBJECT_INPUT_INVALID'; end if;
 m:=v[2]::jsonb;actor:=hf[12]::uuid;scope:=hf[17];opid:=(m->>'operationId')::uuid;
 target:=(m->>'versionId')::uuid;
 -- expectedRevision is sampled by the server on each retry, not client material.
 fingerprint:=encode(crm_crypto.digest(convert_to((m-'expectedRevision')::text,'UTF8'),'sha256'),'hex');
 if nullif(m->>'reason','') is null or nullif(m->>'sourceRef','') is null or nullif(m->>'purpose','') is null then
  raise exception 'OBJECT_INPUT_INVALID'; end if;
 perform pg_advisory_xact_lock(hashtextextended(opid::text,0));
 select * into op from crm_private.b07_operations where operation_id=opid;
 if found then
  if op.admin_scope<>scope or op.actor_id<>actor or op.fingerprint<>fingerprint then raise exception 'OBJECT_REPLAY_CONFLICT'; end if;
  result_ref:=op.result_ref;replayed:=true;
 else
  if m->>'action'='orphan' then
   perform pg_advisory_xact_lock(hashtextextended(m->>'privateRef',1));
   if exists(select 1 from crm_private.b07_object_versions where private_ref=m->>'privateRef') then raise exception 'OBJECT_NOT_ORPHAN'; end if;
   insert into crm_private.b07_object_orphans(private_ref,admin_scope,state,source_ref,recorded_by)
    values(m->>'privateRef',scope,'needs_review',m->>'sourceRef',actor) on conflict do nothing;
   select to_jsonb(o) into after_data from crm_private.b07_object_orphans o where private_ref=m->>'privateRef' and admin_scope=scope;
   if after_data is null then raise exception 'OBJECT_DENIED'; end if;
  elsif m->>'action'='prepare' then
   root:=(m->>'rootId')::uuid;perform pg_advisory_xact_lock(hashtextextended(root::text,2));
   if not exists(select 1 from crm_private.b07_records r join crm_private.b07_links l on l.record_id=r.record_id
    where r.record_id=(m->>'documentId')::uuid and r.record_kind='document' and r.admin_scope=scope
     and l.admin_scope=scope and l.context_kind=m->>'contextKind' and l.context_id=(m->>'contextId')::uuid) then raise exception 'OBJECT_DENIED'; end if;
   if (m->>'expectedVersion')::integer=0 then
    if exists(select 1 from crm_private.b07_object_versions where root_id=root) then raise exception 'OBJECT_VERSION_CONFLICT'; end if;
   else
    select * into previous from crm_private.b07_object_versions where root_id=root and version_number=(m->>'expectedVersion')::integer;
    if not found or previous.admin_scope<>scope or previous.document_id<>(m->>'documentId')::uuid or
     previous.purpose<>m->>'purpose' or exists(select 1 from crm_private.b07_object_versions where root_id=root and version_number>previous.version_number) then raise exception 'OBJECT_VERSION_CONFLICT'; end if;
    before_data:=to_jsonb(previous);
   end if;
   insert into crm_private.b07_object_versions(version_id,root_id,version_number,predecessor_id,document_id,
    admin_scope,purpose,source_ref,private_ref,expected_digest,expected_size,expected_media,state,recorded_by)
   values(target,root,(m->>'expectedVersion')::integer+1,previous.version_id,(m->>'documentId')::uuid,
    scope,m->>'purpose',m->>'sourceRef',root::text||'/'||target::text,m->>'digest',(m->>'size')::bigint,m->>'media','prepared',actor);
   select to_jsonb(o) into after_data from crm_private.b07_object_versions o where version_id=target;
  else
   select * into old from crm_private.b07_object_versions where version_id=target for update;
   if not found or old.admin_scope<>scope or old.purpose<>m->>'purpose' or not exists(
    select 1 from crm_private.b07_links l where l.record_id=old.document_id and l.admin_scope=scope
     and l.context_kind=m->>'contextKind' and l.context_id=(m->>'contextId')::uuid) then raise exception 'OBJECT_DENIED'; end if;
   if old.revision<>(m->>'expectedRevision')::bigint then raise exception 'OBJECT_VERSION_CONFLICT'; end if;
   before_data:=to_jsonb(old);
   if m->>'action'='uploaded' then
    if old.state<>'prepared' and old.state<>'missing' then raise exception 'OBJECT_STATE_INVALID'; end if;
    update crm_private.b07_object_versions set state='present_unverified',revision=revision+1 where version_id=target;
   elsif m->>'action'='observe' then
    next_state:=case when m->>'presence'='missing' then 'missing'
     when m->>'presence'='present' and m->>'digest'=old.expected_digest and (m->>'size')::bigint=old.expected_size
      and m->>'media'=old.expected_media then case when old.linked_at is null then 'verified_unlinked' else 'stored' end
     when m->>'presence'='present' then 'inconsistent' else null end;
    if next_state is null then raise exception 'OBJECT_INPUT_INVALID'; end if;
    update crm_private.b07_object_versions set state=next_state,observed_digest=m->>'digest',
     observed_size=(m->>'size')::bigint,observed_media=m->>'media',observed_at=clock_timestamp(),revision=revision+1 where version_id=target;
   elsif m->>'action'='link' then
    if old.state not in ('verified_unlinked','stored') then raise exception 'OBJECT_STATE_INVALID'; end if;
    if m ? 'evidenceId' then
     if not exists(select 1 from crm_private.b07_records r join crm_private.b07_links l on l.record_id=r.record_id
      where r.record_id=(m->>'evidenceId')::uuid and r.record_kind='evidence' and r.admin_scope=scope
       and r.material->>'document_id'=old.document_id::text and l.admin_scope=scope
       and l.context_kind=m->>'contextKind' and l.context_id=(m->>'contextId')::uuid) then raise exception 'OBJECT_DENIED'; end if;
     if exists(select 1 from crm_private.b07_evidence_object_bindings b where b.evidence_id=(m->>'evidenceId')::uuid
      and b.version_id<>target) then raise exception 'OBJECT_HISTORICAL_BINDING_CONFLICT'; end if;
     insert into crm_private.b07_evidence_object_bindings(evidence_id,version_id,admin_scope,linked_by)
      values((m->>'evidenceId')::uuid,target,scope,actor) on conflict do nothing;
    end if;
    update crm_private.b07_object_versions set state='stored',linked_at=coalesce(linked_at,clock_timestamp()),revision=revision+1 where version_id=target;
   else raise exception 'OBJECT_INPUT_INVALID'; end if;
   select to_jsonb(o) into after_data from crm_private.b07_object_versions o where version_id=target;
  end if;
  if m->>'action'='link' and m ? 'evidenceId' then
   after_data:=after_data||jsonb_build_object('evidence_binding',
    (select to_jsonb(b) from crm_private.b07_evidence_object_bindings b where b.evidence_id=(m->>'evidenceId')::uuid));
  end if;
  insert into crm_private.b07_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(opid,scope,actor,fingerprint,target);
  insert into crm_private.b07_history(history_id,operation_id,subject_id,admin_scope,action_kind,before_state,after_state,reason,source_ref,actor_id)
   values(opid,opid,target,scope,'object_'||(m->>'action'),before_data,after_data,m->>'reason',m->>'sourceRef',actor);
  result_ref:=target;replayed:=false;
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');
 perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_object_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];m jsonb;result jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');
 tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OBJECT_DENIED'; end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H1-OBJECT-READ1' then raise exception 'OBJECT_INPUT_INVALID'; end if;
 m:=v[2]::jsonb;
 select to_jsonb(o)||jsonb_build_object('evidence_bindings',
  (select jsonb_agg(to_jsonb(b)) from crm_private.b07_evidence_object_bindings b where b.version_id=o.version_id
   and b.admin_scope=hf[17] and exists(select 1 from crm_private.b07_links el where el.record_id=b.evidence_id
    and el.admin_scope=hf[17] and el.context_kind=m->>'contextKind' and el.context_id=(m->>'contextId')::uuid)))
 into result from crm_private.b07_object_versions o
  where o.version_id=(m->>'versionId')::uuid and o.admin_scope=hf[17] and o.purpose=m->>'purpose'
   and exists(select 1 from crm_private.b07_links l where l.record_id=o.document_id and l.admin_scope=hf[17]
    and l.context_kind=m->>'contextKind' and l.context_id=(m->>'contextId')::uuid);
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');
 perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return result;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_task_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];m jsonb;i jsonb;a jsonb;actor uuid;scope text;opid uuid;target uuid;
 fingerprint text;causekey text;before_data jsonb;after_data jsonb;action text;
 op crm_private.b07_operations%rowtype;old crm_private.b07_pending_tasks%rowtype;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');
 tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'TASK_DENIED' using errcode='42501'; end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H1-TASK-1' then raise exception 'TASK_INPUT_INVALID'; end if;
 m:=v[2]::jsonb;i:=m->'identity';a:=m->'material';actor:=hf[12]::uuid;scope:=hf[17];
 opid:=(m->>'operationId')::uuid;target:=(m->>'taskId')::uuid;action:=m->>'action';
 if action is null or action not in ('receive','update') or m->>'expectedRevision' is null or (m->>'expectedRevision')::bigint<0
  or m->>'purpose' is distinct from 'pending-followup' then raise exception 'TASK_INPUT_INVALID'; end if;
 if i is null or a is null or jsonb_typeof(i)<>'object' or jsonb_typeof(a)<>'object'
  or (i-array['causeKind','causeId','contextKind','contextId','scopeRef','relatedKind','relatedId','effect'])<>'{}'::jsonb
  or (a-array['title','deadline','priority','sourceRef','sourceVersion','triggerRef','triggerVersion'])<>'{}'::jsonb
  or i->>'causeKind' is null or i->>'causeKind' not in ('review','document','amount','data','block','advance','balance',
  'provider','invoice','suplido','participants_list','availability','modification','cancellation','proposal','final_participants')
  or nullif(i->>'causeId','') is null or nullif(i->>'scopeRef','') is null or nullif(i->>'effect','') is null
  or i->>'contextKind' is null or i->>'contextKind' not in ('contact','organization','opportunity','booking','booking_service','provider','proposal','other')
  or nullif(i->>'contextId','') is null or (i->>'relatedId' is null)<>(i->>'relatedKind' is null)
  or nullif(a->>'title','') is null or nullif(a->>'sourceRef','') is null or nullif(a->>'sourceVersion','') is null
  or nullif(a->>'triggerVersion','') is null or a->>'triggerRef' is null or a->>'triggerRef' not in ('manual','BR-TASK-005')
  or (a->>'triggerRef'='BR-TASK-005' and i->>'causeKind' in ('review','amount','data'))
  or nullif(m->>'reason','') is null then raise exception 'TASK_INPUT_INVALID'; end if;
 perform (i->>'contextId')::uuid;
 if ((a->'priority')-'kind'-'reason')<>'{}'::jsonb or a->'priority'->>'kind' is distinct from 'pending' or nullif(a->'priority'->>'reason','') is null then raise exception 'TASK_PRIORITY_UNVERIFIED'; end if;
 if a->'deadline'->>'kind'='unknown' then
  if nullif(a->'deadline'->>'reason','') is null or ((a->'deadline')-'kind'-'reason')<>'{}'::jsonb then raise exception 'TASK_DEADLINE_INVALID'; end if;
 elsif a->'deadline'->>'kind' in ('civil','instant','d020') then
  if nullif(a->'deadline'->>'sourceRef','') is null or nullif(a->'deadline'->>'version','') is null then raise exception 'TASK_DEADLINE_INVALID'; end if;
  if a->'deadline'->>'kind'='civil' then
   if ((a->'deadline')-array['kind','date','sourceRef','version'])<>'{}'::jsonb then raise exception 'TASK_DEADLINE_INVALID'; end if;
   if coalesce(a->'deadline'->>'date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'TASK_DEADLINE_INVALID'; end if; perform (a->'deadline'->>'date')::date;
  elsif a->'deadline'->>'kind'='instant' then
   if ((a->'deadline')-array['kind','at','sourceRef','version'])<>'{}'::jsonb then raise exception 'TASK_DEADLINE_INVALID'; end if;
   if coalesce(a->'deadline'->>'at','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' or nullif(a->'deadline'->>'at','') is null then raise exception 'TASK_DEADLINE_INVALID'; end if;
   perform (a->'deadline'->>'at')::timestamptz;
  else
   if ((a->'deadline')-array['kind','reference','daysBefore','sourceRef','version'])<>'{}'::jsonb
    or ((a->'deadline'->'reference')-array['scope','scopeId','date','zone','sourceRef','version','basis'])<>'{}'::jsonb
    or ((a->'deadline'->'reference'->'zone')-array['zone','sourceRef','version'])<>'{}'::jsonb then raise exception 'TASK_DEADLINE_INVALID'; end if;
   if a->'deadline'->>'daysBefore' is null or (a->'deadline'->>'daysBefore')::integer<0 or nullif(a->'deadline'->'reference'->>'sourceRef','') is null
    or nullif(a->'deadline'->'reference'->>'version','') is null
    or nullif(a->'deadline'->'reference'->'zone'->>'sourceRef','') is null
    or nullif(a->'deadline'->'reference'->'zone'->>'version','') is null then raise exception 'TASK_DEADLINE_INVALID'; end if;
   perform (a->'deadline'->'reference'->>'date')::date;
  end if;
 else raise exception 'TASK_DEADLINE_INVALID'; end if;
 fingerprint:=encode(crm_crypto.digest(convert_to(m::text,'UTF8'),'sha256'),'hex');
 causekey:=encode(crm_crypto.digest(convert_to(jsonb_build_object('version','h1-pending-cause-v1','identity',i)::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(opid::text,0));
 select * into op from crm_private.b07_operations where operation_id=opid;
 if found then
  if op.admin_scope<>scope or op.actor_id<>actor or op.fingerprint<>fingerprint then raise exception 'TASK_REPLAY_CONFLICT'; end if;
  result_ref:=op.result_ref;replayed:=true;
 else
  -- Protect absence too: unique cause index is the persisted backstop.
  perform pg_advisory_xact_lock(hashtextextended(scope||causekey,17));
  select * into old from crm_private.b07_pending_tasks where admin_scope=scope and identity_key=causekey for update;
  if action='update' and (old.task_id is null or old.task_id<>target) then raise exception 'TASK_IDENTITY_CONFLICT'; end if;
  if old.task_id is null then
   if action<>'receive' or (m->>'expectedRevision')::bigint<>0 then raise exception 'TASK_REVISION_CONFLICT'; end if;
   insert into crm_private.b07_pending_tasks(task_id,admin_scope,identity_version,identity_key,identity,material,state,responsible_actor,revision)
    values(target,scope,'h1-pending-cause-v1',causekey,i,a,'pending',actor,1);
  else
   if old.identity<>i then raise exception 'TASK_IDENTITY_CONFLICT'; end if;
   target:=old.task_id;before_data:=to_jsonb(old);
   if old.material<>a then
    if action<>'update' or old.revision<>(m->>'expectedRevision')::bigint then raise exception 'TASK_REVISION_CONFLICT'; end if;
    update crm_private.b07_pending_tasks set material=a,revision=revision+1,updated_at=clock_timestamp() where task_id=target;
   elsif action='update' and old.revision<>(m->>'expectedRevision')::bigint then raise exception 'TASK_REVISION_CONFLICT'; end if;
  end if;
  select to_jsonb(t) into after_data from crm_private.b07_pending_tasks t where task_id=target;
  insert into crm_private.b07_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(opid,scope,actor,fingerprint,target);
  insert into crm_private.b07_history(history_id,operation_id,subject_id,admin_scope,action_kind,before_state,after_state,reason,source_ref,actor_id)
   values(opid,opid,target,scope,'task_'||action,before_data,after_data,m->>'reason',a->>'sourceRef',actor);
  result_ref:=target;replayed:=false;
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');
 perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_task_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];m jsonb;result jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');
 tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'TASK_DENIED'; end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H1-TASK-READ1' then raise exception 'TASK_INPUT_INVALID'; end if;
 m:=v[2]::jsonb;
 if m->>'purpose' is distinct from 'pending-followup' then raise exception 'TASK_DENIED'; end if;
 select to_jsonb(t) into result from crm_private.b07_pending_tasks t where t.task_id=(m->>'taskId')::uuid
  and t.admin_scope=hf[17] and t.identity->>'contextKind'=m->>'contextKind' and t.identity->>'contextId'=m->>'contextId';
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');
 perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return result;
end $function$

CREATE OR REPLACE FUNCTION crm_private.b03_decide(s text, e jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare k text:=e->>'type';allowed boolean:=false;dest text;id text;keys text[];why text;
begin
 keys:=case k when 'contact' then array['communicationId','outcome','evidenceId'] when 'define_need' then array['need','scope','pending']
 when 'prepare' then array['scope','sufficient','alternativeRef','pending'] when 'send' then array['versionRef','sendEvidenceRef','communicationId']
 when 'negotiate' then array['exchangeRef','scope'] when 'lose' then array['lossReason','context']
 when 'pause' then array['decision','context','followup'] when 'reactivate' then array['interest','review','destination','support']
 when 'revise' then array['change','humanEvaluation','destination','support'] when 'win' then array[]::text[]
 when 'reject_alternative' then array['alternativeRef','context'] end;
 if keys is null or e-(keys||array['type','sourceRef','occurredAt'])<>'{}'::jsonb then
  return jsonb_build_object('allowed',false,'id','SM-FORB-30','blocker','unsupported-effect'); end if;
 if exists(select 1 from jsonb_each(e) x where x.key not in ('pending','support','sufficient','occurredAt') and jsonb_typeof(x.value)<>'string')
  or (e ? 'pending' and (jsonb_typeof(e->'pending')<>'array' or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(e->'pending')='array' then e->'pending' else '[]'::jsonb end) x where jsonb_typeof(x)<>'string' or btrim(x#>>'{}')=''))) then
  return jsonb_build_object('allowed',false,'id','G2','blocker','material-type-invalid');end if;
 if e ? 'support' and (jsonb_typeof(e->'support') is distinct from 'object'
  or exists(select 1 from jsonb_each(case when jsonb_typeof(e->'support')='object' then e->'support' else '{}'::jsonb end) x where x.key<>'pending' and jsonb_typeof(x.value)<>'string')
  or ((e->'support') ? 'pending' and (jsonb_typeof(e->'support'->'pending') is distinct from 'array'
   or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(e->'support'->'pending')='array' then e->'support'->'pending' else '[]'::jsonb end) x where jsonb_typeof(x)<>'string' or btrim(x#>>'{}')='')))) then
  return jsonb_build_object('allowed',false,'id','G2','blocker','current-support-invalid');end if;
 if nullif(btrim(e->>'sourceRef'),'') is null then return jsonb_build_object('allowed',false,'id','G2','blocker','source-required'); end if;
 if k='win' then id:='SPEC-FR-COM-003';why:='verified-acceptance-required-H2-007';
 elsif k='contact' then id:='SM-OP-02';dest:='En contacto';allowed:=s='Nueva' and nullif(btrim(e->>'communicationId'),'') is not null and nullif(btrim(e->>'outcome'),'') is not null and nullif(btrim(e->>'evidenceId'),'') is not null;
 elsif k='define_need' then id:='SM-OP-03';dest:='Necesidad definida';allowed:=s in ('Nueva','En contacto') and nullif(btrim(e->>'need'),'') is not null and nullif(btrim(e->>'scope'),'') is not null and jsonb_typeof(e->'pending')='array';
 elsif k='prepare' then id:='SM-OP-04';why:='preparation-guards-required';
  if s in ('Nueva','En contacto','Necesidad definida','Propuesta enviada','Negociación / cambios') and e->'sufficient'='true'::jsonb
   and nullif(btrim(e->>'scope'),'') is not null and nullif(btrim(e->>'alternativeRef'),'') is not null and jsonb_typeof(e->'pending')='array' then why:='proposal-capability-pending-H2-003';end if;
 elsif k='send' then id:='SM-OP-05';why:='exact-version-send-guards-required';
  if s not in ('Aceptada / Ganada','Perdida','En pausa') and nullif(btrim(e->>'versionRef'),'') is not null
   and nullif(btrim(e->>'sendEvidenceRef'),'') is not null and nullif(btrim(e->>'communicationId'),'') is not null then why:='exact-version-send-capability-pending-H2-005';end if;
 elsif k='negotiate' then id:='SM-OP-06';dest:='Negociación / cambios';allowed:=s in ('Necesidad definida','Propuesta en preparación','Propuesta enviada') and nullif(btrim(e->>'exchangeRef'),'') is not null and nullif(btrim(e->>'scope'),'') is not null;
 elsif k='lose' then id:='SM-OP-08';dest:='Perdida';allowed:=s not in ('Aceptada / Ganada','Perdida') and e->>'lossReason' in
  ('precio','fechas','falta de disponibilidad','cliente no responde','eligió otra empresa','canceló/cambió viaje','no encaja','otro','desconocido') and nullif(btrim(e->>'context'),'') is not null;
 elsif k='pause' then id:='SM-OP-09';dest:='En pausa';allowed:=s not in ('Aceptada / Ganada','Perdida','En pausa') and nullif(btrim(e->>'decision'),'') is not null and nullif(btrim(e->>'context'),'') is not null and nullif(btrim(e->>'followup'),'') is not null;
 elsif k in ('reactivate','revise') then
  id:=case k when 'reactivate' then 'SM-OP-10' else 'SM-OP-11' end;
  if (k='reactivate' and s in ('Perdida','En pausa') and nullif(btrim(e->>'interest'),'') is not null and nullif(btrim(e->>'review'),'') is not null)
   or (k='revise' and s not in ('Aceptada / Ganada','Perdida','En pausa') and nullif(btrim(e->>'change'),'') is not null and nullif(btrim(e->>'humanEvaluation'),'') is not null) then
   if e->>'destination'='Propuesta en preparación' and k='reactivate' then why:='proposal-capability-pending-H2-003';
   elsif jsonb_typeof(e->'support')='object' and (e->'support')-array['contact','need','scope','pending']='{}'::jsonb then
    dest:=e->>'destination';allowed:=(dest='En contacto' and nullif(btrim(e->'support'->>'contact'),'') is not null)
     or (dest='Necesidad definida' and nullif(btrim(e->'support'->>'need'),'') is not null and nullif(btrim(e->'support'->>'scope'),'') is not null and jsonb_typeof(e->'support'->'pending')='array');
   end if;
  end if;
 elsif k='reject_alternative' then id:='AC-005';dest:=s;allowed:=s not in ('Aceptada / Ganada','Perdida','En pausa') and nullif(btrim(e->>'alternativeRef'),'') is not null and nullif(btrim(e->>'context'),'') is not null;
 end if;
 return jsonb_build_object('allowed',coalesce(allowed,false),'destination',case when allowed then dest end,'id',id,'blocker',coalesce(why,'commercial-guards-required'));
end $function$

CREATE OR REPLACE FUNCTION crm_api.b03_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea, cf2p bytea, cf2s bytea, cf1p bytea, cf1s bytea, cq bytea)
 RETURNS TABLE(result_ref uuid, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];cv text[];m jsonb;a jsonb;e jsonb;d jsonb;
 actor uuid;scope text;target uuid;opid uuid;lead uuid;action text;fingerprint text;prior jsonb;after_data jsonb;
 old crm_private.b03_opportunities%rowtype;op crm_private.b03_operations%rowtype;l crm_private.b03_leads%rowtype;ref text;ik text;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'COMMERCIAL_DENIED' using errcode='42501';end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H2-COM-1' then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
 m:=v[2]::jsonb;a:=m->'material';e:=m->'event';actor:=hf[12]::uuid;scope:=hf[17];
 action:=m->>'action';target:=(m->>'targetId')::uuid;opid:=(m->>'operationId')::uuid;lead:=nullif(m->>'leadId','')::uuid;
 if m-array['action','targetId','operationId','leadId','expectedRevision','sourceRef','reason','material','event']<>'{}'::jsonb
  or jsonb_typeof(m->'sourceRef') is distinct from 'string' or jsonb_typeof(m->'reason') is distinct from 'string'
  or nullif(btrim(m->>'sourceRef'),'') is null or nullif(btrim(m->>'reason'),'') is null or coalesce(m->>'expectedRevision','') !~ '^(0|[1-9][0-9]*)$'
  or action is null or action not in ('lead','direct','convert','progress') then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
 fingerprint:=encode(crm_crypto.digest(convert_to(m::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(opid::text,0));
 select * into op from crm_private.b03_operations where operation_id=opid;
 if found then
  if op.admin_scope<>scope or op.actor_id<>actor or op.fingerprint<>fingerprint then raise exception 'COMMERCIAL_REPLAY_CONFLICT';end if;
  result_ref:=op.result_ref;replayed:=true;
 else
  perform pg_advisory_xact_lock(hashtextextended(coalesce(lead,target)::text,31));
  if action in ('lead','direct','convert') then
   if e is not null then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   if jsonb_typeof(a) is distinct from 'object' or a-array['contact','need','commercialPossible','pending','dates','participants','services','budget','contactId','organizationId','groupId']<>'{}'::jsonb
    or not(a ?& array['contact','need','commercialPossible','pending']) or jsonb_typeof(a->'pending') is distinct from 'array'
    or (a->'need'<>'null'::jsonb and (jsonb_typeof(a->'need')<>'string' or nullif(btrim(a->>'need'),'') is null))
    or a->'commercialPossible' not in ('null'::jsonb,'true'::jsonb,'false'::jsonb) then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   if a->'contact'<>'null'::jsonb and (jsonb_typeof(a->'contact')<>'object' or (a->'contact')-array['channel','address','sourceRef','valid']<>'{}'::jsonb
    or jsonb_typeof(a->'contact'->'channel') is distinct from 'string' or jsonb_typeof(a->'contact'->'address') is distinct from 'string'
    or jsonb_typeof(a->'contact'->'sourceRef') is distinct from 'string'
    or not((a->'contact') ?& array['channel','address','sourceRef','valid']) or a->'contact'->'valid' not in ('true'::jsonb,'false'::jsonb)
    or nullif(btrim(a->'contact'->>'channel'),'') is null or nullif(btrim(a->'contact'->>'address'),'') is null
    or nullif(btrim(a->'contact'->>'sourceRef'),'') is null) then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   if exists(select 1 from jsonb_array_elements(a->'pending') x where jsonb_typeof(x)<>'string' or btrim(x#>>'{}')='') then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   foreach ik in array array['contact','organization','group'] loop
    ref:=a->>(ik||'Id');if ref is not null and not exists(select 1 from crm_private.identity_entities i
     where i.identity_id=ref::uuid and i.identity_kind=ik and i.admin_scope=scope and i.archived_at is null and i.merged_into_id is null
      and (ik<>'group' or i.context_id=target)) then raise exception 'COMMERCIAL_IDENTITY_INVALID';end if;
   end loop;
   if action='lead' then
    if lead is not null or (m->>'expectedRevision')::bigint<>0 then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
    insert into crm_private.b03_leads(lead_id,admin_scope,source_ref,responsible_actor,material) values(target,scope,m->>'sourceRef',actor,a);
    select to_jsonb(t) into after_data from crm_private.b03_leads t where lead_id=target;d:=jsonb_build_object('id','BR-LEAD-001');
   else
    if a->'contact'->'valid' is distinct from 'true'::jsonb or nullif(btrim(a->>'need'),'') is null or a->'commercialPossible' is distinct from 'true'::jsonb then raise exception 'COMMERCIAL_MINIMUM_REQUIRED:SM-OP-01';end if;
    if (m->>'expectedRevision')::bigint<>0 then raise exception 'COMMERCIAL_REVISION_CONFLICT';end if;
    if action='convert' then
     select * into l from crm_private.b03_leads where lead_id=lead and admin_scope=scope;
     if not found then raise exception 'COMMERCIAL_LEAD_REQUIRED';end if;
     select * into old from crm_private.b03_opportunities where lead_id=lead;
     if found then
      if old.admin_scope<>scope or old.creation_material<>a or old.source_ref<>l.source_ref then raise exception 'COMMERCIAL_CONVERSION_CONFLICT';end if;
      target:=old.opportunity_id;result_ref:=target;replayed:=true;
     end if;
    elsif lead is not null then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
    if old.opportunity_id is null then
     if exists(select 1 from crm_private.identity_contexts where context_id=target) then
      if not exists(select 1 from crm_private.identity_contexts where context_id=target and context_kind='opportunity' and admin_scope=scope and verified) then raise exception 'COMMERCIAL_CONTEXT_INVALID';end if;
     else
      insert into crm_private.identity_contexts(context_id,context_kind,admin_scope,source_ref,evidence_ref,verified)
       values(target,'opportunity',scope,coalesce(l.source_ref,m->>'sourceRef'),m->>'sourceRef',true);
     end if;
     insert into crm_private.b03_opportunities(opportunity_id,lead_id,admin_scope,source_ref,responsible_actor,material,creation_material,state,revision)
      values(target,lead,scope,coalesce(l.source_ref,m->>'sourceRef'),coalesce(l.responsible_actor,actor),a,a,'Nueva',1);
     -- Reuse the actual H1 API, allocator, counter, D040 and immutable registry.
     cv:=crm_f1.fields(cq);
     if cv is distinct from array['CRM-H1-RESOLVE1','assign_code',target::text,target::text,'','OP',m->>'sourceRef',m->>'sourceRef',m->>'reason','0'] then raise exception 'COMMERCIAL_CODE_CONTRACT_INVALID';end if;
     if not exists(select 1 from crm_private.identity_codes c where c.code_kind='OP' and c.target_id=target and c.admin_scope=scope) then
      perform crm_api.identity_resolve(cf2p,cf2s,cf1p,cf1s,cq);end if;
     select to_jsonb(t) into after_data from crm_private.b03_opportunities t where opportunity_id=target;
     d:=jsonb_build_object('id','SM-OP-01');
    end if;
   end if;
  else
   select * into old from crm_private.b03_opportunities where opportunity_id=target and admin_scope=scope for update;
   if not found then raise exception 'COMMERCIAL_DENIED';end if;
   if old.revision<>(m->>'expectedRevision')::bigint then raise exception 'COMMERCIAL_REVISION_CONFLICT';end if;
   if a is not null or lead is not null or jsonb_typeof(e) is distinct from 'object' then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   d:=crm_private.b03_decide(old.state,e);
   if d->>'allowed' is distinct from 'true' then raise exception 'COMMERCIAL_BLOCKED:%:%',d->>'id',d->>'blocker';end if;
   if e->>'type'='contact' then
    if not exists(select 1 from crm_private.b07_records r join crm_private.b07_links b using(record_id)
     where r.record_id=(e->>'communicationId')::uuid and r.admin_scope=scope and b.admin_scope=scope
     and b.context_kind='opportunity' and b.context_id=target and r.record_kind='communication'
     and nullif(r.material->>'channel','') is not null and nullif(r.material->>'recipient_ref','') is not null
     and r.material->>'direction' in ('incoming','outgoing')) then raise exception 'COMMERCIAL_CONTACT_EVIDENCE_REQUIRED';end if;
   end if;
   if e->>'type' in ('contact','negotiate') then
    ref:=case when e->>'type'='contact' then e->>'evidenceId' else e->>'exchangeRef' end;
    if not exists(select 1 from crm_private.b07_records r join crm_private.b07_links b using(record_id)
     where r.record_id=ref::uuid and r.admin_scope=scope and b.admin_scope=scope and b.context_kind='opportunity' and b.context_id=target
     and ((r.record_kind='evidence' and r.material->>'certainty'='reviewed') or (r.record_kind='communication' and r.material->>'direction'='incoming'))) then
     raise exception 'COMMERCIAL_ACTUAL_EVIDENCE_REQUIRED';end if;
   end if;
   prior:=to_jsonb(old);
   if e->>'type'='define_need' or e->>'destination'='Necesidad definida' then
    a:=case when e->>'type'='define_need' then e else e->'support' end;
    update crm_private.b03_opportunities set material=jsonb_set(jsonb_set(material,'{need}',a->'need'),'{pending}',a->'pending') where opportunity_id=target;
   end if;
   update crm_private.b03_opportunities set state=d->>'destination',revision=revision+1,updated_at=clock_timestamp(),
    previous_state=case when e->>'type'='pause' then old.state else previous_state end,
    loss_reason=case when e->>'type'='lose' then e->>'lossReason' else loss_reason end where opportunity_id=target;
   select to_jsonb(t) into after_data from crm_private.b03_opportunities t where opportunity_id=target;
  end if;
  insert into crm_private.b03_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(opid,scope,actor,fingerprint,target);
  if after_data is not null then
   insert into crm_private.b03_history(history_id,subject_id,admin_scope,before_state,after_state,event,normative_ids,reason,source_ref,actor_id,occurred_at)
    values(opid,target,scope,prior,after_data,coalesce(e,jsonb_build_object('type',action,'leadId',lead)),jsonb_build_array(d->>'id'),m->>'reason',m->>'sourceRef',actor,(e->>'occurredAt')::timestamptz);
  end if;
  result_ref:=target;replayed:=coalesce(replayed,false);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');
 perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b03_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];m jsonb;data jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'COMMERCIAL_DENIED';end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H2-COM-READ1' then raise exception 'COMMERCIAL_INPUT_INVALID';end if;m:=v[2]::jsonb;
 if m->>'kind'='lead' then select to_jsonb(t) into data from crm_private.b03_leads t where lead_id=(m->>'targetId')::uuid and admin_scope=hf[17];
 elsif m->>'kind'='opportunity' then select to_jsonb(t)||jsonb_build_object('human_code',c.human_code) into data
  from crm_private.b03_opportunities t join crm_private.identity_codes c on c.target_id=t.opportunity_id and c.code_kind='OP' and c.admin_scope=t.admin_scope where opportunity_id=(m->>'targetId')::uuid and t.admin_scope=hf[17];
 elsif m->>'kind'='history' then select coalesce(jsonb_agg(to_jsonb(t) order by recorded_at,history_id),'[]'::jsonb) into data from crm_private.b03_history t where subject_id=(m->>'targetId')::uuid and admin_scope=hf[17];
 else raise exception 'COMMERCIAL_INPUT_INVALID';end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return data;
end $function$

CREATE OR REPLACE FUNCTION crm_api.proposal_sources(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];m jsonb;r text;data jsonb:='[]';s jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'PROPOSAL_DENIED';end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H2-PROP-SOURCES1' then raise exception 'PROPOSAL_INPUT_INVALID';end if;m:=v[2]::jsonb;
 if not exists(select 1 from crm_private.b03_opportunities where opportunity_id=(m->>'opportunityId')::uuid and admin_scope=hf[17]) then raise exception 'PROPOSAL_OPPORTUNITY_REQUIRED';end if;
 for r in select jsonb_array_elements_text(m->'references') loop
  s:=null;
  select jsonb_build_object('id',c.revision_id,'kind',i.item_kind,'definition',c.definition,'sourceRef',c.source_ref,'version',c.revision_number::text) into s
   from crm_private.catalog_revisions c join crm_private.catalog_items i using(item_id) where c.revision_id=r::uuid and c.admin_scope=hf[17];
  if s is null then select jsonb_build_object('id',c.revision_id,'kind',i.item_kind,'definition',c.definition,'sourceRef',c.source_ref,'version',c.revision_number::text) into s
   from crm_private.commercial_revisions c join crm_private.commercial_items i using(item_id) where c.revision_id=r::uuid and c.admin_scope=hf[17];end if;
  if s is null then select jsonb_build_object('id',c.record_id,'kind',c.record_kind,'definition',c.material,'sourceRef',c.source_ref,'version','1') into s
   from crm_private.b07_records c join crm_private.b07_links l using(record_id) where c.record_id=r::uuid and c.admin_scope=hf[17] and l.context_id=(m->>'opportunityId')::uuid and l.context_kind='opportunity' limit 1;end if;
  if s is null then raise exception 'PROPOSAL_SOURCE_INVALID';end if;data:=data||jsonb_build_array(s);
  if s->>'kind'='service' then
   data:=data||coalesce((select jsonb_agg(jsonb_build_object('id',er.revision_id,'kind','eligibility_rule','definition',er.definition,'sourceRef',er.source_ref,'version',er.revision_number::text,'serviceRevisionId',r))
    from crm_private.commercial_items ei join lateral (select * from crm_private.commercial_revisions cr where cr.item_id=ei.item_id order by revision_number desc limit 1) er on true
    join crm_private.catalog_revisions sr on sr.revision_id=r::uuid where ei.item_kind='eligibility_rule' and ei.admin_scope=hf[17] and ei.catalog_item_id=sr.item_id),'[]'::jsonb);
  end if;
 end loop;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return data;
end $function$

CREATE OR REPLACE FUNCTION crm_api.proposal_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea, cf2p bytea, cf2s bytea, cf1p bytea, cf1s bytea, cq bytea)
 RETURNS TABLE(result_ref uuid, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];a jsonb;c jsonb;econ jsonb;sources jsonb;m jsonb;l jsonb;prior jsonb;after_data jsonb;norm jsonb;
 actor uuid;scope text;opid uuid;root uuid;opp uuid;fp text;action text;versionid uuid;base uuid;prep crm_private.b03_preparations%rowtype;
 p crm_private.b03_proposals%rowtype;pv crm_private.b03_proposal_versions%rowtype;o crm_private.b03_opportunities%rowtype;operation crm_private.b03_proposal_operations%rowtype;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'PROPOSAL_DENIED';end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H2-PROP-1' then raise exception 'PROPOSAL_INPUT_INVALID';end if;
 a:=v[2]::jsonb;actor:=hf[12]::uuid;scope:=hf[17];root:=(a->>'proposalId')::uuid;opp:=(a->>'opportunityId')::uuid;opid:=(a->>'operationId')::uuid;
 action:=a->>'action';base:=nullif(a->>'baseVersionId','')::uuid;versionid:=nullif(a->>'versionId','')::uuid;
 if a-array['action','operationId','proposalId','opportunityId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','content','baseVersionId','reviewed','versionId','partId','requestEvidenceId','economics','sources']<>'{}'::jsonb
  or action is null or action not in ('prepare','fix','partial_request') or jsonb_typeof(a->'sourceRef') is distinct from 'string' or jsonb_typeof(a->'reason') is distinct from 'string'
  or nullif(btrim(a->>'sourceRef'),'') is null or nullif(btrim(a->>'reason'),'') is null then raise exception 'PROPOSAL_INPUT_INVALID';end if;
 fp:=encode(crm_crypto.digest(convert_to((a-array['economics','sources'])::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(opid::text,0));
 select * into operation from crm_private.b03_proposal_operations where operation_id=opid;
 if found then
  if operation.admin_scope<>scope or operation.actor_id<>actor or operation.fingerprint<>fp then raise exception 'PROPOSAL_REPLAY_CONFLICT';end if;
  result_ref:=operation.result_ref;replayed:=true;
 else
  -- Same existing Opportunity lock order as H2-001, followed by Proposal root.
  perform pg_advisory_xact_lock(hashtextextended(opp::text,31));
  select * into o from crm_private.b03_opportunities where opportunity_id=opp and admin_scope=scope for update;
  if not found then raise exception 'PROPOSAL_OPPORTUNITY_REQUIRED';end if;
  perform pg_advisory_xact_lock(hashtextextended(root::text,33));
  select * into p from crm_private.b03_proposals where proposal_id=root and admin_scope=scope for update;
  if p.proposal_id is not null and p.opportunity_id<>opp then raise exception 'PROPOSAL_RELATION_INVALID';end if;
  if coalesce(p.revision,0)<>(a->>'expectedRevision')::bigint then raise exception 'PROPOSAL_REVISION_CONFLICT';end if;
  if action='prepare' then
   c:=a->'content';econ:=a->'economics';sources:=a->'sources';
   if versionid is not null or not crm_private.proposal_content_guard(c,false) or jsonb_typeof(econ) is distinct from 'array' or jsonb_typeof(sources) is distinct from 'array' or jsonb_array_length(sources)=0 then raise exception 'PROPOSAL_BLOCKED:SM-PV-01';end if;
   if o.revision<>(a->>'expectedOpportunityRevision')::bigint then raise exception 'PROPOSAL_OPPORTUNITY_REVISION_CONFLICT';end if;
   if o.state not in ('Nueva','En contacto','Necesidad definida','Propuesta en preparación','Propuesta enviada','Negociación / cambios') then raise exception 'PROPOSAL_BLOCKED:SM-OP-04';end if;
   if base is not null then
    select * into pv from crm_private.b03_proposal_versions where version_id=base and proposal_id=root;
    if not found or a->'reviewed' is distinct from 'true'::jsonb or pv.content=c then raise exception 'PROPOSAL_BLOCKED:SM-PV-06';end if;prior:=to_jsonb(pv);
   elsif p.last_version_number>0 then raise exception 'PROPOSAL_BASE_VERSION_REQUIRED';end if;
   -- Enforce real, scoped and matching sources at the persistence boundary too.
   for m in select jsonb_array_elements(c->'modalities') loop
    if m ? 'packRevisionId' and not exists(select 1 from crm_private.commercial_revisions r join crm_private.commercial_items i using(item_id) where r.revision_id=(m->>'packRevisionId')::uuid and r.admin_scope=scope and i.item_kind in ('pack','custom_pack')) then raise exception 'PROPOSAL_SOURCE_INVALID';end if;
    for l in select jsonb_array_elements(m->'lines') loop
     if not exists(select 1 from crm_private.catalog_revisions r join crm_private.catalog_items i using(item_id) where r.revision_id=(l->>'serviceRevisionId')::uuid and r.admin_scope=scope and i.item_kind='service')
      or not exists(select 1 from crm_private.catalog_revisions r join crm_private.catalog_items i using(item_id) where r.revision_id=(l->>'unitRevisionId')::uuid and r.admin_scope=scope and i.item_kind='unit') then raise exception 'PROPOSAL_SOURCE_INVALID';end if;
     if l ? 'tariffRevisionId' and not exists(select 1 from crm_private.commercial_revisions r join crm_private.commercial_items i using(item_id) join crm_private.catalog_revisions sr on sr.revision_id=(l->>'serviceRevisionId')::uuid where r.revision_id=(l->>'tariffRevisionId')::uuid and r.admin_scope=scope and i.item_kind='tariff' and i.catalog_item_id=sr.item_id and r.definition->>'unit_revision_id'=l->>'unitRevisionId') then raise exception 'PROPOSAL_SOURCE_INVALID';end if;
    end loop;
   end loop;
   if p.proposal_id is null then
    insert into crm_private.b03_proposals(proposal_id,opportunity_id,admin_scope,revision,source_ref,actor_id) values(root,opp,scope,1,a->>'sourceRef',actor);
    if crm_f1.fields(cq) is distinct from array['CRM-H1-RESOLVE1','assign_code',root::text,root::text,'','PR',a->>'sourceRef',a->>'sourceRef',a->>'reason','0'] then raise exception 'PROPOSAL_CODE_CONTRACT_INVALID';end if;
    perform crm_api.identity_resolve(cf2p,cf2s,cf1p,cf1s,cq);
   else update crm_private.b03_proposals set revision=revision+1 where proposal_id=root;end if;
   insert into crm_private.b03_preparations(preparation_id,proposal_id,admin_scope,revision,content,economics,sources,base_version_id,reviewed,source_ref,reason,actor_id)
    values(opid,root,scope,coalesce(p.revision,0)+1,c,econ,sources,base,coalesce((a->>'reviewed')::boolean,false),a->>'sourceRef',a->>'reason',actor);
   select to_jsonb(t) into after_data from crm_private.b03_preparations t where preparation_id=opid;
   -- Actual preparation and commercial progress are one T01 unit; no invented stages.
   insert into crm_private.b03_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(opid,scope,actor,fp,opp);
   insert into crm_private.b03_history(history_id,subject_id,admin_scope,before_state,after_state,event,normative_ids,reason,source_ref,actor_id)
    values(opid,opp,scope,to_jsonb(o),jsonb_set(jsonb_set(to_jsonb(o),'{state}','"Propuesta en preparación"'),'{revision}',to_jsonb(o.revision+1)),jsonb_build_object('type','prepare','alternativeRef',root,'pending',c->'pending'),jsonb_build_array('SM-OP-04'),a->>'reason',a->>'sourceRef',actor);
   update crm_private.b03_opportunities set state='Propuesta en preparación',revision=revision+1,updated_at=clock_timestamp() where opportunity_id=opp;
   result_ref:=opid;norm:=jsonb_build_array('SM-PV-01','SM-OP-04',case when base is not null then 'SM-PV-06' else 'PLAN-T01' end);
  elsif action='fix' then
   if p.proposal_id is null or versionid is null or a ? 'content' then raise exception 'PROPOSAL_BLOCKED:SM-PV-02';end if;
   select * into prep from crm_private.b03_preparations where proposal_id=root order by revision desc limit 1;
   if prep.preparation_id is null or exists(select 1 from crm_private.b03_proposal_versions where preparation_id=prep.preparation_id) or not crm_private.proposal_content_guard(prep.content,true) then raise exception 'PROPOSAL_BLOCKED:SM-PV-02';end if;
   for m in select jsonb_array_elements(prep.content->'modalities') loop
    if m->'definitive'='true'::jsonb then
     for l in select jsonb_array_elements(m->'lines') loop
      if l->'included'='true'::jsonb and exists(select 1 from jsonb_array_elements(prep.sources) rs where rs->>'kind'='eligibility_rule' and rs->>'serviceRevisionId'=l->>'serviceRevisionId'
       and (rs->'definition'->>'knowledge'<>'known' or not exists(select 1 from crm_private.b07_records er join crm_private.b07_links el using(record_id) where er.record_id=nullif(l->>'eligibilityEvidenceId','')::uuid and er.admin_scope=scope and er.record_kind='evidence' and er.material->>'certainty'='reviewed' and er.material->>'claim'='eligible:'||(rs->>'id') and el.context_id=opp and el.context_kind='opportunity'))) then raise exception 'PROPOSAL_DEPENDENT_PRICE_BLOCKED:AC-085';end if;
     end loop;
    end if;
    if m->'definitive'='true'::jsonb and (m->>'finalPersonPrice' is null or exists(select 1 from jsonb_array_elements(prep.economics) e where e->>'modalityId'=m->>'id' and (e->'calculated'='null'::jsonb or jsonb_array_length(e->'blockers')>0))) then raise exception 'PROPOSAL_DEPENDENT_PRICE_BLOCKED:AC-010';end if;
   end loop;
   c:=prep.content;prior:=to_jsonb(prep);
   insert into crm_private.b03_proposal_versions(version_id,proposal_id,preparation_id,version_number,admin_scope,scope,terms_version,terms_text,terms_source,pending,content,economics,sources,replaces_version_id,reason,source_ref,actor_id)
    values(versionid,root,prep.preparation_id,p.last_version_number+1,scope,c->>'scope',c->'terms'->>'version',c->'terms'->>'text',c->'terms'->>'sourceRef',c->'pending',c,prep.economics,prep.sources,prep.base_version_id,a->>'reason',a->>'sourceRef',actor);
   for m in select jsonb_array_elements(c->'modalities') loop
    insert into crm_private.b03_proposal_modalities values(versionid,(m->>'id')::uuid,m->>'name',(m->>'participants')::bigint,(m->>'independent')::boolean,(m->>'selectable')::boolean,nullif(m->>'packRevisionId','')::uuid,m->>'conditions',(m->>'finalPersonPrice')::numeric,(m->>'definitive')::boolean,scope);
    for l in select jsonb_array_elements(m->'lines') loop
     insert into crm_private.b03_proposal_lines values(versionid,(m->>'id')::uuid,(l->>'id')::uuid,(l->>'serviceRevisionId')::uuid,(l->>'unitRevisionId')::uuid,nullif(l->>'tariffRevisionId','')::uuid,(l->>'quantity')::numeric,(l->>'included')::boolean,(l->>'independent')::boolean,(l->>'selectable')::boolean,(l->>'date')::date,(l->>'datePending')::boolean,l->>'priceBasis',(l->>'costMaterial')::boolean,l->>'sourceRef',nullif(l->>'estimateRuleEvidenceId','')::uuid,nullif(l->>'eligibilityEvidenceId','')::uuid,scope);
    end loop;
   end loop;
   update crm_private.b03_proposals set revision=revision+1,last_version_number=last_version_number+1 where proposal_id=root;
   select to_jsonb(t) into after_data from crm_private.b03_proposal_versions t where version_id=versionid;result_ref:=versionid;norm:=jsonb_build_array('SM-PV-02','PLAN-T01');
  else
   if p.proposal_id is null or versionid is null or a ? 'content' or not exists(select 1 from crm_private.b03_proposal_versions where version_id=versionid and proposal_id=root) then raise exception 'PROPOSAL_RELATION_INVALID';end if;
   if not exists(select 1 from crm_private.b07_records r join crm_private.b07_links l using(record_id) where r.record_id=(a->>'requestEvidenceId')::uuid and r.admin_scope=scope and l.context_id=opp and (r.record_kind='communication' and r.material->>'direction'='incoming' or r.record_kind='evidence' and r.material->>'certainty'='reviewed')) then raise exception 'PROPOSAL_REQUEST_EVIDENCE_REQUIRED';end if;
   if not exists(select 1 from crm_private.b03_proposal_lines where version_id=versionid and line_id=(a->>'partId')::uuid and not selectable) then raise exception 'PROPOSAL_NONSELECTION_REQUIRED';end if;
   after_data:=jsonb_build_object('versionId',versionid,'partId',a->>'partId','requestEvidenceId',a->>'requestEvidenceId','requiresNewVersion',true,'acceptanceCreated',false);
   result_ref:=opid;norm:=jsonb_build_array('AC-013','SPEC-FR-ACC-003');
  end if;
  insert into crm_private.b03_proposal_operations values(opid,root,scope,actor,fp,result_ref,action,a->>'sourceRef',a->>'reason',clock_timestamp());
  insert into crm_private.b03_proposal_history values(opid,root,scope,prior,after_data,a-array['economics','sources'],norm,actor,a->>'sourceRef',a->>'reason',clock_timestamp());replayed:=false;
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.proposal_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];a jsonb;root uuid;vid uuid;data jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'PROPOSAL_DENIED';end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H2-PROP-READ1' then raise exception 'PROPOSAL_INPUT_INVALID';end if;a:=v[2]::jsonb;root:=(a->>'proposalId')::uuid;
 if not exists(select 1 from crm_private.b03_proposals where proposal_id=root and admin_scope=hf[17]) then raise exception 'PROPOSAL_DENIED';end if;
 vid:=nullif(a->>'versionId','')::uuid;
 if a->>'kind'='preparation' then select to_jsonb(t) into data from crm_private.b03_preparations t where proposal_id=root order by revision desc limit 1;
 elsif a->>'kind'='history' then select jsonb_agg(to_jsonb(t) order by recorded_at,history_id) into data from crm_private.b03_proposal_history t where proposal_id=root;
 elsif a->>'kind'='internal' then select to_jsonb(t)||jsonb_build_object('human_code',ic.human_code) into data from crm_private.b03_proposal_versions t join crm_private.identity_codes ic on ic.target_id=root and ic.code_kind='PR' where t.proposal_id=root and (vid is null or version_id=vid) order by version_number desc limit 1;
 elsif a->>'kind'='commercial' then
  if vid is null then select version_id into vid from crm_private.b03_proposal_versions where proposal_id=root order by version_number desc limit 1;end if;
  if not exists(select 1 from crm_private.b03_proposal_versions where version_id=vid and proposal_id=root) then raise exception 'PROPOSAL_DENIED';end if;
  select coalesce(jsonb_agg(jsonb_build_object('finalPersonPrice',case when final_person_price is null then null when m.definitive then to_jsonb(to_char(final_person_price,'FM9999999999999999999999999999990.00')) else jsonb_build_object('amount',to_char(final_person_price,'FM9999999999999999999999999999990.00'),'certainty',case when exists(select 1 from crm_private.b03_proposal_versions pv,jsonb_array_elements(pv.economics) e,jsonb_array_elements(e->'components') ec where pv.version_id=vid and e->>'modalityId'=m.modality_id::text and ec->>'priceState'='estimated') then 'estimated' else 'pending' end) end,'participants',participants,'included',
   (select coalesce(jsonb_agg(jsonb_build_object('service',r.definition->>'name','quantity',l.quantity,'date',l.service_date) order by l.line_id),'[]') from crm_private.b03_proposal_lines l join crm_private.catalog_revisions r on r.revision_id=l.service_revision_id where l.version_id=vid and l.modality_id=m.modality_id and l.included)) order by modality_id),'[]') into data from crm_private.b03_proposal_modalities m where version_id=vid;
 else raise exception 'PROPOSAL_INPUT_INVALID';end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return data;
end $function$

CREATE OR REPLACE FUNCTION crm_api.offer_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fields text[];a jsonb;p crm_private.b03_proposals;o crm_private.b03_opportunities;
 v crm_private.b03_proposal_versions;i crm_private.b03_offer_issuances;prior crm_private.b03_offer_operations;
 com crm_private.b07_records;fact crm_private.b07_records;proof crm_private.b07_records;
 op uuid;root uuid;vid uuid;opp uuid;actor uuid;s text;action text;cov text;at_time timestamptz;
 fp text;res jsonb;norm jsonb;original jsonb;d integer;issued timestamptz;until_time timestamptz;l jsonb;
 reviewed boolean:=false;stale boolean:=false;pending boolean:=false;aspect text;part uuid;kind text;lo timestamptz;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OFFER_DENIED';end if;
 fields:=crm_f1.fields(q);if cardinality(fields)<>2 or fields[1]<>'CRM-H2-OFFER1' then raise exception 'OFFER_INPUT_INVALID';end if;a:=fields[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-array['action','operationId','proposalId','opportunityId','versionId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','coverage','at','actId','actKind','issuance','evidenceId','reviewEvidence','communicationId','factId','recipientId','channel','partId','partKind','lossReason','origin']<>'{}'::jsonb
 or not(a ?& array['action','operationId','proposalId','opportunityId','versionId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','coverage','at'])
 or a->>'action' not in ('issue','intent','evaluate','revalidate','send','reject')
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or jsonb_typeof(a->'expectedOpportunityRevision') is distinct from 'number'
 or a->>'expectedRevision' !~ '^[0-9]+$' or a->>'expectedOpportunityRevision' !~ '^[0-9]+$'
 or exists(select 1 from jsonb_each(a) x where x.key in ('sourceRef','reason','coverage','at') and (jsonb_typeof(x.value)<>'string' or btrim(x.value#>>'{}')=''))
 or a->>'at' !~ '^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d+)?(Z|[+-]\d\d:\d\d)$' then raise exception 'OFFER_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;root:=(a->>'proposalId')::uuid;vid:=(a->>'versionId')::uuid;opp:=(a->>'opportunityId')::uuid;
 actor:=hf[12]::uuid;s:=hf[17];action:=a->>'action';cov:=a->>'coverage';at_time:=(a->>'at')::timestamptz;
 if at_time>clock_timestamp() then raise exception 'OFFER_FUTURE_FACT';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(op::text,0));
 select * into prior from crm_private.b03_offer_operations where operation_id=op;
 if found then
  if prior.admin_scope<>s or prior.actor_id<>actor or prior.fingerprint<>fp then raise exception 'OFFER_REPLAY_CONFLICT';end if;
  res:=jsonb_build_object('id',op,'replayed',true,'result',prior.result);
 else
  perform pg_advisory_xact_lock(hashtextextended(opp::text,31));
  select * into o from crm_private.b03_opportunities where opportunity_id=opp and admin_scope=s for update;
  if not found then raise exception 'OFFER_RELATION_INVALID';end if;
  perform pg_advisory_xact_lock(hashtextextended(root::text,33));
  select * into p from crm_private.b03_proposals where proposal_id=root and opportunity_id=opp and admin_scope=s for update;
  if not found then raise exception 'OFFER_RELATION_INVALID';end if;
  select * into v from crm_private.b03_proposal_versions where version_id=vid and proposal_id=root and admin_scope=s;
  if not found or cov not in (v.scope) and not exists(select 1 from crm_private.b03_proposal_modalities where version_id=vid and modality_id::text=cov) and not exists(select 1 from crm_private.b03_proposal_lines where version_id=vid and line_id::text=cov) then raise exception 'OFFER_COVERAGE_INVALID';end if;
  if p.revision<>(a->>'expectedRevision')::bigint or o.revision<>(a->>'expectedOpportunityRevision')::bigint then raise exception 'OFFER_REVISION_CONFLICT';end if;
  original:=jsonb_build_object('proposalRevision',p.revision,'opportunity',to_jsonb(o));
  select * into i from crm_private.b03_offer_issuances where version_id=vid;
  select coalesce(max(z.occurred_at),'-infinity'::timestamptz) into lo from crm_private.b03_offer_operations z where z.version_id=vid and z.action in ('evaluate','reject') and crm_private.offer_overlap(vid,z.coverage,cov);
  lo:=greatest(lo,coalesce((select max(recorded_at) from crm_private.b03_proposal_versions where replaces_version_id=vid),'-infinity'::timestamptz));
  stale:=exists(select 1 from crm_private.b03_proposal_versions where replaces_version_id=vid)
   or exists(select 1 from crm_private.b03_offer_operations e where e.version_id=vid and e.action='reject' and crm_private.offer_overlap(vid,e.coverage,cov))
   or exists(select 1 from crm_private.b03_offer_operations e where e.version_id=vid and e.action='evaluate' and e.result->'pending'='true' and crm_private.offer_overlap(vid,e.coverage,cov));
  reviewed:=exists(select 1 from crm_private.b03_offer_operations e where e.version_id=vid and e.action='revalidate' and e.coverage=cov and e.event->>'actId'=a->>'actId' and e.event->>'actKind'=coalesce(a->>'actKind','send') and e.occurred_at=at_time and e.recorded_at>coalesce((select max(recorded_at) from crm_private.b03_offer_operations z where z.version_id=vid and z.action in ('reject','evaluate') and crm_private.offer_overlap(vid,z.coverage,cov)),'-infinity'::timestamptz));
  if action='issue' then
   if i.version_id is not null or cov<>v.scope or jsonb_typeof(a->'issuance') is distinct from 'object' or (a->'issuance')-array['issuedAt','days','limits']<>'{}'::jsonb then raise exception 'OFFER_NEW_VERSION_REQUIRED:SM-FORB-01';end if;
   if not((a->'issuance') ?& array['issuedAt','limits']) or jsonb_typeof(a->'issuance'->'limits') is distinct from 'array' then raise exception 'OFFER_INPUT_INVALID';end if;
   d:=coalesce((a->'issuance'->>'days')::integer,7);issued:=(a->'issuance'->>'issuedAt')::timestamptz;
   if d<=0 or issued<>at_time then raise exception 'OFFER_INPUT_INVALID';end if;
   until_time:=issued+make_interval(secs=>d::double precision*86400);
   if not crm_private.offer_evidence((a->>'evidenceId')::uuid,opp,s,'offer:issue:'||vid||':'||(a->'issuance'->>'issuedAt')||':'||d,cov,issued,issued) then raise exception 'OFFER_ISSUANCE_EVIDENCE_REQUIRED';end if;
   for l in select jsonb_array_elements(a->'issuance'->'limits') loop
    if l-array['aspect','until','evidenceId']<>'{}'::jsonb or l->>'aspect' not in ('prices','availability','conditions','capacity') or not crm_private.offer_evidence((l->>'evidenceId')::uuid,opp,s,'offer:limit:'||vid||':'||(l->>'aspect')||':'||(l->>'until'),cov,'-infinity',issued) then raise exception 'OFFER_LIMIT_EVIDENCE_REQUIRED';end if;
    until_time:=least(until_time,(l->>'until')::timestamptz);
   end loop;
   insert into crm_private.b03_offer_issuances(version_id,admin_scope,issued_at,effective_until,issuance,evidence_id,actor_id,source_ref) values(vid,s,issued,until_time,a->'issuance',(a->>'evidenceId')::uuid,actor,a->>'sourceRef');
   res:=jsonb_build_object('issuedAt',issued,'effectiveUntil',until_time,'days',d);norm:=jsonb_build_array('BR-PROP-004','DM-INV-011');
  elsif action='intent' then
   if nullif(a->>'recipientId','') is null or nullif(a->>'channel','') is null then raise exception 'OFFER_RECIPIENT_REQUIRED';end if;
   res:=jsonb_build_object('pendingExternal',true,'sent',false,'versionId',vid,'recipientId',a->>'recipientId','channel',a->>'channel');norm:=jsonb_build_array('PLAN-C05','BR-COMM-002');
  elsif action='evaluate' then
   if i.version_id is null or at_time<i.issued_at then raise exception 'OFFER_ISSUANCE_REQUIRED:SM-PV-04';end if;
   pending:=at_time>i.effective_until;
   if a ? 'evidenceId' then
    if not crm_private.offer_evidence((a->>'evidenceId')::uuid,opp,s,'offer:uncertain:'||vid,cov,'-infinity',at_time) then raise exception 'OFFER_UNCERTAINTY_EVIDENCE_REQUIRED';end if;pending:=true;
   end if;
   res:=jsonb_build_object('pending',pending,'expired',at_time>i.effective_until,'rejected',false,'effectiveUntil',i.effective_until);norm:=jsonb_build_array('SM-PV-04','SM-FORB-01');
  elsif action='revalidate' then
   if i.version_id is null or at_time<i.issued_at or nullif(a->>'actId','') is null or a->>'actKind' not in ('send','accept') or jsonb_typeof(a->'reviewEvidence') is distinct from 'object' or (a->'reviewEvidence')-array['prices','availability','conditions','capacity']<>'{}'::jsonb then raise exception 'OFFER_ACT_REVIEW_REQUIRED';end if;
   foreach aspect in array array['prices','availability','conditions','capacity'] loop
    if not crm_private.offer_evidence((a->'reviewEvidence'->>aspect)::uuid,opp,s,'offer:review:'||vid||':'||(a->>'actId')||':'||(a->>'actKind')||':'||aspect,cov,greatest(i.issued_at,lo),at_time) then raise exception 'OFFER_MATERIAL_REVIEW_REQUIRED:SM-PV-05';end if;
   end loop;
   res:=jsonb_build_object('reviewedForAct',a->>'actId','actKind',a->>'actKind','at',at_time,'coverage',cov,'originalEffectiveUntil',i.effective_until,'acceptanceCreated',false);norm:=jsonb_build_array('SM-PV-05','AC-008','AC-086');
  elsif action='send' then
   if coalesce(a->>'origin','manual')<>'manual' then raise exception 'OFFER_HA_TTE_REQUIRED:G3';end if;
   if i.version_id is null or at_time<i.issued_at or (at_time>i.effective_until or stale) and not reviewed then raise exception 'OFFER_ACT_REVIEW_REQUIRED:SM-PV-03';end if;
   if nullif(a->>'actId','') is null or coalesce(a->>'actKind','send')<>'send' then raise exception 'OFFER_ACT_REVIEW_REQUIRED';end if;
   if o.state not in ('Nueva','En contacto','Necesidad definida','Propuesta en preparación','Propuesta enviada','Negociación / cambios') then raise exception 'OFFER_COMMERCIAL_ORIGIN_REQUIRED:SM-OP-05';end if;
   -- Relevant definitive economics remain blocked; provisional work remains independent.
   if exists(select 1 from jsonb_array_elements(v.content->'modalities') m join lateral jsonb_array_elements(v.economics) e on e->>'modalityId'=m->>'id' where m->'definitive'='true' and (cov=v.scope or cov=m->>'id' or exists(select 1 from jsonb_array_elements(m->'lines') z where z->>'id'=cov)) and (e->'calculated'='null' or jsonb_array_length(e->'blockers')>0)) then raise exception 'OFFER_DEFINITIVE_DATA_REQUIRED:BR-ECON-001';end if;
   -- Current material checks are B07 reviews, not availability/provider confirmations.
   foreach aspect in array array['prices','availability','conditions','capacity'] loop
    if not crm_private.offer_evidence((a->'reviewEvidence'->>aspect)::uuid,opp,s,'offer:review:'||vid||':'||(a->>'actId')||':send:'||aspect,cov,greatest(i.issued_at,lo),at_time) then raise exception 'OFFER_MATERIAL_REVIEW_REQUIRED:SM-PV-03';end if;
   end loop;
   select * into com from crm_private.b07_records where record_id=(a->>'communicationId')::uuid and admin_scope=s;
   select * into fact from crm_private.b07_records where record_id=(a->>'factId')::uuid and admin_scope=s;
   select * into proof from crm_private.b07_records where record_id=(fact.material->>'evidence_id')::uuid and admin_scope=s;
   if com.record_kind is distinct from 'communication' or com.material->>'direction' is distinct from 'outgoing' or com.material->>'proposal_version_ref' is distinct from vid::text or com.material->>'recipient_ref' is distinct from a->>'recipientId' or com.material->>'channel' is distinct from a->>'channel' or com.material->>'coverage' is distinct from cov
    or fact.record_kind is distinct from 'communication_fact' or fact.original_id is distinct from com.record_id or fact.material->>'fact_kind' is distinct from 'sent' or fact.material->>'party_ref' is distinct from a->>'recipientId' or fact.material->>'coverage' is distinct from cov or fact.occurred_at is distinct from at_time
    or proof.record_kind is distinct from 'evidence' or not crm_private.offer_evidence(proof.record_id,opp,s,'offer:sent:'||vid||':'||(a->>'actId')||':'||(a->>'recipientId')||':'||(a->>'channel'),cov,at_time,at_time)
    or not exists(select 1 from crm_private.identity_entities where identity_id=(a->>'recipientId')::uuid and admin_scope=s and identity_kind='contact' and identity_verified and archived_at is null and merged_into_id is null)
    or not exists(select 1 from crm_private.b07_links bl where bl.record_id=com.record_id and bl.admin_scope=s and bl.context_kind='opportunity' and bl.context_id=opp and bl.coverage=a->>'coverage')
    or not exists(select 1 from crm_private.b07_links bl where bl.record_id=fact.record_id and bl.admin_scope=s and bl.context_kind='opportunity' and bl.context_id=opp and bl.coverage=a->>'coverage') then raise exception 'OFFER_REAL_SEND_REQUIRED:SM-CO-04';end if;
   insert into crm_private.b03_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(op,s,actor,fp,opp);
   insert into crm_private.b03_history(history_id,subject_id,admin_scope,before_state,after_state,event,normative_ids,reason,source_ref,actor_id)
    values(op,opp,s,to_jsonb(o),jsonb_set(jsonb_set(to_jsonb(o),'{state}','"Propuesta enviada"'),'{revision}',to_jsonb(o.revision+1)),a,jsonb_build_array('SM-OP-05'),a->>'reason',a->>'sourceRef',actor);
   update crm_private.b03_opportunities set state='Propuesta enviada',revision=revision+1,updated_at=clock_timestamp() where opportunity_id=opp;
   res:=jsonb_build_object('sent',true,'received',false,'acceptanceCreated',false,'versionId',vid,'communicationId',com.record_id,'factId',fact.record_id);norm:=jsonb_build_array('SM-PV-03','SM-OP-05','SM-CO-04');
  else
   part:=nullif(a->>'partId','')::uuid;kind:=a->>'partKind';
   if kind is null or kind not in ('version','modality','line') or nullif(btrim(a->>'lossReason'),'') is null
    or kind='version' and (part is distinct from vid or cov<>v.scope)
    or kind='modality' and not exists(select 1 from crm_private.b03_proposal_modalities where version_id=vid and modality_id=part and cov=part::text)
    or kind='line' and not exists(select 1 from crm_private.b03_proposal_lines where version_id=vid and line_id=part and cov=part::text) then raise exception 'OFFER_REJECTION_SCOPE_REQUIRED';end if;
   select * into com from crm_private.b07_records where record_id=(a->>'communicationId')::uuid and admin_scope=s;
   if com.record_kind is distinct from 'communication' or com.material->>'direction' is distinct from 'incoming' or com.material->>'proposal_version_ref' is distinct from vid::text or com.material->>'sender_ref' is distinct from a->>'recipientId' or com.material->>'coverage' is distinct from cov or com.material->>'channel' is distinct from a->>'channel' or com.occurred_at is distinct from at_time
    or not exists(select 1 from crm_private.identity_entities where identity_id=(a->>'recipientId')::uuid and admin_scope=s and identity_kind='contact' and identity_verified and archived_at is null and merged_into_id is null)
    or not exists(select 1 from crm_private.b07_links bl where bl.record_id=com.record_id and bl.admin_scope=s and bl.context_kind='opportunity' and bl.context_id=opp and bl.coverage=a->>'coverage')
    or not exists(select 1 from crm_private.identity_designations d where d.context_id=opp and d.party_id=(a->>'recipientId')::uuid and d.admin_scope=s and d.role_kind='primary_contact' and d.verified and coalesce(d.effective_at,d.recorded_at)<=at_time and (d.ended_at is null or d.ended_at>at_time))
    or not crm_private.offer_evidence((a->>'evidenceId')::uuid,opp,s,'offer:reject:'||vid||':'||part||':'||(a->>'recipientId')||':'||(a->>'lossReason'),cov,at_time,at_time) then raise exception 'OFFER_ATTRIBUTABLE_REJECTION_REQUIRED:SM-PV-08';end if;
   res:=jsonb_build_object('rejected',true,'partKind',kind,'partId',part,'reason',a->>'lossReason','opportunityLost',false,'acceptanceCreated',false);norm:=jsonb_build_array('SM-PV-08','AC-005','AC-086');
  end if;
  update crm_private.b03_proposals set revision=revision+1 where proposal_id=root;
  insert into crm_private.b03_offer_operations values(op,root,vid,s,actor,fp,action,cov,at_time,a,res,a->>'sourceRef',a->>'reason',clock_timestamp());
  insert into crm_private.b03_offer_history(history_id,admin_scope,before_data,after_data,normative_ids,actor_id) values(op,s,original,res,norm,actor);
  res:=jsonb_build_object('id',op,'replayed',false,'result',res);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return res;
end $function$

CREATE OR REPLACE FUNCTION crm_api.offer_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];f text[];a jsonb;vid uuid;data jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OFFER_DENIED';end if;
 f:=crm_f1.fields(q);if cardinality(f)<>2 or f[1]<>'CRM-H2-OFFER-READ1' then raise exception 'OFFER_INPUT_INVALID';end if;a:=f[2]::jsonb;vid:=(a->>'versionId')::uuid;
 if not exists(select 1 from crm_private.b03_proposal_versions where version_id=vid and proposal_id=(a->>'proposalId')::uuid and admin_scope=hf[17]) then raise exception 'OFFER_DENIED';end if;
 select jsonb_build_object('issuance',(select to_jsonb(t) from crm_private.b03_offer_issuances t where version_id=vid),'events',coalesce((select jsonb_agg(to_jsonb(t) order by recorded_at,operation_id) from crm_private.b03_offer_operations t where version_id=vid),'[]')) into data;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return data;
end $function$

CREATE OR REPLACE FUNCTION crm_api.acceptance_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fields text[];a jsonb;p crm_private.b03_proposals;o crm_private.b03_opportunities;
 v crm_private.b03_proposal_versions;i crm_private.b03_offer_issuances;prior crm_private.b03_acceptance_operations;
 acc crm_private.b03_acceptances;com crm_private.b07_records;des crm_private.identity_designations;
 op uuid;aid uuid;root uuid;vid uuid;opp uuid;actor uuid;s text;action text;cov text;at_time timestamptz;
 fp text;res jsonb;norm jsonb;original jsonb;identified boolean;selectable boolean;valid boolean;proof_ok boolean;aspect text;
 stale_at timestamptz;reviewed boolean;destination text;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'ACCEPTANCE_DENIED';end if;
 fields:=crm_f1.fields(q);if cardinality(fields)<>2 or fields[1]<>'CRM-H2-ACCEPTANCE1' then raise exception 'ACCEPTANCE_INPUT_INVALID';end if;a:=fields[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-array['action','operationId','acceptanceId','proposalId','opportunityId','versionId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','coverage','at','accepterId','designationId','channel','terms','evidenceId','communicationId','authorityEvidenceId','reviewEvidence','won','humanReviewed','reevaluation','origin']<>'{}'::jsonb
 or not(a ?& array['action','operationId','acceptanceId','proposalId','opportunityId','versionId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','coverage','at'])
 or a->>'action' not in ('candidate','register','verify','rectify')
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or jsonb_typeof(a->'expectedOpportunityRevision') is distinct from 'number'
 or a->>'expectedRevision' !~ '^[0-9]+$' or a->>'expectedOpportunityRevision' !~ '^[0-9]+$'
 or exists(select 1 from jsonb_each(a) x where x.key in ('sourceRef','reason','coverage','at') and (jsonb_typeof(x.value)<>'string' or btrim(x.value#>>'{}')=''))
 or (a ? 'won' and jsonb_typeof(a->'won') is distinct from 'boolean')
 or (a ? 'humanReviewed' and jsonb_typeof(a->'humanReviewed') is distinct from 'boolean')
 or a->>'at' !~ '^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d+)?(Z|[+-]\d\d:\d\d)$' then raise exception 'ACCEPTANCE_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;aid:=(a->>'acceptanceId')::uuid;root:=(a->>'proposalId')::uuid;vid:=(a->>'versionId')::uuid;opp:=(a->>'opportunityId')::uuid;
 actor:=hf[12]::uuid;s:=hf[17];action:=a->>'action';cov:=a->>'coverage';at_time:=(a->>'at')::timestamptz;
 if at_time>clock_timestamp() then raise exception 'ACCEPTANCE_FUTURE_FACT';end if;
 if coalesce(a->>'origin','manual')<>'manual' then raise exception 'ACCEPTANCE_HUMAN_REVIEW_REQUIRED:G3';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(op::text,0));
 select * into prior from crm_private.b03_acceptance_operations where operation_id=op;
 if found then
  if prior.admin_scope<>s or prior.actor_id<>actor or prior.fingerprint<>fp then raise exception 'ACCEPTANCE_REPLAY_CONFLICT';end if;
  res:=jsonb_build_object('id',op,'replayed',true,'result',prior.result);
 else
  perform pg_advisory_xact_lock(hashtextextended(opp::text,31));
  select * into o from crm_private.b03_opportunities where opportunity_id=opp and admin_scope=s for update;
  if not found then raise exception 'ACCEPTANCE_RELATION_INVALID';end if;
  perform pg_advisory_xact_lock(hashtextextended(root::text,33));
  select * into p from crm_private.b03_proposals where proposal_id=root and opportunity_id=opp and admin_scope=s for update;
  if not found then raise exception 'ACCEPTANCE_RELATION_INVALID';end if;
  select * into v from crm_private.b03_proposal_versions where version_id=vid and proposal_id=root and admin_scope=s;
  if not found then raise exception 'ACCEPTANCE_RELATION_INVALID';end if;
  if p.revision<>(a->>'expectedRevision')::bigint or o.revision<>(a->>'expectedOpportunityRevision')::bigint then raise exception 'ACCEPTANCE_REVISION_CONFLICT:G6';end if;
  original:=jsonb_build_object('proposalRevision',p.revision,'opportunity',to_jsonb(o));
  select * into acc from crm_private.b03_acceptances where acceptance_id=aid and admin_scope=s;
  if acc.acceptance_id is not null and (acc.proposal_id<>root or acc.version_id<>vid or acc.opportunity_id<>opp or acc.coverage<>cov) then raise exception 'ACCEPTANCE_EXACT_RELATION_REQUIRED';end if;
  if action in ('candidate','register') then
   if acc.acceptance_id is not null then raise exception 'ACCEPTANCE_IMMUTABLE:SM-FORB-02';end if;
   select * into des from crm_private.identity_designations where designation_id=nullif(a->>'designationId','')::uuid and admin_scope=s;
   identified:=a ?& array['accepterId','designationId','channel','terms','evidenceId','authorityEvidenceId']
    and a->'terms'=v.content->'terms' and nullif(btrim(a->>'channel'),'') is not null
    and des.party_id=nullif(a->>'accepterId','')::uuid and des.context_id=opp and des.role_kind='primary_contact' and des.verified
    and coalesce(des.effective_at,des.recorded_at)<=at_time and (des.ended_at is null or des.ended_at>at_time)
    and exists(select 1 from crm_private.identity_entities e where e.identity_id=des.party_id and e.admin_scope=s and e.identity_kind='contact' and e.identity_verified)
    and crm_private.offer_evidence(nullif(a->>'authorityEvidenceId','')::uuid,opp,s,'acceptance:authority:'||vid||':'||(a->>'accepterId')||':'||(a->>'designationId'),cov,'-infinity',at_time);
   selectable:=cov=v.scope or exists(select 1 from crm_private.b03_proposal_modalities m where m.version_id=vid and m.modality_id::text=cov and m.independent and m.selectable)
    or exists(select 1 from crm_private.b03_proposal_lines l where l.version_id=vid and l.line_id::text=cov and l.independent and l.selectable);
   if action='register' and coalesce(identified,false) and selectable then
    if not exists(select 1 from crm_private.b07_records e join crm_private.b07_links l using(record_id) where e.record_id=(a->>'evidenceId')::uuid and e.admin_scope=s and l.admin_scope=s and l.context_id=opp and l.context_kind='opportunity' and l.coverage=cov and e.record_kind='evidence') then raise exception 'ACCEPTANCE_EVIDENCE_REQUIRED';end if;
    insert into crm_private.b03_acceptances(acceptance_id,proposal_id,opportunity_id,version_id,admin_scope,accepter_id,designation_id,channel,coverage,terms,content_snapshot,evidence_id,authority_evidence_id,communication_id,occurred_at,actor_id,source_ref)
     values(aid,root,opp,vid,s,(a->>'accepterId')::uuid,des.designation_id,a->>'channel',cov,v.content->'terms',v.content,(a->>'evidenceId')::uuid,(a->>'authorityEvidenceId')::uuid,nullif(a->>'communicationId','')::uuid,at_time,actor,a->>'sourceRef');
    res:=jsonb_build_object('registered',true,'verified',false,'won',false,'acceptanceId',aid);norm:=jsonb_build_array('SM-AC-01','DM-INV-009','DM-INV-010');
   else
    if not exists(select 1 from crm_private.b07_records e join crm_private.b07_links l using(record_id) where e.record_id=nullif(a->>'evidenceId','')::uuid and e.admin_scope=s and l.admin_scope=s and l.context_id=opp and l.context_kind='opportunity' and l.coverage=cov) then raise exception 'ACCEPTANCE_CANDIDATE_SOURCE_REQUIRED';end if;
    res:=jsonb_build_object('registered',false,'verified',false,'won',false,'pendingReview',true,'requiresNewVersion',not selectable);norm:=jsonb_build_array('SM-AC-01','SPEC-FR-ACC-003','E7');
   end if;
  elsif action='verify' then
   if acc.acceptance_id is null then raise exception 'ACCEPTANCE_REGISTERED_REQUIRED:SM-AC-02';end if;
   if exists(select 1 from crm_private.b03_acceptance_verifications where acceptance_id=aid and (won or not coalesce((a->>'won')::boolean,false))) or exists(select 1 from crm_private.b03_acceptance_rectifications where acceptance_id=aid) then raise exception 'ACCEPTANCE_ALREADY_DECIDED';end if;
   if at_time<>acc.occurred_at then raise exception 'ACCEPTANCE_ACT_IMMUTABLE';end if;
   -- All verification facts refer to the immutable registration, not replacement request fields.
   if a ?| array['terms','accepterId','designationId','channel','evidenceId','authorityEvidenceId','communicationId'] then raise exception 'ACCEPTANCE_REGISTRATION_IMMUTABLE';end if;
   select * into i from crm_private.b03_offer_issuances where version_id=vid and admin_scope=s;
   select max(t) into stale_at from (
    select e.occurred_at t from crm_private.b03_offer_operations e where e.version_id=vid and e.action in ('reject','evaluate') and (e.action='reject' or e.result->'pending'='true') and e.occurred_at<=at_time and crm_private.offer_overlap(vid,e.coverage,cov)
    union all select z.recorded_at from crm_private.b03_proposal_versions z where z.replaces_version_id=vid and z.recorded_at<=at_time
   ) x;
   reviewed:=exists(select 1 from crm_private.b03_offer_operations e where e.version_id=vid and e.action='revalidate' and e.coverage=cov and e.event->>'actId'=aid::text and e.event->>'actKind'='accept' and e.occurred_at=at_time and e.occurred_at>=coalesce(stale_at,'-infinity') and not exists(select 1 from jsonb_each_text(e.event->'reviewEvidence') z left join crm_private.b07_records b on b.record_id=z.value::uuid where b.occurred_at>=at_time or b.record_id is null));
   valid:=i.version_id is not null and at_time>=i.issued_at and ((at_time<=i.effective_until and stale_at is null) or reviewed);
   proof_ok:=crm_private.offer_evidence(acc.evidence_id,opp,s,'acceptance:agree:'||vid||':'||aid||':'||acc.accepter_id||':'||acc.channel,cov,at_time,at_time);
   if acc.communication_id is not null then
    select * into com from crm_private.b07_records where record_id=acc.communication_id and admin_scope=s;
    proof_ok:=proof_ok and com.record_kind='communication' and com.material->>'direction'='incoming' and com.material->>'sender_ref'=acc.accepter_id::text and com.material->>'proposal_version_ref'=vid::text and com.material->>'coverage'=cov and com.material->>'channel'=acc.channel and com.occurred_at=at_time
     and exists(select 1 from crm_private.b07_links l where l.record_id=com.record_id and l.admin_scope=s and l.context_id=opp and l.context_kind='opportunity' and l.coverage=cov);
   elsif acc.channel not in ('phone','advance') then proof_ok:=false;
   end if;
   foreach aspect in array array['prices','availability','conditions','capacity'] loop
    proof_ok:=proof_ok and crm_private.offer_evidence((a->'reviewEvidence'->>aspect)::uuid,opp,s,'offer:review:'||vid||':'||aid||':accept:'||aspect,cov,coalesce(stale_at,i.issued_at),at_time);
   end loop;
   if not coalesce(valid,false) or not coalesce(proof_ok,false) then raise exception 'ACCEPTANCE_VERIFICATION_REQUIRED:SM-AC-02,SM-FORB-01';end if;
   if exists(select 1 from jsonb_array_elements(v.economics) e where (cov=v.scope or cov=e->>'modalityId' or exists(select 1 from crm_private.b03_proposal_lines l where l.version_id=vid and l.modality_id::text=e->>'modalityId' and l.line_id::text=cov)) and (e->'calculated'='null' or jsonb_array_length(e->'blockers')>0)) then raise exception 'ACCEPTANCE_MATERIAL_DATA_REQUIRED:G2';end if;
   if coalesce((a->>'won')::boolean,false) and o.state not in ('Nueva','En contacto','Necesidad definida','Propuesta en preparación','Propuesta enviada','Negociación / cambios') then raise exception 'ACCEPTANCE_ACTIVE_ORIGIN_REQUIRED:SM-OP-07';end if;
   insert into crm_private.b03_acceptance_verifications(verification_id,acceptance_id,admin_scope,actor_id,material,won,commercial_before) values(op,aid,s,actor,a,coalesce((a->>'won')::boolean,false),to_jsonb(o));
   if coalesce((a->>'won')::boolean,false) then
    insert into crm_private.b03_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(op,s,actor,fp,opp);
    insert into crm_private.b03_history(history_id,subject_id,admin_scope,before_state,after_state,event,normative_ids,reason,source_ref,actor_id,occurred_at)
     values(op,opp,s,to_jsonb(o),jsonb_set(jsonb_set(to_jsonb(o),'{state}','"Aceptada / Ganada"'),'{revision}',to_jsonb(o.revision+1)),a,'["SM-OP-07"]',a->>'reason',a->>'sourceRef',actor,at_time);
    update crm_private.b03_opportunities set state='Aceptada / Ganada',revision=revision+1,updated_at=clock_timestamp() where opportunity_id=opp;
   end if;
   res:=jsonb_build_object('registered',true,'verified',true,'won',coalesce((a->>'won')::boolean,false),'acceptanceId',aid,'coverage',cov,'terms',acc.terms);
   norm:=jsonb_build_array('SM-AC-02','SM-PV-07','SM-OP-07','PLAN-T02');
  else
   if acc.acceptance_id is null or a->'humanReviewed' is distinct from 'true'::jsonb or exists(select 1 from crm_private.b03_acceptance_rectifications where acceptance_id=aid)
    or not crm_private.offer_evidence((a->>'evidenceId')::uuid,opp,s,'acceptance:error:'||aid,cov,'-infinity',at_time)
    or jsonb_typeof(a->'reevaluation') is distinct from 'object' or (a->'reevaluation')-array['destination','evidenceId','dependentEffects']<>'{}'::jsonb
    or a->'reevaluation'->'dependentEffects' is distinct from '["verification","commercial"]'::jsonb then raise exception 'ACCEPTANCE_ERROR_REVIEW_REQUIRED:SM-AC-03';end if;
   destination:=a->'reevaluation'->>'destination';
   if destination not in ('Nueva','En contacto','Necesidad definida','Propuesta en preparación','Propuesta enviada','Negociación / cambios')
    or not crm_private.offer_evidence((a->'reevaluation'->>'evidenceId')::uuid,opp,s,'acceptance:reevaluate:'||aid||':'||destination,cov,'-infinity',at_time) then raise exception 'ACCEPTANCE_CURRENT_COMMERCIAL_REVIEW_REQUIRED';end if;
   insert into crm_private.b03_acceptance_rectifications(rectification_id,acceptance_id,admin_scope,actor_id,evidence_id,reason,reevaluation) values(op,aid,s,actor,(a->>'evidenceId')::uuid,a->>'reason',a->'reevaluation');
   if o.state='Aceptada / Ganada' and not exists(select 1 from crm_private.b03_acceptance_verifications z join crm_private.b03_acceptances b using(acceptance_id) where b.opportunity_id=opp and z.won and not exists(select 1 from crm_private.b03_acceptance_rectifications r where r.acceptance_id=b.acceptance_id)) then
    insert into crm_private.b03_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(op,s,actor,fp,opp);
    insert into crm_private.b03_history(history_id,subject_id,admin_scope,before_state,after_state,event,normative_ids,reason,source_ref,actor_id,occurred_at) values(op,opp,s,to_jsonb(o),jsonb_set(jsonb_set(to_jsonb(o),'{state}',to_jsonb(destination)),'{revision}',to_jsonb(o.revision+1)),a,'["SM-AC-03"]',a->>'reason',a->>'sourceRef',actor,at_time);
    update crm_private.b03_opportunities set state=destination,revision=revision+1,updated_at=clock_timestamp() where opportunity_id=opp;
   end if;
   res:=jsonb_build_object('rectified',true,'originalPreserved',true,'verificationUsable',false,'reevaluation',a->'reevaluation');norm:=jsonb_build_array('SM-AC-03','SM-FORB-02','SM-FORB-32','AC-075');
  end if;
  insert into crm_private.b03_acceptance_operations(operation_id,acceptance_id,proposal_id,version_id,admin_scope,actor_id,fingerprint,action,event,result,source_ref,reason) values(op,aid,root,vid,s,actor,fp,action,a,res,a->>'sourceRef',a->>'reason');
  insert into crm_private.b03_acceptance_history(history_id,admin_scope,before_data,after_data,normative_ids,actor_id) values(op,s,original,res,norm,actor);
  update crm_private.b03_proposals set revision=revision+1 where proposal_id=root;
  res:=jsonb_build_object('id',op,'replayed',false,'result',res);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return res;
end $function$

CREATE OR REPLACE FUNCTION crm_api.acceptance_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fields text[];a jsonb;res jsonb;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'ACCEPTANCE_DENIED';end if;
 fields:=crm_f1.fields(q);if cardinality(fields)<>2 or fields[1]<>'CRM-H2-ACCEPTANCE-READ1' then raise exception 'ACCEPTANCE_INPUT_INVALID';end if;a:=fields[2]::jsonb;
 if a-array['proposalId','versionId']<>'{}'::jsonb or not exists(select 1 from crm_private.b03_proposal_versions where version_id=(a->>'versionId')::uuid and proposal_id=(a->>'proposalId')::uuid and admin_scope=hf[17]) then raise exception 'ACCEPTANCE_DENIED';end if;
 select jsonb_build_object('facts',coalesce((select jsonb_agg(to_jsonb(z) order by z.recorded_at) from crm_private.b03_acceptances z where z.version_id=(a->>'versionId')::uuid and z.admin_scope=hf[17]),'[]'),
 'operations',coalesce((select jsonb_agg(to_jsonb(z) order by z.recorded_at) from crm_private.b03_acceptance_operations z where z.version_id=(a->>'versionId')::uuid and z.admin_scope=hf[17]),'[]')) into res;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return res;
end $function$

CREATE OR REPLACE FUNCTION crm_api.booking_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea, cf2p bytea, cf2s bytea, cf1p bytea, cf1s bytea, cq bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;d jsonb;sv jsonb;c jsonb;part jsonb;ass jsonb;
 op uuid;bid uuid;opp uuid;aid uuid;actor uuid;s text;fp text;efp text;res jsonb;
 o crm_private.b03_opportunities;v crm_private.b03_proposal_versions;acc crm_private.b03_acceptances;
 z crm_private.b03_acceptance_verifications;p crm_private.b03_proposals;prior crm_private.b04_operations;
 existing crm_private.b04_bookings;line crm_private.b03_proposal_lines;m crm_private.b03_proposal_modalities;
 expected_lines uuid[];actual_lines uuid[];sr jsonb;nid uuid;pid uuid;sid uuid;ref uuid;total bigint;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'BOOKING_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H2-BOOKING1' then raise exception 'BOOKING_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-array['operationId','bookingId','opportunityId','acceptanceId','proposalId','versionId','coverage','terms','expectedRevision','expectedOpportunityRevision','sourceRef','reason','evidenceId','detail','origin','route']<>'{}'::jsonb
 or not(a ?& array['operationId','bookingId','opportunityId','acceptanceId','proposalId','versionId','coverage','terms','expectedRevision','expectedOpportunityRevision','sourceRef','reason','evidenceId','detail','route'])
 or a->>'route' not in ('normal','direct') or coalesce(a->>'origin','manual')<>'manual'
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or a->>'expectedRevision' !~ '^[0-9]+$'
 or jsonb_typeof(a->'expectedOpportunityRevision') is distinct from 'number' or a->>'expectedOpportunityRevision' !~ '^[0-9]+$'
 or exists(select 1 from jsonb_each(a) x where x.key in ('sourceRef','reason','coverage') and (jsonb_typeof(x.value)<>'string' or btrim(x.value#>>'{}')='')) then raise exception 'BOOKING_INPUT_INVALID:G3';end if;
 op:=(a->>'operationId')::uuid;bid:=(a->>'bookingId')::uuid;opp:=(a->>'opportunityId')::uuid;aid:=(a->>'acceptanceId')::uuid;actor:=hf[12]::uuid;s:=hf[17];d:=a->'detail';
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');
 -- Equivalent functional identity excludes technical key, requested root ID and optimistic versions.
 efp:=encode(crm_crypto.digest(convert_to((a-array['operationId','bookingId','expectedRevision','expectedOpportunityRevision','route'])::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(op::text,0));
 select * into prior from crm_private.b04_operations where operation_id=op;
 if found then
  if prior.admin_scope<>s or prior.actor_id<>actor or prior.fingerprint<>fp then raise exception 'BOOKING_REPLAY_CONFLICT:E2';end if;
  res:=jsonb_build_object('id',prior.booking_id,'replayed',true,'result',prior.result);
 else
  perform pg_advisory_xact_lock(hashtextextended(opp::text,31));
  select * into o from crm_private.b03_opportunities where opportunity_id=opp and admin_scope=s for update;
  if not found then raise exception 'BOOKING_CHAIN_REQUIRED';end if;
  perform pg_advisory_xact_lock(hashtextextended(a->>'proposalId',33));
  select * into p from crm_private.b03_proposals where proposal_id=(a->>'proposalId')::uuid and opportunity_id=opp and admin_scope=s for update;
  select * into acc from crm_private.b03_acceptances where acceptance_id=aid and opportunity_id=opp and proposal_id=p.proposal_id and version_id=(a->>'versionId')::uuid and admin_scope=s;
  select * into v from crm_private.b03_proposal_versions where version_id=acc.version_id and proposal_id=p.proposal_id and admin_scope=s;
  select * into z from crm_private.b03_acceptance_verifications where acceptance_id=aid and admin_scope=s order by won desc,recorded_at desc limit 1;
  if acc.acceptance_id is null or z.verification_id is null or v.version_id is null or a->'terms' is distinct from acc.terms or a->>'coverage'<>acc.coverage
   or exists(select 1 from crm_private.b03_acceptance_rectifications where acceptance_id=aid) then raise exception 'BOOKING_VERIFIED_CHAIN_REQUIRED:SM-BK-01';end if;
  select * into existing from crm_private.b04_bookings where opportunity_id=opp;
  if found then
   if existing.admin_scope<>s or existing.effect_fingerprint<>efp then raise exception 'BOOKING_EXISTING_CONFLICT:E2';end if;
   bid:=existing.booking_id;res:=jsonb_build_object('bookingId',bid,'state',existing.state,'coverage',existing.coverage,'existing',true);
  else
   if o.state<>'Aceptada / Ganada' or o.revision<>(a->>'expectedOpportunityRevision')::bigint or p.revision<>(a->>'expectedRevision')::bigint then raise exception 'BOOKING_REVISION_OR_STATE_CONFLICT:G6';end if;
   if jsonb_typeof(d) is distinct from 'object' or d-array['services','participants','assignments']<>'{}'::jsonb or jsonb_typeof(d->'services') is distinct from 'array' or jsonb_array_length(d->'services')=0
    or jsonb_typeof(d->'participants') is distinct from 'array' or jsonb_typeof(d->'assignments') is distinct from 'array' then raise exception 'BOOKING_DETAIL_REQUIRED:SM-BS-01';end if;
   if not crm_private.offer_evidence((a->>'evidenceId')::uuid,opp,s,'booking:detail:'||aid||':'||encode(crm_crypto.digest(convert_to(d::text,'UTF8'),'sha256'),'hex'),acc.coverage,'-infinity',clock_timestamp()) then raise exception 'BOOKING_DETAIL_EVIDENCE_REQUIRED';end if;
   select array_agg(l.line_id order by l.line_id) into expected_lines from crm_private.b03_proposal_lines l join crm_private.b03_proposal_modalities mm using(version_id,modality_id)
    where l.version_id=v.version_id and l.included and (acc.coverage=v.scope or (mm.modality_id::text=acc.coverage and mm.independent and mm.selectable) or (l.line_id::text=acc.coverage and l.independent and l.selectable));
   select array_agg((x->>'lineId')::uuid order by (x->>'lineId')::uuid) into actual_lines from jsonb_array_elements(d->'services') bs cross join lateral jsonb_array_elements(bs->'contributions') x;
   if expected_lines is null or actual_lines is distinct from expected_lines then raise exception 'BOOKING_EXACT_SELECTION_REQUIRED:SM-FORB-31';end if;
   insert into crm_private.identity_contexts(context_id,context_kind,admin_scope,source_ref,evidence_ref,verified) values(bid,'booking',s,a->>'sourceRef',a->>'evidenceId',true);
   insert into crm_private.b04_bookings(booking_id,opportunity_id,acceptance_id,verification_id,proposal_id,version_id,admin_scope,actor_id,responsible_actor,state,revision,coverage,terms,chain_snapshot,detail,effect_fingerprint,evidence_id,source_ref)
    values(bid,opp,aid,z.verification_id,p.proposal_id,v.version_id,s,actor,o.responsible_actor,'Pendiente de preparación',1,acc.coverage,acc.terms,jsonb_build_object('opportunity',to_jsonb(o),'acceptance',to_jsonb(acc),'verification',to_jsonb(z),'version',to_jsonb(v)),d,efp,(a->>'evidenceId')::uuid,a->>'sourceRef');
   for sv in select * from jsonb_array_elements(d->'services') loop
    if sv-array['id','serviceRevisionId','nature','variant','provider','place','schedule','contributions','nights']<>'{}'::jsonb or not(sv ?& array['id','serviceRevisionId','nature','variant','provider','place','schedule','contributions','nights'])
     or sv->>'nature' not in ('internal','external') or sv->>'nature'='internal' and sv->'provider'<>'null'::jsonb then raise exception 'BOOKING_SERVICE_INVALID';end if;
    sid:=(sv->>'id')::uuid;
    select x into sr from jsonb_array_elements(v.sources) x where x->>'id'=sv->>'serviceRevisionId' and x->>'kind'='service';
    if sr is null or sr->'definition'->>'nature'<>sv->>'nature' then raise exception 'BOOKING_SERVICE_SOURCE_INVALID';end if;
    insert into crm_private.b04_services values(sid,bid,s,'Pendiente',1,(sv->>'serviceRevisionId')::uuid,sv->>'nature',sv);
    for c in select * from jsonb_array_elements(sv->'contributions') loop
     if c-array['id','lineId','modalityId','quantity','attendees','certainty']<>'{}'::jsonb or not(c ?& array['id','lineId','modalityId','quantity','attendees','certainty']) then raise exception 'BOOKING_CONTRIBUTION_INVALID';end if;
     select * into line from crm_private.b03_proposal_lines where version_id=v.version_id and line_id=(c->>'lineId')::uuid;
     select * into m from crm_private.b03_proposal_modalities where version_id=v.version_id and modality_id=line.modality_id;
     if line.service_revision_id<>(sv->>'serviceRevisionId')::uuid or line.modality_id<>(c->>'modalityId')::uuid or line.quantity is distinct from (c->>'quantity')::numeric
      or m.participants is distinct from (c->>'attendees')::bigint or c->>'certainty' not in ('estimated','confirmed') then raise exception 'BOOKING_SOURCE_QUANTITY_REQUIRED:SM-FORB-10';end if;
     insert into crm_private.b04_modalities values(bid,m.modality_id,v.version_id,s,to_jsonb(m)) on conflict do nothing;
     insert into crm_private.b04_contributions values((c->>'id')::uuid,bid,sid,m.modality_id,v.version_id,line.line_id,s,line.quantity,m.participants,c->>'certainty',line.unit_revision_id,to_jsonb(line));
    end loop;
    for c in select * from jsonb_array_elements(sv->'nights') loop
     if c-array['id','date','contributionIds']<>'{}'::jsonb or not(c ?& array['id','date','contributionIds']) or jsonb_array_length(c->'contributionIds')=0 then raise exception 'BOOKING_NIGHT_INVALID';end if;
     nid:=(c->>'id')::uuid;insert into crm_private.b04_nights values(nid,sid,s,(c->>'date')::date);
     for ref in select value::uuid from jsonb_array_elements_text(c->'contributionIds') loop
      if not exists(select 1 from crm_private.b04_contributions bc join crm_private.b03_proposal_lines l using(version_id,line_id) where bc.contribution_id=ref and bc.service_id=sid and l.service_date=(c->>'date')::date) then raise exception 'BOOKING_NIGHT_SOURCE_INVALID';end if;
      insert into crm_private.b04_night_occupancies values(nid,ref,s);
     end loop;
    end loop;
   end loop;
   for part in select * from jsonb_array_elements(d->'participants') loop
    pid:=(part->>'id')::uuid;
    if part-array['id','name','contactId','evidenceId','sourceRef']<>'{}'::jsonb or btrim(coalesce(part->>'name',''))='' or btrim(coalesce(part->>'sourceRef',''))=''
     or not crm_private.offer_evidence((part->>'evidenceId')::uuid,opp,s,'booking:participant:'||aid||':'||pid,acc.coverage,'-infinity',clock_timestamp()) then raise exception 'BOOKING_NOMINAL_EVIDENCE_REQUIRED';end if;
    if part->>'contactId' is not null and not exists(select 1 from crm_private.identity_entities where identity_id=(part->>'contactId')::uuid and identity_kind='contact' and identity_verified and admin_scope=s) then raise exception 'BOOKING_CONTACT_VERIFICATION_REQUIRED';end if;
    insert into crm_private.b04_participants values(pid,bid,s,part->>'name',nullif(part->>'contactId','')::uuid,(part->>'evidenceId')::uuid,part->>'sourceRef');
   end loop;
   for ass in select * from jsonb_array_elements(d->'assignments') loop
    sid:=(ass->>'serviceId')::uuid;nid:=nullif(ass->>'nightId','')::uuid;pid:=(ass->>'participantId')::uuid;
    if ass-array['participantId','serviceId','nightId','necessity','evidenceId']<>'{}'::jsonb or btrim(coalesce(ass->>'necessity',''))='' or not exists(select 1 from crm_private.b04_participants where participant_id=pid and booking_id=bid)
     or not exists(select 1 from crm_private.b04_services where service_id=sid and booking_id=bid)
     or (nid is not null and not exists(select 1 from crm_private.b04_nights where night_id=nid and service_id=sid))
     or not crm_private.offer_evidence((ass->>'evidenceId')::uuid,opp,s,'booking:nominal:'||aid||':'||sid||':'||coalesce(nid::text,'service'),acc.coverage,'-infinity',clock_timestamp()) then raise exception 'BOOKING_NOMINAL_NECESSITY_REQUIRED';end if;
    insert into crm_private.b04_assignments values(pid,sid,nid,s,ass->>'necessity',(ass->>'evidenceId')::uuid);
    select coalesce(sum(bc.attendees),0) into total from crm_private.b04_contributions bc where bc.service_id=sid and (nid is null or exists(select 1 from crm_private.b04_night_occupancies no where no.contribution_id=bc.contribution_id and no.night_id=nid));
    if (select count(*) from crm_private.b04_assignments x where x.service_id=sid and x.night_id is not distinct from nid)>total then raise exception 'BOOKING_NOMINAL_DISCREPANCY_REVIEW_REQUIRED';end if;
   end loop;
   if exists(select 1 from crm_private.b04_participants x where x.booking_id=bid and not exists(select 1 from crm_private.b04_assignments y where y.participant_id=x.participant_id)) then raise exception 'BOOKING_NOMINAL_NECESSITY_REQUIRED';end if;
   fs:=crm_f1.fields(cq);
   if fs is distinct from array['CRM-H1-RESOLVE1','assign_code',bid::text,bid::text,'','RES',a->>'sourceRef',a->>'evidenceId',a->>'reason','0'] then raise exception 'BOOKING_CODE_CONTRACT_INVALID';end if;
   perform crm_api.identity_resolve(cf2p,cf2s,cf1p,cf1s,cq);
   res:=jsonb_build_object('bookingId',bid,'state','Pendiente de preparación','coverage',acc.coverage,'existing',false);
  end if;
  insert into crm_private.b04_operations values(op,bid,s,actor,fp,a,res,clock_timestamp());
  insert into crm_private.b04_history values(op,bid,s,actor,a->>'sourceRef',a->>'reason',to_jsonb(o),res,'["SM-BK-01","SM-BS-01","PLAN-T03","D018"]',clock_timestamp());
  res:=jsonb_build_object('id',bid,'replayed',false,'result',res);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return res;
end $function$

CREATE OR REPLACE FUNCTION crm_api.booking_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;r jsonb;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'BOOKING_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H2-BOOKING-READ1' then raise exception 'BOOKING_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if a-array['bookingId']<>'{}'::jsonb then raise exception 'BOOKING_INPUT_INVALID';end if;
 select jsonb_build_object('booking',to_jsonb(b),'code',ic.human_code,'history',coalesce((select jsonb_agg(to_jsonb(x) order by x.recorded_at) from crm_private.b04_history x where x.booking_id=b.booking_id),'[]')) into r
 from crm_private.b04_bookings b join crm_private.identity_codes ic on ic.target_id=b.booking_id and ic.code_kind='RES' where b.booking_id=(a->>'bookingId')::uuid and b.admin_scope=hf[17];
 r:=crm_private.modification_projection(r,hf[17]);perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');return r;
end $function$

CREATE OR REPLACE FUNCTION crm_api.obligation_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;d jsonb;c jsonb;r jsonb;before_state jsonb;part jsonb;parts jsonb;policy jsonb;
 op uuid;bid uuid;sid uuid;pid uuid;actor uuid;s text;fp text;efp text;proofhash text;rev bigint;pv bigint;amt numeric;accepted numeric;
 firstdate date;actdate date;days integer;due date;initial numeric;balance numeric;action text;
 b crm_private.b04_bookings;pr crm_private.b05_obligation_operations;ps crm_private.b05_payment_schedules;pol crm_private.b05_payment_policies;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OBLIGATION_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-OBLIGATION1' then raise exception 'OBLIGATION_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or not(a ?& array['action','operationId','bookingId','policyId','expectedRevision','sourceRef','reason','at','evidenceId'])
 or a-array['action','operationId','bookingId','policyId','expectedRevision','sourceRef','reason','at','evidenceId','origin','scheduleId','scope','scopeId','policy','definition','computed','policyVersion','selectors','slot','amount','due']<>'{}'::jsonb
 or a->>'action' not in ('publish_policy','determine','adjust') or coalesce(a->>'origin','manual')<>'manual'
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or a->>'expectedRevision' !~ '^[0-9]+$'
 or exists(select 1 from jsonb_each(a) x where x.key in ('sourceRef','reason','at') and (jsonb_typeof(x.value)<>'string' or btrim(x.value#>>'{}')=''))
 or a->>'at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'OBLIGATION_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;bid:=(a->>'bookingId')::uuid;pid:=(a->>'policyId')::uuid;actor:=hf[12]::uuid;s:=hf[17];action:=a->>'action';
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(op::text,0));
 select * into pr from crm_private.b05_obligation_operations where operation_id=op;
 if found then
  if pr.admin_scope<>s or pr.actor_id<>actor or pr.fingerprint<>fp then raise exception 'OBLIGATION_REPLAY_CONFLICT:E2';end if;
  r:=jsonb_build_object('id',pr.result->>'id','replayed',true,'result',pr.result);
 else
  select * into b from crm_private.b04_bookings where booking_id=bid and admin_scope=s;
  if not found then raise exception 'OBLIGATION_BOOKING_REQUIRED';end if;
  -- Reviewed evidence binds the complete human decision including amount/time/reference;
  -- no authority derives from customer/integration/AI payloads.
  proofhash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId','computed'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.offer_evidence((a->>'evidenceId')::uuid,b.opportunity_id,s,'obligation:'||action||':'||proofhash,b.coverage,(a->>'at')::timestamptz,(a->>'at')::timestamptz)
  then raise exception 'OBLIGATION_AUTHORIZED_EVIDENCE_REQUIRED';end if;
  if action='publish_policy' then
   if a ?| array['definition','computed','scheduleId','slot','amount','due','scope','scopeId','policy'] then raise exception 'OBLIGATION_INPUT_INVALID';end if;
   perform pg_advisory_xact_lock(hashtextextended(pid::text,51));
   select coalesce(max(version),0) into rev from crm_private.b05_payment_policies where policy_id=pid;
   if rev<>(a->>'expectedRevision')::bigint or exists(select 1 from crm_private.b05_payment_policies where policy_id=pid and admin_scope<>s)
   then raise exception 'OBLIGATION_REVISION_CONFLICT';end if;
   if jsonb_typeof(a->'policyVersion') is distinct from 'number' or (a->>'policyVersion')::bigint<>rev+1
    or jsonb_typeof(a->'selectors') is distinct from 'object' or (a->'selectors')-array['service','provider','type','case']<>'{}'::jsonb
    or exists(select 1 from jsonb_each(a->'selectors') x where jsonb_typeof(x.value) not in ('string','null')) then raise exception 'OBLIGATION_POLICY_REQUIRED';end if;
   insert into crm_private.b05_payment_policies values(pid,rev+1,s,'ordinary_50_50',a->'selectors',actor,a->>'sourceRef',a->>'reason',(a->>'evidenceId')::uuid,clock_timestamp());
   r:=jsonb_build_object('id',pid,'revision',rev+1,'rule','ordinary_50_50');
  else
   if not(a ?& array['scheduleId','scope','scopeId']) or a->>'scope' not in ('global','modality','service','night') then raise exception 'OBLIGATION_SCOPE_REQUIRED';end if;
   sid:=(a->>'scheduleId')::uuid;
   -- Root lock protects absent children and functional identity, including different keys.
   perform pg_advisory_xact_lock(hashtextextended(bid::text,52));
   if a->>'scope'='global' and a->>'scopeId'<>bid::text
    or a->>'scope'='modality' and not exists(select 1 from crm_private.b04_modalities where booking_id=bid and modality_id=(a->>'scopeId')::uuid)
    or a->>'scope'='service' and not exists(select 1 from crm_private.b04_services where booking_id=bid and service_id=(a->>'scopeId')::uuid)
    or a->>'scope'='night' and not exists(select 1 from crm_private.b04_nights n join crm_private.b04_services bs using(service_id) where bs.booking_id=bid and n.night_id=(a->>'scopeId')::uuid)
   then raise exception 'OBLIGATION_SCOPE_REQUIRED';end if;
   select * into ps from crm_private.b05_payment_schedules where booking_id=bid and scope_kind=a->>'scope' and scope_id=(a->>'scopeId')::uuid;
   if action='determine' then
    if a ?| array['slot','amount','due','policyVersion','selectors'] then raise exception 'OBLIGATION_INPUT_INVALID';end if;
    d:=a->'definition';c:=a->'computed';policy:=a->'policy';
    if jsonb_typeof(d) is distinct from 'object' or not(d ?& array['base','reference','at']) or d-array['base','reference','at','exception']<>'{}'::jsonb
     or jsonb_typeof(d->'base') is distinct from 'object' or (d->'base')-array['amount','sourceRef','version']<>'{}'::jsonb
     or not(d->'base' ?& array['amount','sourceRef','version']) or jsonb_typeof((d->'base')->'amount') is distinct from 'string' or (d->'base')->>'amount' !~ '^(0|[1-9][0-9]*)\.[0-9]{2}$'
     or coalesce((d->'base')->>'sourceRef','')='' or coalesce((d->'base')->>'version','')='' or d->>'at' is distinct from a->>'at'
     or policy-array['id','version','rule']<>'{}'::jsonb or policy->>'id' is distinct from pid::text or policy->>'rule' is distinct from 'ordinary_50_50'
    then raise exception 'OBLIGATION_MATERIAL_REQUIRED';end if;
    pv:=(policy->>'version')::bigint;
    select * into pol from crm_private.b05_payment_policies where policy_id=pid and version=pv and admin_scope=s;
    if not found then raise exception 'OBLIGATION_POLICY_REQUIRED';end if;
    -- Selectors are retained explicit application criteria, never an implicit new commercial rule.
    if pol.selectors->>'case' is not null and pol.selectors->>'case'<>bid::text
     or pol.selectors->>'service' is not null and (a->>'scope'<>'service' or pol.selectors->>'service'<>a->>'scopeId')
     or pol.selectors->>'provider' is not null and not exists(select 1 from crm_private.b04_services bs where bs.booking_id=bid and bs.service_id=(a->>'scopeId')::uuid and bs.applied->>'provider'=pol.selectors->>'provider')
     or pol.selectors->>'type' is not null and not exists(select 1 from crm_private.b04_services bs where bs.booking_id=bid and bs.service_id=(a->>'scopeId')::uuid and bs.nature=pol.selectors->>'type') then raise exception 'OBLIGATION_POLICY_SCOPE_REQUIRED';end if;
    if (d->'reference')->>'scope' is distinct from a->>'scope' or (d->'reference')->>'scopeId' is distinct from a->>'scopeId'
     or (d->'reference')->>'basis' not in ('default','express_contract') or coalesce((d->'reference')->>'sourceRef','')='' or coalesce((d->'reference')->>'version','')=''
     or coalesce((d->'reference'->'zone')->>'sourceRef','')='' or coalesce((d->'reference'->'zone')->>'version','')=''
     or not exists(select 1 from pg_timezone_names where name=(d->'reference'->'zone')->>'zone') or (d->'reference')->>'date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    then raise exception 'OBLIGATION_REFERENCE_REQUIRED';end if;
    -- No default can be guessed if any date in its scope remains pending.
    select case when bool_or(l.service_date is null) then null else min(l.service_date) end into firstdate
    from crm_private.b04_contributions bc join crm_private.b03_proposal_lines l using(version_id,line_id)
    where bc.booking_id=bid and (a->>'scope'='global' or a->>'scope'='modality' and bc.modality_id=(a->>'scopeId')::uuid or a->>'scope'='service' and bc.service_id=(a->>'scopeId')::uuid
     or a->>'scope'='night' and exists(select 1 from crm_private.b04_night_occupancies n where n.night_id=(a->>'scopeId')::uuid and n.contribution_id=bc.contribution_id));
    if (d->'reference')->>'basis'='default' and (firstdate is null or firstdate is distinct from ((d->'reference')->>'date')::date) then raise exception 'OBLIGATION_REFERENCE_REQUIRED';end if;
    amt:=((d->'base')->>'amount')::numeric;
    -- Reproducible whole selected modalities use accepted H2 prices. Other scopes require
    -- explicit evidence-bound determination, never proration or silent alteration of H2.
    if a->>'scope' in ('global','modality') and not exists(select 1 from crm_private.b04_modalities bm join crm_private.b03_proposal_lines l on l.version_id=b.version_id and l.modality_id=bm.modality_id and l.included
     where bm.booking_id=bid and (a->>'scope'='global' or bm.modality_id=(a->>'scopeId')::uuid)
     and not exists(select 1 from crm_private.b04_contributions bc where bc.booking_id=bid and bc.line_id=l.line_id)) then
     select sum(m.final_person_price*m.participants) into accepted from crm_private.b04_modalities bm join crm_private.b03_proposal_modalities m on m.version_id=b.version_id and m.modality_id=bm.modality_id
     where bm.booking_id=bid and (a->>'scope'='global' or bm.modality_id=(a->>'scopeId')::uuid);
     if accepted is not null and accepted<>amt then raise exception 'OBLIGATION_BASE_CONFLICT';end if;
    end if;
    actdate:=((a->>'at')::timestamptz at time zone ((d->'reference'->'zone')->>'zone'))::date;days:=((d->'reference')->>'date')::date-actdate;due:=((d->'reference')->>'date')::date-7;
    -- Exact numeric invariant checks on H1 output; not a second money/calc engine.
    initial:=case when days<7 then amt else round(amt/2,2) end;balance:=amt-initial;
    parts:=c->'parts';
    if jsonb_typeof(c) is distinct from 'object' or c->'policy' is distinct from policy or c->'base' is distinct from d->'base' or c->'reference' is distinct from d->'reference' or c->>'at' is distinct from a->>'at'
     or c->>'moneyVersion' is distinct from 'h1-money-d023-d028-d029-v1' or c->>'civilVersion' is distinct from 'h1-civil-d020-v1'
     or (c->'calculation')->>'algorithmVersion' is distinct from 'h1-money-d023-d028-d029-v1'
     or (c->'calculation')->'input' is distinct from jsonb_build_object('kind','percentage','base',(d->'base')->>'amount','percent',case when days<7 then '100' else '50' end)
     or (c->'calculation'->'output'->'applied')->>'amount' is distinct from to_char(initial,'FM999999999999999999999999999999990.00')
     or (c->'calculation'->'output')->>'remainder' is distinct from to_char(balance,'FM999999999999999999999999999999990.00')
     or (c->'evaluation')->>'actDate' is distinct from actdate::text or ((c->'evaluation')->>'daysBefore')::integer is distinct from days
     or c->'ordinary' is distinct from (case when days<7 then jsonb_build_array(jsonb_build_object('slot','initial','amount',(d->'base')->>'amount','due',jsonb_build_object('kind','before_confirmation')))
      else jsonb_build_array(jsonb_build_object('slot','initial','amount',to_char(initial,'FM999999999999999999999999999999990.00'),'due',jsonb_build_object('kind','at_confirmation')),jsonb_build_object('slot','balance','amount',to_char(balance,'FM999999999999999999999999999999990.00'),'due',jsonb_build_object('kind','civil','date',due::text))) end)
    then raise exception 'OBLIGATION_CALCULATION_INVALID';end if;
    if jsonb_typeof(parts) is distinct from 'array' or jsonb_array_length(parts) not between 1 and 2
     or exists(select 1 from jsonb_array_elements(parts) x where not crm_private.obligation_part_valid(x))
     or (select count(distinct x->>'slot') from jsonb_array_elements(parts) x)<>jsonb_array_length(parts)
     or (select sum((x->>'amount')::numeric) from jsonb_array_elements(parts) x)<>amt then raise exception 'OBLIGATION_PART_INVALID';end if;
    if d ? 'exception' then
     if (d->'exception')-array['reason','parts']<>'{}'::jsonb or coalesce(btrim((d->'exception')->>'reason'),'')='' or c->'exception' is distinct from d->'exception' or parts is distinct from (d->'exception')->'parts'
     then raise exception 'OBLIGATION_EXCEPTION_REQUIRED';end if;
    elsif parts is distinct from c->'ordinary' or c ? 'exception' then raise exception 'OBLIGATION_EXCEPTION_REQUIRED';end if;
    efp:=encode(crm_crypto.digest(convert_to((a-array['operationId','scheduleId','expectedRevision','evidenceId','computed'])::text,'UTF8'),'sha256'),'hex');
    if ps.schedule_id is not null then
     if ps.effect_fingerprint<>efp then raise exception 'OBLIGATION_EXISTS_CONFLICT';end if;
     sid:=ps.schedule_id;r:=jsonb_build_object('id',sid,'revision',1,'existing',true);
    else
     if (a->>'expectedRevision')::bigint<>0 then raise exception 'OBLIGATION_REVISION_CONFLICT';end if;
     insert into crm_private.b05_payment_schedules values(sid,bid,s,a->>'scope',(a->>'scopeId')::uuid,pid,pv,actor,efp,clock_timestamp());
     c:=c||jsonb_build_object('policyApplied',to_jsonb(pol),'bookingChain',b.chain_snapshot,'bookingVersion',b.version_id,'evidenceId',a->>'evidenceId','actorId',actor,'reason',a->>'reason');
     insert into crm_private.b05_schedule_revisions values(sid,1,s,c,actor,clock_timestamp());
     for part in select value from jsonb_array_elements(parts) loop insert into crm_private.b05_expected_payments values(sid,part->>'slot',s,(part->>'amount')::numeric,part->'due');end loop;
     r:=jsonb_build_object('id',sid,'revision',1,'existing',false);
    end if;
   else
    if a ?| array['definition','computed','policy','policyVersion','selectors'] or ps.schedule_id is null or ps.schedule_id<>sid or ps.policy_id<>pid then raise exception 'OBLIGATION_ADJUSTMENT_REQUIRED';end if;
    select revision,snapshot into rev,before_state from crm_private.b05_schedule_revisions where schedule_id=sid order by revision desc limit 1;
    if rev<>(a->>'expectedRevision')::bigint then raise exception 'OBLIGATION_REVISION_CONFLICT';end if;
    part:=jsonb_build_object('slot',a->>'slot','amount',a->>'amount','due',a->'due');
    if not crm_private.obligation_part_valid(part) or not exists(select 1 from crm_private.b05_expected_payments where schedule_id=sid and slot=a->>'slot') then raise exception 'OBLIGATION_ADJUSTMENT_REQUIRED';end if;
    select value into d from jsonb_array_elements(before_state->'parts') where value->>'slot'=a->>'slot';
    select jsonb_agg(case when x->>'slot'=a->>'slot' then part else x end order by ord) into parts from jsonb_array_elements(before_state->'parts') with ordinality z(x,ord);
    c:=jsonb_set(before_state,'{parts}',parts);
    insert into crm_private.b05_schedule_revisions values(sid,rev+1,s,c,actor,clock_timestamp());
    insert into crm_private.b05_obligation_adjustments values(op,sid,a->>'slot',rev+1,s,d,part,(a->>'amount')::numeric-(d->>'amount')::numeric,actor,a->>'reason',a->>'sourceRef',(a->>'evidenceId')::uuid,clock_timestamp());
    r:=jsonb_build_object('id',sid,'revision',rev+1,'originalRetained',true);
   end if;
  end if;
  insert into crm_private.b05_obligation_operations values(op,bid,s,actor,fp,a,r,clock_timestamp());
  insert into crm_private.b05_obligation_history values(op,bid,s,actor,before_state,r,a->>'sourceRef',a->>'reason',(a->>'evidenceId')::uuid,(a->>'at')::timestamptz,clock_timestamp());
  r:=jsonb_build_object('id',r->>'id','replayed',false,'result',r);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end $function$

CREATE OR REPLACE FUNCTION crm_api.obligation_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;r jsonb;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OBLIGATION_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-OBLIGATION-READ1' then raise exception 'OBLIGATION_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-array['bookingId','scheduleId']<>'{}'::jsonb or not(a ?& array['bookingId','scheduleId']) then raise exception 'OBLIGATION_INPUT_INVALID';end if;
 select jsonb_build_object('coverage',crm_private.fund_coverage(ps.schedule_id,hf[17]),'current',(select to_jsonb(x) from crm_private.b05_schedule_revisions x where x.schedule_id=ps.schedule_id order by revision desc limit 1),
 'original',(select jsonb_agg(jsonb_build_object('slot',x.slot,'amount',to_char(x.amount,'FM999999999999999999999999999999990.00'),'due',x.due) order by x.slot) from crm_private.b05_expected_payments x where x.schedule_id=ps.schedule_id),
 'history',coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('difference',x.difference::text) order by x.revision) from crm_private.b05_obligation_adjustments x where x.schedule_id=ps.schedule_id),'[]')) into r
 from crm_private.b05_payment_schedules ps where ps.schedule_id=(a->>'scheduleId')::uuid and ps.booking_id=(a->>'bookingId')::uuid and ps.admin_scope=hf[17];
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end $function$

CREATE OR REPLACE FUNCTION crm_private.payment_summary(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare gross numeric;v numeric:=0;historical numeric:=0;susp numeric:=0;c jsonb;i jsonb;lo numeric;hi numeric;cur numeric;lastlo numeric;lasthi numeric;unions jsonb:='[]';
begin
 if p->'receipt'='null'::jsonb then return jsonb_build_object('grossReceived',null,'verifiedCorrespondence','0.00','unreconciled',null,'suspended',null,
 'base',case when jsonb_array_length(p->'correspondences')>0 then 'pending_reconciliation' else 'detected' end,
 'incidence',exists(select 1 from jsonb_array_elements(p->'incidents') x where not (x->>'resolved')::boolean),'algorithmVersion','h1-money-d023-d028-d029-v1');end if;
 gross:=(p->'receipt'->>'amount')::numeric;
 for i in select value from jsonb_array_elements(p->'incidents') where not(value->>'resolved')::boolean order by (value->>'start')::numeric loop
  lo:=(i->>'start')::numeric;hi:=lo+(i->>'amount')::numeric;
  if lastlo is null then lastlo:=lo;lasthi:=hi;
  elsif lo<=lasthi then lasthi:=greatest(lasthi,hi);
  else unions:=unions||jsonb_build_array(jsonb_build_object('lo',lastlo::text,'hi',lasthi::text));lastlo:=lo;lasthi:=hi;end if;
 end loop;
 if lastlo is not null then unions:=unions||jsonb_build_array(jsonb_build_object('lo',lastlo::text,'hi',lasthi::text));end if;
 for i in select value from jsonb_array_elements(unions) loop susp:=susp+(i->>'hi')::numeric-(i->>'lo')::numeric;end loop;
 for c in select value from jsonb_array_elements(p->'correspondences') where value->>'status'='verified' loop
  lo:=(c->>'start')::numeric;hi:=lo+(c->>'amount')::numeric;cur:=(c->>'amount')::numeric;historical:=historical+cur;
  for i in select value from jsonb_array_elements(unions) loop cur:=cur-greatest(0,least(hi,(i->>'hi')::numeric)-greatest(lo,(i->>'lo')::numeric));end loop;
  v:=v+cur;
 end loop;
 return jsonb_build_object('grossReceived',trunc(gross,2)::text,'verifiedCorrespondence',trunc(v,2)::text,'unreconciled',trunc(gross-v,2)::text,'suspended',trunc(susp,2)::text,
 'base',case when historical=gross then 'reconciled' when jsonb_array_length(p->'correspondences')>0 then 'pending_reconciliation' else 'detected' end,'incidence',susp>0,'algorithmVersion','h1-money-d023-d028-d029-v1');
end $function$

CREATE OR REPLACE FUNCTION crm_api.payment_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;d jsonb;current_state jsonb;before_state jsonb;r jsonb;rc jsonb;oldrc jsonb;inc jsonb;keydata jsonb;newreceipt jsonb;
 op uuid;pid uuid;requested uuid;actor uuid;s text;fp text;proofhash text;effecthash text;action text;rev bigint;at_time timestamptz;canonical uuid;rid uuid;iid uuid;
 p crm_private.b05_customer_payments;prev crm_private.b05_payment_operations;b crm_private.b04_bookings;oldreceipt crm_private.b05_payment_receipts;
 start_at numeric;amt numeric;gross numeric;end_at numeric;changed boolean:=true;allowed text[];
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'PAYMENT_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-PAYMENT1' then raise exception 'PAYMENT_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 action:=a->>'action';allowed:=array['action','operationId','paymentId','expectedRevision','sourceRef','reason','at','evidenceId','origin'];
 if action='detect' then allowed:=allowed||array['detection','sourceEvidenceId','presentedEvidenceId'];
 elsif action='receive' then allowed:=allowed||array['amount','identity','sourceEvidenceId','discrepancy'];
 elsif action='propose' then allowed:=allowed||array['reconciliationId','start','amount','bookingId','scheduleId','slot'];
 elsif action='verify' then allowed:=allowed||array['reconciliationId','sourceEvidenceId'];
 elsif action='discrepancy' then allowed:=allowed||array['reconciliationId','incidentId','start','amount'];
 elsif action='rectify' then allowed:=allowed||array['reconciliationId','incidentId','start','amount','bookingId','scheduleId','slot','sourceEvidenceId'];
 elsif action='resolve' then allowed:=allowed||array['incidentId','sourceEvidenceId'];
 else raise exception 'PAYMENT_INPUT_INVALID';end if;
 if jsonb_typeof(a) is distinct from 'object' or a-allowed<>'{}'::jsonb or not(a ?& array['action','operationId','paymentId','expectedRevision','sourceRef','reason','at','evidenceId'])
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or a->>'expectedRevision' !~ '^[0-9]+$'
 or coalesce(a->>'origin','manual') not in ('manual','ai') or (coalesce(a->>'origin','manual')='ai' and action<>'propose')
 or exists(select 1 from jsonb_each(a) x where x.key in ('sourceRef','reason','at') and (jsonb_typeof(x.value)<>'string' or btrim(x.value#>>'{}')='' or length(x.value#>>'{}')>16384))
