  r:=jsonb_build_object('id',pid,'replayed',false,'result',jsonb_build_object('revision',rev,'effects',results,'summary',crm_private.fund_summary(pid,s)));
  insert into crm_private.b05_fund_operations values(op,pid,s,actor,fp,a,r,clock_timestamp());
  insert into crm_private.b05_fund_history values(op,pid,s,old,r,actor,a->>'reason',a->>'sourceRef',(a->>'evidenceId')::uuid,at_time,clock_timestamp());
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.allocation_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;pid uuid;s text;rev bigint;pr bigint;r jsonb;coverage jsonb:='[]';sid uuid;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'ALLOCATION_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-ALLOCATION-READ1' then raise exception 'ALLOCATION_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-'paymentId'<>'{}'::jsonb or not(a?'paymentId') then raise exception 'ALLOCATION_INPUT_INVALID';end if;pid:=(a->>'paymentId')::uuid;s:=hf[17];
 select revision into pr from crm_private.b05_payment_revisions where payment_id=pid and admin_scope=s order by revision desc limit 1;
 if found then
  select coalesce(max(revision),0) into rev from crm_private.b05_fund_revisions where payment_id=pid and admin_scope=s;
  for sid in select distinct schedule_id from crm_private.b05_reconciliations where payment_id=pid and admin_scope=s order by schedule_id loop coverage:=coverage||crm_private.fund_coverage(sid,s);end loop;
  r:=jsonb_build_object('revision',rev,'paymentRevision',pr,'summary',crm_private.fund_summary(pid,s),'allocations',crm_private.fund_allocations(pid,s),
   'acts',coalesce((select jsonb_agg(to_jsonb(z)||jsonb_build_object('signed_amount',trunc(z.signed_amount,2)::text,'start_amount',trunc(z.start_amount,2)::text) order by recorded_at,act_id) from crm_private.b05_allocation_acts z where z.payment_id=pid and z.admin_scope=s),'[]'),
   'coverage',coverage,'history',coalesce((select jsonb_agg(to_jsonb(z) order by recorded_at) from crm_private.b05_fund_history z where z.payment_id=pid and z.admin_scope=s),'[]'),
   'distributions',coalesce((select jsonb_agg(to_jsonb(z) order by recorded_at) from crm_private.b05_fund_distributions z where z.payment_id=pid and z.admin_scope=s),'[]'));
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_private.invoice_services(ids jsonb, bid uuid, s text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare id jsonb;
begin
 if jsonb_typeof(ids) is distinct from 'array' or jsonb_array_length(ids)=0 or (select count(distinct value) from jsonb_array_elements(ids))<>jsonb_array_length(ids) then return false;end if;
 for id in select value from jsonb_array_elements(ids) loop
  if jsonb_typeof(id) is distinct from 'string' or not exists(select 1 from crm_private.b04_services bs where bs.service_id=(id#>>'{}')::uuid and bs.booking_id=bid and bs.admin_scope=s and bs.nature='external') then return false;end if;
 end loop;return true;
end$function$

CREATE OR REPLACE FUNCTION crm_private.invoice_original(d jsonb, bid uuid, s text, previous uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare r crm_private.b07_records;o crm_private.b07_object_versions;issuer jsonb;
begin
 if jsonb_typeof(d) is distinct from 'object' or d-array['documentId','objectVersionId','issuerRevisionId','recipientId','amount','serviceIds']<>'{}'::jsonb or not(d ?& array['documentId','objectVersionId','issuerRevisionId','recipientId','amount','serviceIds'])
 or exists(select 1 from unnest(array['documentId','objectVersionId','issuerRevisionId','recipientId']) k where not coalesce(crm_private.invoice_text(d->k),false))
 or not coalesce(crm_private.invoice_amount(d->'amount'),false) or not crm_private.invoice_services(d->'serviceIds',bid,s) then raise exception 'INVOICE_DOCUMENT_REQUIRED';end if;
 select * into r from crm_private.b07_records where record_id=(d->>'documentId')::uuid and admin_scope=s and record_kind='document';
 if not found or r.material->>'relation'<>'original' or r.corrects_id is distinct from previous or not exists(select 1 from crm_private.b07_links where record_id=r.record_id and admin_scope=s and context_kind='booking' and context_id=bid) then raise exception 'INVOICE_ORIGINAL_REQUIRED';end if;
 select * into o from crm_private.b07_object_versions where version_id=(d->>'objectVersionId')::uuid and document_id=r.record_id and admin_scope=s and state='stored';
 if not found then raise exception 'INVOICE_ORIGINAL_REQUIRED';end if;
 select to_jsonb(cr) into issuer from crm_private.catalog_revisions cr join crm_private.catalog_items ci using(item_id) where cr.revision_id=(d->>'issuerRevisionId')::uuid and cr.admin_scope=s and ci.item_kind='provider';
 if issuer is null or not exists(select 1 from crm_private.identity_entities where identity_id=(d->>'recipientId')::uuid and admin_scope=s) then raise exception 'INVOICE_DOCUMENT_REQUIRED';end if;
 -- Keep reproducible object metadata, without exposing private references in invoice projections.
 return d||jsonb_build_object('issuerApplied',issuer,'conservation',jsonb_build_object('version',o.version_number,'digest',o.expected_digest,'size',o.expected_size::text,'media',o.expected_media,'sourceRef',r.source_ref,'recordedAt',r.recorded_at));
end$function$

CREATE OR REPLACE FUNCTION crm_api.invoice_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;op uuid;iid uuid;bid uuid;actor uuid;s text;action text;fp text;proofhash text;rev bigint;at_time timestamptz;
 prev crm_private.b05_invoice_operations;root crm_private.b05_provider_invoices;b crm_private.b04_bookings;d jsonb;basis jsonb;old jsonb;state jsonb;r jsonb;diffs jsonb;item jsonb;sum_amount numeric;key text;prior_doc uuid;provider jsonb;client jsonb;comparison jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'INVOICE_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-INVOICE1' then raise exception 'INVOICE_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or not(a ?& array['action','operationId','invoiceId','bookingId','expectedRevision','sourceRef','reason','at','evidenceId'])
 or exists(select 1 from unnest(array['action','operationId','invoiceId','bookingId','sourceRef','reason','at','evidenceId']) k where not coalesce(crm_private.invoice_text(a->k),false))
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or a->>'expectedRevision' !~ '^(0|[1-9][0-9]*)$'
 or coalesce(a->>'origin','manual')<>'manual' or (a?'origin' and jsonb_typeof(a->'origin') is distinct from 'string')
 or a->>'action' not in ('need','receive','review','link','correct') or a->>'at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'INVOICE_INPUT_INVALID';end if;
 action:=a->>'action';
 if a-array['action','operationId','invoiceId','bookingId','expectedRevision','sourceRef','reason','at','evidenceId','origin']-
 (case action when 'need' then array['basis'] when 'receive' then array['document'] when 'review' then array['checks','comparisonBasis'] when 'link' then array['portions'] else array['document','affectedServiceIds','affectedRecipientId','affectedAmount'] end)<>'{}'::jsonb then raise exception 'INVOICE_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;iid:=(a->>'invoiceId')::uuid;bid:=(a->>'bookingId')::uuid;actor:=hf[12]::uuid;s:=hf[17];at_time:=(a->>'at')::timestamptz;
 select * into b from crm_private.b04_bookings where booking_id=bid and admin_scope=s;if not found then raise exception 'INVOICE_DENIED';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('invoice-op:'||op,0));
 select * into prev from crm_private.b05_invoice_operations where operation_id=op;
 if found then
  if prev.admin_scope<>s or prev.actor_id<>actor or prev.fingerprint<>fp then raise exception 'INVOICE_REPLAY_CONFLICT:E2';end if;r:=prev.result||jsonb_build_object('replayed',true);
 else
  proofhash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.payment_evidence((a->>'evidenceId')::uuid,iid,s,'invoice:'||action||':'||proofhash,at_time,true)
  or not exists(select 1 from crm_private.b07_records where record_id=(a->>'evidenceId')::uuid and recorded_by=actor) then raise exception 'INVOICE_EVIDENCE_REQUIRED';end if;
  if action='need' then
   basis:=a->'basis';
   if jsonb_typeof(basis) is distinct from 'object' or basis-array['providerRevisionId','recipientId','amount','serviceIds','sourceRef','version']<>'{}'::jsonb or not(basis ?& array['providerRevisionId','recipientId','amount','serviceIds','sourceRef','version'])
   or exists(select 1 from unnest(array['providerRevisionId','recipientId','sourceRef','version']) k where not coalesce(crm_private.invoice_text(basis->k),false))
   or (basis->'amount'<>'null'::jsonb and not coalesce(crm_private.invoice_amount(basis->'amount'),false)) or not crm_private.invoice_services(basis->'serviceIds',bid,s) or (a->>'expectedRevision')::bigint<>0 then raise exception 'INVOICE_BASIS_REQUIRED';end if;
   select to_jsonb(cr) into provider from crm_private.catalog_revisions cr join crm_private.catalog_items ci using(item_id) where cr.revision_id=(basis->>'providerRevisionId')::uuid and cr.admin_scope=s and ci.item_kind='provider';
   select to_jsonb(e) into client from crm_private.identity_entities e where e.identity_id=(basis->>'recipientId')::uuid and e.admin_scope=s and e.identity_verified;
   if provider is null or client is null then raise exception 'INVOICE_BASIS_REQUIRED';end if;
   -- The reviewed C04 assertion binds the pertinent client/provider/base to these services.
   key:=encode(crm_crypto.digest(convert_to(basis::text,'UTF8'),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('invoice-need:'||bid||':'||key,0));
   select * into root from crm_private.b05_provider_invoices where booking_id=bid and admin_scope=s and need_key=key;
   if found then
    select revision,after_data into rev,state from crm_private.b05_invoice_revisions where invoice_id=root.invoice_id order by revision desc limit 1;iid:=root.invoice_id;
   else
    perform pg_advisory_xact_lock(hashtextextended('invoice-root:'||iid,0));
    insert into crm_private.b05_provider_invoices values(iid,bid,s,key,basis,op);
    rev:=1;state:=jsonb_build_object('id',iid,'bookingId',bid,'revision',rev,'status','Pendiente','basis',basis,'basisApplied',jsonb_build_object('provider',provider,'client',client,'bookingRevision',b.revision),'document',null,'review',null,'link',null,'incident',null);
    insert into crm_private.b05_invoice_revisions values(iid,rev,s,op,action,a,null,state,actor,(a->>'evidenceId')::uuid,a->>'reason',a->>'sourceRef',at_time,clock_timestamp());
   end if;
  else
   perform pg_advisory_xact_lock(hashtextextended('invoice-root:'||iid,0));
   select * into root from crm_private.b05_provider_invoices where invoice_id=iid and booking_id=bid and admin_scope=s;
   if not found then raise exception 'INVOICE_DENIED';end if;
   select revision,after_data into rev,old from crm_private.b05_invoice_revisions where invoice_id=iid order by revision desc limit 1;
   if rev<>(a->>'expectedRevision')::bigint then raise exception 'INVOICE_REVISION_CONFLICT:E2';end if;
   basis:=root.basis;state:=old;
   if action='receive' or (action='correct' and a?'document') then
    prior_doc:=case when action='correct' then (old->'document'->>'documentId')::uuid else null end;
    d:=crm_private.invoice_original(a->'document',bid,s,prior_doc);
    perform pg_advisory_xact_lock(hashtextextended('invoice-document:'||(d->>'documentId'),0));
    if action='receive' and old->>'status'<>'Pendiente' then
     if old->'document' is distinct from d then raise exception 'INVOICE_DOCUMENT_CONFLICT:E2';end if;
     r:=jsonb_build_object('id',iid,'replayed',true,'result',old);
     insert into crm_private.b05_invoice_operations values(op,iid,s,actor,fp,r,rev,clock_timestamp());
     perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
    end if;
    insert into crm_private.b05_invoice_documents values((d->>'documentId')::uuid,(d->>'objectVersionId')::uuid,iid,s,d,prior_doc,op);
    state:=state||jsonb_build_object('document',d);
   end if;
   if action='receive' then state:=state||jsonb_build_object('status','Recibida');
   elsif action='review' then
    if old->>'status' not in ('Recibida','Incidencia') or old->'document'='null'::jsonb or a->'checks' is distinct from '{"provider":true,"recipient":true,"amount":true,"scope":true}'::jsonb then raise exception 'INVOICE_REVIEW_REQUIRED';end if;
    -- Identifying a need does not require knowing its comparison amount.
    -- A subsequently verified base is a new review fact; the initial basis stays immutable.
    if a?'comparisonBasis' then
     comparison:=a->'comparisonBasis';
     if jsonb_typeof(comparison) is distinct from 'object' or comparison-array['providerRevisionId','recipientId','amount','serviceIds','sourceRef','version']<>'{}'::jsonb
     or not(comparison ?& array['providerRevisionId','recipientId','amount','serviceIds','sourceRef','version'])
     or not coalesce(crm_private.invoice_amount(comparison->'amount'),false)
     or not coalesce(crm_private.invoice_text(comparison->'sourceRef'),false) or not coalesce(crm_private.invoice_text(comparison->'version'),false)
     or comparison->'providerRevisionId' is distinct from basis->'providerRevisionId' or comparison->'recipientId' is distinct from basis->'recipientId' or comparison->'serviceIds' is distinct from basis->'serviceIds'
     or (basis->'amount'<>'null'::jsonb and comparison->'amount' is distinct from basis->'amount') then raise exception 'INVOICE_REVIEW_REQUIRED:E3';end if;
     basis:=comparison;
    end if;
    if basis->'amount'='null'::jsonb then raise exception 'INVOICE_REVIEW_REQUIRED:E3';end if;
    d:=old->'document';diffs:='[]';
    if old->'basisApplied'->'provider'->>'item_id' is distinct from d->'issuerApplied'->>'item_id' then diffs:=diffs||'"provider"'::jsonb;end if;
    if basis->>'recipientId'<>d->>'recipientId' then diffs:=diffs||'"recipient"'::jsonb;end if;
    if basis->>'amount'<>d->>'amount' then diffs:=diffs||'"amount"'::jsonb;end if;
    if (select jsonb_agg(value order by value) from jsonb_array_elements(basis->'serviceIds')) is distinct from (select jsonb_agg(value order by value) from jsonb_array_elements(d->'serviceIds')) then diffs:=diffs||'"scope"'::jsonb;end if;
    state:=state||jsonb_build_object('status',case when diffs='[]'::jsonb then 'Revisada' else 'Incidencia' end,'review',jsonb_build_object('operationId',op,'evidenceId',a->>'evidenceId','actorId',actor,'at',a->>'at','basis',basis,'document',d,'differences',diffs,'operationalOnly',true),'link',null,'incident',case when diffs='[]'::jsonb then null else jsonb_build_object('sourceRef',a->>'sourceRef','reason',a->>'reason','differences',diffs) end);
   elsif action='link' then
    if old->>'status'<>'Revisada' or old->'review'='null'::jsonb or jsonb_typeof(a->'portions') is distinct from 'array' or jsonb_array_length(a->'portions')<>jsonb_array_length(basis->'serviceIds') or jsonb_array_length(a->'portions')=0 then raise exception 'INVOICE_LINK_REQUIRED';end if;
    if (select count(distinct value->>'serviceId') from jsonb_array_elements(a->'portions'))<>jsonb_array_length(a->'portions') then raise exception 'INVOICE_PORTIONS_REQUIRED';end if;
    sum_amount:=0;
    for item in select value from jsonb_array_elements(a->'portions') loop
     if jsonb_typeof(item) is distinct from 'object' or item-array['serviceId','amount','sourceRef']<>'{}'::jsonb or not coalesce(crm_private.invoice_text(item->'serviceId'),false) or not coalesce(crm_private.invoice_text(item->'sourceRef'),false)
     or not coalesce(crm_private.invoice_amount(item->'amount'),false) or not (basis->'serviceIds' @> jsonb_build_array(item->'serviceId')) then raise exception 'INVOICE_PORTIONS_REQUIRED';end if;
     sum_amount:=sum_amount+(item->>'amount')::numeric;
    end loop;
    if sum_amount<>(old->'document'->>'amount')::numeric then raise exception 'INVOICE_PORTIONS_REQUIRED';end if;
    state:=state||jsonb_build_object('status','Vinculada','link',jsonb_build_object('operationId',op,'reviewOperationId',old->'review'->>'operationId','documentId',old->'document'->>'documentId','portions',a->'portions','sourceRef',a->>'sourceRef','actorId',actor,'at',a->>'at','externalContext',old->'review'->'basis','documentaryOnly',true));
   elsif action='correct' then
    if old->>'status' not in ('Recibida','Revisada','Vinculada','Incidencia') or old->'document'='null'::jsonb
    or not coalesce(crm_private.invoice_text(a->'affectedRecipientId'),false) or not coalesce(crm_private.invoice_amount(a->'affectedAmount'),false)
    or not crm_private.invoice_services(a->'affectedServiceIds',bid,s) or not ((basis->'serviceIds') @> (a->'affectedServiceIds'))
    or not exists(select 1 from crm_private.identity_entities where identity_id=(a->>'affectedRecipientId')::uuid and admin_scope=s) then raise exception 'INVOICE_CORRECTION_REQUIRED';end if;
    state:=state||jsonb_build_object('status','Incidencia','review',null,'link',null,'incident',jsonb_build_object('operationId',op,'sourceRef',a->>'sourceRef','reason',a->>'reason','previousDocumentId',old->'document'->>'documentId','affectedServiceIds',a->'affectedServiceIds','affectedRecipientId',a->>'affectedRecipientId','affectedAmount',a->>'affectedAmount','requiresReview',true,'requiresLink',true));
   end if;
   rev:=rev+1;state:=state||jsonb_build_object('revision',rev);
   insert into crm_private.b05_invoice_revisions values(iid,rev,s,op,action,a,old,state,actor,(a->>'evidenceId')::uuid,a->>'reason',a->>'sourceRef',at_time,clock_timestamp());
  end if;
  r:=jsonb_build_object('id',iid,'replayed',false,'result',state);
  insert into crm_private.b05_invoice_operations values(op,iid,s,actor,fp,r,rev,clock_timestamp());
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.invoice_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;s text;r jsonb;iid uuid;bid uuid;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'INVOICE_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-INVOICE-READ1' then raise exception 'INVOICE_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-array['invoiceId','bookingId']<>'{}'::jsonb or not coalesce(crm_private.invoice_text(a->'invoiceId'),false) or not coalesce(crm_private.invoice_text(a->'bookingId'),false) then raise exception 'INVOICE_INPUT_INVALID';end if;
 iid:=(a->>'invoiceId')::uuid;bid:=(a->>'bookingId')::uuid;s:=hf[17];
 select after_data into r from crm_private.b05_invoice_revisions v join crm_private.b05_provider_invoices i using(invoice_id) where i.invoice_id=iid and i.booking_id=bid and i.admin_scope=s and v.admin_scope=s order by v.revision desc limit 1;
 if r is not null then r:=r||jsonb_build_object('history',(select jsonb_agg(jsonb_build_object('revision',revision,'action',action_kind,'before',before_data,'after',after_data,'actorId',actor_id,'reason',reason,'sourceRef',source_ref,'evidenceId',evidence_id,'at',occurred_at,'recordedAt',recorded_at) order by revision) from crm_private.b05_invoice_revisions where invoice_id=iid and admin_scope=s));end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_private.suplido_funds(ids jsonb, bid uuid, service uuid, s text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare id jsonb;a jsonb;p jsonb;entries jsonb:='[]';assigned numeric:=0;usable numeric:=0;consumed numeric:=0;usable_consumed numeric:=0;u numeric;act record;
begin
 if jsonb_typeof(ids) is distinct from 'array' or (select count(distinct value) from jsonb_array_elements(ids))<>jsonb_array_length(ids) then raise exception 'SUPLIDO_FUNDS_REQUIRED';end if;
 -- Caller locks shared payment roots before any source reads.
 for id in select value from jsonb_array_elements(ids) order by value loop
  select ar.snapshot into a from crm_private.b05_allocation_revisions ar join crm_private.b05_allocations al using(allocation_id)
   where al.allocation_id=(id#>>'{}')::uuid and al.admin_scope=s and al.booking_id=bid and al.service_id=service and al.purpose='managed_client_funds' and ar.admin_scope=s order by ar.revision desc limit 1;
  if a is null then raise exception 'SUPLIDO_FUNDS_REQUIRED';end if;
  select snapshot into p from crm_private.b05_payment_revisions where payment_id=(a->>'paymentId')::uuid and admin_scope=s order by revision desc limit 1;
  u:=crm_private.fund_usable(a,p);if a->>'status'='verified' then assigned:=assigned+(a->>'amount')::numeric;end if;usable:=usable+u;
  for act in select z.* from crm_private.b05_allocation_acts z where z.allocation_id=(a->>'id')::uuid and z.kind='consume' and not exists(select 1 from crm_private.b05_allocation_acts r where r.original_act_id=z.act_id) loop
   consumed:=consumed-act.signed_amount;
   usable_consumed:=usable_consumed+crm_private.fund_usable(a||jsonb_build_object('start',trunc(act.start_amount,2)::text,'amount',trunc(-act.signed_amount,2)::text),p);
  end loop;
  entries:=entries||jsonb_build_array(jsonb_build_object('allocation',a,'paymentRevision',p->'revision','usable',trunc(u,2)::text));
 end loop;
 return jsonb_build_object('allocationIds',ids,'assigned',trunc(assigned,2)::text,'usable',trunc(usable,2)::text,'consumed',trunc(consumed,2)::text,'availableForPurpose',trunc(usable-usable_consumed,2)::text,'suspended',trunc(assigned-usable,2)::text,'entries',entries,'source','H3-005/006');
end$function$

CREATE OR REPLACE FUNCTION crm_private.suplido_invoice(iid uuid, bid uuid, service uuid, client uuid, provider uuid, s text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare x jsonb;part jsonb;
begin
 select v.after_data into x from crm_private.b05_invoice_revisions v join crm_private.b05_provider_invoices i using(invoice_id)
 where i.invoice_id=iid and i.booking_id=bid and i.admin_scope=s and v.admin_scope=s order by v.revision desc limit 1;
 if x is null or x->'basis'->>'recipientId' is distinct from client::text or x->'basisApplied'->'provider'->>'item_id' is distinct from provider::text or not(x->'basis'->'serviceIds' @> jsonb_build_array(service::text)) then raise exception 'SUPLIDO_INVOICE_REQUIRED';end if;
 select value into part from jsonb_array_elements(coalesce(nullif(x->'link'->'portions','null'::jsonb),'[]')) where value->>'serviceId'=service::text;
 return jsonb_build_object('invoiceId',iid,'revision',x->'revision','status',x->'status','document',x->'document','review',x->'review','portion',part,'linked',x->>'status'='Vinculada' and part is not null,'source','H3-007/008');
end$function$

CREATE OR REPLACE FUNCTION crm_private.suplido_correspondence(rid uuid, bid uuid, s text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare rc crm_private.b05_reconciliations;p jsonb;x jsonb;
begin
 select * into rc from crm_private.b05_reconciliations where reconciliation_id=rid and booking_id=bid and admin_scope=s;if not found then raise exception 'SUPLIDO_RECONCILIATION_REQUIRED';end if;
 select snapshot into p from crm_private.b05_payment_revisions where payment_id=rc.payment_id and admin_scope=s order by revision desc limit 1;
 select value into x from jsonb_array_elements(p->'correspondences') where value->>'id'=rid::text;
 if x->>'status' is distinct from 'verified' or p->'receipt'='null'::jsonb or exists(select 1 from jsonb_array_elements(p->'incidents') z where not(z->>'resolved')::boolean and (z->>'start')::numeric<(x->>'start')::numeric+(x->>'amount')::numeric and (z->>'start')::numeric+(z->>'amount')::numeric>(x->>'start')::numeric) then raise exception 'SUPLIDO_RECONCILIATION_REQUIRED';end if;
 return jsonb_build_object('reconciliationId',rid,'paymentId',rc.payment_id,'paymentRevision',p->'revision','correspondence',x,'direction','incoming','supplierPaymentVerified',false);
end$function$

CREATE OR REPLACE FUNCTION crm_private.suplido_followup(root jsonb, kind text, s text, actor uuid, source text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare identity jsonb;material jsonb;key text;target uuid;op uuid;after_data jsonb;
begin
 identity:=jsonb_build_object('causeKind','suplido','causeId',root->>'id','contextKind','booking','contextId',root->>'bookingId','scopeRef',root->'basis'->>'serviceId','relatedKind','suplido','relatedId',root->>'id','effect','obtain_'||kind);
 key:=encode(crm_crypto.digest(convert_to(jsonb_build_object('version','h1-pending-cause-v1','identity',identity)::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(s||key,17));
 select task_id into target from crm_private.b07_pending_tasks where admin_scope=s and identity_key=key;if found then return target;end if;
 target:=gen_random_uuid();op:=gen_random_uuid();material:=jsonb_build_object('title','Suplido: pendiente '||kind,'deadline',jsonb_build_object('kind','unknown','reason','Plazo no acreditado'),'priority',jsonb_build_object('kind','pending','reason','Prioridad real no acreditada'),'sourceRef',source,'sourceVersion','h3-suplido-v1','triggerRef','manual','triggerVersion','h3-suplido-v1');
 insert into crm_private.b07_pending_tasks(task_id,admin_scope,identity_version,identity_key,identity,material,state,responsible_actor,revision) values(target,s,'h1-pending-cause-v1',key,identity,material,'pending',actor,1);
 select to_jsonb(t) into after_data from crm_private.b07_pending_tasks t where task_id=target;
 insert into crm_private.b07_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(op,s,actor,key,target);
 insert into crm_private.b07_history(history_id,operation_id,subject_id,admin_scope,action_kind,before_state,after_state,reason,source_ref,actor_id) values(op,op,target,s,'task_receive',null,after_data,'Componente documental pendiente',source,actor);
 return target;
end$function$

CREATE OR REPLACE FUNCTION crm_api.suplido_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;s text;actor uuid;op uuid;sid uuid;bid uuid;service uuid;root crm_private.b05_suplidos;prev crm_private.b05_suplido_operations;
 state jsonb;old jsonb;basis jsonb;provider jsonb;client jsonb;fp text;proofhash text;action text;comp text;rev bigint;at_time timestamptz;
 components jsonb;ids jsonb;invoice_id uuid;source_root text;x jsonb;due numeric;usable numeric;pending jsonb;refs jsonb;differences jsonb;r jsonb;mandate jsonb;mh text;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'SUPLIDO_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-SUPLIDO1' then raise exception 'SUPLIDO_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or not(a ?& array['action','operationId','suplidoId','bookingId','expectedRevision','sourceRef','reason','at','evidenceId'])
 or exists(select 1 from unnest(array['action','operationId','suplidoId','bookingId','sourceRef','reason','at','evidenceId']) k where not coalesce(crm_private.invoice_text(a->k),false))
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or a->>'expectedRevision' !~ '^(0|[1-9][0-9]*)$'
 or coalesce(a->>'origin','manual')<>'manual' or (a?'origin' and jsonb_typeof(a->'origin') is distinct from 'string')
 or a->>'action' not in ('open','component','evaluate','discrepancy','resolve')
 or a->>'at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'SUPLIDO_INPUT_INVALID';end if;
 action:=a->>'action';comp:=a->>'component';
 if a-array['action','operationId','suplidoId','bookingId','expectedRevision','sourceRef','reason','at','evidenceId','origin']-
 (case action when 'open' then array['basis'] when 'component' then array['component','confirmedAmount','allocationIds','invoiceId','reconciliationId','mandate'] when 'discrepancy' then array['component','incidentId','affectedAllocationIds'] when 'resolve' then array['component','incidentId'] else array[]::text[] end)<>'{}'::jsonb then raise exception 'SUPLIDO_INPUT_INVALID';end if;
 sid:=(a->>'suplidoId')::uuid;bid:=(a->>'bookingId')::uuid;op:=(a->>'operationId')::uuid;actor:=hf[12]::uuid;s:=hf[17];at_time:=(a->>'at')::timestamptz;
 if not exists(select 1 from crm_private.b04_bookings where booking_id=bid and admin_scope=s) then raise exception 'SUPLIDO_DENIED';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('suplido-op:'||op,0));
 select * into prev from crm_private.b05_suplido_operations where operation_id=op;
 if found then
  if prev.admin_scope<>s or prev.actor_id<>actor or prev.fingerprint<>fp then raise exception 'SUPLIDO_REPLAY_CONFLICT:E2';end if;r:=prev.result||jsonb_build_object('replayed',true);
 else
  proofhash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.payment_evidence((a->>'evidenceId')::uuid,sid,s,'suplido:'||action||':'||proofhash,at_time,true)
   or not exists(select 1 from crm_private.b07_records where record_id=(a->>'evidenceId')::uuid and recorded_by=actor) then raise exception 'SUPLIDO_EVIDENCE_REQUIRED';end if;
  if action='open' then
   basis:=a->'basis';
   if jsonb_typeof(basis) is distinct from 'object' or basis-array['clientId','providerRevisionId','serviceId','expectedAmount','confirmedAmount','sourceRef','version']<>'{}'::jsonb or not(basis ?& array['clientId','providerRevisionId','serviceId','expectedAmount','confirmedAmount','sourceRef','version'])
   or exists(select 1 from unnest(array['clientId','providerRevisionId','serviceId','sourceRef','version']) k where not coalesce(crm_private.invoice_text(basis->k),false))
   or (basis->'expectedAmount'='null'::jsonb and basis->'confirmedAmount'='null'::jsonb)
   or (basis->'expectedAmount'<>'null'::jsonb and not coalesce(crm_private.payment_amount(basis->'expectedAmount'),false))
   or (basis->'confirmedAmount'<>'null'::jsonb and not coalesce(crm_private.payment_amount(basis->'confirmedAmount'),false))
   or (a->>'expectedRevision')::bigint<>0 then raise exception 'SUPLIDO_BASIS_REQUIRED';end if;
   service:=(basis->>'serviceId')::uuid;
   if not exists(select 1 from crm_private.b04_services where service_id=service and booking_id=bid and admin_scope=s and nature='external') then raise exception 'SUPLIDO_BASIS_REQUIRED';end if;
   select to_jsonb(cr) into provider from crm_private.catalog_revisions cr join crm_private.catalog_items ci using(item_id) where cr.revision_id=(basis->>'providerRevisionId')::uuid and cr.admin_scope=s and ci.item_kind='provider';
   select to_jsonb(e) into client from crm_private.identity_entities e where e.identity_id=(basis->>'clientId')::uuid and e.admin_scope=s and e.identity_verified;
   if provider is null or client is null then raise exception 'SUPLIDO_BASIS_REQUIRED';end if;
   perform pg_advisory_xact_lock(hashtextextended('suplido-service:'||bid||':'||service,0));
   select * into root from crm_private.b05_suplidos where booking_id=bid and service_id=service and admin_scope=s;
   if found then
    if root.basis is distinct from basis then raise exception 'SUPLIDO_IDENTITY_CONFLICT:E2';end if;sid:=root.suplido_id;
    select revision,after_data into rev,state from crm_private.b05_suplido_revisions where suplido_id=sid order by revision desc limit 1;
    r:=jsonb_build_object('id',sid,'replayed',true,'result',state);
    insert into crm_private.b05_suplido_operations values(op,sid,s,actor,fp,r,rev,clock_timestamp());
    perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
   end if;
   perform pg_advisory_xact_lock(hashtextextended('suplido-root:'||sid,0));
   insert into crm_private.b05_suplidos values(sid,bid,service,s,basis,op);
   rev:=0;components:=jsonb_build_object('amount',jsonb_build_object('expected',basis->'expectedAmount','confirmed',basis->'confirmedAmount','sourceRef',basis->>'sourceRef','version',basis->>'version'),'funds',null,'invoice',null,'payment',null,'reconciliation',null,'mandate',null);
   state:=jsonb_build_object('id',sid,'bookingId',bid,'revision',1,'basis',basis,'basisApplied',jsonb_build_object('provider',provider,'client',client),'components',components,'differences','[]'::jsonb,'evaluation',null,'status','Gestión abierta');
  else
   perform pg_advisory_xact_lock(hashtextextended('suplido-root:'||sid,0));
   select * into root from crm_private.b05_suplidos where suplido_id=sid and booking_id=bid and admin_scope=s;if not found then raise exception 'SUPLIDO_DENIED';end if;
   select revision,after_data into rev,old from crm_private.b05_suplido_revisions where suplido_id=sid order by revision desc limit 1;
   if rev<>(a->>'expectedRevision')::bigint then raise exception 'SUPLIDO_REVISION_CONFLICT:E2';end if;
   basis:=root.basis;service:=root.service_id;state:=old;components:=old->'components';
   -- Lock all retained and requested sources in stable order; source mutations use the same roots.
   ids:=coalesce(nullif(a->'allocationIds','null'::jsonb),nullif(components->'funds'->'allocationIds','null'::jsonb),'[]');
   if jsonb_typeof(ids) is distinct from 'array' then raise exception 'SUPLIDO_FUNDS_REQUIRED';end if;
   invoice_id:=coalesce((a->>'invoiceId')::uuid,(components->'invoice'->>'invoiceId')::uuid);
   for source_root in select distinct k from (
    select 'payment-root:'||al.payment_id k from crm_private.b05_allocations al where al.admin_scope=s and ids @> jsonb_build_array(al.allocation_id::text)
    union select 'invoice-root:'||invoice_id where invoice_id is not null
    union select 'payment-root:'||rc.payment_id from crm_private.b05_reconciliations rc where rc.admin_scope=s and rc.reconciliation_id=coalesce((a->>'reconciliationId')::uuid,(components->'reconciliation'->>'reconciliationId')::uuid)
   ) locks order by k loop perform pg_advisory_xact_lock(hashtextextended(source_root,0));end loop;
   if action='component' then
    if comp is null or comp not in ('amount','funds','invoice','reconciliation','mandate') then raise exception 'SUPLIDO_COMPONENT_REQUIRED';end if;
    if a-array['action','operationId','suplidoId','bookingId','expectedRevision','sourceRef','reason','at','evidenceId','origin','component']-
    (case comp when 'amount' then array['confirmedAmount'] when 'funds' then array['allocationIds'] when 'invoice' then array['invoiceId'] when 'reconciliation' then array['reconciliationId'] else array['mandate'] end)<>'{}'::jsonb then raise exception 'SUPLIDO_INPUT_INVALID';end if;
    if comp='amount' then
     if not coalesce(crm_private.payment_amount(a->'confirmedAmount'),false) then raise exception 'SUPLIDO_AMOUNT_REQUIRED';end if;
     x:=components->'amount'||jsonb_build_object('confirmed',a->'confirmedAmount','sourceRef',a->>'sourceRef','version',op);
    elsif comp='funds' then
     if not(a?'allocationIds') then raise exception 'SUPLIDO_FUNDS_REQUIRED';end if;x:=crm_private.suplido_funds(ids,bid,service,s);
    elsif comp='invoice' then
     if not coalesce(crm_private.invoice_text(a->'invoiceId'),false) then raise exception 'SUPLIDO_INVOICE_REQUIRED';end if;
     x:=crm_private.suplido_invoice(invoice_id,bid,service,(basis->>'clientId')::uuid,(state->'basisApplied'->'provider'->>'item_id')::uuid,s);
    elsif comp='reconciliation' then
     if not coalesce(crm_private.invoice_text(a->'reconciliationId'),false) then raise exception 'SUPLIDO_RECONCILIATION_REQUIRED';end if;
     x:=crm_private.suplido_correspondence((a->>'reconciliationId')::uuid,bid,s);
    else
     mandate:=a->'mandate';
     if jsonb_typeof(mandate) is distinct from 'object' or mandate-array['id','version','content','acceptanceRef','acceptedBy','acceptedAt','evidenceId']<>'{}'::jsonb or not(mandate ?& array['id','version','content','acceptanceRef','acceptedBy','acceptedAt','evidenceId'])
     or exists(select 1 from unnest(array['id','version','content','acceptanceRef','acceptedBy','acceptedAt','evidenceId']) k where not coalesce(crm_private.invoice_text(mandate->k),false)) or mandate->>'acceptedBy' is distinct from basis->>'clientId'
     or mandate->>'acceptedAt' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'SUPLIDO_MANDATE_REQUIRED';end if;
     mh:=encode(crm_crypto.digest(convert_to((mandate-'evidenceId')::text,'UTF8'),'sha256'),'hex');
     if not crm_private.payment_evidence((mandate->>'evidenceId')::uuid,sid,s,'mandate:accepted:'||mh,(mandate->>'acceptedAt')::timestamptz,true) then raise exception 'SUPLIDO_MANDATE_REQUIRED';end if;x:=mandate;
    end if;
    components:=jsonb_set(components,array[comp],x);
   elsif action in ('discrepancy','resolve') then
    if comp is null or comp not in ('amount','funds','invoice','payment','reconciliation','obligation','mandate') or not coalesce(crm_private.invoice_text(a->'incidentId'),false) then raise exception 'SUPLIDO_DIFFERENCE_REQUIRED';end if;perform (a->>'incidentId')::uuid;
    if action='discrepancy' and comp='funds' then
     if jsonb_typeof(a->'affectedAllocationIds') is distinct from 'array' or jsonb_array_length(a->'affectedAllocationIds')=0 or not coalesce((components->'funds'->'allocationIds') @> (a->'affectedAllocationIds'),false) then raise exception 'SUPLIDO_DIFFERENCE_REQUIRED';end if;
    elsif a?'affectedAllocationIds' then raise exception 'SUPLIDO_DIFFERENCE_REQUIRED';end if;
    differences:=state->'differences';
    if action='discrepancy' then
     if exists(select 1 from jsonb_array_elements(differences) z where z->>'id'=a->>'incidentId') then raise exception 'SUPLIDO_DIFFERENCE_CONFLICT:E2';end if;
     differences:=differences||jsonb_build_array(jsonb_build_object('id',a->>'incidentId','component',comp,'affectedAllocationIds',a->'affectedAllocationIds','sourceRef',a->>'sourceRef','reason',a->>'reason','evidenceId',a->>'evidenceId','actorId',actor,'at',a->>'at','resolved',false));
    else
     if not exists(select 1 from jsonb_array_elements(differences) z where z->>'id'=a->>'incidentId' and z->>'component'=comp and not(z->>'resolved')::boolean) then raise exception 'SUPLIDO_DIFFERENCE_REQUIRED';end if;
     select jsonb_agg(case when z->>'id'=a->>'incidentId' then z||jsonb_build_object('resolved',true,'resolutionEvidenceId',a->>'evidenceId','resolutionSource',a->>'sourceRef','resolutionReason',a->>'reason','resolutionActor',actor,'resolutionAt',a->>'at') else z end) into differences from jsonb_array_elements(differences) z;
    end if;state:=state||jsonb_build_object('differences',differences);
   end if;
  end if;
  if action='evaluate' then
   -- Revalidate attached components under source roots. Payment/outgoing reconciliation stay absent.
   if components->'funds'<>'null'::jsonb then components:=jsonb_set(components,'{funds}',crm_private.suplido_funds(components->'funds'->'allocationIds',bid,service,s));end if;
   if components->'invoice'<>'null'::jsonb then components:=jsonb_set(components,'{invoice}',crm_private.suplido_invoice((components->'invoice'->>'invoiceId')::uuid,bid,service,(basis->>'clientId')::uuid,(state->'basisApplied'->'provider'->>'item_id')::uuid,s));end if;
   if components->'reconciliation'<>'null'::jsonb then
    begin components:=jsonb_set(components,'{reconciliation}',crm_private.suplido_correspondence((components->'reconciliation'->>'reconciliationId')::uuid,bid,s));
    exception when raise_exception then components:=jsonb_set(components,'{reconciliation}',components->'reconciliation'||jsonb_build_object('requiresReview',true));end;
   end if;
  end if;
  state:=state||jsonb_build_object('components',components,'revision',rev+1);
  due:=coalesce((components->'amount'->>'confirmed')::numeric,(components->'amount'->>'expected')::numeric);usable:=coalesce((components->'funds'->>'usable')::numeric,0);
  if exists(select 1 from jsonb_array_elements(state->'differences') z where z->>'component'='funds' and not(z->>'resolved')::boolean) then
   select coalesce(sum((entry->>'usable')::numeric),0) into usable from jsonb_array_elements(components->'funds'->'entries') entry where not exists(select 1 from jsonb_array_elements(state->'differences') z where z->>'component'='funds' and not(z->>'resolved')::boolean and z->'affectedAllocationIds' @> jsonb_build_array(entry->'allocation'->>'id'));
  end if;
  state:=state||jsonb_build_object('funding',jsonb_build_object('due',trunc(due,2)::text,'identified',trunc(usable,2)::text,'remaining',trunc(greatest(0,due-usable),2)::text,'excess',trunc(greatest(0,usable-due),2)::text,'ownFinancingInferred',false));
  pending:=jsonb_build_array('payment','outgoing_reconciliation');
  if components->'invoice'='null'::jsonb or not coalesce((components->'invoice'->>'linked')::boolean,false) or (components->'invoice'->'portion'->>'amount')::numeric is distinct from due then pending:=pending||'"invoice"'::jsonb;end if;
  for x in select value from jsonb_array_elements(state->'differences') where not(value->>'resolved')::boolean loop pending:=pending||jsonb_build_array('difference:'||(x->>'component'));end loop;
  refs:='[]';for comp in select value#>>'{}' from jsonb_array_elements(pending) where value in ('"invoice"'::jsonb,'"payment"'::jsonb) loop refs:=refs||jsonb_build_array(crm_private.suplido_followup(state,comp,s,actor,a->>'sourceRef'));end loop;
  state:=state||jsonb_build_object('pending',pending,'followUpIds',refs,'status',case when exists(select 1 from jsonb_array_elements(state->'differences') z where not(z->>'resolved')::boolean) then 'Revisión' else 'Gestión abierta' end);
  if action='evaluate' then state:=state||jsonb_build_object('evaluation',jsonb_build_object('operationId',op,'actorId',actor,'at',a->>'at','sourceRef',a->>'sourceRef','evidenceId',a->>'evidenceId','components',components,'differences',state->'differences','state','Gestión abierta','pending',pending,'productivePaymentBoundary','NOT_IMPLEMENTED_H3_011_012','bookingClosureInferred',false,'fiscalValidation',false));
  elsif action<>'open' then state:=state||jsonb_build_object('evaluation',null);end if;
  state:=crm_private.provider_payment_documentary(state,s);
  if action='evaluate' then
   state:=jsonb_set(state,'{evaluation}',state->'evaluation'||jsonb_build_object('components',state->'components','state',state->>'status','pending',state->'pending','productivePaymentBoundary','LOCAL_H3_011_012'));
  elsif state->>'status'='Documentalmente resuelto' then state:=jsonb_set(state,'{status}','"Gestión abierta"'::jsonb);end if;
  rev:=rev+1;
  insert into crm_private.b05_suplido_revisions values(sid,rev,s,op,action,a,old,state,actor,(a->>'evidenceId')::uuid,a->>'reason',a->>'sourceRef',at_time,clock_timestamp());
  r:=jsonb_build_object('id',sid,'replayed',false,'result',state);
  insert into crm_private.b05_suplido_operations values(op,sid,s,actor,fp,r,rev,clock_timestamp());
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.suplido_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;r jsonb;current_components jsonb;changed jsonb;source_root text;x jsonb;client uuid;provider uuid;service uuid;bid uuid;ids jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'SUPLIDO_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-SUPLIDO-READ1' then raise exception 'SUPLIDO_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-array['suplidoId','bookingId']<>'{}'::jsonb or not coalesce(crm_private.invoice_text(a->'suplidoId'),false) or not coalesce(crm_private.invoice_text(a->'bookingId'),false) then raise exception 'SUPLIDO_INPUT_INVALID';end if;
 select v.after_data into r from crm_private.b05_suplido_revisions v join crm_private.b05_suplidos i using(suplido_id) where i.suplido_id=(a->>'suplidoId')::uuid and i.booking_id=(a->>'bookingId')::uuid and i.admin_scope=hf[17] and v.admin_scope=hf[17] order by v.revision desc limit 1;
 if r is not null then
  perform pg_advisory_xact_lock(hashtextextended('suplido-root:'||(a->>'suplidoId'),0));
  select after_data into r from crm_private.b05_suplido_revisions where suplido_id=(a->>'suplidoId')::uuid and admin_scope=hf[17] order by revision desc limit 1;
  current_components:=r->'components';changed:='[]';bid:=(r->>'bookingId')::uuid;service:=(r->'basis'->>'serviceId')::uuid;client:=(r->'basis'->>'clientId')::uuid;provider:=(r->'basisApplied'->'provider'->>'item_id')::uuid;
  ids:=coalesce(current_components->'funds'->'allocationIds','[]');
  for source_root in select distinct k from (
   select 'payment-root:'||al.payment_id k from crm_private.b05_allocations al where al.admin_scope=hf[17] and ids @> jsonb_build_array(al.allocation_id::text)
   union select 'invoice-root:'||(current_components->'invoice'->>'invoiceId') where current_components->'invoice'<>'null'::jsonb
   union select 'payment-root:'||rc.payment_id from crm_private.b05_reconciliations rc where rc.admin_scope=hf[17] and rc.reconciliation_id=(current_components->'reconciliation'->>'reconciliationId')::uuid
  ) locks order by k loop perform pg_advisory_xact_lock(hashtextextended(source_root,0));end loop;
  if current_components->'funds'<>'null'::jsonb then
   x:=crm_private.suplido_funds(ids,bid,service,hf[17]);if x is distinct from current_components->'funds' then changed:=changed||'"funds"'::jsonb;end if;current_components:=jsonb_set(current_components,'{funds}',x);
  end if;
  if current_components->'invoice'<>'null'::jsonb then
   x:=crm_private.suplido_invoice((current_components->'invoice'->>'invoiceId')::uuid,bid,service,client,provider,hf[17]);if x is distinct from current_components->'invoice' then changed:=changed||'"invoice"'::jsonb;end if;current_components:=jsonb_set(current_components,'{invoice}',x);
  end if;
  if current_components->'reconciliation'<>'null'::jsonb then
   begin x:=crm_private.suplido_correspondence((current_components->'reconciliation'->>'reconciliationId')::uuid,bid,hf[17]);
   exception when raise_exception then x:=current_components->'reconciliation'||jsonb_build_object('requiresReview',true);end;
   if x is distinct from current_components->'reconciliation' then changed:=changed||'"reconciliation"'::jsonb;end if;current_components:=jsonb_set(current_components,'{reconciliation}',x);
  end if;
  x:=crm_private.provider_payment_documentary(r,hf[17]);
  if x->'components'->'payment' is distinct from r->'components'->'payment' or x->'pending' is distinct from r->'pending' then changed:=changed||'"provider_payment"'::jsonb;end if;
  current_components:=x->'components';
  r:=r||jsonb_build_object('currentComponents',current_components,'sourceRevalidationRequired',changed,'snapshotRevision',r->'revision');
  if changed<>'[]'::jsonb then r:=r||jsonb_build_object('status','Revisión','pending',(r->'pending')||jsonb_build_array('source_revalidation'),'currentDocumentaryResolved',false);end if;
 end if;
 if r is not null then r:=r||jsonb_build_object('history',(select jsonb_agg(jsonb_build_object('revision',revision,'action',action_kind,'before',before_data,'after',after_data,'actorId',actor_id,'reason',reason,'sourceRef',source_ref,'evidenceId',evidence_id,'at',occurred_at,'recordedAt',recorded_at) order by revision) from crm_private.b05_suplido_revisions where suplido_id=(a->>'suplidoId')::uuid and admin_scope=hf[17]));end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_private.provider_payment_funds(parts jsonb, root jsonb, s text, check_revision boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v jsonb;a jsonb;p jsonb;rev bigint;pr bigint;start_at numeric;amt numeric;
begin
 if jsonb_typeof(parts) is distinct from 'array' or jsonb_array_length(parts)=0 then return false;end if;
 for v in select value from jsonb_array_elements(parts) loop
  if jsonb_typeof(v)<>'object' or v-array['allocationId','paymentId','start','amount','fundRevision','paymentRevision']<>'{}'::jsonb
   or not(v?&array['allocationId','paymentId','start','amount','fundRevision','paymentRevision'])
   or not coalesce(crm_private.payment_amount(v->'start'),false) or not coalesce(crm_private.payment_amount(v->'amount',true),false)
   or v->>'fundRevision'!~'^[0-9]+$' or v->>'paymentRevision'!~'^[0-9]+$' then return false;end if;
  select snapshot into a from crm_private.b05_allocation_revisions where allocation_id=(v->>'allocationId')::uuid and admin_scope=s order by revision desc limit 1;
  if a is null or a->>'paymentId' is distinct from v->>'paymentId' or a->>'status'<>'verified' or a->'destination'->>'purpose'<>'managed_client_funds'
   or a->'destination'->>'bookingId' is distinct from root->>'bookingId' or a->'destination'->>'serviceId' is distinct from root->'basis'->>'serviceId' then return false;end if;
  select revision,snapshot into pr,p from crm_private.b05_payment_revisions where payment_id=(v->>'paymentId')::uuid and admin_scope=s order by revision desc limit 1;
  select max(revision) into rev from crm_private.b05_fund_revisions where payment_id=(v->>'paymentId')::uuid and admin_scope=s;
  if check_revision and (rev<>(v->>'fundRevision')::bigint or pr<>(v->>'paymentRevision')::bigint) then raise exception 'PROVIDER_PAYMENT_FUNDS_REVISION_CONFLICT:E2';end if;
  start_at:=(v->>'start')::numeric;amt:=(v->>'amount')::numeric;
  if start_at<(a->>'start')::numeric or start_at+amt>(a->>'start')::numeric+(a->>'amount')::numeric or crm_private.fund_usable(a||jsonb_build_object('start',v->>'start','amount',v->>'amount'),p)<>amt
   or exists(select 1 from crm_private.b05_allocation_acts z where z.allocation_id=(v->>'allocationId')::uuid and z.kind='consume' and z.start_amount<start_at+amt and z.start_amount-z.signed_amount>start_at and not exists(select 1 from crm_private.b05_allocation_acts r where r.original_act_id=z.act_id))
   or exists(select 1 from jsonb_array_elements(parts) other where other<>v and other->>'allocationId'=v->>'allocationId' and (other->>'start')::numeric<start_at+amt and (other->>'start')::numeric+(other->>'amount')::numeric>start_at)
   or (select count(*) from jsonb_array_elements(parts) other where other=v)>1 then return false;end if;
 end loop;return true;
end$function$

CREATE OR REPLACE FUNCTION crm_private.provider_payment_documentary(state jsonb, s text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare p jsonb;comp jsonb;pending jsonb:='[]';due numeric;paid numeric;matched numeric:=0;v jsonb;mv jsonb;a jsonb;receipt jsonb;funds_ids jsonb:='[]';x jsonb;
begin
 select r.after_data into p from crm_private.b05_provider_payment_revisions r join crm_private.b05_provider_payments root using(provider_payment_id)
 where root.suplido_id=(state->>'id')::uuid and root.admin_scope=s and r.admin_scope=s order by r.revision desc limit 1;
 comp:=state->'components';due:=coalesce((comp->'amount'->>'confirmed')::numeric,(comp->'amount'->>'expected')::numeric);
 if p is not null then
  comp:=jsonb_set(comp,'{payment}',jsonb_build_object('providerPaymentId',p->>'id','revision',p->'revision','paid',p->>'paid','remaining',p->>'remaining','status',p->>'status','movements',p->'movements','source','H3-011/012'));
  for mv in select value from jsonb_array_elements(p->'movements') where (value->>'correspondenceVerified')::boolean and not exists(select 1 from jsonb_array_elements(p->'corrections') c where c->>'originalMovementId'=value->>'id') loop
   for v in select value from jsonb_array_elements(mv->'material'->'portions') loop
    select snapshot into a from crm_private.b05_allocation_revisions where allocation_id=(v->>'allocationId')::uuid and admin_scope=s order by revision desc limit 1;
    select snapshot into receipt from crm_private.b05_payment_revisions where payment_id=(v->>'paymentId')::uuid and admin_scope=s order by revision desc limit 1;
    matched:=matched+crm_private.fund_usable(a||jsonb_build_object('start',v->>'start','amount',v->>'amount'),receipt);
    if not(funds_ids @> jsonb_build_array(v->>'allocationId')) then funds_ids:=funds_ids||jsonb_build_array(v->>'allocationId');end if;
   end loop;
  end loop;
  comp:=jsonb_set(comp,'{outgoingReconciliation}',jsonb_build_object('direction','outgoing','providerPaymentId',p->>'id','amount',trunc(matched,2)::text,'verified',matched=due,'movements',p->'movements'));
 end if;
 if comp->'funds'<>'null'::jsonb then comp:=jsonb_set(comp,'{funds}',crm_private.suplido_funds(comp->'funds'->'allocationIds',(state->>'bookingId')::uuid,(state->'basis'->>'serviceId')::uuid,s));end if;
 if comp->'invoice'<>'null'::jsonb then comp:=jsonb_set(comp,'{invoice}',crm_private.suplido_invoice((comp->'invoice'->>'invoiceId')::uuid,(state->>'bookingId')::uuid,(state->'basis'->>'serviceId')::uuid,(state->'basis'->>'clientId')::uuid,(state->'basisApplied'->'provider'->>'item_id')::uuid,s));end if;
 paid:=coalesce((p->>'paid')::numeric,0);
 if p is null or paid is distinct from due or p->>'remaining' is distinct from '0.00' then pending:=pending||'"payment"'::jsonb;end if;
 if matched is distinct from due or p->>'status'='Incidencia' then pending:=pending||'"outgoing_reconciliation"'::jsonb;end if;
 if comp->'invoice'='null'::jsonb or not coalesce((comp->'invoice'->>'linked')::boolean,false) or (comp->'invoice'->'portion'->>'amount')::numeric is distinct from due then pending:=pending||'"invoice"'::jsonb;end if;
 for x in select value from jsonb_array_elements(state->'differences') where not(value->>'resolved')::boolean loop pending:=pending||jsonb_build_array('difference:'||(x->>'component'));end loop;
 return state||jsonb_build_object('components',comp,'pending',pending,'status',case when pending='[]'::jsonb then 'Documentalmente resuelto' when p->>'status'='Incidencia' or exists(select 1 from jsonb_array_elements(state->'differences') z where not(z->>'resolved')::boolean) then 'Revisión' else 'Gestión abierta' end);
end$function$

CREATE OR REPLACE FUNCTION crm_private.provider_payment_core(a jsonb, s text, actor uuid, reservation text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare id uuid;op uuid;bid uuid;sid uuid;root crm_private.b05_provider_payments;previous crm_private.b05_provider_payment_operations;old jsonb;state jsonb;applied_basis jsonb;provider jsonb;rev bigint;fp text;proofhash text;action text;at_time timestamptz;source_root text;v jsonb;m jsonb;stored crm_private.b05_provider_outgoing_movements;movement_id uuid;matched boolean;paid numeric;due numeric;acts jsonb:='[]';act uuid;fund_op uuid;allocation jsonb;fund_before jsonb;fund_result jsonb;fr bigint;incident jsonb;r jsonb;su jsonb;sr bigint;so uuid;refs jsonb;part text[];
begin
 if jsonb_typeof(a) is distinct from 'object' or a-array['action','operationId','providerPaymentId','bookingId','expectedRevision','sourceRef','reason','at','evidenceId','origin','suplidoId','basis','confirmedAmount','schedule','movement','incident','incidentId','previousEffectCheck','originalMovementId','noExecution','noPendingExecution','noUnknownResult']<>'{}'::jsonb
 or not(a?&array['action','operationId','providerPaymentId','bookingId','expectedRevision','sourceRef','reason','at','evidenceId'])
 or exists(select 1 from unnest(array['action','operationId','providerPaymentId','bookingId','sourceRef','reason','at','evidenceId']) k where not coalesce(crm_private.invoice_text(a->k),false))
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or a->>'expectedRevision'!~'^[0-9]+$'
 or coalesce(a->>'origin','manual') not in ('manual','ai') or (a->>'origin'='ai' and (a->>'action'<>'schedule' or reservation is null)) or a->>'action' not in ('open','confirm','schedule','record','incident','resolve','correct','withdraw')
 or a->>'at'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'PROVIDER_PAYMENT_INPUT_INVALID';end if;
 action:=a->>'action';id:=(a->>'providerPaymentId')::uuid;op:=(a->>'operationId')::uuid;bid:=(a->>'bookingId')::uuid;at_time:=(a->>'at')::timestamptz;if at_time>clock_timestamp() then raise exception 'PROVIDER_PAYMENT_OCCURRENCE_REQUIRED';end if;
 if action='schedule' and reservation is null then raise exception 'PROVIDER_PAYMENT_TTE_REQUIRED';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('provider-payment-op:'||op,0));
 select * into previous from crm_private.b05_provider_payment_operations where operation_id=op;
 if found then if previous.admin_scope<>s or previous.actor_id<>actor or previous.fingerprint<>fp then raise exception 'PROVIDER_PAYMENT_REPLAY_CONFLICT:E2';end if;return previous.result||jsonb_build_object('replayed',true);end if;
 if not exists(select 1 from crm_private.b04_bookings where booking_id=bid and admin_scope=s) then raise exception 'PROVIDER_PAYMENT_DENIED';end if;
 proofhash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId'])::text,'UTF8'),'sha256'),'hex');
 if not crm_private.payment_evidence((a->>'evidenceId')::uuid,id,s,'provider-payment:'||action||':'||proofhash,at_time,true)
  or not exists(select 1 from crm_private.b07_records where record_id=(a->>'evidenceId')::uuid and recorded_by=actor) then raise exception 'PROVIDER_PAYMENT_EVIDENCE_REQUIRED';end if;
 select * into root from crm_private.b05_provider_payments where provider_payment_id=id and admin_scope=s and booking_id=bid;
 sid:=coalesce(root.suplido_id,(a->>'suplidoId')::uuid);
 if sid is not null then perform pg_advisory_xact_lock(hashtextextended('suplido-root:'||sid,0));end if;
 perform pg_advisory_xact_lock(hashtextextended('provider-payment-root:'||id,0));
 if action='open' then
  applied_basis:=a->'basis';
  if jsonb_typeof(applied_basis) is distinct from 'object' or applied_basis-array['providerRevisionId','serviceId','expectedAmount','confirmedAmount','obligationRef','sourceRef','version']<>'{}'::jsonb
   or not(applied_basis?&array['providerRevisionId','serviceId','expectedAmount','confirmedAmount','obligationRef','sourceRef','version'])
   or exists(select 1 from unnest(array['providerRevisionId','serviceId','obligationRef','sourceRef','version']) k where not coalesce(crm_private.invoice_text(applied_basis->k),false))
   or (applied_basis->'expectedAmount'='null'::jsonb and applied_basis->'confirmedAmount'='null'::jsonb)
   or (applied_basis->'expectedAmount'<>'null'::jsonb and not coalesce(crm_private.payment_amount(applied_basis->'expectedAmount',true),false))
   or (applied_basis->'confirmedAmount'<>'null'::jsonb and not coalesce(crm_private.payment_amount(applied_basis->'confirmedAmount',true),false)) or (a->>'expectedRevision')::bigint<>0 then raise exception 'PROVIDER_PAYMENT_BASIS_REQUIRED';end if;
  if not exists(select 1 from crm_private.b04_services where service_id=(applied_basis->>'serviceId')::uuid and booking_id=bid and admin_scope=s and nature='external') then raise exception 'PROVIDER_PAYMENT_BASIS_REQUIRED';end if;
  select to_jsonb(cr) into provider from crm_private.catalog_revisions cr join crm_private.catalog_items ci using(item_id) where cr.revision_id=(applied_basis->>'providerRevisionId')::uuid and cr.admin_scope=s and ci.item_kind='provider';
  if provider is null then raise exception 'PROVIDER_PAYMENT_BASIS_REQUIRED';end if;
  if sid is not null and not exists(select 1 from crm_private.b05_suplidos su where su.suplido_id=sid and su.admin_scope=s and su.booking_id=bid and su.service_id=(applied_basis->>'serviceId')::uuid and su.basis->>'providerRevisionId'=applied_basis->>'providerRevisionId') then raise exception 'PROVIDER_PAYMENT_CONTEXT_REQUIRED';end if;
  perform pg_advisory_xact_lock(hashtextextended('provider-payment-service:'||bid||':'||(applied_basis->>'serviceId')||':'||(provider->>'item_id'),0));
  select * into root from crm_private.b05_provider_payments where admin_scope=s and booking_id=bid and service_id=(applied_basis->>'serviceId')::uuid and provider_id=(provider->>'item_id')::uuid;
  if found then
   if root.basis is distinct from applied_basis or root.suplido_id is distinct from sid then raise exception 'PROVIDER_PAYMENT_IDENTITY_CONFLICT:E2';end if;
   select revision,after_data into rev,state from crm_private.b05_provider_payment_revisions where provider_payment_id=root.provider_payment_id order by revision desc limit 1;
   r:=jsonb_build_object('id',root.provider_payment_id,'replayed',true,'result',state);insert into crm_private.b05_provider_payment_operations values(op,root.provider_payment_id,s,actor,fp,r,rev,clock_timestamp());return r;
  end if;
  insert into crm_private.b05_provider_payments values(id,bid,(applied_basis->>'serviceId')::uuid,(provider->>'item_id')::uuid,s,sid,applied_basis,op);
  state:=jsonb_build_object('id',id,'bookingId',bid,'suplidoId',sid,'revision',1,'basis',applied_basis,'providerApplied',provider,'status','Pendiente','schedule',null,'movements','[]'::jsonb,'incidents','[]'::jsonb,'corrections','[]'::jsonb,'paid','0.00','remaining',coalesce(applied_basis->>'confirmedAmount',applied_basis->>'expectedAmount'),'complete',false,'externalExecutionByCRM',false);rev:=0;
 else
  select * into root from crm_private.b05_provider_payments where provider_payment_id=id and booking_id=bid and admin_scope=s;if not found or (a?'suplidoId' and (a->>'suplidoId')::uuid is distinct from root.suplido_id) then raise exception 'PROVIDER_PAYMENT_DENIED';end if;
  select revision,after_data into rev,old from crm_private.b05_provider_payment_revisions where provider_payment_id=id order by revision desc limit 1;state:=old;applied_basis:=state->'basis';
  -- Move identity first, while root is held; duplicate equivalence precedes optimistic revisions.
  if action='record' then
   m:=a->'movement';
   if jsonb_typeof(m) is distinct from 'object' or m-array['identity','providerId','serviceId','amount','occurredAt','method','reference','sourceRef','correspondenceSourceRef','portions']<>'{}'::jsonb or not(m?&array['identity','providerId','serviceId','amount','occurredAt','method','reference','sourceRef','correspondenceSourceRef','portions'])
    or exists(select 1 from unnest(array['providerId','serviceId','occurredAt','method','reference','sourceRef','correspondenceSourceRef']) k where not coalesce(crm_private.invoice_text(m->k),false))
    or not coalesce(crm_private.payment_amount(m->'amount',true),false) or jsonb_typeof(m->'portions') is distinct from 'array'
    or (m->'identity')-array['source','externalId']<>'{}'::jsonb or not coalesce(crm_private.invoice_text(m->'identity'->'source'),false) or not coalesce(crm_private.invoice_text(m->'identity'->'externalId'),false)
    or m->>'providerId'<>root.provider_id::text or m->>'serviceId'<>root.service_id::text or m->>'occurredAt'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' or (m->>'occurredAt')::timestamptz>at_time then raise exception 'PROVIDER_PAYMENT_MOVEMENT_REQUIRED';end if;
   perform pg_advisory_xact_lock(hashtextextended('provider-movement:'||(m->'identity'->>'source')||':'||(m->'identity'->>'externalId'),0));
   select * into stored from crm_private.b05_provider_outgoing_movements where identity_source=m->'identity'->>'source' and external_id=m->'identity'->>'externalId';
   if found then
    if stored.admin_scope<>s or stored.provider_payment_id<>id or stored.material is distinct from m then raise exception 'PROVIDER_PAYMENT_MOVEMENT_CONFLICT:E2';end if;
    r:=jsonb_build_object('id',id,'replayed',true,'result',state);insert into crm_private.b05_provider_payment_operations values(op,id,s,actor,fp,r,rev,clock_timestamp());return r;
   end if;
  end if;
  if rev<>(a->>'expectedRevision')::bigint then raise exception 'PROVIDER_PAYMENT_REVISION_CONFLICT:E2';end if;
  for source_root in select distinct k from (
   select 'payment-root:'||(value->>'paymentId') k from jsonb_array_elements(coalesce(m->'portions',a->'schedule'->'portions','[]'))
   union select 'payment-root:'||(value->>'paymentId') from jsonb_array_elements(coalesce(state->'schedule'->'portions','[]'))
   union select 'invoice-root:'||(after_data->'components'->'invoice'->>'invoiceId') from crm_private.b05_suplido_revisions where suplido_id=sid and after_data->'components'->'invoice'<>'null'::jsonb
  ) locks where k is not null order by k loop perform pg_advisory_xact_lock(hashtextextended(source_root,0));end loop;
  if action='confirm' then
   if not coalesce(crm_private.payment_amount(a->'confirmedAmount',true),false) then raise exception 'PROVIDER_PAYMENT_AMOUNT_REQUIRED';end if;applied_basis:=applied_basis||jsonb_build_object('confirmedAmount',a->'confirmedAmount','confirmationSource',a->>'sourceRef');state:=state||jsonb_build_object('basis',applied_basis);
  elsif action='schedule' then
   v:=a->'schedule';
   if jsonb_typeof(v) is distinct from 'object' or v-array['amount','recipientId','method','scheduledDate','conditions','fundsKind','portions']<>'{}'::jsonb or not(v?&array['amount','recipientId','method','scheduledDate','conditions','fundsKind','portions'])
    or not coalesce(crm_private.payment_amount(v->'amount',true),false) or v->>'recipientId'<>root.provider_id::text
    or exists(select 1 from unnest(array['recipientId','method','scheduledDate','conditions','fundsKind']) k where not coalesce(crm_private.invoice_text(v->k),false))
    or v->>'scheduledDate'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or (v->>'scheduledDate')::date is null or v->>'fundsKind' not in ('planned','verified')
    or jsonb_typeof(v->'portions') is distinct from 'array' or state->>'status' not in ('Pendiente','Incidencia')
    or exists(select 1 from jsonb_array_elements(state->'incidents') z where not(z->>'resolved')::boolean and z->>'result'='uncertain')
    or (v->>'amount')::numeric>coalesce((applied_basis->>'confirmedAmount')::numeric,(applied_basis->>'expectedAmount')::numeric)-(state->>'paid')::numeric then raise exception 'PROVIDER_PAYMENT_SCHEDULE_REQUIRED';end if;
   if v->>'fundsKind'='verified' and (not crm_private.provider_payment_funds(v->'portions',state,s,true) or (select sum((value->>'amount')::numeric) from jsonb_array_elements(v->'portions'))<>(v->>'amount')::numeric) then raise exception 'PROVIDER_PAYMENT_FUNDS_REQUIRED';end if;
   if v->>'fundsKind'='planned' and v->'portions'<>'[]'::jsonb then raise exception 'PROVIDER_PAYMENT_FUNDS_REQUIRED';end if;
   state:=state||jsonb_build_object('schedule',v||jsonb_build_object('approvalReservation',reservation,'operationId',op,'at',a->>'at','basisApplied',state->'basis','withdrawn',false),'status','Programado');
  elsif action='record' then
   matched:=coalesce(crm_private.provider_payment_funds(m->'portions',state,s,true) and (select sum((value->>'amount')::numeric) from jsonb_array_elements(m->'portions'))=(m->>'amount')::numeric,false);
   movement_id:=gen_random_uuid();insert into crm_private.b05_provider_outgoing_movements values(movement_id,id,s,m->'identity'->>'source',m->'identity'->>'externalId',m,op);
   if matched then
