end $function$

CREATE OR REPLACE FUNCTION crm_private.b03_decide(s text, e jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare k text:=e->>'type';allowed boolean:=false;dest text;id text;keys text[];why text;
begin
 keys:=case k when 'contact' then array['communicationId','outcome','evidenceId'] when 'define_need' then array['need','scope','pending']
 when 'prepare' then array['scope','sufficient','alternativeRef','pending'] when 'send' then array['versionRef','sendEvidenceRef','communicationId']
 when 'negotiate' then array['exchangeRef','scope'] when 'lose' then array['lossReason','context']
 when 'pause' then array['decision','context','followup'] when 'reactivate' then array['interest','review','destination','support']
 when 'revise' then array['change','humanEvaluation','destination','support'] when 'win' then array[]::text[]
 when 'reject_alternative' then array['alternativeRef','context'] end;
 if keys is null or e-(keys||array['type','sourceRef','occurredAt'])<>'{}'::jsonb then
  return jsonb_build_object('allowed',false,'id','SM-FORB-30','blocker','unsupported-effect'); end if;
 if exists(select 1 from jsonb_each(e) x where x.key not in ('pending','support','sufficient','occurredAt') and jsonb_typeof(x.value)<>'string')
  or (e ? 'pending' and (jsonb_typeof(e->'pending')<>'array' or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(e->'pending')='array' then e->'pending' else '[]'::jsonb end) x where jsonb_typeof(x)<>'string' or btrim(x#>>'{}')=''))) then
  return jsonb_build_object('allowed',false,'id','G2','blocker','material-type-invalid');end if;
 if e ? 'support' and (jsonb_typeof(e->'support') is distinct from 'object'
  or exists(select 1 from jsonb_each(case when jsonb_typeof(e->'support')='object' then e->'support' else '{}'::jsonb end) x where x.key<>'pending' and jsonb_typeof(x.value)<>'string')
  or ((e->'support') ? 'pending' and (jsonb_typeof(e->'support'->'pending') is distinct from 'array'
   or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(e->'support'->'pending')='array' then e->'support'->'pending' else '[]'::jsonb end) x where jsonb_typeof(x)<>'string' or btrim(x#>>'{}')='')))) then
  return jsonb_build_object('allowed',false,'id','G2','blocker','current-support-invalid');end if;
 if nullif(btrim(e->>'sourceRef'),'') is null then return jsonb_build_object('allowed',false,'id','G2','blocker','source-required'); end if;
 if k='win' then id:='SPEC-FR-COM-003';why:='verified-acceptance-required-H2-007';
 elsif k='contact' then id:='SM-OP-02';dest:='En contacto';allowed:=s='Nueva' and nullif(btrim(e->>'communicationId'),'') is not null and nullif(btrim(e->>'outcome'),'') is not null and nullif(btrim(e->>'evidenceId'),'') is not null;
 elsif k='define_need' then id:='SM-OP-03';dest:='Necesidad definida';allowed:=s in ('Nueva','En contacto') and nullif(btrim(e->>'need'),'') is not null and nullif(btrim(e->>'scope'),'') is not null and jsonb_typeof(e->'pending')='array';
 elsif k='prepare' then id:='SM-OP-04';why:='preparation-guards-required';
  if s in ('Nueva','En contacto','Necesidad definida','Propuesta enviada','Negociación / cambios') and e->'sufficient'='true'::jsonb
   and nullif(btrim(e->>'scope'),'') is not null and nullif(btrim(e->>'alternativeRef'),'') is not null and jsonb_typeof(e->'pending')='array' then why:='proposal-capability-pending-H2-003';end if;
 elsif k='send' then id:='SM-OP-05';why:='exact-version-send-guards-required';
  if s not in ('Aceptada / Ganada','Perdida','En pausa') and nullif(btrim(e->>'versionRef'),'') is not null
   and nullif(btrim(e->>'sendEvidenceRef'),'') is not null and nullif(btrim(e->>'communicationId'),'') is not null then why:='exact-version-send-capability-pending-H2-005';end if;
 elsif k='negotiate' then id:='SM-OP-06';dest:='Negociación / cambios';allowed:=s in ('Necesidad definida','Propuesta en preparación','Propuesta enviada') and nullif(btrim(e->>'exchangeRef'),'') is not null and nullif(btrim(e->>'scope'),'') is not null;
 elsif k='lose' then id:='SM-OP-08';dest:='Perdida';allowed:=s not in ('Aceptada / Ganada','Perdida') and e->>'lossReason' in
  ('precio','fechas','falta de disponibilidad','cliente no responde','eligió otra empresa','canceló/cambió viaje','no encaja','otro','desconocido') and nullif(btrim(e->>'context'),'') is not null;
 elsif k='pause' then id:='SM-OP-09';dest:='En pausa';allowed:=s not in ('Aceptada / Ganada','Perdida','En pausa') and nullif(btrim(e->>'decision'),'') is not null and nullif(btrim(e->>'context'),'') is not null and nullif(btrim(e->>'followup'),'') is not null;
 elsif k in ('reactivate','revise') then
  id:=case k when 'reactivate' then 'SM-OP-10' else 'SM-OP-11' end;
  if (k='reactivate' and s in ('Perdida','En pausa') and nullif(btrim(e->>'interest'),'') is not null and nullif(btrim(e->>'review'),'') is not null)
   or (k='revise' and s not in ('Aceptada / Ganada','Perdida','En pausa') and nullif(btrim(e->>'change'),'') is not null and nullif(btrim(e->>'humanEvaluation'),'') is not null) then
   if e->>'destination'='Propuesta en preparación' and k='reactivate' then why:='proposal-capability-pending-H2-003';
   elsif jsonb_typeof(e->'support')='object' and (e->'support')-array['contact','need','scope','pending']='{}'::jsonb then
    dest:=e->>'destination';allowed:=(dest='En contacto' and nullif(btrim(e->'support'->>'contact'),'') is not null)
     or (dest='Necesidad definida' and nullif(btrim(e->'support'->>'need'),'') is not null and nullif(btrim(e->'support'->>'scope'),'') is not null and jsonb_typeof(e->'support'->'pending')='array');
   end if;
  end if;
 elsif k='reject_alternative' then id:='AC-005';dest:=s;allowed:=s not in ('Aceptada / Ganada','Perdida','En pausa') and nullif(btrim(e->>'alternativeRef'),'') is not null and nullif(btrim(e->>'context'),'') is not null;
 end if;
 return jsonb_build_object('allowed',coalesce(allowed,false),'destination',case when allowed then dest end,'id',id,'blocker',coalesce(why,'commercial-guards-required'));
end $function$

CREATE OR REPLACE FUNCTION crm_api.b03_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea, cf2p bytea, cf2s bytea, cf1p bytea, cf1s bytea, cq bytea)
 RETURNS TABLE(result_ref uuid, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];cv text[];m jsonb;a jsonb;e jsonb;d jsonb;
 actor uuid;scope text;target uuid;opid uuid;lead uuid;action text;fingerprint text;prior jsonb;after_data jsonb;
 old crm_private.b03_opportunities%rowtype;op crm_private.b03_operations%rowtype;l crm_private.b03_leads%rowtype;ref text;ik text;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'COMMERCIAL_DENIED' using errcode='42501';end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H2-COM-1' then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
 m:=v[2]::jsonb;a:=m->'material';e:=m->'event';actor:=hf[12]::uuid;scope:=hf[17];
 action:=m->>'action';target:=(m->>'targetId')::uuid;opid:=(m->>'operationId')::uuid;lead:=nullif(m->>'leadId','')::uuid;
 if m-array['action','targetId','operationId','leadId','expectedRevision','sourceRef','reason','material','event']<>'{}'::jsonb
  or jsonb_typeof(m->'sourceRef') is distinct from 'string' or jsonb_typeof(m->'reason') is distinct from 'string'
  or nullif(btrim(m->>'sourceRef'),'') is null or nullif(btrim(m->>'reason'),'') is null or coalesce(m->>'expectedRevision','') !~ '^(0|[1-9][0-9]*)$'
  or action is null or action not in ('lead','direct','convert','progress') then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
 fingerprint:=encode(crm_crypto.digest(convert_to(m::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(opid::text,0));
 select * into op from crm_private.b03_operations where operation_id=opid;
 if found then
  if op.admin_scope<>scope or op.actor_id<>actor or op.fingerprint<>fingerprint then raise exception 'COMMERCIAL_REPLAY_CONFLICT';end if;
  result_ref:=op.result_ref;replayed:=true;
 else
  perform pg_advisory_xact_lock(hashtextextended(coalesce(lead,target)::text,31));
  if action in ('lead','direct','convert') then
   if e is not null then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   if jsonb_typeof(a) is distinct from 'object' or a-array['contact','need','commercialPossible','pending','dates','participants','services','budget','contactId','organizationId','groupId']<>'{}'::jsonb
    or not(a ?& array['contact','need','commercialPossible','pending']) or jsonb_typeof(a->'pending') is distinct from 'array'
    or (a->'need'<>'null'::jsonb and (jsonb_typeof(a->'need')<>'string' or nullif(btrim(a->>'need'),'') is null))
    or a->'commercialPossible' not in ('null'::jsonb,'true'::jsonb,'false'::jsonb) then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   if a->'contact'<>'null'::jsonb and (jsonb_typeof(a->'contact')<>'object' or (a->'contact')-array['channel','address','sourceRef','valid']<>'{}'::jsonb
    or jsonb_typeof(a->'contact'->'channel') is distinct from 'string' or jsonb_typeof(a->'contact'->'address') is distinct from 'string'
    or jsonb_typeof(a->'contact'->'sourceRef') is distinct from 'string'
    or not((a->'contact') ?& array['channel','address','sourceRef','valid']) or a->'contact'->'valid' not in ('true'::jsonb,'false'::jsonb)
    or nullif(btrim(a->'contact'->>'channel'),'') is null or nullif(btrim(a->'contact'->>'address'),'') is null
    or nullif(btrim(a->'contact'->>'sourceRef'),'') is null) then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   if exists(select 1 from jsonb_array_elements(a->'pending') x where jsonb_typeof(x)<>'string' or btrim(x#>>'{}')='') then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   foreach ik in array array['contact','organization','group'] loop
    ref:=a->>(ik||'Id');if ref is not null and not exists(select 1 from crm_private.identity_entities i
     where i.identity_id=ref::uuid and i.identity_kind=ik and i.admin_scope=scope and i.archived_at is null and i.merged_into_id is null
      and (ik<>'group' or i.context_id=target)) then raise exception 'COMMERCIAL_IDENTITY_INVALID';end if;
   end loop;
   if action='lead' then
    if lead is not null or (m->>'expectedRevision')::bigint<>0 then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
    insert into crm_private.b03_leads(lead_id,admin_scope,source_ref,responsible_actor,material) values(target,scope,m->>'sourceRef',actor,a);
    select to_jsonb(t) into after_data from crm_private.b03_leads t where lead_id=target;d:=jsonb_build_object('id','BR-LEAD-001');
   else
    if a->'contact'->'valid' is distinct from 'true'::jsonb or nullif(btrim(a->>'need'),'') is null or a->'commercialPossible' is distinct from 'true'::jsonb then raise exception 'COMMERCIAL_MINIMUM_REQUIRED:SM-OP-01';end if;
    if (m->>'expectedRevision')::bigint<>0 then raise exception 'COMMERCIAL_REVISION_CONFLICT';end if;
    if action='convert' then
     select * into l from crm_private.b03_leads where lead_id=lead and admin_scope=scope;
     if not found then raise exception 'COMMERCIAL_LEAD_REQUIRED';end if;
     select * into old from crm_private.b03_opportunities where lead_id=lead;
     if found then
      if old.admin_scope<>scope or old.creation_material<>a or old.source_ref<>l.source_ref then raise exception 'COMMERCIAL_CONVERSION_CONFLICT';end if;
      target:=old.opportunity_id;result_ref:=target;replayed:=true;
     end if;
    elsif lead is not null then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
    if old.opportunity_id is null then
     if exists(select 1 from crm_private.identity_contexts where context_id=target) then
      if not exists(select 1 from crm_private.identity_contexts where context_id=target and context_kind='opportunity' and admin_scope=scope and verified) then raise exception 'COMMERCIAL_CONTEXT_INVALID';end if;
     else
      insert into crm_private.identity_contexts(context_id,context_kind,admin_scope,source_ref,evidence_ref,verified)
       values(target,'opportunity',scope,coalesce(l.source_ref,m->>'sourceRef'),m->>'sourceRef',true);
     end if;
     insert into crm_private.b03_opportunities(opportunity_id,lead_id,admin_scope,source_ref,responsible_actor,material,creation_material,state,revision)
      values(target,lead,scope,coalesce(l.source_ref,m->>'sourceRef'),coalesce(l.responsible_actor,actor),a,a,'Nueva',1);
     -- Reuse the actual H1 API, allocator, counter, D040 and immutable registry.
     cv:=crm_f1.fields(cq);
     if cv is distinct from array['CRM-H1-RESOLVE1','assign_code',target::text,target::text,'','OP',m->>'sourceRef',m->>'sourceRef',m->>'reason','0'] then raise exception 'COMMERCIAL_CODE_CONTRACT_INVALID';end if;
     if not exists(select 1 from crm_private.identity_codes c where c.code_kind='OP' and c.target_id=target and c.admin_scope=scope) then
      perform crm_api.identity_resolve(cf2p,cf2s,cf1p,cf1s,cq);end if;
     select to_jsonb(t) into after_data from crm_private.b03_opportunities t where opportunity_id=target;
     d:=jsonb_build_object('id','SM-OP-01');
    end if;
   end if;
  else
   select * into old from crm_private.b03_opportunities where opportunity_id=target and admin_scope=scope for update;
   if not found then raise exception 'COMMERCIAL_DENIED';end if;
   if old.revision<>(m->>'expectedRevision')::bigint then raise exception 'COMMERCIAL_REVISION_CONFLICT';end if;
   if a is not null or lead is not null or jsonb_typeof(e) is distinct from 'object' then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   d:=crm_private.b03_decide(old.state,e);
   if d->>'allowed' is distinct from 'true' then raise exception 'COMMERCIAL_BLOCKED:%:%',d->>'id',d->>'blocker';end if;
   if e->>'type'='contact' then
    if not exists(select 1 from crm_private.b07_records r join crm_private.b07_links b using(record_id)
     where r.record_id=(e->>'communicationId')::uuid and r.admin_scope=scope and b.admin_scope=scope
     and b.context_kind='opportunity' and b.context_id=target and r.record_kind='communication'
     and nullif(r.material->>'channel','') is not null and nullif(r.material->>'recipient_ref','') is not null
     and r.material->>'direction' in ('incoming','outgoing')) then raise exception 'COMMERCIAL_CONTACT_EVIDENCE_REQUIRED';end if;
   end if;
   if e->>'type' in ('contact','negotiate') then
    ref:=case when e->>'type'='contact' then e->>'evidenceId' else e->>'exchangeRef' end;
    if not exists(select 1 from crm_private.b07_records r join crm_private.b07_links b using(record_id)
     where r.record_id=ref::uuid and r.admin_scope=scope and b.admin_scope=scope and b.context_kind='opportunity' and b.context_id=target
     and ((r.record_kind='evidence' and r.material->>'certainty'='reviewed') or (r.record_kind='communication' and r.material->>'direction'='incoming'))) then
     raise exception 'COMMERCIAL_ACTUAL_EVIDENCE_REQUIRED';end if;
   end if;
   prior:=to_jsonb(old);
   if e->>'type'='define_need' or e->>'destination'='Necesidad definida' then
    a:=case when e->>'type'='define_need' then e else e->'support' end;
    update crm_private.b03_opportunities set material=jsonb_set(jsonb_set(material,'{need}',a->'need'),'{pending}',a->'pending') where opportunity_id=target;
   end if;
   update crm_private.b03_opportunities set state=d->>'destination',revision=revision+1,updated_at=clock_timestamp(),
    previous_state=case when e->>'type'='pause' then old.state else previous_state end,
    loss_reason=case when e->>'type'='lose' then e->>'lossReason' else loss_reason end where opportunity_id=target;
   select to_jsonb(t) into after_data from crm_private.b03_opportunities t where opportunity_id=target;
  end if;
  insert into crm_private.b03_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(opid,scope,actor,fingerprint,target);
  if after_data is not null then
   insert into crm_private.b03_history(history_id,subject_id,admin_scope,before_state,after_state,event,normative_ids,reason,source_ref,actor_id,occurred_at)
    values(opid,target,scope,prior,after_data,coalesce(e,jsonb_build_object('type',action,'leadId',lead)),jsonb_build_array(d->>'id'),m->>'reason',m->>'sourceRef',actor,(e->>'occurredAt')::timestamptz);
  end if;
  result_ref:=target;replayed:=coalesce(replayed,false);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');
 perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b03_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];m jsonb;data jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'COMMERCIAL_DENIED';end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H2-COM-READ1' then raise exception 'COMMERCIAL_INPUT_INVALID';end if;m:=v[2]::jsonb;
 if m->>'kind'='lead' then select to_jsonb(t) into data from crm_private.b03_leads t where lead_id=(m->>'targetId')::uuid and admin_scope=hf[17];
 elsif m->>'kind'='opportunity' then select to_jsonb(t)||jsonb_build_object('human_code',c.human_code) into data
  from crm_private.b03_opportunities t join crm_private.identity_codes c on c.target_id=t.opportunity_id and c.code_kind='OP' and c.admin_scope=t.admin_scope where opportunity_id=(m->>'targetId')::uuid and t.admin_scope=hf[17];
 elsif m->>'kind'='history' then select coalesce(jsonb_agg(to_jsonb(t) order by recorded_at,history_id),'[]'::jsonb) into data from crm_private.b03_history t where subject_id=(m->>'targetId')::uuid and admin_scope=hf[17];
 else raise exception 'COMMERCIAL_INPUT_INVALID';end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return data;
end $function$

CREATE OR REPLACE FUNCTION crm_api.proposal_sources(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];m jsonb;r text;data jsonb:='[]';s jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'PROPOSAL_DENIED';end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H2-PROP-SOURCES1' then raise exception 'PROPOSAL_INPUT_INVALID';end if;m:=v[2]::jsonb;
 if not exists(select 1 from crm_private.b03_opportunities where opportunity_id=(m->>'opportunityId')::uuid and admin_scope=hf[17]) then raise exception 'PROPOSAL_OPPORTUNITY_REQUIRED';end if;
 for r in select jsonb_array_elements_text(m->'references') loop
  s:=null;
  select jsonb_build_object('id',c.revision_id,'kind',i.item_kind,'definition',c.definition,'sourceRef',c.source_ref,'version',c.revision_number::text) into s
   from crm_private.catalog_revisions c join crm_private.catalog_items i using(item_id) where c.revision_id=r::uuid and c.admin_scope=hf[17];
  if s is null then select jsonb_build_object('id',c.revision_id,'kind',i.item_kind,'definition',c.definition,'sourceRef',c.source_ref,'version',c.revision_number::text) into s
   from crm_private.commercial_revisions c join crm_private.commercial_items i using(item_id) where c.revision_id=r::uuid and c.admin_scope=hf[17];end if;
  if s is null then select jsonb_build_object('id',c.record_id,'kind',c.record_kind,'definition',c.material,'sourceRef',c.source_ref,'version','1') into s
   from crm_private.b07_records c join crm_private.b07_links l using(record_id) where c.record_id=r::uuid and c.admin_scope=hf[17] and l.context_id=(m->>'opportunityId')::uuid and l.context_kind='opportunity' limit 1;end if;
  if s is null then raise exception 'PROPOSAL_SOURCE_INVALID';end if;data:=data||jsonb_build_array(s);
  if s->>'kind'='service' then
   data:=data||coalesce((select jsonb_agg(jsonb_build_object('id',er.revision_id,'kind','eligibility_rule','definition',er.definition,'sourceRef',er.source_ref,'version',er.revision_number::text,'serviceRevisionId',r))
    from crm_private.commercial_items ei join lateral (select * from crm_private.commercial_revisions cr where cr.item_id=ei.item_id order by revision_number desc limit 1) er on true
    join crm_private.catalog_revisions sr on sr.revision_id=r::uuid where ei.item_kind='eligibility_rule' and ei.admin_scope=hf[17] and ei.catalog_item_id=sr.item_id),'[]'::jsonb);
  end if;
 end loop;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return data;
end $function$

CREATE OR REPLACE FUNCTION crm_api.proposal_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea, cf2p bytea, cf2s bytea, cf1p bytea, cf1s bytea, cq bytea)
 RETURNS TABLE(result_ref uuid, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];a jsonb;c jsonb;econ jsonb;sources jsonb;m jsonb;l jsonb;prior jsonb;after_data jsonb;norm jsonb;
 actor uuid;scope text;opid uuid;root uuid;opp uuid;fp text;action text;versionid uuid;base uuid;prep crm_private.b03_preparations%rowtype;
 p crm_private.b03_proposals%rowtype;pv crm_private.b03_proposal_versions%rowtype;o crm_private.b03_opportunities%rowtype;operation crm_private.b03_proposal_operations%rowtype;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'PROPOSAL_DENIED';end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H2-PROP-1' then raise exception 'PROPOSAL_INPUT_INVALID';end if;
 a:=v[2]::jsonb;actor:=hf[12]::uuid;scope:=hf[17];root:=(a->>'proposalId')::uuid;opp:=(a->>'opportunityId')::uuid;opid:=(a->>'operationId')::uuid;
 action:=a->>'action';base:=nullif(a->>'baseVersionId','')::uuid;versionid:=nullif(a->>'versionId','')::uuid;
 if a-array['action','operationId','proposalId','opportunityId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','content','baseVersionId','reviewed','versionId','partId','requestEvidenceId','economics','sources']<>'{}'::jsonb
  or action is null or action not in ('prepare','fix','partial_request') or jsonb_typeof(a->'sourceRef') is distinct from 'string' or jsonb_typeof(a->'reason') is distinct from 'string'
  or nullif(btrim(a->>'sourceRef'),'') is null or nullif(btrim(a->>'reason'),'') is null then raise exception 'PROPOSAL_INPUT_INVALID';end if;
 fp:=encode(crm_crypto.digest(convert_to((a-array['economics','sources'])::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(opid::text,0));
 select * into operation from crm_private.b03_proposal_operations where operation_id=opid;
 if found then
  if operation.admin_scope<>scope or operation.actor_id<>actor or operation.fingerprint<>fp then raise exception 'PROPOSAL_REPLAY_CONFLICT';end if;
  result_ref:=operation.result_ref;replayed:=true;
 else
  -- Same existing Opportunity lock order as H2-001, followed by Proposal root.
  perform pg_advisory_xact_lock(hashtextextended(opp::text,31));
  select * into o from crm_private.b03_opportunities where opportunity_id=opp and admin_scope=scope for update;
  if not found then raise exception 'PROPOSAL_OPPORTUNITY_REQUIRED';end if;
  perform pg_advisory_xact_lock(hashtextextended(root::text,33));
  select * into p from crm_private.b03_proposals where proposal_id=root and admin_scope=scope for update;
  if p.proposal_id is not null and p.opportunity_id<>opp then raise exception 'PROPOSAL_RELATION_INVALID';end if;
  if coalesce(p.revision,0)<>(a->>'expectedRevision')::bigint then raise exception 'PROPOSAL_REVISION_CONFLICT';end if;
  if action='prepare' then
   c:=a->'content';econ:=a->'economics';sources:=a->'sources';
   if versionid is not null or not crm_private.proposal_content_guard(c,false) or jsonb_typeof(econ) is distinct from 'array' or jsonb_typeof(sources) is distinct from 'array' or jsonb_array_length(sources)=0 then raise exception 'PROPOSAL_BLOCKED:SM-PV-01';end if;
   if o.revision<>(a->>'expectedOpportunityRevision')::bigint then raise exception 'PROPOSAL_OPPORTUNITY_REVISION_CONFLICT';end if;
   if o.state not in ('Nueva','En contacto','Necesidad definida','Propuesta en preparación','Propuesta enviada','Negociación / cambios') then raise exception 'PROPOSAL_BLOCKED:SM-OP-04';end if;
   if base is not null then
    select * into pv from crm_private.b03_proposal_versions where version_id=base and proposal_id=root;
    if not found or a->'reviewed' is distinct from 'true'::jsonb or pv.content=c then raise exception 'PROPOSAL_BLOCKED:SM-PV-06';end if;prior:=to_jsonb(pv);
   elsif p.last_version_number>0 then raise exception 'PROPOSAL_BASE_VERSION_REQUIRED';end if;
   -- Enforce real, scoped and matching sources at the persistence boundary too.
   for m in select jsonb_array_elements(c->'modalities') loop
    if m ? 'packRevisionId' and not exists(select 1 from crm_private.commercial_revisions r join crm_private.commercial_items i using(item_id) where r.revision_id=(m->>'packRevisionId')::uuid and r.admin_scope=scope and i.item_kind in ('pack','custom_pack')) then raise exception 'PROPOSAL_SOURCE_INVALID';end if;
    for l in select jsonb_array_elements(m->'lines') loop
     if not exists(select 1 from crm_private.catalog_revisions r join crm_private.catalog_items i using(item_id) where r.revision_id=(l->>'serviceRevisionId')::uuid and r.admin_scope=scope and i.item_kind='service')
      or not exists(select 1 from crm_private.catalog_revisions r join crm_private.catalog_items i using(item_id) where r.revision_id=(l->>'unitRevisionId')::uuid and r.admin_scope=scope and i.item_kind='unit') then raise exception 'PROPOSAL_SOURCE_INVALID';end if;
     if l ? 'tariffRevisionId' and not exists(select 1 from crm_private.commercial_revisions r join crm_private.commercial_items i using(item_id) join crm_private.catalog_revisions sr on sr.revision_id=(l->>'serviceRevisionId')::uuid where r.revision_id=(l->>'tariffRevisionId')::uuid and r.admin_scope=scope and i.item_kind='tariff' and i.catalog_item_id=sr.item_id and r.definition->>'unit_revision_id'=l->>'unitRevisionId') then raise exception 'PROPOSAL_SOURCE_INVALID';end if;
    end loop;
   end loop;
   if p.proposal_id is null then
    insert into crm_private.b03_proposals(proposal_id,opportunity_id,admin_scope,revision,source_ref,actor_id) values(root,opp,scope,1,a->>'sourceRef',actor);
    if crm_f1.fields(cq) is distinct from array['CRM-H1-RESOLVE1','assign_code',root::text,root::text,'','PR',a->>'sourceRef',a->>'sourceRef',a->>'reason','0'] then raise exception 'PROPOSAL_CODE_CONTRACT_INVALID';end if;
    perform crm_api.identity_resolve(cf2p,cf2s,cf1p,cf1s,cq);
   else update crm_private.b03_proposals set revision=revision+1 where proposal_id=root;end if;
   insert into crm_private.b03_preparations(preparation_id,proposal_id,admin_scope,revision,content,economics,sources,base_version_id,reviewed,source_ref,reason,actor_id)
    values(opid,root,scope,coalesce(p.revision,0)+1,c,econ,sources,base,coalesce((a->>'reviewed')::boolean,false),a->>'sourceRef',a->>'reason',actor);
   select to_jsonb(t) into after_data from crm_private.b03_preparations t where preparation_id=opid;
   -- Actual preparation and commercial progress are one T01 unit; no invented stages.
   insert into crm_private.b03_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(opid,scope,actor,fp,opp);
   insert into crm_private.b03_history(history_id,subject_id,admin_scope,before_state,after_state,event,normative_ids,reason,source_ref,actor_id)
    values(opid,opp,scope,to_jsonb(o),jsonb_set(jsonb_set(to_jsonb(o),'{state}','"Propuesta en preparación"'),'{revision}',to_jsonb(o.revision+1)),jsonb_build_object('type','prepare','alternativeRef',root,'pending',c->'pending'),jsonb_build_array('SM-OP-04'),a->>'reason',a->>'sourceRef',actor);
   update crm_private.b03_opportunities set state='Propuesta en preparación',revision=revision+1,updated_at=clock_timestamp() where opportunity_id=opp;
   result_ref:=opid;norm:=jsonb_build_array('SM-PV-01','SM-OP-04',case when base is not null then 'SM-PV-06' else 'PLAN-T01' end);
  elsif action='fix' then
   if p.proposal_id is null or versionid is null or a ? 'content' then raise exception 'PROPOSAL_BLOCKED:SM-PV-02';end if;
   select * into prep from crm_private.b03_preparations where proposal_id=root order by revision desc limit 1;
   if prep.preparation_id is null or exists(select 1 from crm_private.b03_proposal_versions where preparation_id=prep.preparation_id) or not crm_private.proposal_content_guard(prep.content,true) then raise exception 'PROPOSAL_BLOCKED:SM-PV-02';end if;
   for m in select jsonb_array_elements(prep.content->'modalities') loop
    if m->'definitive'='true'::jsonb then
     for l in select jsonb_array_elements(m->'lines') loop
      if l->'included'='true'::jsonb and exists(select 1 from jsonb_array_elements(prep.sources) rs where rs->>'kind'='eligibility_rule' and rs->>'serviceRevisionId'=l->>'serviceRevisionId'
       and (rs->'definition'->>'knowledge'<>'known' or not exists(select 1 from crm_private.b07_records er join crm_private.b07_links el using(record_id) where er.record_id=nullif(l->>'eligibilityEvidenceId','')::uuid and er.admin_scope=scope and er.record_kind='evidence' and er.material->>'certainty'='reviewed' and er.material->>'claim'='eligible:'||(rs->>'id') and el.context_id=opp and el.context_kind='opportunity'))) then raise exception 'PROPOSAL_DEPENDENT_PRICE_BLOCKED:AC-085';end if;
     end loop;
    end if;
    if m->'definitive'='true'::jsonb and (m->>'finalPersonPrice' is null or exists(select 1 from jsonb_array_elements(prep.economics) e where e->>'modalityId'=m->>'id' and (e->'calculated'='null'::jsonb or jsonb_array_length(e->'blockers')>0))) then raise exception 'PROPOSAL_DEPENDENT_PRICE_BLOCKED:AC-010';end if;
   end loop;
   c:=prep.content;prior:=to_jsonb(prep);
   insert into crm_private.b03_proposal_versions(version_id,proposal_id,preparation_id,version_number,admin_scope,scope,terms_version,terms_text,terms_source,pending,content,economics,sources,replaces_version_id,reason,source_ref,actor_id)
    values(versionid,root,prep.preparation_id,p.last_version_number+1,scope,c->>'scope',c->'terms'->>'version',c->'terms'->>'text',c->'terms'->>'sourceRef',c->'pending',c,prep.economics,prep.sources,prep.base_version_id,a->>'reason',a->>'sourceRef',actor);
   for m in select jsonb_array_elements(c->'modalities') loop
    insert into crm_private.b03_proposal_modalities values(versionid,(m->>'id')::uuid,m->>'name',(m->>'participants')::bigint,(m->>'independent')::boolean,(m->>'selectable')::boolean,nullif(m->>'packRevisionId','')::uuid,m->>'conditions',(m->>'finalPersonPrice')::numeric,(m->>'definitive')::boolean,scope);
    for l in select jsonb_array_elements(m->'lines') loop
     insert into crm_private.b03_proposal_lines values(versionid,(m->>'id')::uuid,(l->>'id')::uuid,(l->>'serviceRevisionId')::uuid,(l->>'unitRevisionId')::uuid,nullif(l->>'tariffRevisionId','')::uuid,(l->>'quantity')::numeric,(l->>'included')::boolean,(l->>'independent')::boolean,(l->>'selectable')::boolean,(l->>'date')::date,(l->>'datePending')::boolean,l->>'priceBasis',(l->>'costMaterial')::boolean,l->>'sourceRef',nullif(l->>'estimateRuleEvidenceId','')::uuid,nullif(l->>'eligibilityEvidenceId','')::uuid,scope);
    end loop;
   end loop;
   update crm_private.b03_proposals set revision=revision+1,last_version_number=last_version_number+1 where proposal_id=root;
   select to_jsonb(t) into after_data from crm_private.b03_proposal_versions t where version_id=versionid;result_ref:=versionid;norm:=jsonb_build_array('SM-PV-02','PLAN-T01');
  else
   if p.proposal_id is null or versionid is null or a ? 'content' or not exists(select 1 from crm_private.b03_proposal_versions where version_id=versionid and proposal_id=root) then raise exception 'PROPOSAL_RELATION_INVALID';end if;
   if not exists(select 1 from crm_private.b07_records r join crm_private.b07_links l using(record_id) where r.record_id=(a->>'requestEvidenceId')::uuid and r.admin_scope=scope and l.context_id=opp and (r.record_kind='communication' and r.material->>'direction'='incoming' or r.record_kind='evidence' and r.material->>'certainty'='reviewed')) then raise exception 'PROPOSAL_REQUEST_EVIDENCE_REQUIRED';end if;
   if not exists(select 1 from crm_private.b03_proposal_lines where version_id=versionid and line_id=(a->>'partId')::uuid and not selectable) then raise exception 'PROPOSAL_NONSELECTION_REQUIRED';end if;
   after_data:=jsonb_build_object('versionId',versionid,'partId',a->>'partId','requestEvidenceId',a->>'requestEvidenceId','requiresNewVersion',true,'acceptanceCreated',false);
   result_ref:=opid;norm:=jsonb_build_array('AC-013','SPEC-FR-ACC-003');
  end if;
  insert into crm_private.b03_proposal_operations values(opid,root,scope,actor,fp,result_ref,action,a->>'sourceRef',a->>'reason',clock_timestamp());
  insert into crm_private.b03_proposal_history values(opid,root,scope,prior,after_data,a-array['economics','sources'],norm,actor,a->>'sourceRef',a->>'reason',clock_timestamp());replayed:=false;
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.proposal_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];a jsonb;root uuid;vid uuid;data jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'PROPOSAL_DENIED';end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H2-PROP-READ1' then raise exception 'PROPOSAL_INPUT_INVALID';end if;a:=v[2]::jsonb;root:=(a->>'proposalId')::uuid;
 if not exists(select 1 from crm_private.b03_proposals where proposal_id=root and admin_scope=hf[17]) then raise exception 'PROPOSAL_DENIED';end if;
 vid:=nullif(a->>'versionId','')::uuid;
 if a->>'kind'='preparation' then select to_jsonb(t) into data from crm_private.b03_preparations t where proposal_id=root order by revision desc limit 1;
 elsif a->>'kind'='history' then select jsonb_agg(to_jsonb(t) order by recorded_at,history_id) into data from crm_private.b03_proposal_history t where proposal_id=root;
 elsif a->>'kind'='internal' then select to_jsonb(t)||jsonb_build_object('human_code',ic.human_code) into data from crm_private.b03_proposal_versions t join crm_private.identity_codes ic on ic.target_id=root and ic.code_kind='PR' where t.proposal_id=root and (vid is null or version_id=vid) order by version_number desc limit 1;
 elsif a->>'kind'='commercial' then
  if vid is null then select version_id into vid from crm_private.b03_proposal_versions where proposal_id=root order by version_number desc limit 1;end if;
  if not exists(select 1 from crm_private.b03_proposal_versions where version_id=vid and proposal_id=root) then raise exception 'PROPOSAL_DENIED';end if;
  select coalesce(jsonb_agg(jsonb_build_object('finalPersonPrice',case when final_person_price is null then null when m.definitive then to_jsonb(to_char(final_person_price,'FM9999999999999999999999999999990.00')) else jsonb_build_object('amount',to_char(final_person_price,'FM9999999999999999999999999999990.00'),'certainty',case when exists(select 1 from crm_private.b03_proposal_versions pv,jsonb_array_elements(pv.economics) e,jsonb_array_elements(e->'components') ec where pv.version_id=vid and e->>'modalityId'=m.modality_id::text and ec->>'priceState'='estimated') then 'estimated' else 'pending' end) end,'participants',participants,'included',
   (select coalesce(jsonb_agg(jsonb_build_object('service',r.definition->>'name','quantity',l.quantity,'date',l.service_date) order by l.line_id),'[]') from crm_private.b03_proposal_lines l join crm_private.catalog_revisions r on r.revision_id=l.service_revision_id where l.version_id=vid and l.modality_id=m.modality_id and l.included)) order by modality_id),'[]') into data from crm_private.b03_proposal_modalities m where version_id=vid;
 else raise exception 'PROPOSAL_INPUT_INVALID';end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return data;
end $function$

CREATE OR REPLACE FUNCTION crm_api.offer_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fields text[];a jsonb;p crm_private.b03_proposals;o crm_private.b03_opportunities;
 v crm_private.b03_proposal_versions;i crm_private.b03_offer_issuances;prior crm_private.b03_offer_operations;
 com crm_private.b07_records;fact crm_private.b07_records;proof crm_private.b07_records;
 op uuid;root uuid;vid uuid;opp uuid;actor uuid;s text;action text;cov text;at_time timestamptz;
 fp text;res jsonb;norm jsonb;original jsonb;d integer;issued timestamptz;until_time timestamptz;l jsonb;
 reviewed boolean:=false;stale boolean:=false;pending boolean:=false;aspect text;part uuid;kind text;lo timestamptz;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OFFER_DENIED';end if;
 fields:=crm_f1.fields(q);if cardinality(fields)<>2 or fields[1]<>'CRM-H2-OFFER1' then raise exception 'OFFER_INPUT_INVALID';end if;a:=fields[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-array['action','operationId','proposalId','opportunityId','versionId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','coverage','at','actId','actKind','issuance','evidenceId','reviewEvidence','communicationId','factId','recipientId','channel','partId','partKind','lossReason','origin']<>'{}'::jsonb
 or not(a ?& array['action','operationId','proposalId','opportunityId','versionId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','coverage','at'])
 or a->>'action' not in ('issue','intent','evaluate','revalidate','send','reject')
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or jsonb_typeof(a->'expectedOpportunityRevision') is distinct from 'number'
 or a->>'expectedRevision' !~ '^[0-9]+$' or a->>'expectedOpportunityRevision' !~ '^[0-9]+$'
 or exists(select 1 from jsonb_each(a) x where x.key in ('sourceRef','reason','coverage','at') and (jsonb_typeof(x.value)<>'string' or btrim(x.value#>>'{}')=''))
 or a->>'at' !~ '^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d+)?(Z|[+-]\d\d:\d\d)$' then raise exception 'OFFER_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;root:=(a->>'proposalId')::uuid;vid:=(a->>'versionId')::uuid;opp:=(a->>'opportunityId')::uuid;
 actor:=hf[12]::uuid;s:=hf[17];action:=a->>'action';cov:=a->>'coverage';at_time:=(a->>'at')::timestamptz;
 if at_time>clock_timestamp() then raise exception 'OFFER_FUTURE_FACT';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(op::text,0));
 select * into prior from crm_private.b03_offer_operations where operation_id=op;
 if found then
  if prior.admin_scope<>s or prior.actor_id<>actor or prior.fingerprint<>fp then raise exception 'OFFER_REPLAY_CONFLICT';end if;
  res:=jsonb_build_object('id',op,'replayed',true,'result',prior.result);
 else
  perform pg_advisory_xact_lock(hashtextextended(opp::text,31));
  select * into o from crm_private.b03_opportunities where opportunity_id=opp and admin_scope=s for update;
  if not found then raise exception 'OFFER_RELATION_INVALID';end if;
  perform pg_advisory_xact_lock(hashtextextended(root::text,33));
  select * into p from crm_private.b03_proposals where proposal_id=root and opportunity_id=opp and admin_scope=s for update;
  if not found then raise exception 'OFFER_RELATION_INVALID';end if;
  select * into v from crm_private.b03_proposal_versions where version_id=vid and proposal_id=root and admin_scope=s;
  if not found or cov not in (v.scope) and not exists(select 1 from crm_private.b03_proposal_modalities where version_id=vid and modality_id::text=cov) and not exists(select 1 from crm_private.b03_proposal_lines where version_id=vid and line_id::text=cov) then raise exception 'OFFER_COVERAGE_INVALID';end if;
  if p.revision<>(a->>'expectedRevision')::bigint or o.revision<>(a->>'expectedOpportunityRevision')::bigint then raise exception 'OFFER_REVISION_CONFLICT';end if;
  original:=jsonb_build_object('proposalRevision',p.revision,'opportunity',to_jsonb(o));
  select * into i from crm_private.b03_offer_issuances where version_id=vid;
  select coalesce(max(z.occurred_at),'-infinity'::timestamptz) into lo from crm_private.b03_offer_operations z where z.version_id=vid and z.action in ('evaluate','reject') and crm_private.offer_overlap(vid,z.coverage,cov);
  lo:=greatest(lo,coalesce((select max(recorded_at) from crm_private.b03_proposal_versions where replaces_version_id=vid),'-infinity'::timestamptz));
  stale:=exists(select 1 from crm_private.b03_proposal_versions where replaces_version_id=vid)
   or exists(select 1 from crm_private.b03_offer_operations e where e.version_id=vid and e.action='reject' and crm_private.offer_overlap(vid,e.coverage,cov))
   or exists(select 1 from crm_private.b03_offer_operations e where e.version_id=vid and e.action='evaluate' and e.result->'pending'='true' and crm_private.offer_overlap(vid,e.coverage,cov));
  reviewed:=exists(select 1 from crm_private.b03_offer_operations e where e.version_id=vid and e.action='revalidate' and e.coverage=cov and e.event->>'actId'=a->>'actId' and e.event->>'actKind'=coalesce(a->>'actKind','send') and e.occurred_at=at_time and e.recorded_at>coalesce((select max(recorded_at) from crm_private.b03_offer_operations z where z.version_id=vid and z.action in ('reject','evaluate') and crm_private.offer_overlap(vid,z.coverage,cov)),'-infinity'::timestamptz));
  if action='issue' then
   if i.version_id is not null or cov<>v.scope or jsonb_typeof(a->'issuance') is distinct from 'object' or (a->'issuance')-array['issuedAt','days','limits']<>'{}'::jsonb then raise exception 'OFFER_NEW_VERSION_REQUIRED:SM-FORB-01';end if;
   if not((a->'issuance') ?& array['issuedAt','limits']) or jsonb_typeof(a->'issuance'->'limits') is distinct from 'array' then raise exception 'OFFER_INPUT_INVALID';end if;
   d:=coalesce((a->'issuance'->>'days')::integer,7);issued:=(a->'issuance'->>'issuedAt')::timestamptz;
   if d<=0 or issued<>at_time then raise exception 'OFFER_INPUT_INVALID';end if;
   until_time:=issued+make_interval(secs=>d::double precision*86400);
   if not crm_private.offer_evidence((a->>'evidenceId')::uuid,opp,s,'offer:issue:'||vid||':'||(a->'issuance'->>'issuedAt')||':'||d,cov,issued,issued) then raise exception 'OFFER_ISSUANCE_EVIDENCE_REQUIRED';end if;
   for l in select jsonb_array_elements(a->'issuance'->'limits') loop
    if l-array['aspect','until','evidenceId']<>'{}'::jsonb or l->>'aspect' not in ('prices','availability','conditions','capacity') or not crm_private.offer_evidence((l->>'evidenceId')::uuid,opp,s,'offer:limit:'||vid||':'||(l->>'aspect')||':'||(l->>'until'),cov,'-infinity',issued) then raise exception 'OFFER_LIMIT_EVIDENCE_REQUIRED';end if;
    until_time:=least(until_time,(l->>'until')::timestamptz);
   end loop;
   insert into crm_private.b03_offer_issuances(version_id,admin_scope,issued_at,effective_until,issuance,evidence_id,actor_id,source_ref) values(vid,s,issued,until_time,a->'issuance',(a->>'evidenceId')::uuid,actor,a->>'sourceRef');
   res:=jsonb_build_object('issuedAt',issued,'effectiveUntil',until_time,'days',d);norm:=jsonb_build_array('BR-PROP-004','DM-INV-011');
  elsif action='intent' then
   if nullif(a->>'recipientId','') is null or nullif(a->>'channel','') is null then raise exception 'OFFER_RECIPIENT_REQUIRED';end if;
   res:=jsonb_build_object('pendingExternal',true,'sent',false,'versionId',vid,'recipientId',a->>'recipientId','channel',a->>'channel');norm:=jsonb_build_array('PLAN-C05','BR-COMM-002');
  elsif action='evaluate' then
   if i.version_id is null or at_time<i.issued_at then raise exception 'OFFER_ISSUANCE_REQUIRED:SM-PV-04';end if;
   pending:=at_time>i.effective_until;
   if a ? 'evidenceId' then
    if not crm_private.offer_evidence((a->>'evidenceId')::uuid,opp,s,'offer:uncertain:'||vid,cov,'-infinity',at_time) then raise exception 'OFFER_UNCERTAINTY_EVIDENCE_REQUIRED';end if;pending:=true;
   end if;
   res:=jsonb_build_object('pending',pending,'expired',at_time>i.effective_until,'rejected',false,'effectiveUntil',i.effective_until);norm:=jsonb_build_array('SM-PV-04','SM-FORB-01');
  elsif action='revalidate' then
   if i.version_id is null or at_time<i.issued_at or nullif(a->>'actId','') is null or a->>'actKind' not in ('send','accept') or jsonb_typeof(a->'reviewEvidence') is distinct from 'object' or (a->'reviewEvidence')-array['prices','availability','conditions','capacity']<>'{}'::jsonb then raise exception 'OFFER_ACT_REVIEW_REQUIRED';end if;
   foreach aspect in array array['prices','availability','conditions','capacity'] loop
    if not crm_private.offer_evidence((a->'reviewEvidence'->>aspect)::uuid,opp,s,'offer:review:'||vid||':'||(a->>'actId')||':'||(a->>'actKind')||':'||aspect,cov,greatest(i.issued_at,lo),at_time) then raise exception 'OFFER_MATERIAL_REVIEW_REQUIRED:SM-PV-05';end if;
   end loop;
   res:=jsonb_build_object('reviewedForAct',a->>'actId','actKind',a->>'actKind','at',at_time,'coverage',cov,'originalEffectiveUntil',i.effective_until,'acceptanceCreated',false);norm:=jsonb_build_array('SM-PV-05','AC-008','AC-086');
  elsif action='send' then
   if coalesce(a->>'origin','manual')<>'manual' then raise exception 'OFFER_HA_TTE_REQUIRED:G3';end if;
   if i.version_id is null or at_time<i.issued_at or (at_time>i.effective_until or stale) and not reviewed then raise exception 'OFFER_ACT_REVIEW_REQUIRED:SM-PV-03';end if;
   if nullif(a->>'actId','') is null or coalesce(a->>'actKind','send')<>'send' then raise exception 'OFFER_ACT_REVIEW_REQUIRED';end if;
   if o.state not in ('Nueva','En contacto','Necesidad definida','Propuesta en preparación','Propuesta enviada','Negociación / cambios') then raise exception 'OFFER_COMMERCIAL_ORIGIN_REQUIRED:SM-OP-05';end if;
   -- Relevant definitive economics remain blocked; provisional work remains independent.
   if exists(select 1 from jsonb_array_elements(v.content->'modalities') m join lateral jsonb_array_elements(v.economics) e on e->>'modalityId'=m->>'id' where m->'definitive'='true' and (cov=v.scope or cov=m->>'id' or exists(select 1 from jsonb_array_elements(m->'lines') z where z->>'id'=cov)) and (e->'calculated'='null' or jsonb_array_length(e->'blockers')>0)) then raise exception 'OFFER_DEFINITIVE_DATA_REQUIRED:BR-ECON-001';end if;
   -- Current material checks are B07 reviews, not availability/provider confirmations.
   foreach aspect in array array['prices','availability','conditions','capacity'] loop
    if not crm_private.offer_evidence((a->'reviewEvidence'->>aspect)::uuid,opp,s,'offer:review:'||vid||':'||(a->>'actId')||':send:'||aspect,cov,greatest(i.issued_at,lo),at_time) then raise exception 'OFFER_MATERIAL_REVIEW_REQUIRED:SM-PV-03';end if;
   end loop;
   select * into com from crm_private.b07_records where record_id=(a->>'communicationId')::uuid and admin_scope=s;
   select * into fact from crm_private.b07_records where record_id=(a->>'factId')::uuid and admin_scope=s;
   select * into proof from crm_private.b07_records where record_id=(fact.material->>'evidence_id')::uuid and admin_scope=s;
   if com.record_kind is distinct from 'communication' or com.material->>'direction' is distinct from 'outgoing' or com.material->>'proposal_version_ref' is distinct from vid::text or com.material->>'recipient_ref' is distinct from a->>'recipientId' or com.material->>'channel' is distinct from a->>'channel' or com.material->>'coverage' is distinct from cov
    or fact.record_kind is distinct from 'communication_fact' or fact.original_id is distinct from com.record_id or fact.material->>'fact_kind' is distinct from 'sent' or fact.material->>'party_ref' is distinct from a->>'recipientId' or fact.material->>'coverage' is distinct from cov or fact.occurred_at is distinct from at_time
    or proof.record_kind is distinct from 'evidence' or not crm_private.offer_evidence(proof.record_id,opp,s,'offer:sent:'||vid||':'||(a->>'actId')||':'||(a->>'recipientId')||':'||(a->>'channel'),cov,at_time,at_time)
    or not exists(select 1 from crm_private.identity_entities where identity_id=(a->>'recipientId')::uuid and admin_scope=s and identity_kind='contact' and identity_verified and archived_at is null and merged_into_id is null)
    or not exists(select 1 from crm_private.b07_links bl where bl.record_id=com.record_id and bl.admin_scope=s and bl.context_kind='opportunity' and bl.context_id=opp and bl.coverage=a->>'coverage')
    or not exists(select 1 from crm_private.b07_links bl where bl.record_id=fact.record_id and bl.admin_scope=s and bl.context_kind='opportunity' and bl.context_id=opp and bl.coverage=a->>'coverage') then raise exception 'OFFER_REAL_SEND_REQUIRED:SM-CO-04';end if;
   insert into crm_private.b03_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(op,s,actor,fp,opp);
   insert into crm_private.b03_history(history_id,subject_id,admin_scope,before_state,after_state,event,normative_ids,reason,source_ref,actor_id)
    values(op,opp,s,to_jsonb(o),jsonb_set(jsonb_set(to_jsonb(o),'{state}','"Propuesta enviada"'),'{revision}',to_jsonb(o.revision+1)),a,jsonb_build_array('SM-OP-05'),a->>'reason',a->>'sourceRef',actor);
   update crm_private.b03_opportunities set state='Propuesta enviada',revision=revision+1,updated_at=clock_timestamp() where opportunity_id=opp;
   res:=jsonb_build_object('sent',true,'received',false,'acceptanceCreated',false,'versionId',vid,'communicationId',com.record_id,'factId',fact.record_id);norm:=jsonb_build_array('SM-PV-03','SM-OP-05','SM-CO-04');
  else
   part:=nullif(a->>'partId','')::uuid;kind:=a->>'partKind';
   if kind is null or kind not in ('version','modality','line') or nullif(btrim(a->>'lossReason'),'') is null
    or kind='version' and (part is distinct from vid or cov<>v.scope)
    or kind='modality' and not exists(select 1 from crm_private.b03_proposal_modalities where version_id=vid and modality_id=part and cov=part::text)
    or kind='line' and not exists(select 1 from crm_private.b03_proposal_lines where version_id=vid and line_id=part and cov=part::text) then raise exception 'OFFER_REJECTION_SCOPE_REQUIRED';end if;
   select * into com from crm_private.b07_records where record_id=(a->>'communicationId')::uuid and admin_scope=s;
   if com.record_kind is distinct from 'communication' or com.material->>'direction' is distinct from 'incoming' or com.material->>'proposal_version_ref' is distinct from vid::text or com.material->>'sender_ref' is distinct from a->>'recipientId' or com.material->>'coverage' is distinct from cov or com.material->>'channel' is distinct from a->>'channel' or com.occurred_at is distinct from at_time
    or not exists(select 1 from crm_private.identity_entities where identity_id=(a->>'recipientId')::uuid and admin_scope=s and identity_kind='contact' and identity_verified and archived_at is null and merged_into_id is null)
    or not exists(select 1 from crm_private.b07_links bl where bl.record_id=com.record_id and bl.admin_scope=s and bl.context_kind='opportunity' and bl.context_id=opp and bl.coverage=a->>'coverage')
    or not exists(select 1 from crm_private.identity_designations d where d.context_id=opp and d.party_id=(a->>'recipientId')::uuid and d.admin_scope=s and d.role_kind='primary_contact' and d.verified and coalesce(d.effective_at,d.recorded_at)<=at_time and (d.ended_at is null or d.ended_at>at_time))
    or not crm_private.offer_evidence((a->>'evidenceId')::uuid,opp,s,'offer:reject:'||vid||':'||part||':'||(a->>'recipientId')||':'||(a->>'lossReason'),cov,at_time,at_time) then raise exception 'OFFER_ATTRIBUTABLE_REJECTION_REQUIRED:SM-PV-08';end if;
   res:=jsonb_build_object('rejected',true,'partKind',kind,'partId',part,'reason',a->>'lossReason','opportunityLost',false,'acceptanceCreated',false);norm:=jsonb_build_array('SM-PV-08','AC-005','AC-086');
  end if;
  update crm_private.b03_proposals set revision=revision+1 where proposal_id=root;
  insert into crm_private.b03_offer_operations values(op,root,vid,s,actor,fp,action,cov,at_time,a,res,a->>'sourceRef',a->>'reason',clock_timestamp());
  insert into crm_private.b03_offer_history(history_id,admin_scope,before_data,after_data,normative_ids,actor_id) values(op,s,original,res,norm,actor);
  res:=jsonb_build_object('id',op,'replayed',false,'result',res);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return res;
end $function$

CREATE OR REPLACE FUNCTION crm_api.offer_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];f text[];a jsonb;vid uuid;data jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OFFER_DENIED';end if;
 f:=crm_f1.fields(q);if cardinality(f)<>2 or f[1]<>'CRM-H2-OFFER-READ1' then raise exception 'OFFER_INPUT_INVALID';end if;a:=f[2]::jsonb;vid:=(a->>'versionId')::uuid;
 if not exists(select 1 from crm_private.b03_proposal_versions where version_id=vid and proposal_id=(a->>'proposalId')::uuid and admin_scope=hf[17]) then raise exception 'OFFER_DENIED';end if;
 select jsonb_build_object('issuance',(select to_jsonb(t) from crm_private.b03_offer_issuances t where version_id=vid),'events',coalesce((select jsonb_agg(to_jsonb(t) order by recorded_at,operation_id) from crm_private.b03_offer_operations t where version_id=vid),'[]')) into data;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return data;
end $function$

CREATE OR REPLACE FUNCTION crm_api.acceptance_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fields text[];a jsonb;p crm_private.b03_proposals;o crm_private.b03_opportunities;
 v crm_private.b03_proposal_versions;i crm_private.b03_offer_issuances;prior crm_private.b03_acceptance_operations;
 acc crm_private.b03_acceptances;com crm_private.b07_records;des crm_private.identity_designations;
 op uuid;aid uuid;root uuid;vid uuid;opp uuid;actor uuid;s text;action text;cov text;at_time timestamptz;
 fp text;res jsonb;norm jsonb;original jsonb;identified boolean;selectable boolean;valid boolean;proof_ok boolean;aspect text;
 stale_at timestamptz;reviewed boolean;destination text;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'ACCEPTANCE_DENIED';end if;
 fields:=crm_f1.fields(q);if cardinality(fields)<>2 or fields[1]<>'CRM-H2-ACCEPTANCE1' then raise exception 'ACCEPTANCE_INPUT_INVALID';end if;a:=fields[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-array['action','operationId','acceptanceId','proposalId','opportunityId','versionId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','coverage','at','accepterId','designationId','channel','terms','evidenceId','communicationId','authorityEvidenceId','reviewEvidence','won','humanReviewed','reevaluation','origin']<>'{}'::jsonb
