   if expected_lines is null or actual_lines is distinct from expected_lines then raise exception 'BOOKING_EXACT_SELECTION_REQUIRED:SM-FORB-31';end if;
   insert into crm_private.identity_contexts(context_id,context_kind,admin_scope,source_ref,evidence_ref,verified) values(bid,'booking',s,a->>'sourceRef',a->>'evidenceId',true);
   insert into crm_private.b04_bookings(booking_id,opportunity_id,acceptance_id,verification_id,proposal_id,version_id,admin_scope,actor_id,responsible_actor,state,revision,coverage,terms,chain_snapshot,detail,effect_fingerprint,evidence_id,source_ref)
    values(bid,opp,aid,z.verification_id,p.proposal_id,v.version_id,s,actor,o.responsible_actor,'Pendiente de preparación',1,acc.coverage,acc.terms,jsonb_build_object('opportunity',to_jsonb(o),'acceptance',to_jsonb(acc),'verification',to_jsonb(z),'version',to_jsonb(v)),d,efp,(a->>'evidenceId')::uuid,a->>'sourceRef');
   for sv in select * from jsonb_array_elements(d->'services') loop
    if sv-array['id','serviceRevisionId','nature','variant','provider','place','schedule','contributions','nights']<>'{}'::jsonb or not(sv ?& array['id','serviceRevisionId','nature','variant','provider','place','schedule','contributions','nights'])
     or sv->>'nature' not in ('internal','external') or sv->>'nature'='internal' and sv->'provider'<>'null'::jsonb then raise exception 'BOOKING_SERVICE_INVALID';end if;
    sid:=(sv->>'id')::uuid;
    select x into sr from jsonb_array_elements(v.sources) x where x->>'id'=sv->>'serviceRevisionId' and x->>'kind'='service';
    if sr is null or sr->'definition'->>'nature'<>sv->>'nature' then raise exception 'BOOKING_SERVICE_SOURCE_INVALID';end if;
    insert into crm_private.b04_services values(sid,bid,s,'Pendiente',1,(sv->>'serviceRevisionId')::uuid,sv->>'nature',sv);
    for c in select * from jsonb_array_elements(sv->'contributions') loop
     if c-array['id','lineId','modalityId','quantity','attendees','certainty']<>'{}'::jsonb or not(c ?& array['id','lineId','modalityId','quantity','attendees','certainty']) then raise exception 'BOOKING_CONTRIBUTION_INVALID';end if;
     select * into line from crm_private.b03_proposal_lines where version_id=v.version_id and line_id=(c->>'lineId')::uuid;
     select * into m from crm_private.b03_proposal_modalities where version_id=v.version_id and modality_id=line.modality_id;
     if line.service_revision_id<>(sv->>'serviceRevisionId')::uuid or line.modality_id<>(c->>'modalityId')::uuid or line.quantity is distinct from (c->>'quantity')::numeric
      or m.participants is distinct from (c->>'attendees')::bigint or c->>'certainty' not in ('estimated','confirmed') then raise exception 'BOOKING_SOURCE_QUANTITY_REQUIRED:SM-FORB-10';end if;
     insert into crm_private.b04_modalities values(bid,m.modality_id,v.version_id,s,to_jsonb(m)) on conflict do nothing;
     insert into crm_private.b04_contributions values((c->>'id')::uuid,bid,sid,m.modality_id,v.version_id,line.line_id,s,line.quantity,m.participants,c->>'certainty',line.unit_revision_id,to_jsonb(line));
    end loop;
    for c in select * from jsonb_array_elements(sv->'nights') loop
     if c-array['id','date','contributionIds']<>'{}'::jsonb or not(c ?& array['id','date','contributionIds']) or jsonb_array_length(c->'contributionIds')=0 then raise exception 'BOOKING_NIGHT_INVALID';end if;
     nid:=(c->>'id')::uuid;insert into crm_private.b04_nights values(nid,sid,s,(c->>'date')::date);
     for ref in select value::uuid from jsonb_array_elements_text(c->'contributionIds') loop
      if not exists(select 1 from crm_private.b04_contributions bc join crm_private.b03_proposal_lines l using(version_id,line_id) where bc.contribution_id=ref and bc.service_id=sid and l.service_date=(c->>'date')::date) then raise exception 'BOOKING_NIGHT_SOURCE_INVALID';end if;
      insert into crm_private.b04_night_occupancies values(nid,ref,s);
     end loop;
    end loop;
   end loop;
   for part in select * from jsonb_array_elements(d->'participants') loop
    pid:=(part->>'id')::uuid;
    if part-array['id','name','contactId','evidenceId','sourceRef']<>'{}'::jsonb or btrim(coalesce(part->>'name',''))='' or btrim(coalesce(part->>'sourceRef',''))=''
     or not crm_private.offer_evidence((part->>'evidenceId')::uuid,opp,s,'booking:participant:'||aid||':'||pid,acc.coverage,'-infinity',clock_timestamp()) then raise exception 'BOOKING_NOMINAL_EVIDENCE_REQUIRED';end if;
    if part->>'contactId' is not null and not exists(select 1 from crm_private.identity_entities where identity_id=(part->>'contactId')::uuid and identity_kind='contact' and identity_verified and admin_scope=s) then raise exception 'BOOKING_CONTACT_VERIFICATION_REQUIRED';end if;
    insert into crm_private.b04_participants values(pid,bid,s,part->>'name',nullif(part->>'contactId','')::uuid,(part->>'evidenceId')::uuid,part->>'sourceRef');
   end loop;
   for ass in select * from jsonb_array_elements(d->'assignments') loop
    sid:=(ass->>'serviceId')::uuid;nid:=nullif(ass->>'nightId','')::uuid;pid:=(ass->>'participantId')::uuid;
    if ass-array['participantId','serviceId','nightId','necessity','evidenceId']<>'{}'::jsonb or btrim(coalesce(ass->>'necessity',''))='' or not exists(select 1 from crm_private.b04_participants where participant_id=pid and booking_id=bid)
     or not exists(select 1 from crm_private.b04_services where service_id=sid and booking_id=bid)
     or (nid is not null and not exists(select 1 from crm_private.b04_nights where night_id=nid and service_id=sid))
     or not crm_private.offer_evidence((ass->>'evidenceId')::uuid,opp,s,'booking:nominal:'||aid||':'||sid||':'||coalesce(nid::text,'service'),acc.coverage,'-infinity',clock_timestamp()) then raise exception 'BOOKING_NOMINAL_NECESSITY_REQUIRED';end if;
    insert into crm_private.b04_assignments values(pid,sid,nid,s,ass->>'necessity',(ass->>'evidenceId')::uuid);
    select coalesce(sum(bc.attendees),0) into total from crm_private.b04_contributions bc where bc.service_id=sid and (nid is null or exists(select 1 from crm_private.b04_night_occupancies no where no.contribution_id=bc.contribution_id and no.night_id=nid));
    if (select count(*) from crm_private.b04_assignments x where x.service_id=sid and x.night_id is not distinct from nid)>total then raise exception 'BOOKING_NOMINAL_DISCREPANCY_REVIEW_REQUIRED';end if;
   end loop;
   if exists(select 1 from crm_private.b04_participants x where x.booking_id=bid and not exists(select 1 from crm_private.b04_assignments y where y.participant_id=x.participant_id)) then raise exception 'BOOKING_NOMINAL_NECESSITY_REQUIRED';end if;
   fs:=crm_f1.fields(cq);
   if fs is distinct from array['CRM-H1-RESOLVE1','assign_code',bid::text,bid::text,'','RES',a->>'sourceRef',a->>'evidenceId',a->>'reason','0'] then raise exception 'BOOKING_CODE_CONTRACT_INVALID';end if;
   perform crm_api.identity_resolve(cf2p,cf2s,cf1p,cf1s,cq);
   res:=jsonb_build_object('bookingId',bid,'state','Pendiente de preparación','coverage',acc.coverage,'existing',false);
  end if;
  insert into crm_private.b04_operations values(op,bid,s,actor,fp,a,res,clock_timestamp());
  insert into crm_private.b04_history values(op,bid,s,actor,a->>'sourceRef',a->>'reason',to_jsonb(o),res,'["SM-BK-01","SM-BS-01","PLAN-T03","D018"]',clock_timestamp());
  res:=jsonb_build_object('id',bid,'replayed',false,'result',res);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return res;
end $function$

CREATE OR REPLACE FUNCTION crm_api.booking_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;r jsonb;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'BOOKING_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H2-BOOKING-READ1' then raise exception 'BOOKING_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if a-array['bookingId']<>'{}'::jsonb then raise exception 'BOOKING_INPUT_INVALID';end if;
 select jsonb_build_object('booking',to_jsonb(b),'code',ic.human_code,'history',coalesce((select jsonb_agg(to_jsonb(x) order by x.recorded_at) from crm_private.b04_history x where x.booking_id=b.booking_id),'[]')) into r
 from crm_private.b04_bookings b join crm_private.identity_codes ic on ic.target_id=b.booking_id and ic.code_kind='RES' where b.booking_id=(a->>'bookingId')::uuid and b.admin_scope=hf[17];
 r:=crm_private.modification_projection(r,hf[17]);perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');return r;
end $function$

CREATE OR REPLACE FUNCTION crm_api.obligation_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;d jsonb;c jsonb;r jsonb;before_state jsonb;part jsonb;parts jsonb;policy jsonb;
 op uuid;bid uuid;sid uuid;pid uuid;actor uuid;s text;fp text;efp text;proofhash text;rev bigint;pv bigint;amt numeric;accepted numeric;
 firstdate date;actdate date;days integer;due date;initial numeric;balance numeric;action text;
 b crm_private.b04_bookings;pr crm_private.b05_obligation_operations;ps crm_private.b05_payment_schedules;pol crm_private.b05_payment_policies;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OBLIGATION_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-OBLIGATION1' then raise exception 'OBLIGATION_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or not(a ?& array['action','operationId','bookingId','policyId','expectedRevision','sourceRef','reason','at','evidenceId'])
 or a-array['action','operationId','bookingId','policyId','expectedRevision','sourceRef','reason','at','evidenceId','origin','scheduleId','scope','scopeId','policy','definition','computed','policyVersion','selectors','slot','amount','due']<>'{}'::jsonb
 or a->>'action' not in ('publish_policy','determine','adjust') or coalesce(a->>'origin','manual')<>'manual'
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or a->>'expectedRevision' !~ '^[0-9]+$'
 or exists(select 1 from jsonb_each(a) x where x.key in ('sourceRef','reason','at') and (jsonb_typeof(x.value)<>'string' or btrim(x.value#>>'{}')=''))
 or a->>'at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'OBLIGATION_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;bid:=(a->>'bookingId')::uuid;pid:=(a->>'policyId')::uuid;actor:=hf[12]::uuid;s:=hf[17];action:=a->>'action';
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(op::text,0));
 select * into pr from crm_private.b05_obligation_operations where operation_id=op;
 if found then
  if pr.admin_scope<>s or pr.actor_id<>actor or pr.fingerprint<>fp then raise exception 'OBLIGATION_REPLAY_CONFLICT:E2';end if;
  r:=jsonb_build_object('id',pr.result->>'id','replayed',true,'result',pr.result);
 else
  select * into b from crm_private.b04_bookings where booking_id=bid and admin_scope=s;
  if not found then raise exception 'OBLIGATION_BOOKING_REQUIRED';end if;
  -- Reviewed evidence binds the complete human decision including amount/time/reference;
  -- no authority derives from customer/integration/AI payloads.
  proofhash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId','computed'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.offer_evidence((a->>'evidenceId')::uuid,b.opportunity_id,s,'obligation:'||action||':'||proofhash,b.coverage,(a->>'at')::timestamptz,(a->>'at')::timestamptz)
  then raise exception 'OBLIGATION_AUTHORIZED_EVIDENCE_REQUIRED';end if;
  if action='publish_policy' then
   if a ?| array['definition','computed','scheduleId','slot','amount','due','scope','scopeId','policy'] then raise exception 'OBLIGATION_INPUT_INVALID';end if;
   perform pg_advisory_xact_lock(hashtextextended(pid::text,51));
   select coalesce(max(version),0) into rev from crm_private.b05_payment_policies where policy_id=pid;
   if rev<>(a->>'expectedRevision')::bigint or exists(select 1 from crm_private.b05_payment_policies where policy_id=pid and admin_scope<>s)
   then raise exception 'OBLIGATION_REVISION_CONFLICT';end if;
   if jsonb_typeof(a->'policyVersion') is distinct from 'number' or (a->>'policyVersion')::bigint<>rev+1
    or jsonb_typeof(a->'selectors') is distinct from 'object' or (a->'selectors')-array['service','provider','type','case']<>'{}'::jsonb
    or exists(select 1 from jsonb_each(a->'selectors') x where jsonb_typeof(x.value) not in ('string','null')) then raise exception 'OBLIGATION_POLICY_REQUIRED';end if;
   insert into crm_private.b05_payment_policies values(pid,rev+1,s,'ordinary_50_50',a->'selectors',actor,a->>'sourceRef',a->>'reason',(a->>'evidenceId')::uuid,clock_timestamp());
   r:=jsonb_build_object('id',pid,'revision',rev+1,'rule','ordinary_50_50');
  else
   if not(a ?& array['scheduleId','scope','scopeId']) or a->>'scope' not in ('global','modality','service','night') then raise exception 'OBLIGATION_SCOPE_REQUIRED';end if;
   sid:=(a->>'scheduleId')::uuid;
   -- Root lock protects absent children and functional identity, including different keys.
   perform pg_advisory_xact_lock(hashtextextended(bid::text,52));
   if a->>'scope'='global' and a->>'scopeId'<>bid::text
    or a->>'scope'='modality' and not exists(select 1 from crm_private.b04_modalities where booking_id=bid and modality_id=(a->>'scopeId')::uuid)
    or a->>'scope'='service' and not exists(select 1 from crm_private.b04_services where booking_id=bid and service_id=(a->>'scopeId')::uuid)
    or a->>'scope'='night' and not exists(select 1 from crm_private.b04_nights n join crm_private.b04_services bs using(service_id) where bs.booking_id=bid and n.night_id=(a->>'scopeId')::uuid)
   then raise exception 'OBLIGATION_SCOPE_REQUIRED';end if;
   select * into ps from crm_private.b05_payment_schedules where booking_id=bid and scope_kind=a->>'scope' and scope_id=(a->>'scopeId')::uuid;
   if action='determine' then
    if a ?| array['slot','amount','due','policyVersion','selectors'] then raise exception 'OBLIGATION_INPUT_INVALID';end if;
    d:=a->'definition';c:=a->'computed';policy:=a->'policy';
    if jsonb_typeof(d) is distinct from 'object' or not(d ?& array['base','reference','at']) or d-array['base','reference','at','exception']<>'{}'::jsonb
     or jsonb_typeof(d->'base') is distinct from 'object' or (d->'base')-array['amount','sourceRef','version']<>'{}'::jsonb
     or not(d->'base' ?& array['amount','sourceRef','version']) or jsonb_typeof((d->'base')->'amount') is distinct from 'string' or (d->'base')->>'amount' !~ '^(0|[1-9][0-9]*)\.[0-9]{2}$'
     or coalesce((d->'base')->>'sourceRef','')='' or coalesce((d->'base')->>'version','')='' or d->>'at' is distinct from a->>'at'
     or policy-array['id','version','rule']<>'{}'::jsonb or policy->>'id' is distinct from pid::text or policy->>'rule' is distinct from 'ordinary_50_50'
    then raise exception 'OBLIGATION_MATERIAL_REQUIRED';end if;
    pv:=(policy->>'version')::bigint;
    select * into pol from crm_private.b05_payment_policies where policy_id=pid and version=pv and admin_scope=s;
    if not found then raise exception 'OBLIGATION_POLICY_REQUIRED';end if;
    -- Selectors are retained explicit application criteria, never an implicit new commercial rule.
    if pol.selectors->>'case' is not null and pol.selectors->>'case'<>bid::text
     or pol.selectors->>'service' is not null and (a->>'scope'<>'service' or pol.selectors->>'service'<>a->>'scopeId')
     or pol.selectors->>'provider' is not null and not exists(select 1 from crm_private.b04_services bs where bs.booking_id=bid and bs.service_id=(a->>'scopeId')::uuid and bs.applied->>'provider'=pol.selectors->>'provider')
     or pol.selectors->>'type' is not null and not exists(select 1 from crm_private.b04_services bs where bs.booking_id=bid and bs.service_id=(a->>'scopeId')::uuid and bs.nature=pol.selectors->>'type') then raise exception 'OBLIGATION_POLICY_SCOPE_REQUIRED';end if;
    if (d->'reference')->>'scope' is distinct from a->>'scope' or (d->'reference')->>'scopeId' is distinct from a->>'scopeId'
     or (d->'reference')->>'basis' not in ('default','express_contract') or coalesce((d->'reference')->>'sourceRef','')='' or coalesce((d->'reference')->>'version','')=''
     or coalesce((d->'reference'->'zone')->>'sourceRef','')='' or coalesce((d->'reference'->'zone')->>'version','')=''
     or not exists(select 1 from pg_timezone_names where name=(d->'reference'->'zone')->>'zone') or (d->'reference')->>'date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    then raise exception 'OBLIGATION_REFERENCE_REQUIRED';end if;
    -- No default can be guessed if any date in its scope remains pending.
    select case when bool_or(l.service_date is null) then null else min(l.service_date) end into firstdate
    from crm_private.b04_contributions bc join crm_private.b03_proposal_lines l using(version_id,line_id)
    where bc.booking_id=bid and (a->>'scope'='global' or a->>'scope'='modality' and bc.modality_id=(a->>'scopeId')::uuid or a->>'scope'='service' and bc.service_id=(a->>'scopeId')::uuid
     or a->>'scope'='night' and exists(select 1 from crm_private.b04_night_occupancies n where n.night_id=(a->>'scopeId')::uuid and n.contribution_id=bc.contribution_id));
    if (d->'reference')->>'basis'='default' and (firstdate is null or firstdate is distinct from ((d->'reference')->>'date')::date) then raise exception 'OBLIGATION_REFERENCE_REQUIRED';end if;
    amt:=((d->'base')->>'amount')::numeric;
    -- Reproducible whole selected modalities use accepted H2 prices. Other scopes require
    -- explicit evidence-bound determination, never proration or silent alteration of H2.
    if a->>'scope' in ('global','modality') and not exists(select 1 from crm_private.b04_modalities bm join crm_private.b03_proposal_lines l on l.version_id=b.version_id and l.modality_id=bm.modality_id and l.included
     where bm.booking_id=bid and (a->>'scope'='global' or bm.modality_id=(a->>'scopeId')::uuid)
     and not exists(select 1 from crm_private.b04_contributions bc where bc.booking_id=bid and bc.line_id=l.line_id)) then
     select sum(m.final_person_price*m.participants) into accepted from crm_private.b04_modalities bm join crm_private.b03_proposal_modalities m on m.version_id=b.version_id and m.modality_id=bm.modality_id
     where bm.booking_id=bid and (a->>'scope'='global' or bm.modality_id=(a->>'scopeId')::uuid);
     if accepted is not null and accepted<>amt then raise exception 'OBLIGATION_BASE_CONFLICT';end if;
    end if;
    actdate:=((a->>'at')::timestamptz at time zone ((d->'reference'->'zone')->>'zone'))::date;days:=((d->'reference')->>'date')::date-actdate;due:=((d->'reference')->>'date')::date-7;
    -- Exact numeric invariant checks on H1 output; not a second money/calc engine.
    initial:=case when days<7 then amt else round(amt/2,2) end;balance:=amt-initial;
    parts:=c->'parts';
    if jsonb_typeof(c) is distinct from 'object' or c->'policy' is distinct from policy or c->'base' is distinct from d->'base' or c->'reference' is distinct from d->'reference' or c->>'at' is distinct from a->>'at'
     or c->>'moneyVersion' is distinct from 'h1-money-d023-d028-d029-v1' or c->>'civilVersion' is distinct from 'h1-civil-d020-v1'
     or (c->'calculation')->>'algorithmVersion' is distinct from 'h1-money-d023-d028-d029-v1'
     or (c->'calculation')->'input' is distinct from jsonb_build_object('kind','percentage','base',(d->'base')->>'amount','percent',case when days<7 then '100' else '50' end)
     or (c->'calculation'->'output'->'applied')->>'amount' is distinct from to_char(initial,'FM999999999999999999999999999999990.00')
     or (c->'calculation'->'output')->>'remainder' is distinct from to_char(balance,'FM999999999999999999999999999999990.00')
     or (c->'evaluation')->>'actDate' is distinct from actdate::text or ((c->'evaluation')->>'daysBefore')::integer is distinct from days
     or c->'ordinary' is distinct from (case when days<7 then jsonb_build_array(jsonb_build_object('slot','initial','amount',(d->'base')->>'amount','due',jsonb_build_object('kind','before_confirmation')))
      else jsonb_build_array(jsonb_build_object('slot','initial','amount',to_char(initial,'FM999999999999999999999999999999990.00'),'due',jsonb_build_object('kind','at_confirmation')),jsonb_build_object('slot','balance','amount',to_char(balance,'FM999999999999999999999999999999990.00'),'due',jsonb_build_object('kind','civil','date',due::text))) end)
    then raise exception 'OBLIGATION_CALCULATION_INVALID';end if;
    if jsonb_typeof(parts) is distinct from 'array' or jsonb_array_length(parts) not between 1 and 2
     or exists(select 1 from jsonb_array_elements(parts) x where not crm_private.obligation_part_valid(x))
     or (select count(distinct x->>'slot') from jsonb_array_elements(parts) x)<>jsonb_array_length(parts)
     or (select sum((x->>'amount')::numeric) from jsonb_array_elements(parts) x)<>amt then raise exception 'OBLIGATION_PART_INVALID';end if;
    if d ? 'exception' then
     if (d->'exception')-array['reason','parts']<>'{}'::jsonb or coalesce(btrim((d->'exception')->>'reason'),'')='' or c->'exception' is distinct from d->'exception' or parts is distinct from (d->'exception')->'parts'
     then raise exception 'OBLIGATION_EXCEPTION_REQUIRED';end if;
    elsif parts is distinct from c->'ordinary' or c ? 'exception' then raise exception 'OBLIGATION_EXCEPTION_REQUIRED';end if;
    efp:=encode(crm_crypto.digest(convert_to((a-array['operationId','scheduleId','expectedRevision','evidenceId','computed'])::text,'UTF8'),'sha256'),'hex');
    if ps.schedule_id is not null then
     if ps.effect_fingerprint<>efp then raise exception 'OBLIGATION_EXISTS_CONFLICT';end if;
     sid:=ps.schedule_id;r:=jsonb_build_object('id',sid,'revision',1,'existing',true);
    else
     if (a->>'expectedRevision')::bigint<>0 then raise exception 'OBLIGATION_REVISION_CONFLICT';end if;
     insert into crm_private.b05_payment_schedules values(sid,bid,s,a->>'scope',(a->>'scopeId')::uuid,pid,pv,actor,efp,clock_timestamp());
     c:=c||jsonb_build_object('policyApplied',to_jsonb(pol),'bookingChain',b.chain_snapshot,'bookingVersion',b.version_id,'evidenceId',a->>'evidenceId','actorId',actor,'reason',a->>'reason');
     insert into crm_private.b05_schedule_revisions values(sid,1,s,c,actor,clock_timestamp());
     for part in select value from jsonb_array_elements(parts) loop insert into crm_private.b05_expected_payments values(sid,part->>'slot',s,(part->>'amount')::numeric,part->'due');end loop;
     r:=jsonb_build_object('id',sid,'revision',1,'existing',false);
    end if;
   else
    if a ?| array['definition','computed','policy','policyVersion','selectors'] or ps.schedule_id is null or ps.schedule_id<>sid or ps.policy_id<>pid then raise exception 'OBLIGATION_ADJUSTMENT_REQUIRED';end if;
    select revision,snapshot into rev,before_state from crm_private.b05_schedule_revisions where schedule_id=sid order by revision desc limit 1;
    if rev<>(a->>'expectedRevision')::bigint then raise exception 'OBLIGATION_REVISION_CONFLICT';end if;
    part:=jsonb_build_object('slot',a->>'slot','amount',a->>'amount','due',a->'due');
    if not crm_private.obligation_part_valid(part) or not exists(select 1 from crm_private.b05_expected_payments where schedule_id=sid and slot=a->>'slot') then raise exception 'OBLIGATION_ADJUSTMENT_REQUIRED';end if;
    select value into d from jsonb_array_elements(before_state->'parts') where value->>'slot'=a->>'slot';
    select jsonb_agg(case when x->>'slot'=a->>'slot' then part else x end order by ord) into parts from jsonb_array_elements(before_state->'parts') with ordinality z(x,ord);
    c:=jsonb_set(before_state,'{parts}',parts);
    insert into crm_private.b05_schedule_revisions values(sid,rev+1,s,c,actor,clock_timestamp());
    insert into crm_private.b05_obligation_adjustments values(op,sid,a->>'slot',rev+1,s,d,part,(a->>'amount')::numeric-(d->>'amount')::numeric,actor,a->>'reason',a->>'sourceRef',(a->>'evidenceId')::uuid,clock_timestamp());
    r:=jsonb_build_object('id',sid,'revision',rev+1,'originalRetained',true);
   end if;
  end if;
  insert into crm_private.b05_obligation_operations values(op,bid,s,actor,fp,a,r,clock_timestamp());
  insert into crm_private.b05_obligation_history values(op,bid,s,actor,before_state,r,a->>'sourceRef',a->>'reason',(a->>'evidenceId')::uuid,(a->>'at')::timestamptz,clock_timestamp());
  r:=jsonb_build_object('id',r->>'id','replayed',false,'result',r);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end $function$

CREATE OR REPLACE FUNCTION crm_api.obligation_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;r jsonb;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OBLIGATION_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-OBLIGATION-READ1' then raise exception 'OBLIGATION_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-array['bookingId','scheduleId']<>'{}'::jsonb or not(a ?& array['bookingId','scheduleId']) then raise exception 'OBLIGATION_INPUT_INVALID';end if;
 select jsonb_build_object('coverage',crm_private.fund_coverage(ps.schedule_id,hf[17]),'current',(select to_jsonb(x) from crm_private.b05_schedule_revisions x where x.schedule_id=ps.schedule_id order by revision desc limit 1),
 'original',(select jsonb_agg(jsonb_build_object('slot',x.slot,'amount',to_char(x.amount,'FM999999999999999999999999999999990.00'),'due',x.due) order by x.slot) from crm_private.b05_expected_payments x where x.schedule_id=ps.schedule_id),
 'history',coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('difference',x.difference::text) order by x.revision) from crm_private.b05_obligation_adjustments x where x.schedule_id=ps.schedule_id),'[]')) into r
 from crm_private.b05_payment_schedules ps where ps.schedule_id=(a->>'scheduleId')::uuid and ps.booking_id=(a->>'bookingId')::uuid and ps.admin_scope=hf[17];
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end $function$

CREATE OR REPLACE FUNCTION crm_private.payment_summary(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare gross numeric;v numeric:=0;historical numeric:=0;susp numeric:=0;c jsonb;i jsonb;lo numeric;hi numeric;cur numeric;lastlo numeric;lasthi numeric;unions jsonb:='[]';
begin
 if p->'receipt'='null'::jsonb then return jsonb_build_object('grossReceived',null,'verifiedCorrespondence','0.00','unreconciled',null,'suspended',null,
 'base',case when jsonb_array_length(p->'correspondences')>0 then 'pending_reconciliation' else 'detected' end,
 'incidence',exists(select 1 from jsonb_array_elements(p->'incidents') x where not (x->>'resolved')::boolean),'algorithmVersion','h1-money-d023-d028-d029-v1');end if;
 gross:=(p->'receipt'->>'amount')::numeric;
 for i in select value from jsonb_array_elements(p->'incidents') where not(value->>'resolved')::boolean order by (value->>'start')::numeric loop
  lo:=(i->>'start')::numeric;hi:=lo+(i->>'amount')::numeric;
  if lastlo is null then lastlo:=lo;lasthi:=hi;
  elsif lo<=lasthi then lasthi:=greatest(lasthi,hi);
  else unions:=unions||jsonb_build_array(jsonb_build_object('lo',lastlo::text,'hi',lasthi::text));lastlo:=lo;lasthi:=hi;end if;
 end loop;
 if lastlo is not null then unions:=unions||jsonb_build_array(jsonb_build_object('lo',lastlo::text,'hi',lasthi::text));end if;
 for i in select value from jsonb_array_elements(unions) loop susp:=susp+(i->>'hi')::numeric-(i->>'lo')::numeric;end loop;
 for c in select value from jsonb_array_elements(p->'correspondences') where value->>'status'='verified' loop
  lo:=(c->>'start')::numeric;hi:=lo+(c->>'amount')::numeric;cur:=(c->>'amount')::numeric;historical:=historical+cur;
  for i in select value from jsonb_array_elements(unions) loop cur:=cur-greatest(0,least(hi,(i->>'hi')::numeric)-greatest(lo,(i->>'lo')::numeric));end loop;
  v:=v+cur;
 end loop;
 return jsonb_build_object('grossReceived',trunc(gross,2)::text,'verifiedCorrespondence',trunc(v,2)::text,'unreconciled',trunc(gross-v,2)::text,'suspended',trunc(susp,2)::text,
 'base',case when historical=gross then 'reconciled' when jsonb_array_length(p->'correspondences')>0 then 'pending_reconciliation' else 'detected' end,'incidence',susp>0,'algorithmVersion','h1-money-d023-d028-d029-v1');
end $function$

CREATE OR REPLACE FUNCTION crm_api.payment_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;d jsonb;current_state jsonb;before_state jsonb;r jsonb;rc jsonb;oldrc jsonb;inc jsonb;keydata jsonb;newreceipt jsonb;
 op uuid;pid uuid;requested uuid;actor uuid;s text;fp text;proofhash text;effecthash text;action text;rev bigint;at_time timestamptz;canonical uuid;rid uuid;iid uuid;
 p crm_private.b05_customer_payments;prev crm_private.b05_payment_operations;b crm_private.b04_bookings;oldreceipt crm_private.b05_payment_receipts;
 start_at numeric;amt numeric;gross numeric;end_at numeric;changed boolean:=true;allowed text[];
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'PAYMENT_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-PAYMENT1' then raise exception 'PAYMENT_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 action:=a->>'action';allowed:=array['action','operationId','paymentId','expectedRevision','sourceRef','reason','at','evidenceId','origin'];
 if action='detect' then allowed:=allowed||array['detection','sourceEvidenceId','presentedEvidenceId'];
 elsif action='receive' then allowed:=allowed||array['amount','identity','sourceEvidenceId','discrepancy'];
 elsif action='propose' then allowed:=allowed||array['reconciliationId','start','amount','bookingId','scheduleId','slot'];
 elsif action='verify' then allowed:=allowed||array['reconciliationId','sourceEvidenceId'];
 elsif action='discrepancy' then allowed:=allowed||array['reconciliationId','incidentId','start','amount'];
 elsif action='rectify' then allowed:=allowed||array['reconciliationId','incidentId','start','amount','bookingId','scheduleId','slot','sourceEvidenceId'];
 elsif action='resolve' then allowed:=allowed||array['incidentId','sourceEvidenceId'];
 else raise exception 'PAYMENT_INPUT_INVALID';end if;
 if jsonb_typeof(a) is distinct from 'object' or a-allowed<>'{}'::jsonb or not(a ?& array['action','operationId','paymentId','expectedRevision','sourceRef','reason','at','evidenceId'])
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or a->>'expectedRevision' !~ '^[0-9]+$'
 or coalesce(a->>'origin','manual') not in ('manual','ai') or (coalesce(a->>'origin','manual')='ai' and action<>'propose')
 or exists(select 1 from jsonb_each(a) x where x.key in ('sourceRef','reason','at') and (jsonb_typeof(x.value)<>'string' or btrim(x.value#>>'{}')='' or length(x.value#>>'{}')>16384))
 or a->>'at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'PAYMENT_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;requested:=(a->>'paymentId')::uuid;pid:=requested;actor:=hf[12]::uuid;s:=hf[17];at_time:=(a->>'at')::timestamptz;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('payment-op:'||op,0));
 select * into prev from crm_private.b05_payment_operations where operation_id=op;
 if found then
  if prev.admin_scope<>s or prev.actor_id<>actor or prev.fingerprint<>fp then raise exception 'PAYMENT_REPLAY_CONFLICT:E2';end if;r:=prev.result||jsonb_build_object('replayed',true);
 else
  if action='detect' then
   d:=a->'detection';
   if jsonb_typeof(d) is distinct from 'object' or d-array['amount','payerRef','date','method','reference','bookingId','identity']<>'{}'::jsonb
   or not(d ?& array['amount','payerRef','date','method','reference','bookingId','identity'])
   or (d->'amount'<>'null'::jsonb and not coalesce(crm_private.payment_amount(d->'amount',true),false))
   or (d->'method'<>'null'::jsonb and d->>'method'<>'bank_transfer')
   or exists(select 1 from jsonb_each(d) x where x.key in ('payerRef','reference','date','bookingId') and x.value<>'null'::jsonb and (jsonb_typeof(x.value)<>'string' or btrim(x.value#>>'{}')=''))
   then raise exception 'PAYMENT_INPUT_INVALID';end if;
   if d->'date'<>'null'::jsonb and (d->>'date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or (d->>'date')::date::text<>d->>'date') then raise exception 'PAYMENT_INPUT_INVALID';end if;
   keydata:=d->'identity';perform pg_advisory_xact_lock(hashtextextended('payment-signal:'||(a->>'evidenceId'),0));
   select payment_id into canonical from crm_private.b05_customer_payments where evidence_id=(a->>'evidenceId')::uuid;
   if canonical is not null then pid:=canonical;end if;
   effecthash:=encode(crm_crypto.digest(convert_to(d::text,'UTF8'),'sha256'),'hex');
  elsif action='receive' then keydata:=a->'identity';end if;
  if keydata is not null and keydata<>'null'::jsonb then
   if jsonb_typeof(keydata) is distinct from 'object' or keydata-array['sourceRef','externalId']<>'{}'::jsonb or not(keydata ?& array['sourceRef','externalId'])
   or exists(select 1 from jsonb_each(keydata) x where jsonb_typeof(x.value)<>'string' or btrim(x.value#>>'{}')='' or length(x.value#>>'{}')>4096) then raise exception 'PAYMENT_IDENTITY_REQUIRED';end if;
   perform pg_advisory_xact_lock(hashtextextended('payment-key:'||keydata::text,0));
   select payment_id into canonical from crm_private.b05_movement_keys where source_ref=keydata->>'sourceRef' and external_id=keydata->>'externalId';
   if action='detect' and canonical is not null then pid:=canonical;end if;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('payment-root:'||pid,0));
  select * into p from crm_private.b05_customer_payments where payment_id=pid;
  if found then
   if p.admin_scope<>s then raise exception 'PAYMENT_DENIED';end if;
   select snapshot,revision into current_state,rev from crm_private.b05_payment_revisions where payment_id=pid order by revision desc limit 1;before_state:=current_state;
  elsif action<>'detect' then raise exception 'PAYMENT_DENIED';end if;
  proofhash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId','sourceEvidenceId','paymentId'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.payment_evidence((a->>'evidenceId')::uuid,pid,s,'payment:'||action||':'||proofhash,at_time,action<>'detect' and action<>'propose') then raise exception 'PAYMENT_EVIDENCE_REQUIRED';end if;
  if (action='detect' and keydata<>'null'::jsonb) or action in ('receive','verify','rectify','resolve') then
   if action='detect' or action='receive' then
    if keydata is null or keydata='null'::jsonb then raise exception 'PAYMENT_IDENTITY_REQUIRED';end if;
   else keydata:=current_state->'receipt'->'identity';end if;
   if keydata is null or keydata='null'::jsonb or not crm_private.payment_evidence((a->>'sourceEvidenceId')::uuid,pid,s,'payment-source:'||(keydata->>'sourceRef'),at_time,true)
   then raise exception 'PAYMENT_AUTHORIZED_SOURCE_REQUIRED';end if;
  end if;
  if action='detect' then
   if a?'presentedEvidenceId' and not exists(select 1 from crm_private.b07_records er join crm_private.b07_links el using(record_id)
    where er.record_id=(a->>'presentedEvidenceId')::uuid and er.admin_scope=s and el.admin_scope=s and el.context_kind='other' and el.context_id=pid and el.coverage=pid::text)
    then raise exception 'PAYMENT_PRESENTED_EVIDENCE_REQUIRED';end if;
   if p.payment_id is not null then
    if p.detection_fingerprint<>effecthash then raise exception 'PAYMENT_MOVEMENT_CONFLICT:E2';end if;changed:=false;
   else
    if (a->>'expectedRevision')::bigint<>0 then raise exception 'PAYMENT_REVISION_CONFLICT:E2';end if;
    if d->'bookingId'<>'null'::jsonb then select * into b from crm_private.b04_bookings where booking_id=(d->>'bookingId')::uuid and admin_scope=s;if not found then raise exception 'PAYMENT_CONTEXT_REQUIRED';end if;end if;
    insert into crm_private.b05_customer_payments values(pid,s,d,effecthash,(a->>'evidenceId')::uuid,actor,clock_timestamp());
    current_state:=jsonb_build_object('detection',d,'receipt',null,'correspondences','[]'::jsonb,'incidents','[]'::jsonb,'duplicateOf',null,'presentedEvidenceId',a->'presentedEvidenceId','revision',1);rev:=0;
    if keydata<>'null'::jsonb then insert into crm_private.b05_movement_keys values(keydata->>'sourceRef',keydata->>'externalId',pid,s);end if;
   end if;
  else
   if current_state->'duplicateOf'<>'null'::jsonb then raise exception 'PAYMENT_DUPLICATE_SIGNAL';end if;
   if action='receive' then
    if not coalesce(crm_private.payment_amount(a->'amount',true),false) then raise exception 'PAYMENT_AMOUNT_INVALID';end if;
    if a->'discrepancy' is not null and a->'discrepancy'<>'null'::jsonb and (jsonb_typeof(a->'discrepancy')<>'string' or btrim(a->>'discrepancy')='') then raise exception 'PAYMENT_DISCREPANCY_REQUIRED';end if;
    if current_state->'detection'->'identity'<>'null'::jsonb and current_state->'detection'->'identity'<>keydata then raise exception 'PAYMENT_MOVEMENT_CONFLICT:E2';end if;
    newreceipt:=jsonb_build_object('amount',a->>'amount','sourceRef',a->>'sourceRef','evidenceId',a->>'evidenceId','identity',keydata,'discrepancy',a->'discrepancy');
    if current_state->'receipt'<>'null'::jsonb then
     if ((current_state->'receipt')-'evidenceId')<>(newreceipt-'evidenceId') then raise exception 'PAYMENT_RECEIPT_CONFLICT:E2';end if;changed:=false;
    else
     if (a->>'expectedRevision')::bigint<>rev then raise exception 'PAYMENT_REVISION_CONFLICT:E2';end if;
     if canonical is not null and canonical<>pid then
      select * into oldreceipt from crm_private.b05_payment_receipts where payment_id=canonical and admin_scope=s;
      if not found or (oldreceipt.fact->>'amount')<>(a->>'amount') then raise exception 'PAYMENT_MOVEMENT_CONFLICT:E2';end if;
      current_state:=jsonb_set(current_state,'{duplicateOf}',to_jsonb(canonical::text));
     else
      if current_state->'detection'->'amount'<>'null'::jsonb and current_state->'detection'->>'amount'<>a->>'amount' and nullif(a->>'discrepancy','') is null then raise exception 'PAYMENT_DISCREPANCY_REQUIRED';end if;
      insert into crm_private.b05_payment_receipts values(pid,s,newreceipt,actor,(a->>'evidenceId')::uuid,(a->>'sourceEvidenceId')::uuid,at_time,clock_timestamp());
      if canonical is null then insert into crm_private.b05_movement_keys values(keydata->>'sourceRef',keydata->>'externalId',pid,s);end if;
      current_state:=jsonb_set(current_state,'{receipt}',newreceipt);
      if nullif(a->>'discrepancy','') is not null then current_state:=jsonb_set(current_state,'{incidents}',current_state->'incidents'||jsonb_build_array(jsonb_build_object('id',op,'reconciliationId',null,'start','0.00','amount',a->>'amount','resolved',false,'reason',a->>'discrepancy')));end if;
     end if;
    end if;
   else
    if (a->>'expectedRevision')::bigint<>rev then raise exception 'PAYMENT_REVISION_CONFLICT:E2';end if;
    rid:=(a->>'reconciliationId')::uuid;iid:=(a->>'incidentId')::uuid;
    if action in ('verify','rectify') then
     select value into oldrc from jsonb_array_elements(current_state->'correspondences') where value->>'id'=rid::text;
     if oldrc is null or current_state->'receipt'='null'::jsonb then raise exception 'PAYMENT_CORRESPONDENCE_REQUIRED';end if;
    end if;
    if action in ('propose','rectify') then
     if rid is null or not coalesce(crm_private.payment_amount(a->'start'),false) or not coalesce(crm_private.payment_amount(a->'amount',true),false) then raise exception 'PAYMENT_PORTION_REQUIRED';end if;
     select * into b from crm_private.b04_bookings where booking_id=(a->>'bookingId')::uuid and admin_scope=s;
     if not found or a->>'slot' not in ('initial','balance') or not exists(select 1 from crm_private.b05_payment_schedules ps join crm_private.b05_expected_payments ep using(schedule_id) where ps.schedule_id=(a->>'scheduleId')::uuid and ps.booking_id=b.booking_id and ps.admin_scope=s and ep.slot=a->>'slot') then raise exception 'PAYMENT_CONTEXT_REQUIRED';end if;
     if current_state->'detection'->'bookingId'<>'null'::jsonb and current_state->'detection'->>'bookingId'<>b.booking_id::text
     or exists(select 1 from jsonb_array_elements(current_state->'correspondences') x where x->>'bookingId'<>b.booking_id::text)
     then raise exception 'PAYMENT_CONTEXT_REQUIRED';end if;
     rc:=jsonb_build_object('id',rid,'start',a->>'start','amount',a->>'amount','bookingId',b.booking_id,'scheduleId',a->>'scheduleId','slot',a->>'slot','status',case when action='propose' then 'proposed' else 'verified' end,'revision',case when action='propose' then 1 else (oldrc->>'revision')::bigint+1 end,'sourceRef',a->>'sourceRef','evidenceId',a->>'evidenceId');
    elsif action='verify' then
     if oldrc->>'status'<>'proposed' then raise exception 'PAYMENT_REVISION_CONFLICT:E2';end if;
     rc:=oldrc||jsonb_build_object('status','verified','revision',(oldrc->>'revision')::bigint+1,'sourceRef',a->>'sourceRef','evidenceId',a->>'evidenceId');
    end if;
    if action in ('rectify','resolve') then
     select value into inc from jsonb_array_elements(current_state->'incidents') where value->>'id'=iid::text and not(value->>'resolved')::boolean;
     if inc is null or (action='rectify' and inc->>'reconciliationId' is distinct from rid::text) or (action='resolve' and inc->'reconciliationId'<>'null'::jsonb) then raise exception 'PAYMENT_REVIEW_REQUIRED';end if;
     current_state:=jsonb_set(current_state,'{incidents}',(select jsonb_agg(case when x->>'id'=iid::text then x||jsonb_build_object('resolved',true,'resolutionEvidenceId',a->>'evidenceId','resolutionReason',a->>'reason','resolutionSource',a->>'sourceRef') else x end) from jsonb_array_elements(current_state->'incidents') x));
    end if;
    if action in ('propose','verify','rectify','discrepancy') then
     if action='discrepancy' then
      if iid is null or not coalesce(crm_private.payment_amount(a->'start'),false) or not coalesce(crm_private.payment_amount(a->'amount',true),false) then raise exception 'PAYMENT_PORTION_REQUIRED';end if;
      if exists(select 1 from jsonb_array_elements(current_state->'incidents') x where x->>'id'=iid::text) then raise exception 'PAYMENT_REVISION_CONFLICT:E2';end if;
      start_at:=(a->>'start')::numeric;amt:=(a->>'amount')::numeric;
      if rid is not null then select value into oldrc from jsonb_array_elements(current_state->'correspondences') where value->>'id'=rid::text;
       if oldrc is null or start_at<(oldrc->>'start')::numeric or start_at+amt>(oldrc->>'start')::numeric+(oldrc->>'amount')::numeric then raise exception 'PAYMENT_PORTION_REQUIRED';end if;end if;
     else start_at:=(rc->>'start')::numeric;amt:=(rc->>'amount')::numeric;end if;
     gross:=coalesce((current_state->'receipt'->>'amount')::numeric,(current_state->'detection'->>'amount')::numeric);end_at:=start_at+amt;
     if gross is not null and end_at>gross or (gross is null and action<>'propose') then raise exception 'PAYMENT_PORTION_REQUIRED';end if;
     if action in ('verify','rectify') then
      if exists(select 1 from jsonb_array_elements(current_state->'correspondences') x where x->>'id'<>rid::text and x->>'status'='verified' and (x->>'start')::numeric<end_at and (x->>'start')::numeric+(x->>'amount')::numeric>start_at)
      or exists(select 1 from jsonb_array_elements(current_state->'incidents') x where not(x->>'resolved')::boolean and (x->>'start')::numeric<end_at and (x->>'start')::numeric+(x->>'amount')::numeric>start_at) then raise exception 'PAYMENT_PORTION_SUSPENDED_OR_USED';end if;
     end if;
     if action='discrepancy' then
      inc:=jsonb_build_object('id',iid,'reconciliationId',rid,'start',a->>'start','amount',a->>'amount','resolved',false,'reason',a->>'reason');
      current_state:=jsonb_set(current_state,'{incidents}',current_state->'incidents'||jsonb_build_array(inc));
     elsif action='propose' then
      insert into crm_private.b05_reconciliations values(rid,pid,s,b.booking_id,(a->>'scheduleId')::uuid,a->>'slot');
      current_state:=jsonb_set(current_state,'{correspondences}',current_state->'correspondences'||jsonb_build_array(rc));
     else current_state:=jsonb_set(current_state,'{correspondences}',(select jsonb_agg(case when x->>'id'=rid::text then rc else x end) from jsonb_array_elements(current_state->'correspondences') x));end if;
     if rid is not null then insert into crm_private.b05_reconciliation_acts values(op,rid,pid,s,action,oldrc,case when action='discrepancy' then inc else rc end,actor,a->>'reason',a->>'sourceRef',(a->>'evidenceId')::uuid,at_time,clock_timestamp());end if;
    end if;
   end if;
  end if;
  if changed then current_state:=jsonb_set(current_state,'{revision}',to_jsonb(rev+1));insert into crm_private.b05_payment_revisions values(pid,rev+1,s,current_state,actor,clock_timestamp());end if;
  r:=jsonb_build_object('id',pid,'replayed',false,'result',jsonb_build_object('revision',current_state->'revision','duplicateOf',current_state->'duplicateOf','summary',crm_private.payment_summary(current_state)));
  insert into crm_private.b05_payment_operations values(op,pid,s,actor,fp,a,r,clock_timestamp());
  insert into crm_private.b05_payment_history values(op,pid,s,actor,before_state,current_state,a->>'reason',a->>'sourceRef',(a->>'evidenceId')::uuid,at_time,clock_timestamp());
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end $function$

CREATE OR REPLACE FUNCTION crm_api.payment_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;r jsonb;pid uuid;s text;p jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'PAYMENT_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-PAYMENT-READ1' then raise exception 'PAYMENT_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-'paymentId'<>'{}'::jsonb or not(a?'paymentId') then raise exception 'PAYMENT_INPUT_INVALID';end if;
 pid:=(a->>'paymentId')::uuid;s:=hf[17];
 select snapshot into p from crm_private.b05_payment_revisions where payment_id=pid and admin_scope=s order by revision desc limit 1;
 if found then r:=jsonb_build_object('current',p,'summary',crm_private.payment_summary(p),
 'history',(select jsonb_agg(to_jsonb(x) order by x.recorded_at,x.history_id) from crm_private.b05_payment_history x where x.payment_id=pid and x.admin_scope=s),
 'receipts',coalesce((select jsonb_agg(to_jsonb(x)) from crm_private.b05_payment_receipts x where x.payment_id=pid and x.admin_scope=s),'[]'),
 'acts',coalesce((select jsonb_agg(to_jsonb(x) order by x.recorded_at,x.act_id) from crm_private.b05_reconciliation_acts x where x.payment_id=pid and x.admin_scope=s),'[]'));end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end $function$

CREATE OR REPLACE FUNCTION crm_private.fund_usable(a jsonb, p jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare rc jsonb;lo numeric;hi numeric;doubts nummultirange;part numrange;lost numeric;
begin
 if a->>'status'<>'verified' or p->'receipt'='null'::jsonb or p->>'duplicateOf' is not null then return 0;end if;
 select value into rc from jsonb_array_elements(p->'correspondences') where value->>'id'=a->>'reconciliationId' and value->>'status'='verified';
 if rc is null or rc->>'bookingId'<>a->'destination'->>'bookingId' or rc->>'scheduleId'<>a->>'sourceScheduleId' or rc->>'slot'<>a->>'sourceSlot' then return 0;end if;
 lo:=greatest((a->>'start')::numeric,(rc->>'start')::numeric);hi:=least((a->>'start')::numeric+(a->>'amount')::numeric,(rc->>'start')::numeric+(rc->>'amount')::numeric);
 if hi<=lo then return 0;end if;part:=numrange(lo,hi,'[)');
 select coalesce(range_agg(numrange((x->>'start')::numeric,(x->>'start')::numeric+(x->>'amount')::numeric,'[)')),'{}'::nummultirange) into doubts from jsonb_array_elements(p->'incidents') x where not(x->>'resolved')::boolean;
 select coalesce(sum(upper(r)-lower(r)),0) into lost from unnest(nummultirange(part)*doubts) r;
 return hi-lo-lost;
end$function$

CREATE OR REPLACE FUNCTION crm_private.fund_coverage(sid uuid, s text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare current_schedule jsonb;revision bigint;part jsonb;allocation jsonb;payment jsonb;u numeric;covered numeric;items jsonb;result jsonb:='[]';due numeric;
begin
 select r.snapshot,r.revision into current_schedule,revision from crm_private.b05_schedule_revisions r where r.schedule_id=sid and r.admin_scope=s order by r.revision desc limit 1;
 if not found then return null;end if;
 for part in select value from jsonb_array_elements(current_schedule->'parts') loop
  due:=(part->>'amount')::numeric;covered:=0;items:='[]';
  for allocation in select r.snapshot from crm_private.b05_allocations a join lateral(select ar.snapshot from crm_private.b05_allocation_revisions ar where ar.allocation_id=a.allocation_id order by ar.revision desc limit 1) r on true where a.schedule_id=sid and a.slot=part->>'slot' and a.admin_scope=s loop
   select cp.snapshot into payment from crm_private.b05_payment_revisions cp where payment_id=(allocation->>'paymentId')::uuid and cp.admin_scope=s order by cp.revision desc limit 1;
   u:=crm_private.fund_usable(allocation,payment);covered:=covered+u;
   if u>0 then items:=items||jsonb_build_array(jsonb_build_object('id',allocation->>'id','paymentId',allocation->>'paymentId','reconciliationId',allocation->>'reconciliationId','start',allocation->>'start','amount',trunc(u,2)::text,'allocationRevision',allocation->'revision','paymentRevision',payment->'revision'));end if;
  end loop;
  -- An excess is retained visibly, never funding another destination implicitly.
  result:=result||jsonb_build_array(jsonb_build_object('scheduleId',sid,'slot',part->>'slot','scheduleRevision',revision,'obligationAmount',trunc(due,2)::text,'verifiedAmount',trunc(least(due,covered),2)::text,'excess',trunc(greatest(0,covered-due),2)::text,'remaining',trunc(greatest(0,due-covered),2)::text,
   'state',case when covered=0 then 'pending' when covered<due then 'partial' else 'complete' end,'portions',items,'algorithmVersion','h1-money-d023-d028-d029-v1'));
 end loop;return result;
end$function$

CREATE OR REPLACE FUNCTION crm_private.fund_summary(pid uuid, s text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare p jsonb;ps jsonb;a jsonb;c record;allocated numeric:=0;usable numeric:=0;consumed numeric:=0;used_valid numeric:=0;u numeric;total numeric;plans numeric:=0;purposes jsonb:='{}';x jsonb;k text;amount numeric;
begin
 select snapshot into p from crm_private.b05_payment_revisions where payment_id=pid and admin_scope=s order by revision desc limit 1;if not found then return null;end if;
 ps:=crm_private.payment_summary(p);total:=(ps->>'grossReceived')::numeric;
 for a in select value from jsonb_array_elements(crm_private.fund_allocations(pid,s)) loop
  if a->>'status'='planned' then plans:=plans+(a->>'amount')::numeric;continue;end if;if a->>'status'<>'verified' then continue;end if;
  amount:=(a->>'amount')::numeric;u:=crm_private.fund_usable(a,p);allocated:=allocated+amount;usable:=usable+u;k:=a->'destination'->>'purpose';
  x:=coalesce(purposes->k,jsonb_build_object('assigned','0.00','usableAssigned','0.00','consumed','0.00','usableConsumed','0.00'));
  x:=x||jsonb_build_object('assigned',trunc((x->>'assigned')::numeric+amount,2)::text,'usableAssigned',trunc((x->>'usableAssigned')::numeric+u,2)::text);
  for c in select z.* from crm_private.b05_allocation_acts z where z.allocation_id=(a->>'id')::uuid and z.kind='consume' and not exists(select 1 from crm_private.b05_allocation_acts rev where rev.original_act_id=z.act_id) loop
   consumed:=consumed-c.signed_amount;u:=crm_private.fund_usable(a||jsonb_build_object('start',trunc(c.start_amount,2)::text,'amount',trunc(-c.signed_amount,2)::text),p);used_valid:=used_valid+u;
   x:=x||jsonb_build_object('consumed',trunc((x->>'consumed')::numeric-c.signed_amount,2)::text,'usableConsumed',trunc((x->>'usableConsumed')::numeric+u,2)::text);
  end loop;
  x:=x||jsonb_build_object('availableForPurpose',trunc((x->>'usableAssigned')::numeric-(x->>'usableConsumed')::numeric,2)::text);
  purposes:=jsonb_set(purposes,array[k],x);
 end loop;
 if total is not null and (allocated>total or usable<used_valid or usable>(ps->>'verifiedCorrespondence')::numeric) then raise exception 'ALLOCATION_CONSERVATION_VIOLATION';end if;
 return jsonb_build_object('received',ps->'grossReceived','verifiedCorrespondence',ps->'verifiedCorrespondence','planned',trunc(plans,2)::text,'assigned',trunc(allocated,2)::text,'usableAssigned',trunc(usable,2)::text,
 'unassigned',case when total is null then null else trunc(total-allocated,2)::text end,'available',case when total is null then null else trunc((ps->>'verifiedCorrespondence')::numeric-usable,2)::text end,
 'consumed',trunc(consumed,2)::text,'usableConsumed',trunc(used_valid,2)::text,'suspendedAssigned',trunc(allocated-usable,2)::text,'suspendedConsumed',trunc(consumed-used_valid,2)::text,
 'representedReturned','0.00','externalReturned',null,'suspended',ps->'suspended','byPurpose',purposes,'algorithmVersion','h1-money-d023-d028-d029-v1');
end$function$

CREATE OR REPLACE FUNCTION crm_private.fund_record_coverage(bid uuid, s text, actor uuid, cause text, ref uuid, rev bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare sid uuid;item jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(bid::text,52));
 for sid in select schedule_id from crm_private.b05_payment_schedules where booking_id=bid and admin_scope=s order by schedule_id loop
  for item in select value from jsonb_array_elements(crm_private.fund_coverage(sid,s)) loop
   insert into crm_private.b05_coverage_evaluations values(gen_random_uuid(),sid,item->>'slot',(item->>'scheduleRevision')::bigint,s,item,actor,cause,ref,rev,clock_timestamp());
  end loop;
 end loop;
end$function$

CREATE OR REPLACE FUNCTION crm_private.fund_refresh(pid uuid, s text, actor uuid, cause text, ref uuid, cause_rev bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare revision bigint;pr bigint;bid uuid;state jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended('payment-root:'||pid,0));
 select coalesce(max(r.revision),0)+1 into revision from crm_private.b05_fund_revisions r where r.payment_id=pid;
 select r.revision into pr from crm_private.b05_payment_revisions r where r.payment_id=pid order by r.revision desc limit 1;
 state:=crm_private.fund_summary(pid,s);
 insert into crm_private.b05_fund_revisions values(pid,revision,pr,s,state,actor,cause,ref,cause_rev,clock_timestamp());
 for bid in select distinct booking_id from crm_private.b05_allocations where payment_id=pid and admin_scope=s order by booking_id loop perform crm_private.fund_record_coverage(bid,s,actor,cause,ref,cause_rev);end loop;
 return revision;
end$function$

CREATE OR REPLACE FUNCTION crm_private.fund_calculation_valid(c jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare p jsonb;q jsonb;total numeric;weights numeric:=0;sum_full numeric:=0;residual numeric;rank bigint;num numeric;den numeric;full_cents numeric;extra numeric;sign numeric;
begin
 if c->>'algorithmVersion'<>'h1-money-d023-d028-d029-v1' or c->'input'->>'kind'<>'allocation' or c->'output'->>'algorithmVersion'<>c->>'algorithmVersion'
 or c->'input'->>'total'<>c->'output'->>'total' or jsonb_array_length(c->'input'->'parts')<>jsonb_array_length(c->'output'->'parts') or jsonb_array_length(c->'input'->'parts') not between 1 and 1000 then return false;end if;
 total:=(c->'input'->>'total')::numeric;sign:=case when total<0 then -1 else 1 end;
 if total<>trunc(total,2) then return false;end if;
 for p in select value from jsonb_array_elements(c->'input'->'parts') loop if (p->>'weight')::numeric<=0 then return false;end if;weights:=weights+(p->>'weight')::numeric;end loop;
 for p in select value from jsonb_array_elements(c->'output'->'parts') loop
  select value into q from jsonb_array_elements(c->'input'->'parts') where value->>'id'=p->>'id' and value->>'order'=p->>'order' and value->>'weight'=p->>'weight';if q is null then return false;end if;
  num:=abs((p->'internal'->>'numerator')::numeric);den:=(p->'internal'->>'denominator')::numeric;
  if den<=0 or num*weights<>abs(total)*(p->>'weight')::numeric*den or sign*(p->'internal'->>'numerator')::numeric<0 then return false;end if;
  full_cents:=div(num*100,den);if full_cents<>(p->>'fullCents')::numeric then return false;end if;sum_full:=sum_full+full_cents;
  if (p->'remainder'->>'numerator')::numeric*den<>(num-full_cents*den/100)*(p->'remainder'->>'denominator')::numeric then return false;end if;
 end loop;
 residual:=abs(total)*100-sum_full;if residual<0 or residual>jsonb_array_length(c->'output'->'parts') then return false;end if;
 for p in select value from jsonb_array_elements(c->'output'->'parts') loop
  select count(*) into rank from jsonb_array_elements(c->'output'->'parts') other where
   (other->'remainder'->>'numerator')::numeric*(p->'remainder'->>'denominator')::numeric>(p->'remainder'->>'numerator')::numeric*(other->'remainder'->>'denominator')::numeric
   or ((other->'remainder'->>'numerator')::numeric*(p->'remainder'->>'denominator')::numeric=(p->'remainder'->>'numerator')::numeric*(other->'remainder'->>'denominator')::numeric and (other->>'order')::bigint<(p->>'order')::bigint);
  extra:=case when rank<residual then 1 else 0 end;
  if extra<>(p->>'residualCents')::numeric or (p->>'amount')::numeric<>sign*((p->>'fullCents')::numeric+extra)/100 then return false;end if;
 end loop;
 if (select count(distinct value->>'id') from jsonb_array_elements(c->'output'->'parts'))<>jsonb_array_length(c->'output'->'parts')
 or (select count(distinct value->>'order') from jsonb_array_elements(c->'output'->'parts'))<>jsonb_array_length(c->'output'->'parts') then return false;end if;
 return true;
exception when others then return false;
end$function$

CREATE OR REPLACE FUNCTION crm_private.fund_assign(q jsonb, p jsonb, s text, actor uuid, op uuid, action text, original uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare aid uuid;pid uuid;rc jsonb;d jsonb;state jsonb;old jsonb;pr bigint;sid uuid;bid uuid;amt numeric;start_at numeric;coverage jsonb;part jsonb;used numeric;due numeric;revision bigint:=1;
begin
 aid:=(q->>'allocationId')::uuid;pid:=(q->>'paymentId')::uuid;d:=q->'destination';amt:=(q->>'amount')::numeric;start_at:=(q->>'start')::numeric;bid:=(d->>'bookingId')::uuid;sid:=(d->>'scheduleId')::uuid;
 if aid is null or jsonb_typeof(q->'expectedReconciliationRevision') is distinct from 'number' or q->>'expectedReconciliationRevision'!~'^[0-9]+$'
 or (q?'expectedScheduleRevision' and (jsonb_typeof(q->'expectedScheduleRevision') is distinct from 'number' or q->>'expectedScheduleRevision'!~'^[0-9]+$'))
 or not coalesce(crm_private.payment_amount(q->'amount',true),false) or not coalesce(crm_private.payment_amount(q->'start'),false)
 or jsonb_typeof(d) is distinct from 'object' or d-array['bookingId','purpose','reference','scheduleId','slot','serviceId']<>'{}'::jsonb or not(d ?& array['bookingId','purpose','reference'])
 or d->>'purpose' not in ('obligation','managed_client_funds','fee','deposit') or jsonb_typeof(d->'reference') is distinct from 'string' or btrim(d->>'reference')='' or lower(d->>'reference')='unknown'
 or (d?'scheduleId')<>(d?'slot') or (d->>'purpose'='obligation' and sid is null) then raise exception 'ALLOCATION_DESTINATION_REQUIRED';end if;
 if not exists(select 1 from crm_private.b04_bookings where booking_id=bid and admin_scope=s) or (p->'detection'->>'bookingId' is not null and p->'detection'->>'bookingId'<>bid::text)
 or (d?'serviceId' and not exists(select 1 from crm_private.b04_services where service_id=(d->>'serviceId')::uuid and booking_id=bid)) then raise exception 'ALLOCATION_CONTEXT_REQUIRED';end if;
 select value into rc from jsonb_array_elements(p->'correspondences') where value->>'id'=q->>'reconciliationId';
 if rc is null or rc->>'bookingId'<>bid::text or rc->>'revision' is distinct from q->>'expectedReconciliationRevision' then raise exception 'ALLOCATION_CORRESPONDENCE_REQUIRED';end if;
 if sid is not null then
  if sid::text<>rc->>'scheduleId' or d->>'slot'<>rc->>'slot' then raise exception 'ALLOCATION_CONTEXT_REQUIRED';end if;
  perform pg_advisory_xact_lock(hashtextextended(bid::text,52));
  select r.revision into pr from crm_private.b05_schedule_revisions r where schedule_id=sid and admin_scope=s order by revision desc limit 1;
  if q?'expectedScheduleRevision' and pr<>(q->>'expectedScheduleRevision')::bigint then raise exception 'ALLOCATION_REVISION_CONFLICT:E2';end if;
 end if;
 state:=jsonb_build_object('id',aid,'paymentId',pid,'reconciliationId',rc->>'id','reconciliationRevision',rc->'revision','sourceScheduleId',rc->>'scheduleId','sourceSlot',rc->>'slot','destination',d,'start',q->>'start','amount',q->>'amount','status',case when action='plan' then 'planned' else 'verified' end,'revision',revision,'originalRef',original);
 if action='verify' then select ar.snapshot into old from crm_private.b05_allocation_revisions ar where ar.allocation_id=aid and ar.admin_scope=s order by ar.revision desc limit 1;
  if old is null or old->>'status'<>'planned' or old-'status'-'revision'-'reconciliationRevision' is distinct from state-'status'-'revision'-'reconciliationRevision' then raise exception 'ALLOCATION_ORIGINAL_REQUIRED';end if;
  revision:=(old->>'revision')::bigint+1;state:=state||jsonb_build_object('revision',revision);
 elsif exists(select 1 from crm_private.b05_allocations where allocation_id=aid) then raise exception 'ALLOCATION_EXISTS_CONFLICT:E2';end if;
 if action<>'plan' then
  if p->'receipt'='null'::jsonb or rc->>'status'<>'verified' or start_at<(rc->>'start')::numeric or start_at+amt>(rc->>'start')::numeric+(rc->>'amount')::numeric or crm_private.fund_usable(state,p)<>amt then raise exception 'ALLOCATION_PORTION_UNVERIFIED';end if;
  if exists(select 1 from jsonb_array_elements(crm_private.fund_allocations(pid,s)) x where x->>'id'<>aid::text and x->>'status'='verified' and (x->>'start')::numeric<start_at+amt and (x->>'start')::numeric+(x->>'amount')::numeric>start_at) then raise exception 'ALLOCATION_PORTION_USED';end if;
  if sid is not null then coverage:=crm_private.fund_coverage(sid,s);select value into part from jsonb_array_elements(coverage) where value->>'slot'=d->>'slot';if part is null then raise exception 'ALLOCATION_OBLIGATION_REQUIRED';end if;
   due:=(part->>'obligationAmount')::numeric;used:=(part->>'verifiedAmount')::numeric+(part->>'excess')::numeric;if used+amt>due then raise exception 'ALLOCATION_OBLIGATION_EXCESS';end if;
  end if;
 end if;
 if action<>'verify' then insert into crm_private.b05_allocations values(aid,pid,(rc->>'id')::uuid,s,bid,d->>'purpose',d->>'reference',sid,d->>'slot',(d->>'serviceId')::uuid,start_at,amt,original);end if;
 insert into crm_private.b05_allocation_revisions values(aid,revision,s,state,actor,clock_timestamp());
 insert into crm_private.b05_allocation_acts values(gen_random_uuid(),op,aid,pid,s,action,start_at,amt,null,old,state,actor,q->>'reason',q->>'sourceRef',(q->>'evidenceId')::uuid,(q->>'at')::timestamptz,clock_timestamp());
 return state;
end$function$

CREATE OR REPLACE FUNCTION crm_private.fund_reverse(q jsonb, s text, actor uuid, op uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare original crm_private.b05_allocation_acts;a jsonb;pid uuid;amt numeric;state jsonb;
begin
 select * into original from crm_private.b05_allocation_acts where act_id=(q->>'originalActId')::uuid and admin_scope=s;
 if not found or original.kind in ('plan','reverse','reverse_distribution') or original.payment_id<>(q->>'paymentId')::uuid or exists(select 1 from crm_private.b05_allocation_acts where original_act_id=original.act_id) then raise exception 'ALLOCATION_ORIGINAL_REQUIRED';end if;
 if q->>'cause' in ('cancellation','refund','new_obligation','modification') and abs(original.signed_amount)<>(q->'economicBasis'->>'amount')::numeric then raise exception 'ALLOCATION_D019_REQUIRED:E3';end if;
 pid:=original.payment_id;select snapshot into a from crm_private.b05_allocation_revisions where allocation_id=original.allocation_id order by revision desc limit 1;
 if a->>'status'<>'verified' then raise exception 'ALLOCATION_ORIGINAL_REQUIRED';end if;
 if original.kind<>'consume' then
  if exists(select 1 from crm_private.b05_allocation_acts z where z.allocation_id=original.allocation_id and z.kind='consume' and not exists(select 1 from crm_private.b05_allocation_acts rev where rev.original_act_id=z.act_id)) then raise exception 'ALLOCATION_CONSUMED_REQUIRES_CORRECTION';end if;
  state:=a||jsonb_build_object('status','reversed','revision',(a->>'revision')::bigint+1);
  insert into crm_private.b05_allocation_revisions values(original.allocation_id,(state->>'revision')::bigint,s,state,actor,clock_timestamp());
 else state:=a;end if;
 amt:=-original.signed_amount;
 insert into crm_private.b05_allocation_acts values(gen_random_uuid(),op,original.allocation_id,pid,s,case when q->>'action'='reverse_distribution' then 'reverse_distribution' else 'reverse' end,original.start_amount,amt,original.act_id,a,state,actor,q->>'reason',q->>'sourceRef',(q->>'evidenceId')::uuid,(q->>'at')::timestamptz,clock_timestamp());
 return jsonb_build_object('originalActId',original.act_id,'originalAmount',trunc(original.signed_amount,2)::text,'amount',trunc(amt,2)::text,'originalRetained',true,'algorithmVersion','h1-money-d023-d028-d029-v1');
end$function$

CREATE OR REPLACE FUNCTION crm_api.allocation_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;p jsonb;prev crm_private.b05_fund_operations;pid uuid;op uuid;actor uuid;s text;fp text;hash text;rev bigint;pr bigint;action text;r jsonb;old jsonb;state jsonb;item jsonb;calcp jsonb;partq jsonb;start_at numeric;amt numeric;at_time timestamptz;basis jsonb;basis_hash text;original crm_private.b05_fund_distributions;act record;results jsonb:='[]';
begin
