  if prev.admin_scope<>s or prev.actor_id<>actor or prev.fingerprint<>fp then raise exception 'REQUIREMENT_REPLAY_CONFLICT:E2';end if;r:=prev.result||jsonb_build_object('replayed',true);
 else
  proofhash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.payment_evidence((a->>'evidenceId')::uuid,iid,s,'requirement:'||action||':'||proofhash,at_time,true)
  or not exists(select 1 from crm_private.b07_records where record_id=(a->>'evidenceId')::uuid and recorded_by=actor) then raise exception 'REQUIREMENT_EVIDENCE_REQUIRED:E3';end if;
  -- Serialize equivalent needs, scope moves and reviews together even before children exist.
  perform pg_advisory_xact_lock(hashtextextended('requirement-booking:'||bid,0));
  select * into root from crm_private.b07_requirements where requirement_id=iid and booking_id=bid and admin_scope=s;
  if found then select revision,after_data,event into rev,old,last_event from crm_private.b07_requirement_revisions where requirement_id=iid order by revision desc limit 1;end if;
  if action='need' then
   basis:=a->'basis';if not crm_private.requirement_basis(basis,bid,s) or (a->>'expectedRevision')::bigint<>0 then raise exception 'REQUIREMENT_BASIS_REQUIRED:E3';end if;
   select i.requirement_id into equivalent from crm_private.b07_requirements i cross join lateral (select after_data from crm_private.b07_requirement_revisions v where v.requirement_id=i.requirement_id order by revision desc limit 1) v where i.booking_id=bid and i.admin_scope=s and v.after_data->'basis'->'rule'->>'id'=basis->'rule'->>'id' and v.after_data->'basis'->'scope'=basis->'scope' and v.after_data->'basis'->'rule'->>'purpose'=basis->'rule'->>'purpose';
   if equivalent is not null then
    select revision,after_data into rev,state from crm_private.b07_requirement_revisions where requirement_id=equivalent order by revision desc limit 1;
    if state->'basis' is distinct from basis then raise exception 'REQUIREMENT_NEED_CONFLICT:E2';end if;iid:=equivalent;
   else
    if root.requirement_id is not null or exists(select 1 from crm_private.b07_requirements where requirement_id=iid) then raise exception 'REQUIREMENT_DENIED';end if;
    state:=jsonb_build_object('id',iid,'bookingId',bid,'revision',1,'basis',basis,'document',null,'review',null,'incident',null,'status',case when basis->'context'->>'value'=basis->'rule'->>'equals' then 'Pendiente' else 'No aplica' end);rev:=1;
    insert into crm_private.b07_requirements values(iid,bid,s,basis,op);
   end if;
  else
   if root.requirement_id is null then raise exception 'REQUIREMENT_DENIED';end if;
   if rev<>(a->>'expectedRevision')::bigint then raise exception 'REQUIREMENT_REVISION_CONFLICT:E2';end if;
   basis:=old->'basis';state:=old;
   if action='receive' then
    d:=crm_private.requirement_original(a->'document',bid,s,null);
    if old->'document'=d then state:=old;
    elsif old->>'status'<>'Pendiente' then raise exception 'REQUIREMENT_TRANSITION_INVALID';
    else state:=state||jsonb_build_object('document',d,'status','Recibido','review',null);end if;
   elsif action='review' then
    if old->>'status' not in ('Recibido','Incidencia','Revisado') or old->'document'='null'::jsonb or jsonb_typeof(a->'checks') is distinct from 'object' or (a->'checks')-array['content','version','scope','purpose']<>'{}'::jsonb or not(a->'checks' ?& array['content','version','scope','purpose']) or exists(select 1 from jsonb_each(a->'checks') c where jsonb_typeof(c.value)<>'boolean') then raise exception 'REQUIREMENT_REVIEW_REQUIRED:E3';end if;
    if old->>'status'='Revisado' then
     if a->'checks' is distinct from last_event->'checks' then raise exception 'REQUIREMENT_TRANSITION_INVALID';end if;
    else
     diffs:='[]';if a->'checks'->'content'<>'true' then diffs:=diffs||'"content"'::jsonb;end if;
     if a->'checks'->'version'<>'true' or old->'document'->>'ruleVersion'<>basis->'rule'->>'version' then diffs:=diffs||'"version"'::jsonb;end if;
     if a->'checks'->'scope'<>'true' or not(old->'document'->'coverage' @> jsonb_build_array(basis->'scope')) then diffs:=diffs||'"scope"'::jsonb;end if;
     if a->'checks'->'purpose'<>'true' or old->'document'->>'purpose'<>basis->'rule'->>'purpose' then diffs:=diffs||'"purpose"'::jsonb;end if;
     state:=state||jsonb_build_object('status',case when diffs='[]'::jsonb then 'Revisado' else 'Incidencia' end,'review',jsonb_build_object('actorId',actor,'at',a->>'at','evidenceId',a->>'evidenceId','basis',basis,'document',old->'document','checks',a->'checks','differences',diffs),'incident',case when diffs='[]'::jsonb then null else jsonb_build_object('differences',diffs,'reason',a->>'reason','sourceRef',a->>'sourceRef') end);
     if old->>'status'='Incidencia' and old->'review'->'checks'=a->'checks' and old->'review'->'differences'=diffs then state:=old;end if;
    end if;
   elsif action='no_apply' then
    basis:=basis||jsonb_build_object('context',a->'context');
    if not crm_private.requirement_basis(basis,bid,s) or basis->'context'->>'value'=basis->'rule'->>'equals' then raise exception 'REQUIREMENT_NOT_APPLICABLE_REQUIRED';end if;
    state:=state||jsonb_build_object('basis',basis,'status','No aplica');
   else
    if old->>'status' not in ('Revisado','No aplica') then raise exception 'REQUIREMENT_TRANSITION_INVALID';end if;
    basis:=a->'basis';if not crm_private.requirement_basis(basis,bid,s) or basis->'rule'->>'id'<>old->'basis'->'rule'->>'id' or basis->'rule'->>'purpose'<>old->'basis'->'rule'->>'purpose' or (basis=old->'basis' and not(a?'document') and not(a?'discrepancy')) then raise exception 'REQUIREMENT_MATERIAL_CHANGE_REQUIRED';end if;
    if basis->'context'->>'value'<>basis->'rule'->>'equals' then raise exception 'REQUIREMENT_NOT_APPLICABLE_REQUIRED';end if;
    if a?'document' and a->'document'<>'null'::jsonb then
     previous:=case when basis=old->'basis' and a->'document'->>'documentId' is distinct from old->'document'->>'documentId' then (old->'document'->>'documentId')::uuid else null end;
     d:=crm_private.requirement_original(a->'document',bid,s,previous);
    else d:='null';end if;
    if basis=old->'basis' and d=old->'document' and not(a?'discrepancy') then raise exception 'REQUIREMENT_MATERIAL_CHANGE_REQUIRED';end if;
    if a?'discrepancy' and not coalesce(crm_private.invoice_text(a->'discrepancy'),false) then raise exception 'REQUIREMENT_MATERIAL_CHANGE_REQUIRED';end if;
    if exists(select 1 from crm_private.b07_requirements i cross join lateral (select after_data from crm_private.b07_requirement_revisions v where v.requirement_id=i.requirement_id order by revision desc limit 1) v where i.booking_id=bid and i.admin_scope=s and i.requirement_id<>iid and v.after_data->'basis'->'rule'->>'id'=basis->'rule'->>'id' and v.after_data->'basis'->'scope'=basis->'scope' and v.after_data->'basis'->'rule'->>'purpose'=basis->'rule'->>'purpose') then raise exception 'REQUIREMENT_NEED_CONFLICT:E2';end if;
    state:=state||jsonb_build_object('basis',basis,'document',d,'review',null,'status',case when a?'discrepancy' then 'Incidencia' when d='null'::jsonb then 'Pendiente' else 'Recibido' end,'incident',case when a?'discrepancy' then jsonb_build_object('differences',jsonb_build_array(a->>'discrepancy'),'reason',a->>'reason','sourceRef',a->>'sourceRef') else null end);
   end if;
  end if;
  rule:=basis->'rule';select definition into stored from crm_private.b07_document_rules where admin_scope=s and rule_id=rule->>'id' and version=rule->>'version';
  if stored is not null and stored<>rule then raise exception 'REQUIREMENT_RULE_VERSION_CONFLICT:E2';end if;
  if stored is null then insert into crm_private.b07_document_rules values(rule->>'id',rule->>'version',s,rule,(a->>'evidenceId')::uuid);end if;
  if (action='need' and equivalent is null) or (action<>'need' and state is distinct from old) then
   if action<>'need' then rev:=rev+1;state:=state||jsonb_build_object('revision',rev);end if;
   if state->'document'<>'null'::jsonb then
    d:=state->'document';select material into stored from crm_private.b07_requirement_documents where requirement_id=iid and document_id=(d->>'documentId')::uuid;
    if stored is not null and stored<>d then raise exception 'REQUIREMENT_DOCUMENT_CONFLICT:E2';end if;
    if stored is null then insert into crm_private.b07_requirement_documents values(iid,(d->>'documentId')::uuid,(d->>'objectVersionId')::uuid,s,d,op);end if;
   end if;
   insert into crm_private.b07_requirement_revisions values(iid,rev,s,op,action,a,old,state,actor,(a->>'evidenceId')::uuid,a->>'sourceRef',a->>'reason',at_time,clock_timestamp());
  end if;
  r:=jsonb_build_object('id',iid,'replayed',coalesce(state=old,false) or equivalent is not null,'result',state);
  insert into crm_private.b07_requirement_operations values(op,iid,s,actor,fp,r,rev,clock_timestamp());
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.requirement_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;s text;bid uuid;iid uuid;r jsonb;pending jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'REQUIREMENT_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-REQUIREMENT-READ1' then raise exception 'REQUIREMENT_INPUT_INVALID';end if;a:=fs[2]::jsonb;s:=hf[17];bid:=(a->>'bookingId')::uuid;
 if not exists(select 1 from crm_private.b04_bookings where booking_id=bid and admin_scope=s) then r:=null;
 elsif a?'requirementId' then
  if a-array['requirementId','bookingId']<>'{}'::jsonb then raise exception 'REQUIREMENT_INPUT_INVALID';end if;iid:=(a->>'requirementId')::uuid;
  select after_data into r from crm_private.b07_requirement_revisions v join crm_private.b07_requirements i using(requirement_id) where i.requirement_id=iid and i.booking_id=bid and i.admin_scope=s and v.admin_scope=s order by v.revision desc limit 1;
  if r is not null then r:=r||jsonb_build_object('history',(select jsonb_agg(jsonb_build_object('revision',revision,'action',action_kind,'before',before_data,'after',after_data,'actorId',actor_id,'reason',reason,'sourceRef',source_ref,'evidenceId',evidence_id,'at',occurred_at,'recordedAt',recorded_at) order by revision) from crm_private.b07_requirement_revisions where requirement_id=iid and admin_scope=s));end if;
 else
  if a-array['bookingId','scope','purpose']<>'{}'::jsonb or not crm_private.requirement_scope(a->'scope',bid,s) or not coalesce(crm_private.invoice_text(a->'purpose'),false) then raise exception 'REQUIREMENT_INPUT_INVALID';end if;
  select coalesce(jsonb_agg(jsonb_build_object('requirementId',i.requirement_id,'scope',v.after_data->'basis'->'scope','missing',case v.after_data->>'status' when 'Pendiente' then 'document' when 'Recibido' then 'review' else 'compliance' end)),'[]') into pending from crm_private.b07_requirements i cross join lateral (select after_data from crm_private.b07_requirement_revisions v where v.requirement_id=i.requirement_id order by revision desc limit 1) v where i.booking_id=bid and i.admin_scope=s and v.after_data->'basis'->'rule'->>'purpose'=a->>'purpose' and v.after_data->'basis'->'scope'=a->'scope' and v.after_data->'basis'->'rule'->'indispensable'='true'::jsonb and v.after_data->>'status' not in ('Revisado','No aplica');
  r:=jsonb_build_object('allowed',pending='[]'::jsonb,'pending',pending);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_private.incident_links(x jsonb, bid uuid, s text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$declare e jsonb;begin
 if jsonb_typeof(x) is distinct from 'array' then return false;end if;
 for e in select value from jsonb_array_elements(x) loop
  if jsonb_typeof(e) is distinct from 'object' or e-array['kind','id']<>'{}'::jsonb or not(e ?& array['kind','id']) or not coalesce(crm_private.invoice_text(e->'id'),false) then return false;end if;
  if e->>'kind'='requirement' then if not exists(select 1 from crm_private.b07_requirements where requirement_id=(e->>'id')::uuid and booking_id=bid and admin_scope=s) then return false;end if;
  elsif e->>'kind'='invoice' then if not exists(select 1 from crm_private.b05_provider_invoices where invoice_id=(e->>'id')::uuid and booking_id=bid and admin_scope=s) then return false;end if;
  elsif e->>'kind'='provider-payment' then if not exists(select 1 from crm_private.b05_provider_payments where provider_payment_id=(e->>'id')::uuid and booking_id=bid and admin_scope=s) then return false;end if;
  else return false;end if;
 end loop;return true;end$function$

CREATE OR REPLACE FUNCTION crm_api.incident_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea, cf2p bytea, cf2s bytea, cf1p bytea, cf1s bytea, cq bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];cs text[];a jsonb;op uuid;iid uuid;bid uuid;actor uuid;s text;action text;fp text;proofhash text;rev bigint;at_time timestamptz;
 prev crm_private.b07_incident_operations;root crm_private.b07_incidents;old jsonb;state jsonb;r jsonb;data jsonb;st text;code text;assigned timestamptz;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'INCIDENT_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-INCIDENT1' then raise exception 'INCIDENT_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or not(a ?& array['action','operationId','incidentId','bookingId','expectedRevision','sourceRef','reason','at','evidenceId','data'])
 or a-array['action','operationId','incidentId','bookingId','expectedRevision','sourceRef','reason','at','evidenceId','data','origin']<>'{}'::jsonb
 or exists(select 1 from unnest(array['action','operationId','incidentId','bookingId','sourceRef','reason','at','evidenceId']) k where not coalesce(crm_private.invoice_text(a->k),false))
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or a->>'expectedRevision' !~ '^(0|[1-9][0-9]*)$'
 or (a?'origin' and jsonb_typeof(a->'origin') is distinct from 'string') or coalesce(a->>'origin','manual')<>'manual'
 or a->>'action' not in ('detect','manage','resolve','close','reopen','severity','justify') or jsonb_typeof(a->'data') is distinct from 'object'
 or a->>'at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'INCIDENT_INPUT_INVALID';end if;
 action:=a->>'action';data:=a->'data';op:=(a->>'operationId')::uuid;iid:=(a->>'incidentId')::uuid;bid:=(a->>'bookingId')::uuid;actor:=hf[12]::uuid;s:=hf[17];at_time:=(a->>'at')::timestamptz;
 if not exists(select 1 from crm_private.b04_bookings where booking_id=bid and admin_scope=s) then raise exception 'INCIDENT_DENIED';end if;
 perform pg_advisory_xact_lock(hashtextextended('incident-booking:'||bid,0));
 select * into root from crm_private.b07_incidents where incident_id=iid and booking_id=bid and admin_scope=s;
 if action<>'detect' and root.incident_id is null then raise exception 'INCIDENT_DENIED';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('incident-op:'||op,0));
 select * into prev from crm_private.b07_incident_operations where operation_id=op;
 if found then
  if prev.admin_scope<>s or prev.actor_id<>actor or prev.fingerprint<>fp then raise exception 'INCIDENT_REPLAY_CONFLICT:E2';end if;r:=prev.result||jsonb_build_object('replayed',true);
 else
  proofhash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.payment_evidence((a->>'evidenceId')::uuid,iid,s,'incident:'||action||':'||proofhash,at_time,true)
  or not exists(select 1 from crm_private.b07_records where record_id=(a->>'evidenceId')::uuid and recorded_by=actor) then raise exception 'INCIDENT_EVIDENCE_REQUIRED:E3';end if;
  if root.incident_id is not null then select revision,after_data into rev,old from crm_private.b07_incident_revisions where incident_id=iid order by revision desc limit 1;end if;
  if action='detect' then
   if (a->>'expectedRevision')::bigint<>0 or data-array['detectorId','happenedAt','description','facts','hypothesis','severity','impact','knownEvidence','effectLinks','context']<>'{}'::jsonb
   or not(data ?& array['detectorId','happenedAt','description','facts','hypothesis','severity','impact','knownEvidence','effectLinks','context'])
   or exists(select 1 from unnest(array['happenedAt','description','facts','severity']) k where not coalesce(crm_private.invoice_text(data->k),false))
   or not coalesce(crm_private.incident_actor(data->'detectorId',s),false) or coalesce(data->>'severity' not in ('Leve','Importante','Crítica'),true)
   or (data->'hypothesis'<>'null'::jsonb and not coalesce(crm_private.invoice_text(data->'hypothesis'),false))
   or data->>'happenedAt' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$'
   or not coalesce(crm_private.incident_impact(data->'impact',bid,s),false) or jsonb_typeof(data->'knownEvidence') is distinct from 'array' or not coalesce(crm_private.incident_links(data->'effectLinks',bid,s),false) or jsonb_typeof(data->'context') is distinct from 'object' or (data->'context')-array['providerId','clientId']<>'{}'::jsonb
   then raise exception 'INCIDENT_DETECTION_REQUIRED:E3';end if;
   perform (data->>'happenedAt')::timestamptz;
   if data->'context'?'providerId' and not exists(select 1 from crm_private.catalog_items where item_id=(data->'context'->>'providerId')::uuid and item_kind='provider' and admin_scope=s) then raise exception 'INCIDENT_DENIED';end if;
   if data->'context'?'clientId' and not exists(select 1 from crm_private.identity_entities where identity_id=(data->'context'->>'clientId')::uuid and admin_scope=s and identity_verified) then raise exception 'INCIDENT_DENIED';end if;
   if exists(select 1 from jsonb_array_elements_text(data->'knownEvidence') e where not exists(select 1 from crm_private.b07_records b join crm_private.b07_links l on l.record_id=b.record_id where b.record_id=e::uuid and b.admin_scope=s and l.admin_scope=s and l.context_kind='booking' and l.context_id=bid)) then raise exception 'INCIDENT_DENIED';end if;
   if root.incident_id is not null then
    if not exists(select 1 from crm_private.b07_incident_revisions where incident_id=iid and revision=1 and event->'data'=data) then raise exception 'INCIDENT_REPLAY_CONFLICT:E2';end if;
    state:=old;
   else
    if exists(select 1 from crm_private.b07_incidents where incident_id=iid) then raise exception 'INCIDENT_DENIED';end if;
    cs:=crm_f1.fields(cq);if cardinality(cs)<>10 or cs[1]<>'CRM-H1-RESOLVE1' or cs[2]<>'assign_code' or cs[3]<>iid::text or cs[4]<>iid::text or cs[5]<>'' or cs[6]<>'INC' or cs[7]<>a->>'sourceRef' or cs[8]<>a->>'evidenceId' or cs[9]<>a->>'reason' or cs[10]<>'0' then raise exception 'INCIDENT_DENIED';end if;
    perform crm_api.identity_resolve(cf2p,cf2s,cf1p,cf1s,cq);
    select human_code,assigned_at into code,assigned from crm_private.identity_codes where code_id=iid and target_id=iid and code_kind='INC' and admin_scope=s;
    if code is null then raise exception 'INCIDENT_DENIED';end if;
    state:=data||jsonb_build_object('id',iid,'bookingId',bid,'code',code,'assignedAt',assigned,'revision',1,'status','Abierta','responsibleId',null,'solution',null,'closure',null,'justification',null);
    rev:=1;insert into crm_private.b07_incidents values(iid,bid,s,op,iid);
   end if;
  else
   if rev<>(a->>'expectedRevision')::bigint then raise exception 'INCIDENT_REVISION_CONFLICT:E2';end if;
   st:=old->>'status';state:=old;
   if action='manage' then
    if st<>'Abierta' or data-array['responsibleId','action']<>'{}'::jsonb or not(data ?& array['responsibleId','action']) or not coalesce(crm_private.incident_actor(data->'responsibleId',s),false) or not coalesce(crm_private.invoice_text(data->'action'),false) then raise exception 'INCIDENT_MANAGEMENT_REQUIRED:E3';end if;
    state:=state||jsonb_build_object('status','En gestión','responsibleId',data->'responsibleId');
   elsif action='resolve' then
    if st not in ('Abierta','En gestión') or data-array['result','resultVerified','actions','scopeResolved','cause','causeVerified','uncertainty','uncertaintyCompatible','effectsIdentified']<>'{}'::jsonb
    or not(data ?& array['result','resultVerified','actions','scopeResolved','cause','causeVerified','uncertainty','uncertaintyCompatible','effectsIdentified'])
    or not coalesce(crm_private.invoice_text(data->'result'),false) or not coalesce(crm_private.invoice_text(data->'actions'),false)
    or data->'resultVerified' is distinct from 'true'::jsonb or data->'scopeResolved' is distinct from 'true'::jsonb or data->'effectsIdentified' is distinct from 'true'::jsonb
    or not ((coalesce(crm_private.invoice_text(data->'cause'),false) and data->'causeVerified'='true'::jsonb and data->'uncertainty'='null'::jsonb and data->'uncertaintyCompatible'='false'::jsonb)
     or (data->'cause'='null'::jsonb and data->'causeVerified'='false'::jsonb and coalesce(crm_private.invoice_text(data->'uncertainty'),false) and data->'uncertaintyCompatible'='true'::jsonb)) then raise exception 'INCIDENT_SOLUTION_REQUIRED:E3';end if;
    state:=state||jsonb_build_object('status','Resuelta','solution',data,'justification',null);
   elsif action='close' then
    if st<>'Resuelta' or data-array['solutionVerified','recordSufficient','effectsIdentified']<>'{}'::jsonb or not(data ?& array['solutionVerified','recordSufficient','effectsIdentified'])
    or data->'solutionVerified' is distinct from 'true'::jsonb or data->'recordSufficient' is distinct from 'true'::jsonb or data->'effectsIdentified' is distinct from 'true'::jsonb then raise exception 'INCIDENT_CLOSURE_REQUIRED:E3';end if;
    state:=state||jsonb_build_object('status','Cerrada','closure',data);
   elsif action='reopen' then
    if st not in ('Resuelta','Cerrada') or data-array['sameProblem','basis','action','responsibleId']<>'{}'::jsonb or not(data ?& array['sameProblem','basis','action','responsibleId']) or data->'sameProblem' is distinct from 'true'::jsonb or coalesce(data->>'basis' not in ('recurrence','incorrect-solution'),true)
    or (data->'action'<>'null'::jsonb and (not coalesce(crm_private.invoice_text(data->'action'),false) or not coalesce(crm_private.incident_actor(data->'responsibleId',s),false)))
    or (data->'action'='null'::jsonb and data->'responsibleId'<>'null'::jsonb) then raise exception 'INCIDENT_REOPEN_REQUIRED:E3';end if;
    state:=state||jsonb_build_object('status',case when data->'action'='null'::jsonb then 'Abierta' else 'En gestión' end,'responsibleId',data->'responsibleId','justification',null);
   elsif action='severity' then
    if data-array['severity','basis','evasion']<>'{}'::jsonb or not(data ?& array['severity','basis','evasion']) or coalesce(data->>'severity' not in ('Leve','Importante','Crítica'),true) or not coalesce(crm_private.invoice_text(data->'basis'),false) or data->'evasion' is distinct from 'false'::jsonb then raise exception 'INCIDENT_SEVERITY_REQUIRED:E3';end if;
    state:=state||jsonb_build_object('severity',data->'severity','justification',null);
   else
    if st not in ('Abierta','En gestión') or old->>'severity'<>'Crítica' or data-array['scope','responsibleId','purpose','basis']<>'{}'::jsonb or not(data ?& array['scope','responsibleId','purpose','basis'])
    or data->'scope' is distinct from old->'impact'->'scope' or data->>'purpose' is distinct from 'complete-close' or not coalesce(crm_private.incident_actor(data->'responsibleId',s),false) or not coalesce(crm_private.invoice_text(data->'basis'),false) then raise exception 'INCIDENT_JUSTIFICATION_REQUIRED:E3';end if;
    state:=state||jsonb_build_object('justification',data||jsonb_build_object('actorId',actor,'at',at_time,'evidenceId',a->'evidenceId','reason',a->'reason'));
   end if;
   rev:=rev+1;state:=state||jsonb_build_object('revision',rev);
  end if;
  r:=jsonb_build_object('id',iid,'replayed',false,'result',state);
  if old is distinct from state then insert into crm_private.b07_incident_revisions values(iid,rev,s,op,action,a,old,state,actor,(a->>'evidenceId')::uuid,a->>'sourceRef',a->>'reason',at_time,clock_timestamp());end if;
  insert into crm_private.b07_incident_operations values(op,iid,s,actor,fp,r,rev,clock_timestamp());
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.incident_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;s text;bid uuid;iid uuid;r jsonb;items jsonb;pending jsonb;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'INCIDENT_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-INCIDENT-READ1' then raise exception 'INCIDENT_INPUT_INVALID';end if;a:=fs[2]::jsonb;s:=hf[17];bid:=(a->>'bookingId')::uuid;
 if not exists(select 1 from crm_private.b04_bookings where booking_id=bid and admin_scope=s) then r:=null;
 elsif a?'incidentId' or a?'code' then
  if a-array['incidentId','bookingId','code']<>'{}'::jsonb or (a?'incidentId' and a?'code') then raise exception 'INCIDENT_INPUT_INVALID';end if;
  select i.incident_id into iid from crm_private.b07_incidents i join crm_private.identity_codes c on c.code_id=i.code_id where i.booking_id=bid and i.admin_scope=s and c.admin_scope=s and ((a?'incidentId' and i.incident_id=(a->>'incidentId')::uuid) or (a?'code' and c.human_code=a->>'code'));
  select after_data into r from crm_private.b07_incident_revisions where incident_id=iid and admin_scope=s order by revision desc limit 1;
  if r is not null then r:=r||jsonb_build_object('history',(select jsonb_agg(jsonb_build_object('revision',revision,'action',action_kind,'before',before_data,'after',after_data,'actorId',actor_id,'reason',reason,'sourceRef',source_ref,'evidenceId',evidence_id,'at',occurred_at,'recordedAt',recorded_at) order by revision) from crm_private.b07_incident_revisions where incident_id=iid and admin_scope=s));end if;
 else
  if a-array['bookingId','scope','purpose']<>'{}'::jsonb or not coalesce(crm_private.requirement_scope(a->'scope',bid,s),false) or coalesce(a->>'purpose' not in ('preparation','operation','complete-close','economic-review'),true) then raise exception 'INCIDENT_INPUT_INVALID';end if;
  select coalesce(jsonb_agg(jsonb_build_object('incidentId',i.incident_id,'revision',v.after_data->'revision','status',v.after_data->'status','severity',v.after_data->'severity','scope',v.after_data->'impact'->'scope','effect',v.after_data->'impact'->'effect','justified',v.after_data->'justification'<>'null'::jsonb)),'[]') into items
   from crm_private.b07_incidents i cross join lateral (select after_data from crm_private.b07_incident_revisions where incident_id=i.incident_id order by revision desc limit 1) v
   where i.booking_id=bid and i.admin_scope=s and v.after_data->>'status' in ('Abierta','En gestión') and
    (a->>'purpose'='complete-close' and v.after_data->>'severity'='Crítica' or
     a->>'purpose'<>'complete-close' and v.after_data->'impact'->'material'='true'::jsonb and v.after_data->'impact'->>'effect'=a->>'purpose'
      and (v.after_data->'impact'->'scope'=a->'scope' or (not(v.after_data->'impact'->'scope'?'serviceId') and v.after_data->'impact'->'scope'->'action'=a->'scope'->'action')));
  select coalesce(jsonb_agg(e),'[]') into pending from jsonb_array_elements(items) e where not(a->>'purpose'='complete-close' and e->'justified'='true'::jsonb);
  r:=jsonb_build_object('incidentGuardAllowed',pending='[]'::jsonb,'active',items,'pending',pending,'completeClosureImplemented',false);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.availability_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea, tf2p bytea, tf2s bytea, tf1p bytea, tf1s bytea, tq bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;op uuid;iid uuid;bid uuid;actor uuid;s text;action text;fp text;proofhash text;rev bigint;at_time timestamptz;
 prev crm_private.b04_availability_operations;root crm_private.b04_availability;old jsonb;state jsonb;r jsonb;data jsonb;response jsonb;record crm_private.b07_records;task jsonb;follow boolean:=false;task_id uuid;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'AVAILABILITY_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-AVAILABILITY1' then raise exception 'AVAILABILITY_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or not(a ?& array['action','operationId','availabilityId','bookingId','expectedRevision','sourceRef','reason','at','evidenceId','data'])
 or a-array['action','operationId','availabilityId','bookingId','expectedRevision','sourceRef','reason','at','evidenceId','data','origin']<>'{}'::jsonb
 or exists(select 1 from unnest(array['action','operationId','availabilityId','bookingId','sourceRef','reason','evidenceId']) k where not coalesce(crm_private.invoice_text(a->k),false))
 or not coalesce(crm_private.availability_time(a->'at'),false) or jsonb_typeof(a->'data') is distinct from 'object'
 or coalesce(a->>'expectedRevision','') !~ '^(0|[1-9][0-9]*)$' or coalesce(a->>'origin','manual')<>'manual' then raise exception 'AVAILABILITY_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;iid:=(a->>'availabilityId')::uuid;bid:=(a->>'bookingId')::uuid;actor:=hf[12]::uuid;s:=hf[17];action:=a->>'action';data:=a->'data';at_time:=(a->>'at')::timestamptz;
 if action not in ('query','receive','verify','review') then raise exception 'AVAILABILITY_INPUT_INVALID';end if;
 if not exists(select 1 from crm_private.b04_bookings where booking_id=bid and admin_scope=s) then raise exception 'AVAILABILITY_DENIED';end if;
 perform pg_advisory_xact_lock(hashtextextended('availability-booking:'||bid,0));
 -- H2 parent is an immutable revision-1 baseline; advisory unit and version check protect its use.
 select * into root from crm_private.b04_availability where availability_id=iid;
 if root.availability_id is not null and (root.booking_id<>bid or root.admin_scope<>s) then raise exception 'AVAILABILITY_DENIED';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('availability-op:'||op,0));
 select * into prev from crm_private.b04_availability_operations where operation_id=op;
 if found then
  if prev.admin_scope<>s or prev.actor_id<>actor or prev.fingerprint<>fp then raise exception 'AVAILABILITY_REPLAY_CONFLICT:E2';end if;r:=prev.result||jsonb_build_object('replayed',true);
 else
  proofhash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.payment_evidence((a->>'evidenceId')::uuid,iid,s,'availability:'||action||':'||proofhash,at_time,true)
  or not exists(select 1 from crm_private.b07_records where record_id=(a->>'evidenceId')::uuid and recorded_by=actor) then raise exception 'AVAILABILITY_EVIDENCE_REQUIRED:E3';end if;
  if root.availability_id is not null then select revision,after_data into rev,old from crm_private.b04_availability_revisions where availability_id=iid order by revision desc limit 1;end if;
  -- Identity of the fact is the stable root/query or explicit response factId, never similar text.
  if action='receive' and exists(select 1 from crm_private.b04_availability_revisions where admin_scope=s and event->'data'->>'factId'=data->>'factId' and (availability_id<>iid or event->'data' is distinct from data)) then raise exception 'AVAILABILITY_FACT_CONFLICT:E2';end if;
  if (action='query' and old->'query'=data) or (action='receive' and exists(select 1 from crm_private.b04_availability_revisions where availability_id=iid and admin_scope=s and action_kind='receive' and event->'data'=data)) then state:=old;
  else
   if coalesce(rev,0)<>(a->>'expectedRevision')::bigint then raise exception 'AVAILABILITY_REVISION_CONFLICT:E2';end if;
   state:=coalesce(old,jsonb_build_object('id',iid,'bookingId',bid,'query',null,'response',null,'confirmed',null,'review',null));
   if action in ('query','receive') then
    if not coalesce(crm_private.availability_coverage(data->'coverage',bid,s),false) or not coalesce(crm_private.availability_source(data->'source',bid,(data->'coverage'->>'serviceId')::uuid,s),false)
    or not coalesce(crm_private.availability_time(data->'happenedAt'),false) or not coalesce(crm_private.invoice_text(data->'content'),false) then raise exception 'AVAILABILITY_FACT_REQUIRED:E3';end if;
    -- Service baseline is immutable; no UPDATE grant is introduced to lock it.
    if old is not null and (data->'coverage'->'serviceId' is distinct from coalesce(old->'query'->'coverage'->'serviceId',old->'response'->'coverage'->'serviceId')
    or data->'coverage'->'nightId' is distinct from coalesce(old->'query'->'coverage'->'nightId',old->'response'->'coverage'->'nightId')
    or data->'coverage'->'purpose' is distinct from coalesce(old->'query'->'coverage'->'purpose',old->'response'->'coverage'->'purpose')
    or data->'source' is distinct from coalesce(old->'query'->'source',old->'response'->'source')) then raise exception 'AVAILABILITY_SCOPE_CONFLICT:E2';end if;
    if action='query' then
     if old is not null or data-array['coverage','source','happenedAt','content']<>'{}'::jsonb then raise exception 'AVAILABILITY_QUERY_REQUIRED:E3';end if;
     state:=state||jsonb_build_object('query',data,'status','Consulta registrada','serviceAvailabilityState','Disponibilidad consultada');follow:=true;
    else
     if data-array['coverage','source','happenedAt','content','factId','recordId','certainty','conditions','validUntil']<>'{}'::jsonb
     or not(data ?& array['factId','recordId','certainty','conditions','validUntil']) or coalesce(data->>'certainty' not in ('communicated','negative','uncertain'),true)
     or not coalesce(crm_private.invoice_text(data->'conditions'),false) or not coalesce(crm_private.invoice_text(data->'factId'),false)
     or (data->'validUntil'<>'null'::jsonb and not coalesce(crm_private.availability_time(data->'validUntil'),false)) then raise exception 'AVAILABILITY_RESPONSE_REQUIRED:E3';end if;
     perform (data->>'factId')::uuid;
     select * into record from crm_private.b07_records where record_id=(data->>'recordId')::uuid and admin_scope=s;
     if record.record_id is null or not exists(select 1 from crm_private.b07_links where record_id=record.record_id and admin_scope=s and context_kind='booking' and context_id=bid) then raise exception 'AVAILABILITY_DENIED';end if;
     if exists(select 1 from crm_private.b04_availability_revisions where admin_scope=s and event->'data'->>'factId'=data->>'factId' and event->'data' is distinct from data) then raise exception 'AVAILABILITY_FACT_CONFLICT:E2';end if;
     state:=state||jsonb_build_object('response',data,'status',case data->>'certainty' when 'communicated' then 'Disponibilidad comunicada' when 'negative' then 'Negativa' else 'Incierta' end);
     if old->'confirmed'<>'null'::jsonb then state:=state||jsonb_build_object('review',jsonb_build_object('cause','Nueva comunicación pendiente de contraste','before',old->'confirmed','after',data,'dependencies',jsonb_build_array(data->'coverage'),'evidenceId',a->'evidenceId','result','pending'),'status','Pendiente de revalidación');follow:=true;end if;
     if data->>'certainty'<>'communicated' then follow:=true;state:=state||jsonb_build_object('review',jsonb_build_object('cause',data->>'content','before',old->'confirmed','after',data,'dependencies',jsonb_build_array(data->'coverage'),'evidenceId',a->'evidenceId','result','pending'));end if;
    end if;
   elsif action='verify' then
    response:=old->'response';
    if response is null or response='null'::jsonb or response->>'certainty'<>'communicated' or data-array['coverage','source','actionAt','actionUntil','authority','unequivocal','checks','precedence','basis','resolvedAspects']<>'{}'::jsonb
    or not(data ?& array['coverage','source','actionAt','actionUntil','authority','unequivocal','checks','precedence','basis','resolvedAspects'])
    or data->'coverage' is distinct from response->'coverage' or data->'source' is distinct from response->'source'
    or not coalesce(crm_private.availability_coverage(data->'coverage',bid,s),false) or not coalesce(crm_private.availability_source(data->'source',bid,(data->'coverage'->>'serviceId')::uuid,s),false)
    or data->'authority' is distinct from 'true'::jsonb or data->'unequivocal' is distinct from 'true'::jsonb
    or data->'checks' is distinct from '{"dates":true,"quantity":true,"unit":true,"variant":true,"conditions":true,"capacity":true,"validity":true}'::jsonb
    or not coalesce(crm_private.availability_time(data->'actionAt'),false) or not coalesce(crm_private.availability_time(data->'actionUntil'),false)
    or not coalesce(crm_private.invoice_text(data->'basis'),false) or jsonb_typeof(data->'resolvedAspects') is distinct from 'array'
    then raise exception 'AVAILABILITY_VERIFICATION_REQUIRED:E3';end if;
    if (response->>'happenedAt')::timestamptz>at_time or (response->>'happenedAt')::timestamptz>(data->>'actionAt')::timestamptz or at_time>(data->>'actionAt')::timestamptz then raise exception 'AVAILABILITY_CHRONOLOGY_REQUIRED:E3';end if;
    if (data->>'actionUntil')::timestamptz<(data->>'actionAt')::timestamptz or (response->'validUntil'<>'null'::jsonb and (data->>'actionUntil')::timestamptz>=(response->>'validUntil')::timestamptz) then raise exception 'AVAILABILITY_EXPIRED:E3';end if;
    if old->'confirmed'<>'null'::jsonb and not (
      data->>'precedence'='verified-newer' and (response->>'happenedAt')::timestamptz>(old->'confirmed'->'response'->>'happenedAt')::timestamptz
      or data->>'precedence'='ratified' and response=old->'confirmed'->'response' and a->'evidenceId' is distinct from old->'confirmed'->'evidenceId' and at_time>=(old->'confirmed'->>'at')::timestamptz
    ) then raise exception 'AVAILABILITY_DISCREPANCY:E8';end if;
    if old->'review'<>'null'::jsonb and not(data->'resolvedAspects' @> coalesce(old->'review'->'aspects','["dates","quantity","unit","variant","conditions","capacity","validity"]')) then raise exception 'AVAILABILITY_REVIEW_INCOMPLETE:E3';end if;
    state:=state||jsonb_build_object('status','Disponibilidad confirmada','confirmed',jsonb_build_object('response',response,'verification',data,'evidenceId',a->'evidenceId','actorId',actor,'at',at_time),'review',null);
   else
    if old is null or data-array['cause','before','after','dependencies','aspects','result']<>'{}'::jsonb or not(data ?& array['cause','before','after','dependencies','aspects','result'])
    or not coalesce(crm_private.invoice_text(data->'cause'),false) or jsonb_typeof(data->'dependencies') is distinct from 'array' or jsonb_array_length(data->'dependencies')=0
    or data->'before' is distinct from old->'confirmed' or jsonb_typeof(data->'aspects') is distinct from 'array' or jsonb_array_length(data->'aspects')=0
    or coalesce(data->>'result' not in ('pending','rejected','uncertain'),true) then raise exception 'AVAILABILITY_REVIEW_REQUIRED:E3';end if;
    if exists(select 1 from jsonb_array_elements(data->'dependencies') d where d is distinct from coalesce(old->'response'->'coverage',old->'query'->'coverage'))
    or exists(select 1 from jsonb_array_elements_text(data->'aspects') k where k not in ('dates','quantity','unit','variant','conditions','capacity','validity'))
    or jsonb_typeof(data->'after') is distinct from 'object' or (data->'after')-array['dates','quantity','unitRevisionId','variant','conditions','capacity','source','validUntil','schedule']<>'{}'::jsonb then raise exception 'AVAILABILITY_REVIEW_SCOPE_REQUIRED:E3';end if;
    state:=state||jsonb_build_object('status','Pendiente de revalidación','review',data||jsonb_build_object('evidenceId',a->'evidenceId','actorId',actor,'at',at_time));follow:=true;
   end if;
   rev:=coalesce(rev,0)+1;state:=state||jsonb_build_object('revision',rev);
  end if;
  r:=jsonb_build_object('id',iid,'replayed',false,'result',state);
  if root.availability_id is null then insert into crm_private.b04_availability values(iid,bid,s,op);end if;
  if old is distinct from state then insert into crm_private.b04_availability_revisions values(iid,rev,s,op,action,a,old,state,actor,(a->>'evidenceId')::uuid,a->>'sourceRef',a->>'reason',at_time,clock_timestamp());end if;
  if follow then
   fs:=crm_f1.fields(tq);task:=fs[2]::jsonb;
   if fs[1]<>'CRM-H1-TASK-1' or task->>'taskId'<>iid::text or task->>'operationId'<>op::text or task->'identity' is distinct from jsonb_build_object('causeKind','availability','causeId',iid,'contextKind','booking','contextId',bid,'scopeRef',iid,'effect','availability-review')
   or task->'material' is distinct from '{"title":"Revisar disponibilidad del alcance","deadline":{"kind":"unknown","reason":"No consta plazo informado para el seguimiento"},"priority":{"kind":"pending","reason":"Prioridad no configurada"},"sourceRef":"SM-AV-04","sourceVersion":"1","triggerRef":"BR-TASK-005","triggerVersion":"1"}'::jsonb then raise exception 'AVAILABILITY_TASK_REQUIRED';end if;
   select result_ref into task_id from crm_api.b07_task_apply(tf2p,tf2s,tf1p,tf1s,tq);
  end if;
  insert into crm_private.b04_availability_operations values(op,iid,s,actor,fp,r,rev,clock_timestamp());
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.availability_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;s text;bid uuid;iid uuid;r jsonb;items jsonb;usable boolean;v jsonb;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'AVAILABILITY_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-AVAILABILITY-READ1' then raise exception 'AVAILABILITY_INPUT_INVALID';end if;a:=fs[2]::jsonb;s:=hf[17];bid:=(a->>'bookingId')::uuid;
 if not exists(select 1 from crm_private.b04_bookings where booking_id=bid and admin_scope=s) then r:=null;
 elsif a?'availabilityId' then
  if a-array['availabilityId','bookingId']<>'{}'::jsonb then raise exception 'AVAILABILITY_INPUT_INVALID';end if;
  select availability_id into iid from crm_private.b04_availability where availability_id=(a->>'availabilityId')::uuid and booking_id=bid and admin_scope=s;
  select after_data into r from crm_private.b04_availability_revisions where availability_id=iid and admin_scope=s order by revision desc limit 1;
  if r is not null then r:=r||jsonb_build_object('history',(select jsonb_agg(jsonb_build_object('revision',revision,'action',action_kind,'before',before_data,'after',after_data,'actorId',actor_id,'sourceRef',source_ref,'reason',reason,'evidenceId',evidence_id,'at',occurred_at,'recordedAt',recorded_at) order by revision) from crm_private.b04_availability_revisions where availability_id=iid and admin_scope=s));end if;
 else
  if a-array['bookingId','coverage','source','actionAt','actionUntil']<>'{}'::jsonb or (not coalesce(crm_private.availability_coverage(a->'coverage',bid,s),false) and not exists(select 1 from crm_private.b04_availability av join crm_private.b04_availability_revisions rv using(availability_id) where av.booking_id=bid and av.admin_scope=s and (rv.after_data->'confirmed'->'response'->'coverage'=a->'coverage' or rv.after_data->'response'->'coverage'=a->'coverage')))
  or not coalesce(crm_private.availability_time(a->'actionAt'),false) or not coalesce(crm_private.availability_time(a->'actionUntil'),false) then raise exception 'AVAILABILITY_INPUT_INVALID';end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',i.availability_id,'revision',v.after_data->'revision','status',v.after_data->'status','confirmed',case when v.after_data->'confirmed'='null'::jsonb then 'null'::jsonb else jsonb_build_object('response',(v.after_data->'confirmed'->'response')-array['content','factId','recordId','certainty'],'verification',jsonb_build_object('actionAt',v.after_data->'confirmed'->'verification'->'actionAt','actionUntil',v.after_data->'confirmed'->'verification'->'actionUntil')) end,'pending',v.after_data->'review'<>'null'::jsonb)),'[]') into items
  from crm_private.b04_availability i cross join lateral (select after_data from crm_private.b04_availability_revisions where availability_id=i.availability_id order by revision desc limit 1) v
  where i.booking_id=bid and i.admin_scope=s and coalesce(v.after_data->'response'->'coverage',v.after_data->'query'->'coverage')->>'serviceId'=a->'coverage'->>'serviceId'
  and coalesce(v.after_data->'response'->'coverage',v.after_data->'query'->'coverage')->'nightId'=a->'coverage'->'nightId'
  and coalesce(v.after_data->'response'->'coverage',v.after_data->'query'->'coverage')->'purpose'=a->'coverage'->'purpose'
  and coalesce(v.after_data->'response'->'source',v.after_data->'query'->'source')=a->'source'
  and (v.after_data->'response'->'coverage'=a->'coverage' or v.after_data->'confirmed'->'response'->'coverage'=a->'coverage' or v.after_data->'query'->'coverage'=a->'coverage');
  usable:=false;
  for v in select value from jsonb_array_elements(items) loop
   if v->>'status'='Disponibilidad confirmada' and v->'confirmed'->'response'->'coverage'=a->'coverage' and v->'confirmed'->'response'->'source'=a->'source'
   and v->'confirmed'->'verification'->'actionAt'=a->'actionAt' and v->'confirmed'->'verification'->'actionUntil'=a->'actionUntil'
   and (v->'confirmed'->'response'->'validUntil'='null'::jsonb or (a->>'actionUntil')::timestamptz<(v->'confirmed'->'response'->>'validUntil')::timestamptz) then usable:=true;end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(items) e where e->'pending'='true'::jsonb) then usable:=false;end if;
  -- Multiple independent roots with differing verified external facts cannot choose precedence by arrival.
  if (select count(distinct (e->'confirmed'->'response')-'happenedAt') from jsonb_array_elements(items) e where e->'confirmed'<>'null'::jsonb and e->'confirmed'->'response'->'coverage'=a->'coverage')>1 then usable:=false;end if;
  if not coalesce(crm_private.availability_coverage(a->'coverage',bid,s),false) then usable:=false;end if;if crm_private.modification_pending(bid,(a->'coverage'->>'serviceId')::uuid,(a->'coverage'->>'nightId')::uuid,s) then usable:=false;end if;r:=jsonb_build_object('usable',usable,'certainty',case when usable then 'verified-for-action' else 'pending' end,'missing',case when usable then '[]'::jsonb else case when (select count(distinct (e->'confirmed'->'response')-'happenedAt') from jsonb_array_elements(items) e where e->'confirmed'<>'null'::jsonb and e->'confirmed'->'response'->'coverage'=a->'coverage')>1 then '["E8","coverage-or-review"]'::jsonb else '["coverage-or-review"]'::jsonb end end,'evidence',items,'serviceConfirmed',false,'firmReservation',false,'executed',false);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_private.hold_part(x jsonb, opp uuid, s text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$begin
 if jsonb_typeof(x) is distinct from 'object' or not(x ?& array['id','versionId','lineId','serviceRevisionId','variantRevisionId','date','quantity','unitRevisionId','conditions','expiresAt'])
 or x-array['id','versionId','lineId','serviceRevisionId','variantRevisionId','date','quantity','unitRevisionId','conditions','expiresAt']<>'{}'::jsonb
 or not coalesce(crm_private.invoice_text(x->'conditions'),false) or coalesce(x->>'quantity','')!~'^[0-9]+(\.[0-9]+)?$' or (x->>'quantity')::numeric<=0
 or coalesce(x->>'date','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or not(x->'expiresAt'='null'::jsonb or coalesce(crm_private.availability_time(x->'expiresAt'),false)) then return false;end if;
 perform (x->>'id')::uuid;perform (x->>'date')::date;
 if not exists(select 1 from crm_private.b03_proposal_lines l join crm_private.b03_proposal_versions v using(version_id) join crm_private.b03_proposals p using(proposal_id)
 where p.opportunity_id=opp and p.admin_scope=s and l.admin_scope=s and v.admin_scope=s and l.version_id=(x->>'versionId')::uuid and l.line_id=(x->>'lineId')::uuid
 and l.service_revision_id=(x->>'serviceRevisionId')::uuid and (l.service_date is null or l.service_date=(x->>'date')::date)) then return false;end if;
 if not exists(select 1 from crm_private.catalog_revisions r join crm_private.catalog_items i using(item_id) where r.revision_id=(x->>'unitRevisionId')::uuid and r.admin_scope=s and i.admin_scope=s and i.item_kind='unit') then return false;end if;
 if x->'variantRevisionId'<>'null'::jsonb and not exists(select 1 from crm_private.catalog_revisions r join crm_private.catalog_items i using(item_id) where r.revision_id=(x->>'variantRevisionId')::uuid and r.admin_scope=s and i.item_kind='variant' and i.parent_id=(select item_id from crm_private.catalog_revisions where revision_id=(x->>'serviceRevisionId')::uuid)) then return false;end if;return true;end$function$

CREATE OR REPLACE FUNCTION crm_api.hold_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea, tf2p bytea, tf2s bytea, tf1p bytea, tf1s bytea, tq bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;op uuid;iid uuid;opp uuid;actor uuid;s text;action text;fp text;proofhash text;rev bigint;at_time timestamptz;
 prev crm_private.b04_hold_operations;root crm_private.b04_holds;old jsonb;state jsonb;r jsonb;data jsonb;p jsonb;v jsonb;parts jsonb;selection jsonb;amount numeric;remaining numeric;
 fact crm_private.b04_hold_revisions;known boolean:=false;follow boolean:=false;task jsonb;task_id uuid;entry jsonb;record crm_private.b07_records;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'HOLD_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-HOLD1' then raise exception 'HOLD_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or not(a ?& array['action','operationId','holdId','opportunityId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','at','evidenceId','data'])
 or a-array['action','operationId','holdId','opportunityId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','at','evidenceId','data','origin']<>'{}'::jsonb
 or exists(select 1 from unnest(array['action','operationId','holdId','opportunityId','sourceRef','reason','evidenceId']) k where not coalesce(crm_private.invoice_text(a->k),false))
 or not coalesce(crm_private.availability_time(a->'at'),false) or jsonb_typeof(a->'data') is distinct from 'object'
 or coalesce(a->>'expectedRevision','')!~'^(0|[1-9][0-9]*)$' or coalesce(a->>'expectedOpportunityRevision','')!~'^[1-9][0-9]*$' or coalesce(a->>'origin','manual')<>'manual' then raise exception 'HOLD_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;iid:=(a->>'holdId')::uuid;opp:=(a->>'opportunityId')::uuid;actor:=hf[12]::uuid;s:=hf[17];action:=a->>'action';data:=a->'data';at_time:=(a->>'at')::timestamptz;
 if action not in ('grant','check','near','invalidate','request','release','extend','link') then raise exception 'HOLD_INPUT_INVALID';end if;
 if not exists(select 1 from crm_private.b03_opportunities where opportunity_id=opp and admin_scope=s) then raise exception 'HOLD_DENIED';end if;
 -- Same parent lock/order as real H2 conversion; protects first roots and link/conversion race.
 perform pg_advisory_xact_lock(hashtextextended(opp::text,31));
 perform pg_advisory_xact_lock(hashtextextended('hold:'||iid,0));
 select * into root from crm_private.b04_holds where hold_id=iid;
 if (action<>'grant' and root.hold_id is null) or (root.hold_id is not null and (root.opportunity_id<>opp or root.admin_scope<>s)) then raise exception 'HOLD_DENIED';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('hold-op:'||op,0));
 select * into prev from crm_private.b04_hold_operations where operation_id=op;
 if found then
  if prev.admin_scope<>s or prev.actor_id<>actor or prev.fingerprint<>fp then raise exception 'HOLD_REPLAY_CONFLICT:E2';end if;r:=prev.result||jsonb_build_object('replayed',true);
 else
  proofhash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.payment_evidence((a->>'evidenceId')::uuid,iid,s,'hold:'||action||':'||proofhash,at_time,true)
  or not exists(select 1 from crm_private.b07_records where record_id=(a->>'evidenceId')::uuid and recorded_by=actor) then raise exception 'HOLD_EVIDENCE_REQUIRED:E3';end if;
  if data?'factId' then
   perform (data->>'factId')::uuid;
   perform pg_advisory_xact_lock(hashtextextended('hold-fact:'||(data->>'factId'),0));
   select * into fact from crm_private.b04_hold_revisions where admin_scope=s and event->'data'->>'factId'=data->>'factId';
   if found then
    if fact.action_kind<>action or fact.event->'data' is distinct from data or not exists(select 1 from crm_private.b04_holds where hold_id=fact.hold_id and opportunity_id=opp and admin_scope=s) then raise exception 'HOLD_FACT_CONFLICT:E2';end if;
    if action<>'grant' and fact.hold_id<>iid then raise exception 'HOLD_FACT_CONFLICT:E2';end if;
    iid:=fact.hold_id;select * into root from crm_private.b04_holds where hold_id=iid;known:=true;
   end if;
  end if;
  if root.hold_id is not null then select revision,after_data into rev,old from crm_private.b04_hold_revisions where hold_id=iid order by revision desc limit 1;end if;
  if not known and action in ('check','near','invalidate','request','link') and exists(select 1 from crm_private.b04_hold_revisions where hold_id=iid and admin_scope=s and action_kind=action and event->'data'=data) then known:=true;end if;
  if known then state:=old;
  else
   if coalesce(rev,0)<>(a->>'expectedRevision')::bigint or not exists(select 1 from crm_private.b03_opportunities where opportunity_id=opp and admin_scope=s and revision=(a->>'expectedOpportunityRevision')::bigint) then raise exception 'HOLD_REVISION_CONFLICT:E2';end if;
   state:=old;
   if action='grant' then
    if root.hold_id is not null or data-array['providerRevisionId','externalRef','factId','recordId','happenedAt','certainty','parts','replacesHoldId']<>'{}'::jsonb
    or not(data ?& array['providerRevisionId','externalRef','factId','recordId','happenedAt','certainty','parts','replacesHoldId']) or data->>'certainty' is distinct from 'granted'
    or not coalesce(crm_private.invoice_text(data->'externalRef'),false) or not coalesce(crm_private.availability_time(data->'happenedAt'),false) or (data->>'happenedAt')::timestamptz>at_time
    or jsonb_typeof(data->'parts') is distinct from 'array' or jsonb_array_length(data->'parts')=0
    or exists(select 1 from jsonb_array_elements(data->'parts') x where not coalesce(crm_private.hold_part(x,opp,s),false))
    or (select count(*)<>count(distinct x->>'id') from jsonb_array_elements(data->'parts') x)
    or not exists(select 1 from crm_private.catalog_revisions r join crm_private.catalog_items i using(item_id) where r.revision_id=(data->>'providerRevisionId')::uuid and r.admin_scope=s and i.admin_scope=s and i.item_kind='provider')
    or not coalesce(crm_private.hold_record((data->>'recordId')::uuid,opp,s),false) then raise exception 'HOLD_GRANT_REQUIRED:E3';end if;
    perform pg_advisory_xact_lock(hashtextextended('hold-resource:'||(data->>'providerRevisionId')||':'||(data->>'externalRef'),0));
    if exists(select 1 from crm_private.b04_holds where admin_scope=s and provider_revision_id=(data->>'providerRevisionId')::uuid and external_ref=data->>'externalRef') then raise exception 'HOLD_IDENTITY_CONFLICT:E2';end if;
    if data->'replacesHoldId'<>'null'::jsonb and not exists(select 1 from crm_private.b04_holds where hold_id=(data->>'replacesHoldId')::uuid and opportunity_id=opp and admin_scope=s and provider_revision_id=(data->>'providerRevisionId')::uuid) then raise exception 'HOLD_SUBSTITUTION_REQUIRED:E3';end if;
    parts:='[]';for p in select value from jsonb_array_elements(data->'parts') loop
     if p->'expiresAt'<>'null'::jsonb and (p->>'expiresAt')::timestamptz<=(data->>'happenedAt')::timestamptz then raise exception 'HOLD_EXPIRY_REQUIRED:E3';end if;
     parts:=parts||jsonb_build_array(jsonb_build_object('terms',p,'remaining',p->>'quantity','validity','Creado','verified',null,'request',null,'review',null,'near',null,'link',null,'lastFactAt',data->'happenedAt'));
     if p->'expiresAt'='null'::jsonb then follow:=true;end if;
    end loop;
    state:=jsonb_build_object('id',iid,'opportunityId',opp,'providerRevisionId',data->'providerRevisionId','externalRef',data->'externalRef','grant',data,'parts',parts,'replacesHoldId',data->'replacesHoldId');
   else
    if old is null then raise exception 'HOLD_DENIED';end if;
    if action in ('release','extend') then
     if data-array['selections','factId','recordId','happenedAt','providerRevisionId','authority','unequivocal','certainty','basis']<>'{}'::jsonb
     or not(data ?& array['selections','factId','recordId','happenedAt','providerRevisionId','authority','unequivocal','certainty','basis'])
     or data->'providerRevisionId' is distinct from old->'providerRevisionId' or data->'authority' is distinct from 'true'::jsonb or data->'unequivocal' is distinct from 'true'::jsonb
     or data->>'certainty' is distinct from (case action when 'release' then 'released' else 'extended' end)
     or not coalesce(crm_private.invoice_text(data->'basis'),false) or not coalesce(crm_private.availability_time(data->'happenedAt'),false) or (data->>'happenedAt')::timestamptz>at_time
     or not coalesce(crm_private.hold_record((data->>'recordId')::uuid,opp,s),false) or jsonb_typeof(data->'selections') is distinct from 'array' or jsonb_array_length(data->'selections')=0
     or (select count(*)<>count(distinct x->>'partId') from jsonb_array_elements(data->'selections') x) then raise exception 'HOLD_RESPONSE_REQUIRED:E3';end if;
    else
     if jsonb_typeof(data->'partIds') is distinct from 'array' or jsonb_array_length(data->'partIds')=0 or (select count(*)<>count(distinct x) from jsonb_array_elements_text(data->'partIds') x) then raise exception 'HOLD_SCOPE_REQUIRED:E3';end if;
    end if;
    if exists(select 1 from jsonb_array_elements(case when action in ('release','extend') then data->'selections' else (select jsonb_agg(jsonb_build_object('partId',x)) from jsonb_array_elements_text(data->'partIds') x) end) x where not exists(select 1 from jsonb_array_elements(old->'parts') y where y->'terms'->>'id'=x->>'partId')) then raise exception 'HOLD_SCOPE_REQUIRED:E3';end if;
    parts:='[]';
    for p in select value from jsonb_array_elements(old->'parts') loop
     selection:=null;
     if action in ('release','extend') then select value into selection from jsonb_array_elements(data->'selections') where value->>'partId'=p->'terms'->>'id';end if;
     if selection is not null or data->'partIds' ? (p->'terms'->>'id') then
      remaining:=(p->>'remaining')::numeric;
      if remaining<=0 then raise exception 'HOLD_RELEASED:E3';end if;
      if action in ('release','extend') then
       if selection-array['partId','quantity','unitRevisionId','date','expiresAt','conditions','newPartId','newDate']<>'{}'::jsonb or not(selection ?& array['partId','quantity','unitRevisionId','date'])
       or coalesce(selection->>'quantity','')!~'^[0-9]+(\.[0-9]+)?$' or (selection->>'quantity')::numeric<=0 or (selection->>'quantity')::numeric>remaining
       or selection->'unitRevisionId' is distinct from p->'terms'->'unitRevisionId' or selection->'date' is distinct from p->'terms'->'date' then raise exception 'HOLD_PORTION_REQUIRED:E3';end if;
       if (data->>'happenedAt')::timestamptz<=(p->>'lastFactAt')::timestamptz then raise exception 'HOLD_PRECEDENCE_REQUIRED:E8';end if;
       amount:=(selection->>'quantity')::numeric;
       if action='release' then
        if selection-array['partId','quantity','unitRevisionId','date']<>'{}'::jsonb then raise exception 'HOLD_PORTION_REQUIRED:E3';end if;
        p:=p||jsonb_build_object('remaining',(remaining-amount)::text,'lastFactAt',data->'happenedAt','release',jsonb_build_object('fact',data,'selection',selection,'evidenceId',a->'evidenceId','actorId',actor,'at',at_time));
        if remaining=amount then p:=p||jsonb_build_object('validity','Liberado','verified',null,'near',null);else p:=p||jsonb_build_object('validity','No verificado','verified',null);follow:=true;end if;
       else
        if not(selection ?& array['expiresAt','conditions']) or not coalesce(crm_private.invoice_text(selection->'conditions'),false)
        or not coalesce(crm_private.availability_time(selection->'expiresAt'),false) or (selection->>'expiresAt')::timestamptz<=at_time then raise exception 'HOLD_EXTENSION_REQUIRED:E3';end if;
        if selection?'newDate' then
         if coalesce(selection->>'newDate','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'HOLD_EXTENSION_REQUIRED:E3';end if;perform (selection->>'newDate')::date;
        end if;
        if amount<remaining then
         if not coalesce(crm_private.invoice_text(selection->'newPartId'),false) then raise exception 'HOLD_SPLIT_REQUIRED:E3';end if;perform (selection->>'newPartId')::uuid;
         if exists(select 1 from jsonb_array_elements(old->'parts') x where x->'terms'->>'id'=selection->>'newPartId') then raise exception 'HOLD_SPLIT_REQUIRED:E3';end if;
         v:=p||jsonb_build_object('terms',(p->'terms')||jsonb_build_object('id',selection->'newPartId','quantity',amount::text,'expiresAt',selection->'expiresAt','conditions',selection->'conditions','date',coalesce(selection->'newDate',p->'terms'->'date')),'remaining',amount::text,'parentPartId',p->'terms'->'id','validity','No verificado','verified',null,'near',null,'review',jsonb_build_object('cause','Prórroga parcial acreditada','before',p,'after',selection,'result','new-scope','evidenceId',a->'evidenceId'),'lastFactAt',data->'happenedAt');
         if selection?'newDate' and selection->'newDate' is distinct from p->'terms'->'date' then v:=v||jsonb_build_object('link',null);end if;
         parts:=parts||jsonb_build_array(v);p:=p||jsonb_build_object('remaining',(remaining-amount)::text);
        else
         if selection?'newPartId' then raise exception 'HOLD_SPLIT_REQUIRED:E3';end if;
         p:=p||jsonb_build_object('terms',(p->'terms')||jsonb_build_object('expiresAt',selection->'expiresAt','conditions',selection->'conditions','date',coalesce(selection->'newDate',p->'terms'->'date')),'validity','No verificado','verified',null,'near',null,'review',jsonb_build_object('cause','Términos nuevos acreditados','before',p,'after',selection,'result','new-scope','evidenceId',a->'evidenceId'),'lastFactAt',data->'happenedAt');
         if selection?'newDate' then p:=p||jsonb_build_object('link',null);end if;
        end if;follow:=true;
       end if;
      elsif action='check' then
       if data-array['partIds','actionAt','actionUntil','happenedAt','recordId','providerRevisionId','authority','conditionsMet','basis']<>'{}'::jsonb or not(data ?& array['actionAt','actionUntil','happenedAt','recordId','providerRevisionId','authority','conditionsMet','basis'])
       or data->'providerRevisionId' is distinct from old->'providerRevisionId' or data->'authority' is distinct from 'true'::jsonb or data->'conditionsMet' is distinct from 'true'::jsonb or not coalesce(crm_private.invoice_text(data->'basis'),false)
       or not coalesce(crm_private.availability_time(data->'happenedAt'),false) or not coalesce(crm_private.availability_time(data->'actionAt'),false) or not coalesce(crm_private.availability_time(data->'actionUntil'),false)
       or (data->>'happenedAt')::timestamptz<(p->>'lastFactAt')::timestamptz or (data->>'happenedAt')::timestamptz>at_time or at_time>(data->>'actionAt')::timestamptz or (data->>'actionUntil')::timestamptz<(data->>'actionAt')::timestamptz
       or not coalesce(crm_private.hold_record((data->>'recordId')::uuid,opp,s),false) then raise exception 'HOLD_CHECK_REQUIRED:E3';end if;
       if p->'terms'->'expiresAt'<>'null'::jsonb and (data->>'actionUntil')::timestamptz>=(p->'terms'->>'expiresAt')::timestamptz then raise exception 'HOLD_EXPIRED:E3';end if;
       p:=p||jsonb_build_object('validity','Vigente','verified',data||jsonb_build_object('evidenceId',a->'evidenceId','actorId',actor,'at',at_time),'review',null);
       if p->'terms'->'expiresAt'='null'::jsonb then follow:=true;end if;
      elsif action='near' then
       if data-array['partIds','evaluatedAt','advance']<>'{}'::jsonb or p->>'validity'<>'Vigente' or not coalesce(crm_private.availability_time(data->'evaluatedAt'),false)
       or (data->>'evaluatedAt')::timestamptz<>at_time or p->'terms'->'expiresAt'='null'::jsonb or jsonb_typeof(data->'advance') is distinct from 'object' or (data->'advance')-array['seconds','sourceRef','version']<>'{}'::jsonb
       or coalesce(data->'advance'->>'seconds','')!~'^[1-9][0-9]*$' or not coalesce(crm_private.invoice_text(data->'advance'->'sourceRef'),false) or not coalesce(crm_private.invoice_text(data->'advance'->'version'),false)
       or (data->>'evaluatedAt')::timestamptz>=(p->'terms'->>'expiresAt')::timestamptz or (data->>'evaluatedAt')::timestamptz<(p->'terms'->>'expiresAt')::timestamptz-make_interval(secs=>(data->'advance'->>'seconds')::double precision) then raise exception 'HOLD_ADVANCE_REQUIRED:E3';end if;
       p:=p||jsonb_build_object('near',data||jsonb_build_object('evidenceId',a->'evidenceId'));follow:=true;
      elsif action='invalidate' then
       if data-array['partIds','cause','result','before','after','dependencies']<>'{}'::jsonb or not(data ?& array['cause','result','before','after','dependencies'])
       or not coalesce(crm_private.invoice_text(data->'cause'),false) or data->'before' is distinct from old->'parts' or data->'dependencies' is distinct from data->'partIds'
       or jsonb_typeof(data->'after') is distinct from 'object' or coalesce(data->>'result' not in ('expired','uncertain'),true) then raise exception 'HOLD_REVIEW_REQUIRED:E3';end if;
       if data->>'result'='expired' and (p->'terms'->'expiresAt'='null'::jsonb or at_time<(p->'terms'->>'expiresAt')::timestamptz) then raise exception 'HOLD_EXPIRY_REQUIRED:E3';end if;
       p:=p||jsonb_build_object('validity',case data->>'result' when 'expired' then 'Vencido' else 'No verificado' end,'review',data||jsonb_build_object('evidenceId',a->'evidenceId','actorId',actor,'at',at_time),'near',null);follow:=true;
      elsif action='request' then
       if data-array['partIds','decision','communicationFactId','sentAt','providerRevisionId','basis']<>'{}'::jsonb or not(data ?& array['decision','communicationFactId','sentAt','providerRevisionId','basis'])
       or not coalesce(crm_private.invoice_text(data->'decision'),false) or not coalesce(crm_private.invoice_text(data->'basis'),false) or data->'providerRevisionId' is distinct from old->'providerRevisionId'
       or not coalesce(crm_private.availability_time(data->'sentAt'),false) or (data->>'sentAt')::timestamptz>at_time then raise exception 'HOLD_REQUEST_REQUIRED:E3';end if;
       select * into record from crm_private.b07_records where record_id=(data->>'communicationFactId')::uuid and admin_scope=s and record_kind='communication_fact' and material->>'fact_kind'='sent'
       and material->>'party_ref'=old->>'providerRevisionId' and material->>'coverage'=iid::text and occurred_at=(data->>'sentAt')::timestamptz;
       if record.record_id is null or not coalesce(crm_private.hold_record(record.record_id,opp,s),false)
       or not exists(select 1 from crm_private.b07_records where record_id=record.original_id and admin_scope=s and record_kind='communication' and material->>'direction'='outgoing' and material->>'recipient_ref'=old->>'providerRevisionId') then raise exception 'HOLD_SENT_REQUIRED:E3';end if;
       p:=p||jsonb_build_object('request',data||jsonb_build_object('status','Liberación solicitada','evidenceId',a->'evidenceId','actorId',actor,'at',at_time));
      else
       if data-array['partIds','bookingId','serviceId','nightId','bookingRevision','serviceRevision','conditionsChecked','scopeRevision']<>'{}'::jsonb or not(data ?& array['bookingId','serviceId','nightId','bookingRevision','serviceRevision','conditionsChecked']) or data->'conditionsChecked' is distinct from 'true'::jsonb
       or p->>'validity'<>'Vigente' or p->'review'<>'null'::jsonb or (p->'verified'->>'actionAt')::timestamptz is distinct from at_time or (p->'terms'->'expiresAt'<>'null'::jsonb and at_time>=(p->'terms'->>'expiresAt')::timestamptz)
       or not exists(select 1 from crm_private.b04_bookings b join crm_private.b04_current_services bs using(booking_id) join crm_private.b04_contributions c on c.service_id=bs.service_id join crm_private.b03_proposal_lines pl on pl.version_id=c.version_id and pl.line_id=c.line_id
       where b.opportunity_id=opp and b.admin_scope=s and bs.admin_scope=s and b.booking_id=(data->>'bookingId')::uuid and bs.service_id=(data->>'serviceId')::uuid
       and b.revision::text=data->>'bookingRevision' and bs.revision::text=data->>'serviceRevision' and c.version_id=(p->'terms'->>'versionId')::uuid and c.line_id=(p->'terms'->>'lineId')::uuid and bs.service_revision_id=(p->'terms'->>'serviceRevisionId')::uuid and coalesce(bs.applied->'variant','null'::jsonb)=p->'terms'->'variantRevisionId' and (crm_private.modification_reference(jsonb_build_object('kind','service','id',bs.service_id),b.booking_id,s) is null or crm_private.modification_reference(jsonb_build_object('kind','service','id',bs.service_id),b.booking_id,s)=(p->'terms'->>'date')::date))
       or (data->'nightId'<>'null'::jsonb and not exists(select 1 from crm_private.b04_current_nights where night_id=(data->>'nightId')::uuid and service_id=(data->>'serviceId')::uuid and admin_scope=s and night_date=(p->'terms'->>'date')::date))
       or not crm_private.modification_hold_link(data,p->'terms',s) then raise exception 'HOLD_LINK_REQUIRED:E3';end if;
       if p->'link'<>'null'::jsonb and p->'link' is distinct from data and ((p->'link')-array['scopeRevision','serviceRevision'] is distinct from data-array['scopeRevision','serviceRevision'] or not crm_private.modification_hold_link(data,p->'terms',s)) then raise exception 'HOLD_LINK_CONFLICT:E2';end if;
       p:=p||jsonb_build_object('link',data);
      end if;
     end if;
     parts:=parts||jsonb_build_array(p);
    end loop;
    if (select count(*)<>count(distinct x->'terms'->>'id') from jsonb_array_elements(parts) x) then raise exception 'HOLD_SPLIT_REQUIRED:E3';end if;
    state:=state||jsonb_build_object('parts',parts);
   end if;
   rev:=coalesce(rev,0)+1;state:=state||jsonb_build_object('revision',rev);
  end if;
  r:=jsonb_build_object('id',iid,'replayed',known,'result',state);
  if root.hold_id is null then insert into crm_private.b04_holds values(iid,opp,s,(data->>'providerRevisionId')::uuid,data->>'externalRef',op);end if;
  if old is distinct from state then insert into crm_private.b04_hold_revisions values(iid,rev,s,op,action,a,old,state,actor,(a->>'evidenceId')::uuid,a->>'sourceRef',a->>'reason',at_time,clock_timestamp());end if;
  if follow then
   fs:=crm_f1.fields(tq);task:=fs[2]::jsonb;
   if fs[1]<>'CRM-H1-TASK-1' or task->>'taskId'<>iid::text or task->>'operationId'<>op::text or task->'identity' is distinct from jsonb_build_object('causeKind','block','causeId',iid,'contextKind','opportunity','contextId',opp,'scopeRef',iid,'effect','hold-review')
   or task->'material' is distinct from '{"title":"Revisar opción y cobertura del alcance","deadline":{"kind":"unknown","reason":"No consta fecha fijada para el seguimiento"},"priority":{"kind":"pending","reason":"Prioridad no configurada"},"sourceRef":"SM-HO","sourceVersion":"1","triggerRef":"BR-TASK-005","triggerVersion":"1"}'::jsonb then raise exception 'HOLD_TASK_REQUIRED';end if;
   select result_ref into task_id from crm_api.b07_task_apply(tf2p,tf2s,tf1p,tf1s,tq);
  end if;
  insert into crm_private.b04_hold_operations values(op,iid,s,actor,fp,r,rev,clock_timestamp());
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.hold_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;s text;opp uuid;iid uuid;r jsonb;p jsonb;usable boolean;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'HOLD_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-HOLD-READ1' then raise exception 'HOLD_INPUT_INVALID';end if;a:=fs[2]::jsonb;s:=hf[17];opp:=(a->>'opportunityId')::uuid;
 if a-array['holdId','opportunityId','projection']<>'{}'::jsonb or not(a ?& array['holdId','opportunityId']) then raise exception 'HOLD_INPUT_INVALID';end if;
 if not exists(select 1 from crm_private.b03_opportunities where opportunity_id=opp and admin_scope=s) then r:=null;
 else
  select hold_id into iid from crm_private.b04_holds where hold_id=(a->>'holdId')::uuid and opportunity_id=opp and admin_scope=s;
  select after_data into r from crm_private.b04_hold_revisions where hold_id=iid and admin_scope=s order by revision desc limit 1;
  if r is not null then
   if a?'projection' then
    if (a->'projection')-array['partId','actionAt','actionUntil','quantity','unitRevisionId','date']<>'{}'::jsonb or not(a->'projection' ?& array['partId','actionAt','actionUntil','quantity','unitRevisionId','date']) or not coalesce(crm_private.availability_time(a->'projection'->'actionAt'),false) or not coalesce(crm_private.availability_time(a->'projection'->'actionUntil'),false) or coalesce(a->'projection'->>'quantity','')!~'^[0-9]+(\.[0-9]+)?$' then raise exception 'HOLD_INPUT_INVALID';end if;
    select value into p from jsonb_array_elements(r->'parts') where value->'terms'->>'id'=a->'projection'->>'partId';
    usable:=coalesce(p->>'validity'='Vigente' and (p->>'remaining')::numeric>=(a->'projection'->>'quantity')::numeric and (a->'projection'->>'quantity')::numeric>0 and p->'terms'->'unitRevisionId'=a->'projection'->'unitRevisionId' and p->'terms'->'date'=a->'projection'->'date'
    and p->'review'='null'::jsonb and p->'verified'->'actionAt'=a->'projection'->'actionAt' and p->'verified'->'actionUntil'=a->'projection'->'actionUntil'
    and (p->'terms'->'expiresAt'='null'::jsonb or (a->'projection'->>'actionUntil')::timestamptz<(p->'terms'->>'expiresAt')::timestamptz),false);
    if p->'link'<>'null'::jsonb and (not crm_private.modification_hold_link(p->'link',p->'terms',s) or crm_private.modification_pending((p->'link'->>'bookingId')::uuid,(p->'link'->>'serviceId')::uuid,(select n.night_id from crm_private.b04_nights n where n.service_id=(p->'link'->>'serviceId')::uuid and n.night_date=(p->'terms'->>'date')::date limit 1),s)) then usable:=false;end if;r:=jsonb_build_object('id',iid,'revision',r->'revision','usable',usable,'remaining',p->'remaining','unitRevisionId',p->'terms'->'unitRevisionId','date',p->'terms'->'date','validity',p->'validity','expiresAt',p->'terms'->'expiresAt','releaseRequested',p->'request'<>'null'::jsonb,'revalidationNeeded',p->'terms'->'expiresAt'='null'::jsonb or p->'review'<>'null'::jsonb,'serviceState',case when p->'link'<>'null'::jsonb and usable then 'Opcionado / bloqueado' else null end,'serviceConfirmed',false,'firmReservation',false,'executed',false);
   else
    r:=r||jsonb_build_object('history',(select jsonb_agg(jsonb_build_object('revision',revision,'action',action_kind,'before',before_data,'after',after_data,'actorId',actor_id,'sourceRef',source_ref,'reason',reason,'evidenceId',evidence_id,'at',occurred_at,'recordedAt',recorded_at) order by revision) from crm_private.b04_hold_revisions where hold_id=iid and admin_scope=s));
   end if;
  end if;
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_private.confirmation_coverage(x jsonb, bid uuid, s text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare sv crm_private.b04_services;begin
 if jsonb_typeof(x) is distinct from 'object' or not((x||'{"scopeRevision":null}'::jsonb) ?& array['serviceId','nightId','contributionId','serviceRevisionId','serviceRevision','bookingRevision','variant','date','time','quantity','scopeRevision','unitRevisionId','commercialBasis','conditions'])
 or x-array['serviceId','nightId','contributionId','serviceRevisionId','serviceRevision','bookingRevision','variant','date','time','quantity','scopeRevision','unitRevisionId','commercialBasis','conditions']<>'{}'::jsonb
 or coalesce(x->>'quantity','')!~'^[0-9]+(\.[0-9]+)?$' or (x->>'quantity')::numeric<=0
 or coalesce(x->>'date','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or coalesce(x->>'time','')!~'^[0-9]{2}:[0-9]{2}(:[0-9]{2})?[+-][0-9]{2}:[0-9]{2}$'
 or not coalesce(crm_private.invoice_text(x->'conditions'),false) then return false;end if;perform (x->>'time')::timetz;perform (x->>'date')::date;
 select * into sv from crm_private.b04_current_services where service_id=(x->>'serviceId')::uuid and booking_id=bid and admin_scope=s;
 if not found or sv.revision::text is distinct from x->>'serviceRevision' or sv.service_revision_id::text is distinct from x->>'serviceRevisionId'
 or sv.applied->'variant' is distinct from x->'variant' or not exists(select 1 from crm_private.b04_bookings where booking_id=bid and admin_scope=s and revision::text=x->>'bookingRevision') then return false;end if;
 if x->'contributionId'<>'null'::jsonb and not exists(select 1 from crm_private.b04_contributions where contribution_id=(x->>'contributionId')::uuid and service_id=sv.service_id and booking_id=bid and admin_scope=s) then return false;end if;
 if x->'nightId'<>'null'::jsonb then
  if not exists(select 1 from crm_private.b04_current_nights where night_id=(x->>'nightId')::uuid and service_id=sv.service_id and admin_scope=s and night_date=(x->>'date')::date) then return false;end if;
 else
  if not exists(select 1 from crm_private.b04_contributions c join crm_private.b03_proposal_lines l on l.line_id=c.line_id and l.version_id=c.version_id where c.service_id=sv.service_id and c.admin_scope=s and l.admin_scope=s and (x->'contributionId'='null'::jsonb or c.contribution_id=(x->>'contributionId')::uuid) and (case when exists(select 1 from crm_private.b04_operational_versions ov where ov.scope_kind='service' and ov.scope_id=sv.service_id) then (crm_private.modification_scope(jsonb_build_object('kind','service','id',sv.service_id),bid,s)->>'date')::date else (crm_private.modification_scope(jsonb_build_object('kind','contribution','id',c.contribution_id,'serviceId',sv.service_id),bid,s)->>'date')::date end)=(x->>'date')::date) then return false;end if;
 end if;
 if x->'commercialBasis' is distinct from crm_private.confirmation_commercial(bid,sv.service_id,(x->>'contributionId')::uuid,(x->>'nightId')::uuid,s) then return false;end if;
 if crm_private.modification_token(bid,sv.service_id,(x->>'nightId')::uuid,(x->>'contributionId')::uuid,s)<>encode(crm_crypto.digest(convert_to('[]','UTF8'),'sha256'),'hex') and x->>'scopeRevision' is distinct from crm_private.modification_token(bid,sv.service_id,(x->>'nightId')::uuid,(x->>'contributionId')::uuid,s) then return false;end if;return exists(select 1 from crm_private.catalog_revisions r join crm_private.catalog_items i using(item_id) where r.revision_id=(x->>'unitRevisionId')::uuid and r.admin_scope=s and i.admin_scope=s and i.item_kind='unit');
end$function$

CREATE OR REPLACE FUNCTION crm_private.confirmation_fact(x jsonb, bid uuid, s text, actor uuid, at_time timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare sv crm_private.b04_services;src jsonb;ofr crm_private.catalog_revisions;begin
 if jsonb_typeof(x) is distinct from 'object' or not(x ?& array['factId','recordId','source','happenedAt','content','certainty','coverage'])
 or x-array['factId','recordId','source','happenedAt','content','certainty','coverage']<>'{}'::jsonb or x->>'certainty' is distinct from 'confirmed'
 or not coalesce(crm_private.invoice_text(x->'content'),false) or not coalesce(crm_private.availability_time(x->'happenedAt'),false)
 or (x->>'happenedAt')::timestamptz>at_time or not coalesce(crm_private.confirmation_coverage(x->'coverage',bid,s),false)
 or not coalesce(crm_private.confirmation_record((x->>'recordId')::uuid,bid,s),false) then return false;end if;perform (x->>'factId')::uuid;
 src:=x->'source';if jsonb_typeof(src) is distinct from 'object' or not(src ?& array['kind','id','offeringRevisionId','counterpart','channel']) or src-array['kind','id','offeringRevisionId','counterpart','channel']<>'{}'::jsonb or not coalesce(crm_private.invoice_text(src->'counterpart'),false) then return false;end if;
 select * into sv from crm_private.b04_current_services where service_id=(x->'coverage'->>'serviceId')::uuid and admin_scope=s;
 if sv.nature='internal' then
  return src->>'kind'='internal' and src->'offeringRevisionId'='null'::jsonb and src->>'channel'='internal-record' and exists(select 1 from crm_private.crm_actors where actor_id=(src->>'id')::uuid and admin_scope=s and enabled);
 end if;
 if src->>'kind' is distinct from 'provider' or src->>'channel' not in ('phone','whatsapp','email','provider-platform') then return false;end if;
 select r.* into ofr from crm_private.catalog_revisions r join crm_private.catalog_items i using(item_id) where r.revision_id=(src->>'offeringRevisionId')::uuid and r.admin_scope=s and i.admin_scope=s and i.item_kind='offering';
 return ofr.revision_id is not null and ofr.parent_revision_id=(src->>'id')::uuid and (ofr.related_revision_id=sv.service_revision_id or ofr.related_revision_id=(x->'coverage'->>'variant')::uuid)
 and exists(select 1 from crm_private.catalog_revisions r join crm_private.catalog_items i using(item_id) where r.revision_id=(src->>'id')::uuid and r.admin_scope=s and i.item_kind='provider')
 and (sv.applied->'provider'='null'::jsonb or sv.applied->'provider'=src->'id');
end$function$

CREATE OR REPLACE FUNCTION crm_private.confirmation_dependencies(d jsonb, bid uuid, c jsonb, s text, action_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare x jsonb;v jsonb;cov jsonb;token jsonb;usable boolean;r jsonb:='[]';opp uuid;begin
 if jsonb_typeof(d) is distinct from 'array' then raise exception 'CONFIRMATION_DEPENDENCY_REQUIRED:E3';end if;
 select opportunity_id into opp from crm_private.b04_bookings where booking_id=bid and admin_scope=s;
 for x in select value from jsonb_array_elements(d) loop
  if x-array['kind','id','partId','reason']<>'{}'::jsonb or not(x ?& array['kind','id','reason']) or not coalesce(crm_private.invoice_text(x->'reason'),false) then raise exception 'CONFIRMATION_DEPENDENCY_REQUIRED:E3';end if;
  if x->>'kind'='availability' then
   select v.after_data into v from crm_private.b04_availability a cross join lateral(select after_data from crm_private.b04_availability_revisions where availability_id=a.availability_id order by revision desc limit 1) v where a.availability_id=(x->>'id')::uuid and a.booking_id=bid and a.admin_scope=s;
   cov:=coalesce(v->'confirmed'->'response'->'coverage',v->'response'->'coverage',v->'query'->'coverage');
   if v is null or cov->'serviceId' is distinct from c->'serviceId' or cov->'nightId' is distinct from c->'nightId' then raise exception 'CONFIRMATION_DENIED';end if;
   usable:=coalesce(v->'confirmed'<>'null'::jsonb and v->'review'='null'::jsonb and cov->'unitRevisionId'=c->'unitRevisionId' and cov->'variant'=c->'variant' and cov->'dates' ? (c->>'date') and (v->'confirmed'->'verification'->>'actionAt')::timestamptz=action_at and (v->'confirmed'->'verification'->>'actionUntil')::timestamptz>=action_at and (cov->>'quantity')::numeric>=(c->>'quantity')::numeric and (v->'confirmed'->'response'->'validUntil'='null'::jsonb or (v->'confirmed'->'response'->>'validUntil')::timestamptz>action_at),false);
   token:=jsonb_build_object('confirmed',v->'confirmed','review',v->'review','usable',usable);
  elsif x->>'kind'='hold' then
   select v.after_data into v from crm_private.b04_holds a cross join lateral(select after_data from crm_private.b04_hold_revisions where hold_id=a.hold_id order by revision desc limit 1) v where a.hold_id=(x->>'id')::uuid and a.opportunity_id=opp and a.admin_scope=s;
   select value into v from jsonb_array_elements(v->'parts') where value->'terms'->'id'=x->'partId' and value->'link'->'serviceId'=c->'serviceId' and value->'link'->'bookingId'=to_jsonb(bid);
   if v is null then raise exception 'CONFIRMATION_DENIED';end if;
   usable:=coalesce(v->>'validity'='Vigente' and v->'review'='null'::jsonb and (v->'verified'->>'actionAt')::timestamptz=action_at and (v->'verified'->>'actionUntil')::timestamptz>=action_at and (v->>'remaining')::numeric>=(c->>'quantity')::numeric and v->'terms'->'unitRevisionId'=c->'unitRevisionId' and v->'terms'->'date'=c->'date' and (v->'terms'->'expiresAt'='null'::jsonb or (v->'terms'->>'expiresAt')::timestamptz>action_at),false);
   token:=jsonb_build_object('terms',v->'terms','remaining',v->'remaining','validity',v->'validity','review',v->'review','verified',v->'verified','usable',usable);
  else raise exception 'CONFIRMATION_DEPENDENCY_REQUIRED:E3';end if;
  r:=r||jsonb_build_array(jsonb_build_object('dependency',x,'current',token));
 end loop;return r;
end$function$

CREATE OR REPLACE FUNCTION crm_private.confirmation_current(state jsonb, bid uuid, s text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare missing jsonb:='[]';e jsonb:=state->'evaluation';current jsonb;app crm_private.catalog_applications;begin
 if e is null or e='null'::jsonb then return jsonb_build_object('usable',false,'missing',jsonb_build_array('evaluation'));end if;
 if crm_private.modification_pending(bid,(e->'coverage'->>'serviceId')::uuid,(e->'coverage'->>'nightId')::uuid,s) then missing:=missing||'"modification-review"'::jsonb;end if;if state->'review'<>'null'::jsonb then missing:=missing||'"review"'::jsonb;end if;
 if crm_private.confirmation_discrepancy(state->'fact',bid,s,(state->>'id')::uuid) then missing:=missing||'"external-discrepancy:E8"'::jsonb;end if;
 if not coalesce(crm_private.confirmation_coverage(e->'coverage',bid,s),false) then missing:=missing||'"scope"'::jsonb;end if;
 current:=crm_private.confirmation_requirements(bid,e->'coverage',s);
 if current is distinct from e->'requirements' or exists(select 1 from jsonb_array_elements(current) x where x->>'status' not in ('Revisado','No aplica')) then missing:=missing||'"requirement"'::jsonb;end if;
 if crm_private.confirmation_dependencies(e->'dependencies',bid,e->'coverage',s,(e->>'at')::timestamptz) is distinct from e->'dependencySnapshot' then missing:=missing||'"dependency-review"'::jsonb;end if;
 select * into app from crm_private.catalog_applications where subject_ref=(e->'coverage'->>'serviceId')::uuid and admin_scope=s order by recorded_at desc,application_id desc limit 1;
 if app.application_id::text is distinct from e->>'catalogApplicationId' then missing:=missing||'"catalog-version"'::jsonb;end if;
 if e->'missing'<>'[]'::jsonb then missing:=missing||(e->'missing');end if;
 return jsonb_build_object('usable',missing='[]'::jsonb,'missing',missing);
end$function$

CREATE OR REPLACE FUNCTION crm_api.confirmation_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea, tf2p bytea, tf2s bytea, tf1p bytea, tf1s bytea, tq bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;op uuid;iid uuid;bid uuid;actor uuid;s text;action text;fp text;hash text;at_time timestamptz;rev bigint;evalrev bigint;
 root crm_private.b04_confirmations;prev crm_private.b04_confirmation_operations;existing crm_private.b04_confirmation_facts;
 old jsonb;state jsonb;d jsonb;r jsonb;fact jsonb;c jsonb;reqs jsonb;deps jsonb;missing jsonb;app crm_private.catalog_applications;sv uuid;
 known boolean:=false;follow boolean:=false;task jsonb;task_id uuid;opp uuid;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'CONFIRMATION_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-CONFIRMATION1' then raise exception 'CONFIRMATION_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or not(a ?& array['action','operationId','confirmationId','bookingId','expectedRevision','expectedEvaluationRevision','sourceRef','reason','at','evidenceId','data'])
 or a-array['action','operationId','confirmationId','bookingId','expectedRevision','expectedEvaluationRevision','sourceRef','reason','at','evidenceId','data','origin']<>'{}'::jsonb
 or exists(select 1 from unnest(array['action','operationId','confirmationId','bookingId','sourceRef','reason','evidenceId']) k where not coalesce(crm_private.invoice_text(a->k),false))
 or not coalesce(crm_private.availability_time(a->'at'),false) or jsonb_typeof(a->'data') is distinct from 'object'
 or coalesce(a->>'expectedRevision','')!~'^(0|[1-9][0-9]*)$' or coalesce(a->>'expectedEvaluationRevision','')!~'^(0|[1-9][0-9]*)$' or coalesce(a->>'origin','manual')<>'manual' then raise exception 'CONFIRMATION_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;iid:=(a->>'confirmationId')::uuid;bid:=(a->>'bookingId')::uuid;actor:=hf[12]::uuid;s:=hf[17];action:=a->>'action';d:=a->'data';at_time:=(a->>'at')::timestamptz;
 if action not in ('register','evaluate','review','rectify') then raise exception 'CONFIRMATION_INPUT_INVALID';end if;
 select opportunity_id into opp from crm_private.b04_bookings where booking_id=bid and admin_scope=s;if not found then raise exception 'CONFIRMATION_DENIED';end if;
 -- Shared accepted parent, documentary and availability roots, in the existing lock order.
 perform pg_advisory_xact_lock(hashtextextended(opp::text,31));perform pg_advisory_xact_lock(hashtextextended('requirement-booking:'||bid,0));perform pg_advisory_xact_lock(hashtextextended('availability-booking:'||bid,0));perform pg_advisory_xact_lock(hashtextextended('confirmation-booking:'||bid,0));
 select * into root from crm_private.b04_confirmations where confirmation_id=iid;
 if (action<>'register' and root.confirmation_id is null) or (root.confirmation_id is not null and (root.booking_id<>bid or root.admin_scope<>s)) then raise exception 'CONFIRMATION_DENIED';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('confirmation-op:'||op,0));select * into prev from crm_private.b04_confirmation_operations where operation_id=op;
 if found then
  if prev.admin_scope<>s or prev.actor_id<>actor or prev.fingerprint<>fp then raise exception 'CONFIRMATION_REPLAY_CONFLICT:E2';end if;r:=prev.result||jsonb_build_object('replayed',true);
 else
  hash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.payment_evidence((a->>'evidenceId')::uuid,iid,s,'confirmation:'||action||':'||hash,at_time,true) or not exists(select 1 from crm_private.b07_records where record_id=(a->>'evidenceId')::uuid and recorded_by=actor) then raise exception 'CONFIRMATION_EVIDENCE_REQUIRED:E3';end if;
  if action in ('register','rectify') then
   perform pg_advisory_xact_lock(hashtextextended('confirmation-fact:'||(d->>'factId'),0));select * into existing from crm_private.b04_confirmation_facts where fact_id=(d->>'factId')::uuid;
   if found then
    if existing.admin_scope<>s or existing.material is distinct from d or not exists(select 1 from crm_private.b04_confirmations where confirmation_id=existing.confirmation_id and booking_id=bid and admin_scope=s) then raise exception 'CONFIRMATION_FACT_CONFLICT:E2';end if;
    if action='rectify' and existing.confirmation_id<>iid then raise exception 'CONFIRMATION_FACT_CONFLICT:E2';end if;iid:=existing.confirmation_id;select * into root from crm_private.b04_confirmations where confirmation_id=iid;known:=true;
   end if;
  end if;
  if root.confirmation_id is not null then select revision,after_data into rev,old from crm_private.b04_confirmation_revisions where confirmation_id=iid order by revision desc limit 1;end if;
  if not known and action in ('review','evaluate') and exists(select 1 from crm_private.b04_confirmation_revisions where confirmation_id=iid and action_kind=action and event->'data'=d) then
   if action='review' and old->'review'<>'null'::jsonb or action='evaluate' and (crm_private.confirmation_current(old,bid,s)->>'usable')::boolean then known:=true;end if;
  end if;
  state:=old;
  if not known then
   if coalesce(rev,0)<>(a->>'expectedRevision')::bigint then raise exception 'CONFIRMATION_REVISION_CONFLICT:E2';end if;
   if action in ('register','rectify') then
    if not coalesce(crm_private.confirmation_fact(d,bid,s,actor,at_time),false) then raise exception 'CONFIRMATION_FACT_REQUIRED:E3';end if;
    if action='register' then
     if root.confirmation_id is not null or (a->>'expectedRevision')::bigint<>0 then raise exception 'CONFIRMATION_REVISION_CONFLICT:E2';end if;
     insert into crm_private.b04_confirmations values(iid,bid,s,op);state:=jsonb_build_object('id',iid,'bookingId',bid,'fact',d,'review',null,'evaluation',null);rev:=0;
    else
     if old->'review'='null'::jsonb or d->'recordId'=old->'fact'->'recordId' then raise exception 'CONFIRMATION_NEW_PROOF_REQUIRED:E3';end if;
     if (d->>'happenedAt')::timestamptz<=(old->'fact'->>'happenedAt')::timestamptz then raise exception 'CONFIRMATION_PRECEDENCE_REQUIRED:E8';end if;
     if d->'coverage'->'serviceId'<>old->'fact'->'coverage'->'serviceId' then raise exception 'CONFIRMATION_SCOPE_REQUIRED:E3';end if;
     state:=old||jsonb_build_object('fact',d,'review',null,'evaluation',null);
    end if;
    insert into crm_private.b04_confirmation_facts values((d->>'factId')::uuid,iid,s,case when action='rectify' then (old->'fact'->>'factId')::uuid else null end,d,actor,(a->>'evidenceId')::uuid,(d->>'happenedAt')::timestamptz,clock_timestamp(),op);
   elsif action='review' then
    if d-array['recordId','cause','before','after','aspects','dependencies','result']<>'{}'::jsonb or not(d ?& array['recordId','cause','before','after','aspects','dependencies','result'])
    or not coalesce(crm_private.confirmation_record((d->>'recordId')::uuid,bid,s),false) or not coalesce(crm_private.invoice_text(d->'cause'),false)
    or d->'before' is distinct from old->'fact' or jsonb_typeof(d->'after') is distinct from 'object' or jsonb_typeof(d->'aspects') is distinct from 'array' or jsonb_array_length(d->'aspects')=0
    or exists(select 1 from jsonb_array_elements_text(d->'aspects') x where x not in ('time','date','quantity','unit','price','conditions','capacity','source','variant','scope'))
    or d->'dependencies' is distinct from jsonb_build_array(old->'fact'->'coverage') or d->>'result' is distinct from 'pending' then raise exception 'CONFIRMATION_REVIEW_REQUIRED:E3';end if;
    state:=old||jsonb_build_object('review',d||jsonb_build_object('evidenceId',a->'evidenceId','actorId',actor,'at',at_time));follow:=true;
   else
    if d-array['coverage','catalogApplicationId','eligibilityProofId','scopeProofId','agreementProofId','dependencies']<>'{}'::jsonb or not(d ?& array['coverage','catalogApplicationId','eligibilityProofId','scopeProofId','agreementProofId','dependencies']) then raise exception 'CONFIRMATION_EVALUATION_REQUIRED:E3';end if;
    c:=d->'coverage';if not coalesce(crm_private.confirmation_coverage(c,bid,s),false) then raise exception 'CONFIRMATION_SCOPE_REQUIRED:E3';end if;sv:=(c->>'serviceId')::uuid;
    if (c-array['quantity']) is distinct from ((old->'fact'->'coverage')-array['quantity']) or (c->>'quantity')::numeric>(old->'fact'->'coverage'->>'quantity')::numeric then raise exception 'CONFIRMATION_COVERAGE_REQUIRED:E3';end if;
    select coalesce(max(revision),0) into evalrev from crm_private.b04_confirmation_evaluations where service_id=sv and admin_scope=s;
    if evalrev<>(a->>'expectedEvaluationRevision')::bigint then raise exception 'CONFIRMATION_EVALUATION_CONFLICT:E2';end if;
    missing:='[]';if old->'review'<>'null'::jsonb then missing:=missing||'"review"'::jsonb;end if;
    -- A reviewed applied catalogue manifest is real versioned input, never a recommendation boolean.
    select * into app from crm_private.catalog_applications where application_id=(d->>'catalogApplicationId')::uuid and subject_ref=sv and admin_scope=s;
    if not found or not exists(select 1 from jsonb_array_elements(app.applied_revisions) x where x->'revision'->>'revision_id'=c->>'serviceRevisionId')
    or app.application_id is distinct from (select application_id from crm_private.catalog_applications where subject_ref=sv and admin_scope=s order by recorded_at desc,application_id desc limit 1) then raise exception 'CONFIRMATION_CATALOG_REQUIRED:E3';end if;
    hash:=encode(crm_crypto.digest(convert_to(jsonb_build_object('coverage',c,'application',to_jsonb(app))::text,'UTF8'),'sha256'),'hex');
    if not crm_private.payment_evidence((d->>'eligibilityProofId')::uuid,sv,s,'confirmation:eligibility:'||hash,at_time,true) then missing:=missing||'"objective-eligibility"'::jsonb;end if;
    hash:=encode(crm_crypto.digest(convert_to(c::text,'UTF8'),'sha256'),'hex');
    if not crm_private.payment_evidence((d->>'scopeProofId')::uuid,sv,s,'confirmation:scope:'||hash,at_time,true) then missing:=missing||'"scope-capacity-price-conditions"'::jsonb;end if;
    if not crm_private.payment_evidence((d->>'agreementProofId')::uuid,sv,s,'confirmation:time:'||hash,at_time,true) then missing:=missing||'"time-agreement"'::jsonb;end if;
    reqs:=crm_private.confirmation_requirements(bid,c,s);
    if exists(select 1 from jsonb_array_elements(reqs) x where x->>'status' not in ('Revisado','No aplica')) then missing:=missing||'"requirement"'::jsonb;end if;
    deps:=crm_private.confirmation_dependencies(d->'dependencies',bid,c,s,at_time);
    if exists(select 1 from jsonb_array_elements(deps) x where x->'current'->'usable' is distinct from 'true'::jsonb) then missing:=missing||'"dependency-review"'::jsonb;end if;
    -- Two distinct contemporaneous contradictory facts remain E8, not receipt-order precedence.
    if crm_private.confirmation_discrepancy(old->'fact',bid,s,iid) then missing:=missing||'"external-discrepancy:E8"'::jsonb;end if;
    state:=old||jsonb_build_object('evaluation',d||jsonb_build_object('requirements',reqs,'dependencySnapshot',deps,'missing',missing,'evaluationRevision',evalrev+1,'actorId',actor,'at',at_time,'evidenceId',a->'evidenceId','factId',old->'fact'->'factId'));
    insert into crm_private.b04_confirmation_evaluations values(bid,sv,evalrev+1,iid,s,op,state->'evaluation');follow:=missing<>'[]'::jsonb;
   end if;
   rev:=rev+1;state:=state||jsonb_build_object('revision',rev);
  end if;
  if old is distinct from state then insert into crm_private.b04_confirmation_revisions values(iid,rev,s,op,action,a,old,state,actor,(a->>'evidenceId')::uuid,a->>'sourceRef',a->>'reason',at_time,clock_timestamp());end if;
  r:=jsonb_build_object('id',iid,'replayed',known,'result',state);
  if follow then
   fs:=crm_f1.fields(tq);task:=fs[2]::jsonb;
   if fs[1]<>'CRM-H1-TASK-1' or task->>'taskId'<>iid::text or task->>'operationId'<>op::text or task->'identity' is distinct from jsonb_build_object('causeKind','block','causeId',iid,'contextKind','booking','contextId',bid,'scopeRef',iid,'effect','confirmation-review')
   or task->'material' is distinct from '{"title":"Revisar confirmación y cobertura del alcance","deadline":{"kind":"unknown","reason":"No consta fecha fijada para el seguimiento"},"priority":{"kind":"pending","reason":"Prioridad no configurada"},"sourceRef":"SM-PC","sourceVersion":"1","triggerRef":"BR-TASK-005","triggerVersion":"1"}'::jsonb then raise exception 'CONFIRMATION_TASK_REQUIRED';end if;
   select result_ref into task_id from crm_api.b07_task_apply(tf2p,tf2s,tf1p,tf1s,tq);
  end if;
  insert into crm_private.b04_confirmation_operations values(op,iid,s,actor,fp,r,rev,clock_timestamp());
